contract MockERC20ReturnFalse {
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address, uint256) external pure returns (bool) {
        return false;
    }
}

/// @notice Token whose approve() always reverts.
contract MockERC20Revert {
    function approve(address, uint256) external pure returns (bool) {
        revert("APPROVE_REVERTED");
    }
}

/// @notice Token whose approve() reverts with no reason string (e.g. failed assert/require without message).
contract MockERC20RevertNoReason {
    function approve(address, uint256) external pure returns (bool) {
        revert();
    }
}

/// @notice Token whose approve() returns malformed (non-32-byte) return data.
contract MockERC20InvalidReturnData {
    fallback() external {
        // return 1 byte of data — not a valid abi-encoded bool
