        strategy.transfer(carol, shares);

        assertEq(strategy.balanceOf(carol), shares);
        assertEq(strategy.balanceOf(alice), 0);
    }

    function test_NonPrivilegedHolder_CanRedeemSharesReceivedByTransfer() public {
        _setPrivileged(alice, true);

        vm.prank(alice);
