        emit AddressSetAltered(alice, AddressSet.AddressSetOperation.Remove);
        vm.expectEmit(true, true, false, true);
        emit AddressSetAltered(bob, AddressSet.AddressSetOperation.Remove);

        set.remove(accounts);
    }

    function test_removeBatch_revertsOnEmptyArray() public {
        address[] memory accounts = new address[](0);
        vm.expectRevert(AddressSet.EmptyArray.selector);
        set.remove(accounts);
    }

    function test_removeBatch_revertsOnZeroAddressInArray() public {
        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = address(0);
        set.add(alice);

        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, address(0), "Address zero not allowed."
            )
        );
        set.remove(accounts);
    }

    function test_removeBatch_revertsOnAddressNotInSet() public {
        set.add(alice);

        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = bob;

        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, bob, "Address not in set."
            )
        );
        set.remove(accounts);
    }

    function test_removeBatch_revertsIfNotOwner() public {
        address[] memory accounts = new address[](1);
        accounts[0] = alice;
        set.add(alice);

        vm.prank(notOwner);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, notOwner));
        set.remove(accounts);
    }

    function test_removeBatch_partialFailureDoesNotPersist() public {
        set.add(alice);

        address[] memory accounts = new address[](2);
        accounts[0] = alice;
        accounts[1] = bob; // not in set, should revert entire tx

        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, bob, "Address not in set."
            )
        );
        set.remove(accounts);

        // alice's removal should have been rolled back
        assertTrue(set.contains(alice));
        assertEq(set.length(), 1);
    }

    // ============================================
    // contains / values / length
    // ============================================

    function test_contains_falseForAbsentAddress() public view {
        assertFalse(set.contains(alice));
    }

    function test_contains_trueAfterAdd_falseAfterRemove() public {
        set.add(alice);
        assertTrue(set.contains(alice));
        set.remove(alice);
        assertFalse(set.contains(alice));
    }

    function test_values_returnsAllAddedAddresses() public {
        address[] memory accounts = new address[](3);
        accounts[0] = alice;
        accounts[1] = bob;
        accounts[2] = carol;
        set.add(accounts);

        address[] memory result = set.values();
        assertEq(result.length, 3);

        bool foundAlice;
        bool foundBob;
        bool foundCarol;
        for (uint256 i = 0; i < result.length; i++) {
            if (result[i] == alice) foundAlice = true;
            if (result[i] == bob) foundBob = true;
            if (result[i] == carol) foundCarol = true;
        }
        assertTrue(foundAlice);
        assertTrue(foundBob);
        assertTrue(foundCarol);
    }

    function test_length_tracksAddsAndRemoves() public {
        assertEq(set.length(), 0);
        set.add(alice);
        assertEq(set.length(), 1);
        set.add(bob);
        assertEq(set.length(), 2);
        set.remove(alice);
        assertEq(set.length(), 1);
        set.remove(bob);
        assertEq(set.length(), 0);
    }

    // ============================================
    // OWNERSHIP TRANSFER INTERACTION
    // ============================================

    function test_newOwnerCanManageSet() public {
        set.transferOwnership(notOwner);

        vm.prank(notOwner);
        set.add(alice);
        assertTrue(set.contains(alice));

        // old owner can no longer add
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, owner));
        set.add(bob);
    }

    // ============================================
    // FUZZ TESTS
    // ============================================

    function testFuzz_addSingle_nonZeroAddress(address account) public {
        vm.assume(account != address(0));
        set.add(account);
        assertTrue(set.contains(account));
    }

    function testFuzz_addSingle_zeroAddressAlwaysReverts(address caller) public {
        vm.assume(caller == owner);
        vm.expectRevert(
            abi.encodeWithSelector(
                AddressSet.IllegalAddressSetOperation.selector, address(0), "Address zero not allowed."
            )
        );
        set.add(address(0));
    }

    function testFuzz_addThenRemove_roundTrip(address account) public {
        vm.assume(account != address(0));
        set.add(account);
        assertTrue(set.contains(account));
        set.remove(account);
        assertFalse(set.contains(account));
        assertEq(set.length(), 0);
    }

    function testFuzz_onlyOwnerCanAdd(address caller) public {
        vm.assume(caller != owner);
        vm.prank(caller);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, caller));
        set.add(alice);
    }

    function testFuzz_onlyOwnerCanRemove(address caller) public {
        vm.assume(caller != owner);
        set.add(alice);
        vm.prank(caller);
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, caller));
