// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

contract SparkStrategyTest is Test {
    SparkStrategy internal strategy;
    MockERC20 internal asset;
    MockERC4626Vault internal vault;
    MockDragonTokenizedStrategy internal tokenizedStrategyImpl;
    MockERC20 internal airdropToken;

    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal dragonRouter = makeAddr("dragonRouter");
    address internal stranger = makeAddr("stranger");

    event TokenSwept(address indexed token, uint256 amount, address indexed recipient);

    function setUp() public {
        asset = new MockERC20("Mock USDC", "mUSDC", 6);
        vault = new MockERC4626Vault(IERC20(address(asset)), "Mock Spark Vault", "spMUSDC");
        tokenizedStrategyImpl = new MockDragonTokenizedStrategy();

        strategy = new SparkStrategy(
            address(vault),
            address(asset),
            "Spark USDC Strategy",
            "osSparkUSDC",
            management,
            keeper,
            emergencyAdmin,
            dragonRouter,
            true,
            address(tokenizedStrategyImpl)
        );

        // Defensive re-wiring: guarantee role storage is set correctly
        // regardless of whether the constructor's own `initialize` call used
        // exactly the parameter order this mock assumes.
        (bool okM,) = address(strategy).call(abi.encodeWithSignature("setManagement(address)", management));
        (bool okK,) = address(strategy).call(abi.encodeWithSignature("setKeeper(address)", keeper));
        (bool okD,) = address(strategy).call(abi.encodeWithSignature("setDragonRouter(address)", dragonRouter));
        require(okM && okK && okD, "mock role wiring failed");

        airdropToken = new MockERC20("Random Airdrop", "DROP", 18);
    }

