    function test_SweepAirdrop_RevertsForNonKeeperNonManagement() public {
        airdropToken.mint(address(strategy), 100e18);

        vm.prank(stranger);
        vm.expectRevert();
        strategy.sweepAirdrop(address(airdropToken));
    }

    function test_SweepAirdrop_CallableByKeeper() public {
        airdropToken.mint(address(strategy), 100e18);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(dragonRouter), 100e18);
    }

    function test_SweepAirdrop_CallableByManagement() public {
        airdropToken.mint(address(strategy), 100e18);

        vm.prank(management);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(dragonRouter), 100e18);
    }

    // -- protected-token guards -------------------------------------------

    function test_SweepAirdrop_RevertsWhenSweepingAsset() public {
        asset.mint(address(strategy), 1_000e6);

        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep main asset"));
        strategy.sweepAirdrop(address(asset));
    }

    function test_SweepAirdrop_RevertsWhenSweepingVaultShares() public {
        // Give the strategy a vault-share balance directly (no need to route
        // through deposit/report flows we don't have visibility into).
        deal(address(vault), address(strategy), 500e6);

        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep vault shares"));
        strategy.sweepAirdrop(address(vault));
    }

    function test_SweepAirdrop_RevertsOnZeroBalance() public {
        // airdropToken balance of strategy is 0 by default.
        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: No balance to sweep"));
        strategy.sweepAirdrop(address(airdropToken));
    }

    function test_SweepAirdrop_AssetGuardCheckedBeforeBalanceCheck() public {
        // Even with zero asset balance held, the asset-guard should fire
        // first (checks happen before the balance read/require).
        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep main asset"));
        strategy.sweepAirdrop(address(asset));
    }

    // -- success path -------------------------------------------------------

    function test_SweepAirdrop_TransfersFullBalanceToDragonRouter() public {
        uint256 amount = 1234.5678e18;
        airdropToken.mint(address(strategy), amount);

        assertEq(airdropToken.balanceOf(address(strategy)), amount);
        assertEq(airdropToken.balanceOf(dragonRouter), 0);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(address(strategy)), 0);
        assertEq(airdropToken.balanceOf(dragonRouter), amount);
    }

    function test_SweepAirdrop_EmitsTokenSweptEvent() public {
        uint256 amount = 42e18;
        airdropToken.mint(address(strategy), amount);

        vm.expectEmit(true, true, false, true, address(strategy));
        emit TokenSwept(address(airdropToken), amount, dragonRouter);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));
    }

    function test_SweepAirdrop_DoesNotAffectAssetOrVaultBalances() public {
        uint256 assetAmount = 1_000e6;
        uint256 vaultShareAmount = 500e6;
        uint256 airdropAmount = 7e18;

        asset.mint(address(strategy), assetAmount);
        deal(address(vault), address(strategy), vaultShareAmount);
        airdropToken.mint(address(strategy), airdropAmount);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        // Sweeping the airdrop token must not touch principal asset or
        // vault-share balances held by the strategy.
        assertEq(asset.balanceOf(address(strategy)), assetAmount);
        assertEq(vault.balanceOf(address(strategy)), vaultShareAmount);
        assertEq(airdropToken.balanceOf(address(strategy)), 0);
    }

    function test_SweepAirdrop_CumulativeAirdropsSweptTogether() public {
        // Simulate several separate airdrop transfers landing on the
        // strategy before a sweep is triggered.
        airdropToken.mint(address(strategy), 10e18);
        airdropToken.mint(address(strategy), 5e18);
        airdropToken.mint(address(strategy), 1e18);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(dragonRouter), 16e18);
        assertEq(airdropToken.balanceOf(address(strategy)), 0);
    }

    function test_SweepAirdrop_CanSweepMultipleDistinctTokens() public {
        MockERC20 secondToken = new MockERC20("Other Airdrop", "DROP2", 18);

        airdropToken.mint(address(strategy), 3e18);
        secondToken.mint(address(strategy), 9e18);

        vm.startPrank(keeper);
        strategy.sweepAirdrop(address(airdropToken));
        strategy.sweepAirdrop(address(secondToken));
        vm.stopPrank();

        assertEq(airdropToken.balanceOf(dragonRouter), 3e18);
        assertEq(secondToken.balanceOf(dragonRouter), 9e18);
    }

    function test_SweepAirdrop_RevertsOnSecondSweepWithNothingLeft() public {
        airdropToken.mint(address(strategy), 1e18);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: No balance to sweep"));
        strategy.sweepAirdrop(address(airdropToken));
    }

    // -- fuzz ---------------------------------------------------------------

    function testFuzz_SweepAirdrop_SweepsExactBalance(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        airdropToken.mint(address(strategy), amount);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(address(strategy)), 0);
        assertEq(airdropToken.balanceOf(dragonRouter), amount);
    }

    function testFuzz_SweepAirdrop_RevertsForNonAuthorizedCaller(address caller) public {
        vm.assume(caller != keeper && caller != management);
        airdropToken.mint(address(strategy), 1e18);

        vm.prank(caller);
        vm.expectRevert();
        strategy.sweepAirdrop(address(airdropToken));
    }
}
