// Mocks
// ---------------------------------------------------------------------------

contract MockERC20 is ERC20 {
    uint8 private immutable _decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _decimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

contract MockERC4626Vault is ERC20, ERC4626 {
    constructor(
        IERC20 asset_,
        string memory name_,
        string memory symbol_
    ) ERC20(name_, symbol_) ERC4626(asset_) { }
}

library DragonMockStorage {
    // Namespaced slot so this mock's storage never collides with whatever
    // storage layout SparkStrategy / ERC4626Strategy actually use when this
    // contract's code runs via `delegatecall` from the strategy.
    bytes32 internal constant SLOT = keccak256("test.mock.dragon.tokenized.strategy.storage");

    struct Data {
        address asset;
        string name;
        string symbol;
        address management;
        address keeper;
        address emergencyAdmin;
        address dragonRouter;
        bool enableBurning;
        bool initialized;
    }

    function data() internal pure returns (Data storage d) {
        bytes32 slot = SLOT;
        assembly {
            d.slot := slot
        }
    }
}

