    function initialize(
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning
    ) external {
        DragonMockStorage.Data storage d = DragonMockStorage.data();
        d.asset = _asset;
        d.name = _name;
        d.symbol = _symbol;
        d.management = _management;
        d.keeper = _keeper;
        d.emergencyAdmin = _emergencyAdmin;
        d.dragonRouter = _donationAddress;
        d.enableBurning = _enableBurning;
        d.initialized = true;
    }

    function setManagement(address _management) external {
        DragonMockStorage.data().management = _management;
    }

    function setKeeper(address _keeper) external {
        DragonMockStorage.data().keeper = _keeper;
    }

    function setDragonRouter(address _dragonRouter) external {
        DragonMockStorage.data().dragonRouter = _dragonRouter;
    }

    function dragonRouter() external view returns (address) {
        return DragonMockStorage.data().dragonRouter;
    }

    function management() external view returns (address) {
        return DragonMockStorage.data().management;
    }

    function keeper() external view returns (address) {
        return DragonMockStorage.data().keeper;
    }

    function requireManagement(address _sender) external view {
        require(_sender == DragonMockStorage.data().management, "!management");
    }

    function requireKeeperOrManagement(address _sender) external view {
        DragonMockStorage.Data storage d = DragonMockStorage.data();
        require(_sender == d.keeper || _sender == d.management, "!keeper");
    }

    function requireEmergencyAuthorized(address _sender) external view {
        DragonMockStorage.Data storage d = DragonMockStorage.data();
        require(_sender == d.emergencyAdmin || _sender == d.management, "!emergency");
    }

    // Permissive fallback: any selector this mock doesn't explicitly know
    // about (e.g. profit-unlock accounting, fee config, ERC20 plumbing for
    // the strategy's own shares, ...) succeeds as a no-op instead of
    // reverting, so strategy deployment/operation doesn't unexpectedly fail
    // due to interface details this suite could not observe.
    fallback() external {
        // no-op
    }
}

