        strategy.sweepAirdrop(address(rewardToken));

        assertEq(rewardToken.balanceOf(address(strategy)), 0, "strategy balance should be zero");
        assertEq(rewardToken.balanceOf(dragonRouter), amount, "dragon router should receive swept tokens");
    }

    function test_sweepAirdrop_succeedsWhenCalledByManagement() public {
