        emit TokenSwept(address(rewardToken), amount, dragonRouter);

        vm.prank(management);
        strategy.sweepAirdrop(address(rewardToken));

        assertEq(rewardToken.balanceOf(address(strategy)), 0);
        assertEq(rewardToken.balanceOf(dragonRouter), amount);
