        // theoretically hold and that must be blocked from sweeping).
        asset.mint(address(this), 10e18);
        asset.approve(address(vault), 10e18);
        vault.deposit(10e18, address(strategy));

        vm.prank(keeper);
        vm.expectRevert(bytes("SparkStrategy: Cannot sweep vault shares"));
        strategy.sweepAirdrop(address(vault));
    }

