        uint256 airdropAmount = 10e18;
        airdropToken.mint(address(strategy), airdropAmount);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        // Underlying asset balance must be untouched by the sweep.
        assertEq(asset.balanceOf(address(strategy)), assetBalance);
    }

