        uint256 firstAmount = 100e18;
        uint256 secondAmount = 250e18;

        airdropToken.mint(address(strategy), firstAmount);
        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        airdropToken.mint(address(strategy), secondAmount);
        vm.prank(management);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(dragonRouter), firstAmount + secondAmount);
        assertEq(airdropToken.balanceOf(address(strategy)), 0);
    }

    function test_SweepAirdrop_HandlesMultipleDistinctTokensIndependently() public {
        MockERC20 secondAirdropToken = new MockERC20("Second Airdrop", "AIR2", 8);

        uint256 amount1 = 42e18;
