        assertEq(airdropToken.balanceOf(address(strategy)), 0);
        assertEq(secondAirdropToken.balanceOf(address(strategy)), 0);
    }

    function test_SweepAirdrop_DoesNotAffectPreexistingDragonRouterBalance() public {
        uint256 preexisting = 5e18;
        airdropToken.mint(dragonRouter, preexisting);

