        airdropToken.mint(address(strategy), sweepAmount);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(dragonRouter), preexisting + sweepAmount);
    }

    /*//////////////////////////////////////////////////////////////////
                                FUZZ TESTS
    //////////////////////////////////////////////////////////////////*/

    function testFuzz_SweepAirdrop_TransfersExactAmount(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        airdropToken.mint(address(strategy), amount);

        vm.prank(keeper);
        strategy.sweepAirdrop(address(airdropToken));

        assertEq(airdropToken.balanceOf(address(strategy)), 0);
        assertEq(airdropToken.balanceOf(dragonRouter), amount);
    }

    function testFuzz_SweepAirdrop_RevertWhen_CallerUnauthorized(address caller) public {
        vm.assume(caller != keeper && caller != management);

        airdropToken.mint(address(strategy), 1e18);

        vm.prank(caller);
        vm.expectRevert();
        strategy.sweepAirdrop(address(airdropToken));
    }

    function testFuzz_SweepAirdrop_RevertWhen_SweepingProtectedTokens(bool sweepAsset) public {
        address token = sweepAsset ? address(asset) : address(vault);
        bytes memory expectedError = sweepAsset
            ? bytes("SparkStrategy: Cannot sweep main asset")
            : bytes("SparkStrategy: Cannot sweep vault shares");

        vm.prank(keeper);
        vm.expectRevert(expectedError);
        strategy.sweepAirdrop(token);
    }
}
