            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        );
        strategyAddress = _deployStrategy(_getBytecode(p), _hashParams(p));
