// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity >=0.8.25;

import { Test } from "forge-std/Test.sol";
import { Create2 } from "@openzeppelin/contracts/utils/Create2.sol";
import { BaseStrategyFactory } from "src/factories/BaseStrategyFactory.sol";

/// @dev Minimal "strategy" contract used as CREATE2 deployment target in tests.
/// Its constructor args mirror the parameters accepted by computeStrategyAddress
/// so that changing any parameter changes the resulting bytecode/address.
contract MockStrategy {
    address public vault;
    address public asset;
    string public name;
    string public symbol;
    address public management;
    address public keeper;
    address public emergencyAdmin;
    address public donationAddress;
    bool public enableBurning;
    address public tokenizedStrategyAddress;

    constructor(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    ) {
        vault = _vault;
        asset = _asset;
        name = _name;
        symbol = _symbol;
        management = _management;
        keeper = _keeper;
        emergencyAdmin = _emergencyAdmin;
        donationAddress = _donationAddress;
        enableBurning = _enableBurning;
        tokenizedStrategyAddress = _tokenizedStrategyAddress;
    }
}

/// @dev Concrete harness exercising the abstract BaseStrategyFactory internals.
contract BaseStrategyFactoryHarness is BaseStrategyFactory {
    event StrategyDeploy(address indexed strategy, address indexed deployer, string name);

    struct Params {
        address vault;
        address asset;
        string name;
        string symbol;
        address management;
        address keeper;
        address emergencyAdmin;
        address donationAddress;
        bool enableBurning;
        address tokenizedStrategyAddress;
    }

    function _getBytecode(Params memory p) internal pure returns (bytes memory) {
        return abi.encodePacked(
            type(MockStrategy).creationCode,
            abi.encode(
                p.vault,
                p.asset,
                p.name,
                p.symbol,
                p.management,
                p.keeper,
                p.emergencyAdmin,
                p.donationAddress,
                p.enableBurning,
                p.tokenizedStrategyAddress
            )
        );
    }

    function _hashParams(Params memory p) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                p.vault,
                p.asset,
                p.name,
                p.symbol,
                p.management,
                p.keeper,
                p.emergencyAdmin,
                p.donationAddress,
                p.enableBurning,
                p.tokenizedStrategyAddress
            )
        );
    }

    function computeStrategyAddress(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress,
        address _deployer
    ) public view override returns (address) {
        Params memory p = Params(
            _vault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        );
        return _predictStrategyAddress(_hashParams(p), _deployer, _getBytecode(p));
    }

    function deployStrategy(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    ) external returns (address strategyAddress) {
        Params memory p = Params(
            _vault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        );
        strategyAddress = _deployStrategy(_getBytecode(p), _hashParams(p));
        _recordStrategy(_name, _donationAddress, strategyAddress);
        emit StrategyDeploy(strategyAddress, msg.sender, _name);
    }

    /// @dev Exposes the predicted address computed straight from bytecode, bypassing
    /// the public computeStrategyAddress wrapper, for cross-checking.
    function predictRaw(bytes32 parameterHash, address deployer, bytes memory bytecode) external view returns (address) {
        return _predictStrategyAddress(parameterHash, deployer, bytecode);
    }
}

contract BaseStrategyFactoryTest is Test {
    BaseStrategyFactoryHarness internal factory;

    address internal deployer = makeAddr("deployer");
    address internal otherDeployer = makeAddr("otherDeployer");
    address internal vault = makeAddr("vault");
    address internal asset = makeAddr("asset");
    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal donationAddress = makeAddr("donationAddress");
    address internal tokenizedStrategyAddress = makeAddr("tokenizedStrategyAddress");

    function setUp() public {
        factory = new BaseStrategyFactoryHarness();
    }

    // ---------------------------------------------------------------------
    // computeStrategyAddress
    // ---------------------------------------------------------------------

    function test_ComputeStrategyAddress_IsDeterministic() public view {
        address a1 = _computeDefault(deployer);
        address a2 = _computeDefault(deployer);
        assertEq(a1, a2, "same params should predict same address");
    }

    function test_ComputeStrategyAddress_DiffersByDeployer() public view {
        address a1 = _computeDefault(deployer);
        address a2 = _computeDefault(otherDeployer);
        assertTrue(a1 != a2, "different deployers must yield different addresses");
    }

    function test_ComputeStrategyAddress_DiffersByName() public view {
        address a1 = factory.computeStrategyAddress(
            vault, asset, "Strategy A", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress, deployer
        );
        address a2 = factory.computeStrategyAddress(
            vault, asset, "Strategy B", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress, deployer
        );
        assertTrue(a1 != a2, "different names must yield different addresses");
    }

    function test_ComputeStrategyAddress_DiffersByEnableBurning() public view {
        address a1 = factory.computeStrategyAddress(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress, deployer
        );
        address a2 = factory.computeStrategyAddress(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyAddress, deployer
        );
        assertTrue(a1 != a2, "different enableBurning flag must yield different addresses");
    }

    function test_ComputeStrategyAddress_HasNoCodeBeforeDeployment() public view {
        address predicted = _computeDefault(deployer);
        assertEq(predicted.code.length, 0, "predicted address should be empty before deployment");
    }

    function testFuzz_ComputeStrategyAddress_MatchesManualSaltDerivation(
        string memory name_,
        string memory symbol_,
        bool enableBurning_
    ) public view {
        BaseStrategyFactoryHarness.Params memory p = BaseStrategyFactoryHarness.Params(
            vault, asset, name_, symbol_, management, keeper, emergencyAdmin, donationAddress, enableBurning_, tokenizedStrategyAddress
        );

        bytes memory bytecode = abi.encodePacked(
            type(MockStrategy).creationCode,
            abi.encode(
                p.vault, p.asset, p.name, p.symbol, p.management, p.keeper, p.emergencyAdmin, p.donationAddress, p.enableBurning, p.tokenizedStrategyAddress
            )
        );
        bytes32 parameterHash = keccak256(
            abi.encode(
                p.vault, p.asset, p.name, p.symbol, p.management, p.keeper, p.emergencyAdmin, p.donationAddress, p.enableBurning, p.tokenizedStrategyAddress
            )
        );
        bytes32 finalSalt = keccak256(abi.encodePacked(parameterHash, deployer));
        address expected = Create2.computeAddress(finalSalt, keccak256(bytecode), address(factory));

        address actual = factory.computeStrategyAddress(
            p.vault, p.asset, p.name, p.symbol, p.management, p.keeper, p.emergencyAdmin, p.donationAddress, p.enableBurning, p.tokenizedStrategyAddress, deployer
        );

        assertEq(actual, expected, "computed address must match manual CREATE2 derivation");
    }

    // ---------------------------------------------------------------------
    // deployment
    // ---------------------------------------------------------------------

    function test_DeployStrategy_MatchesPredictedAddress() public {
        address predicted = _computeDefault(deployer);

        vm.prank(deployer);
        address deployed = factory.deployStrategy(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );

        assertEq(deployed, predicted, "deployed address should match prediction");
        assertGt(deployed.code.length, 0, "deployed address should contain code");
    }

    function test_DeployStrategy_EmitsEvent() public {
        address predicted = _computeDefault(deployer);

        vm.expectEmit(true, true, false, true, address(factory));
        emit BaseStrategyFactoryHarness.StrategyDeploy(predicted, deployer, "Strategy");

        vm.prank(deployer);
        factory.deployStrategy(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );
    }

    function test_DeployStrategy_RevertsOnExactDuplicate() public {
        vm.prank(deployer);
        factory.deployStrategy(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );

        address predicted = _computeDefault(deployer);

        vm.expectRevert(abi.encodeWithSelector(BaseStrategyFactory.StrategyAlreadyExists.selector, predicted));
        vm.prank(deployer);
        factory.deployStrategy(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );
    }

    function test_DeployStrategy_RevertsIfPredictedAddressAlreadyHasCode() public {
        // Simulate front-running / address squatting: put arbitrary code at the
        // predicted address before the factory attempts to deploy there.
        address predicted = _computeDefault(deployer);
        vm.etch(predicted, hex"6080");

        vm.expectRevert(abi.encodeWithSelector(BaseStrategyFactory.StrategyAlreadyExists.selector, predicted));
        vm.prank(deployer);
        factory.deployStrategy(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );
    }

    function test_DeployStrategy_SameParamsDifferentSenderSucceeds() public {
        vm.prank(deployer);
        address deployed1 = factory.deployStrategy(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );

        vm.prank(otherDeployer);
        address deployed2 = factory.deployStrategy(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );

        assertTrue(deployed1 != deployed2, "different senders should not collide even with identical params");
    }

    function test_DeployStrategy_DifferentParamsFromSameSenderSucceeds() public {
        vm.startPrank(deployer);
        address deployed1 = factory.deployStrategy(
            vault, asset, "Strategy A", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );
        address deployed2 = factory.deployStrategy(
            vault, asset, "Strategy B", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );
        vm.stopPrank();

        assertTrue(deployed1 != deployed2, "different params from same sender should produce different addresses");
    }

    // ---------------------------------------------------------------------
    // strategy bookkeeping
    // ---------------------------------------------------------------------

    function test_RecordStrategy_StoresExpectedInfo() public {
        uint256 ts = 1_700_000_000;
        vm.warp(ts);

        vm.prank(deployer);
        factory.deployStrategy(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );

        BaseStrategyFactory.StrategyInfo[] memory infos = factory.getStrategiesByDeployer(deployer);
        assertEq(infos.length, 1, "should have exactly one recorded strategy");
        assertEq(infos[0].deployerAddress, deployer);
        assertEq(infos[0].timestamp, ts);
        assertEq(infos[0].vaultTokenName, "Strategy");
        assertEq(infos[0].donationAddress, donationAddress);
    }

    function test_RecordStrategy_PublicMappingGetterMatches() public {
        vm.prank(deployer);
        factory.deployStrategy(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );

        (address deployerAddress, uint256 timestamp, string memory vaultTokenName, address donation) = factory.strategies(deployer, 0);
        assertEq(deployerAddress, deployer);
        assertEq(timestamp, block.timestamp);
        assertEq(vaultTokenName, "Strategy");
        assertEq(donation, donationAddress);
    }

    function test_GetStrategiesByDeployer_AccumulatesMultipleEntries() public {
        vm.startPrank(deployer);
        factory.deployStrategy(
            vault, asset, "Strategy A", "SYA", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );
        factory.deployStrategy(
            vault, asset, "Strategy B", "SYB", management, keeper, emergencyAdmin, donationAddress, true, tokenizedStrategyAddress
        );
        vm.stopPrank();

        BaseStrategyFactory.StrategyInfo[] memory infos = factory.getStrategiesByDeployer(deployer);
        assertEq(infos.length, 2, "should accumulate entries across deployments");
        assertEq(infos[0].vaultTokenName, "Strategy A");
        assertEq(infos[1].vaultTokenName, "Strategy B");
    }

    function test_GetStrategiesByDeployer_IsolatedPerDeployer() public {
        vm.prank(deployer);
        factory.deployStrategy(
            vault, asset, "Strategy A", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );

        vm.prank(otherDeployer);
        factory.deployStrategy(
            vault, asset, "Strategy A", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress
        );

        assertEq(factory.getStrategiesByDeployer(deployer).length, 1);
        assertEq(factory.getStrategiesByDeployer(otherDeployer).length, 1);
    }

    function test_GetStrategiesByDeployer_EmptyForUnknownDeployer() public view {
        BaseStrategyFactory.StrategyInfo[] memory infos = factory.getStrategiesByDeployer(makeAddr("nobody"));
        assertEq(infos.length, 0, "unknown deployer should have no recorded strategies");
    }

    // ---------------------------------------------------------------------
    // helpers
    // ---------------------------------------------------------------------

    function _computeDefault(address _deployer) internal view returns (address) {
        return factory.computeStrategyAddress(
            vault, asset, "Strategy", "SYM", management, keeper, emergencyAdmin, donationAddress, false, tokenizedStrategyAddress, _deployer
        );
    }
}

