    address internal vault = makeAddr("vault");
    address internal asset = makeAddr("asset");
    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal donationAddress = makeAddr("donationAddress");
    address internal tokenizedStrategyAddress = makeAddr("tokenizedStrategyAddress");
    address internal deployer = makeAddr("deployer");

    string internal name = "Test Strategy";
    string internal symbol = "tSTRAT";
    bool internal enableBurning = true;

    event StrategyDeploy(address indexed strategy, address indexed deployer, string vaultTokenName);

    function setUp() public {
        factory = new BaseStrategyFactoryHarness();
    }

    // ---------------------------------------------------------------------
    // computeStrategyAddress
    // ---------------------------------------------------------------------

    function test_ComputeStrategyAddress_IsDeterministicAcrossCalls() public view {
        address predicted1 = _compute(deployer);
        address predicted2 = _compute(deployer);
        assertEq(predicted1, predicted2, "prediction should be stable across repeated calls");
    }

    function test_ComputeStrategyAddress_MatchesActualDeployment() public {
        address predicted = _compute(deployer);

        vm.prank(deployer);
        address deployed = _deploy();

        assertEq(deployed, predicted, "deployed address must match predicted address");
        assertGt(deployed.code.length, 0, "deployed strategy should have code");
    }

    function test_ComputeStrategyAddress_DiffersByDeployer() public view {
        address other = makeAddr("otherDeployer");
        address predictedA = _compute(deployer);
        address predictedB = _compute(other);
        assertTrue(predictedA != predictedB, "different deployers must yield different addresses");
    }

    function test_ComputeStrategyAddress_DiffersByName() public view {
        address predictedA = factory.computeStrategyAddress(
            vault, asset, name, symbol, management, keeper, emergencyAdmin, donationAddress, enableBurning, tokenizedStrategyAddress, deployer
        );
        address predictedB = factory.computeStrategyAddress(
            vault,
            asset,
            "Different Name",
            symbol,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            enableBurning,
            tokenizedStrategyAddress,
            deployer
        );
        assertTrue(predictedA != predictedB, "different names must yield different addresses");
    }

    function test_ComputeStrategyAddress_DiffersByDonationAddress() public view {
        address predictedA = _compute(deployer);
        address altDonation = makeAddr("altDonation");
        address predictedB = factory.computeStrategyAddress(
            vault, asset, name, symbol, management, keeper, emergencyAdmin, altDonation, enableBurning, tokenizedStrategyAddress, deployer
        );
        assertTrue(predictedA != predictedB, "different donation addresses must yield different addresses");
    }

    function test_ComputeStrategyAddress_DiffersByEnableBurning() public view {
        address predictedA = _compute(deployer);
        address predictedB = factory.computeStrategyAddress(
            vault, asset, name, symbol, management, keeper, emergencyAdmin, donationAddress, !enableBurning, tokenizedStrategyAddress, deployer
        );
        assertTrue(predictedA != predictedB, "different enableBurning flag must yield different addresses");
    }

    function testFuzz_ComputeStrategyAddress_Deterministic(
        address _vault,
        address _asset,
        address _management,
        address _keeper,
        address _deployer
    ) public view {
        address predicted1 = factory.computeStrategyAddress(
            _vault, _asset, name, symbol, _management, _keeper, emergencyAdmin, donationAddress, enableBurning, tokenizedStrategyAddress, _deployer
        );
        address predicted2 = factory.computeStrategyAddress(
            _vault, _asset, name, symbol, _management, _keeper, emergencyAdmin, donationAddress, enableBurning, tokenizedStrategyAddress, _deployer
        );
        assertEq(predicted1, predicted2);
    }

    // ---------------------------------------------------------------------
    // Deployment behavior
    // ---------------------------------------------------------------------

    function test_Deploy_RevertsOnDuplicateDeployment() public {
        vm.prank(deployer);
        address firstDeployment = _deploy();
        assertGt(firstDeployment.code.length, 0);

        vm.prank(deployer);
        vm.expectRevert(
            abi.encodeWithSelector(BaseStrategyFactory.StrategyAlreadyExists.selector, firstDeployment)
        );
        _deploy();
    }

    function test_Deploy_SameParamsDifferentDeployer_DoesNotRevert() public {
        vm.prank(deployer);
        address deployedByFirst = _deploy();

        address otherDeployer = makeAddr("otherDeployer");
        vm.prank(otherDeployer);
        address deployedBySecond = _deploy();

        assertTrue(deployedByFirst != deployedBySecond, "different deployers should get different addresses");
        assertGt(deployedByFirst.code.length, 0);
        assertGt(deployedBySecond.code.length, 0);
    }

    function test_Deploy_DifferentParamsSameDeployer_ProducesDifferentAddresses() public {
        vm.startPrank(deployer);
        address deployed1 = _deploy();

        address deployed2 = factory.deployStrategy(
            vault,
            asset,
            "Another Strategy",
            symbol,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            enableBurning,
            tokenizedStrategyAddress
        );
        vm.stopPrank();

        assertTrue(deployed1 != deployed2, "different params should yield different addresses");
    }

    function test_Deploy_EmitsStrategyDeployEvent() public {
        address predicted = _compute(deployer);

        vm.expectEmit(true, true, false, true, address(factory));
        emit StrategyDeploy(predicted, deployer, name);

        vm.prank(deployer);
        _deploy();
    }

    function test_Deploy_DeployedContractHasExpectedConstructorArgs() public {
        vm.prank(deployer);
        address deployed = _deploy();

        MockStrategy strat = MockStrategy(deployed);
        assertEq(strat.vault(), vault);
        assertEq(strat.asset(), asset);
        assertEq(strat.name(), name);
        assertEq(strat.symbol(), symbol);
        assertEq(strat.management(), management);
        assertEq(strat.keeper(), keeper);
        assertEq(strat.emergencyAdmin(), emergencyAdmin);
        assertEq(strat.donationAddress(), donationAddress);
        assertEq(strat.enableBurning(), enableBurning);
        assertEq(strat.tokenizedStrategyAddress(), tokenizedStrategyAddress);
    }

    // ---------------------------------------------------------------------
    // Strategy bookkeeping
    // ---------------------------------------------------------------------

    function test_RecordStrategy_StoresCorrectInfo() public {
        uint256 ts = 1_800_000_000;
        vm.warp(ts);

        vm.prank(deployer);
        address deployed = _deploy();

        BaseStrategyFactory.StrategyInfo[] memory infos = factory.getStrategiesByDeployer(deployer);
        assertEq(infos.length, 1);
        assertEq(infos[0].deployerAddress, deployer);
        assertEq(infos[0].timestamp, ts);
        assertEq(infos[0].vaultTokenName, name);
        assertEq(infos[0].donationAddress, donationAddress);

        // sanity: deployment address itself is not part of StrategyInfo, but should exist
        assertGt(deployed.code.length, 0);
    }

    function test_GetStrategiesByDeployer_AccumulatesMultipleStrategies() public {
        vm.startPrank(deployer);
        _deploy();
        factory.deployStrategy(
            vault,
            asset,
            "Second Strategy",
            symbol,
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            enableBurning,
            tokenizedStrategyAddress
        );
        vm.stopPrank();

        BaseStrategyFactory.StrategyInfo[] memory infos = factory.getStrategiesByDeployer(deployer);
        assertEq(infos.length, 2);
        assertEq(infos[0].vaultTokenName, name);
        assertEq(infos[1].vaultTokenName, "Second Strategy");
    }

    function test_GetStrategiesByDeployer_IsolatedPerDeployer() public {
        address otherDeployer = makeAddr("otherDeployer");

        vm.prank(deployer);
        _deploy();

        BaseStrategyFactory.StrategyInfo[] memory infosOther = factory.getStrategiesByDeployer(otherDeployer);
        assertEq(infosOther.length, 0, "unrelated deployer should have no recorded strategies");

        BaseStrategyFactory.StrategyInfo[] memory infosDeployer = factory.getStrategiesByDeployer(deployer);
        assertEq(infosDeployer.length, 1);
    }

    function test_GetStrategiesByDeployer_EmptyForUnknownAddress() public view {
        BaseStrategyFactory.StrategyInfo[] memory infos = factory.getStrategiesByDeployer(makeAddr("unknown"));
        assertEq(infos.length, 0);
    }

    function test_PublicStrategiesMapping_ReturnsSameDataAsGetter() public {
        vm.prank(deployer);
        _deploy();

        (address deployerAddr, uint256 timestamp, string memory vaultTokenName, address donation) =
            factory.strategies(deployer, 0);

        BaseStrategyFactory.StrategyInfo[] memory infos = factory.getStrategiesByDeployer(deployer);

        assertEq(deployerAddr, infos[0].deployerAddress);
        assertEq(timestamp, infos[0].timestamp);
        assertEq(vaultTokenName, infos[0].vaultTokenName);
        assertEq(donation, infos[0].donationAddress);
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    function _compute(address _deployer) internal view returns (address) {
        return factory.computeStrategyAddress(
            vault, asset, name, symbol, management, keeper, emergencyAdmin, donationAddress, enableBurning, tokenizedStrategyAddress, _deployer
        );
    }

    function _deploy() internal returns (address) {
        return factory.deployStrategy(
            vault, asset, name, symbol, management, keeper, emergencyAdmin, donationAddress, enableBurning, tokenizedStrategyAddress
        );
    }
}

