// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity >=0.8.25;

import { Test } from "forge-std/Test.sol";
import { BaseStrategyFactory } from "src/factories/BaseStrategyFactory.sol";

/// @dev Minimal deployable "strategy" used as CREATE2 bytecode payload for tests.
contract DummyStrategy {
    address public vault;
    address public asset;
    string public strategyName;
    address public deployerParam;

    constructor(address _vault, address _asset, string memory _name, address _deployer) {
        vault = _vault;
        asset = _asset;
        strategyName = _name;
        deployerParam = _deployer;
    }
}

/// @dev Concrete harness exposing the internal machinery of BaseStrategyFactory for testing.
contract TestStrategyFactory is BaseStrategyFactory {
    event StrategyDeploy(address indexed strategy, address indexed deployer);

    function computeStrategyAddress(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress,
        address _deployer
    ) public view override returns (address) {
        bytes32 parameterHash = _hashParams(
            _vault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        );
        bytes memory bytecode = _buildBytecode(_vault, _asset, _name, _deployer);
        return _predictStrategyAddress(parameterHash, _deployer, bytecode);
    }

    function deployStrategy(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    ) external returns (address strategyAddress) {
        bytes32 parameterHash = _hashParams(
            _vault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        );
        bytes memory bytecode = _buildBytecode(_vault, _asset, _name, msg.sender);
        strategyAddress = _deployStrategy(bytecode, parameterHash);
        _recordStrategy(_name, _donationAddress, strategyAddress);
        emit StrategyDeploy(strategyAddress, msg.sender);
    }

    function exposedPredict(
        bytes32 _parameterHash,
        address _deployer,
        bytes memory _bytecode
    ) external view returns (address) {
        return _predictStrategyAddress(_parameterHash, _deployer, _bytecode);
    }

    function exposedDeploy(bytes memory _bytecode, bytes32 _parameterHash) external returns (address) {
        return _deployStrategy(_bytecode, _parameterHash);
    }

    function exposedRecord(string memory _name, address _donationAddress, address _strategyAddress) external {
        _recordStrategy(_name, _donationAddress, _strategyAddress);
    }

    function _hashParams(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                _vault,
                _asset,
                _name,
                _symbol,
                _management,
                _keeper,
                _emergencyAdmin,
                _donationAddress,
                _enableBurning,
                _tokenizedStrategyAddress
            )
        );
    }

    function _buildBytecode(
        address _vault,
        address _asset,
        string memory _name,
        address _deployer
    ) internal pure returns (bytes memory) {
        return abi.encodePacked(type(DummyStrategy).creationCode, abi.encode(_vault, _asset, _name, _deployer));
    }
}

contract BaseStrategyFactoryTest is Test {
