// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity >=0.8.25;

import { Test } from "forge-std/Test.sol";
import { BaseStrategyFactory } from "src/factories/BaseStrategyFactory.sol";

/// @dev Minimal deployable "strategy" used as CREATE2 bytecode payload for tests.
contract DummyStrategy {
    address public vault;
    address public asset;
    string public strategyName;
    address public deployerParam;

    constructor(address _vault, address _asset, string memory _name, address _deployer) {
        vault = _vault;
        asset = _asset;
        strategyName = _name;
        deployerParam = _deployer;
    }
}

/// @dev Concrete harness exposing the internal machinery of BaseStrategyFactory for testing.
contract TestStrategyFactory is BaseStrategyFactory {
    event StrategyDeploy(address indexed strategy, address indexed deployer);

    function computeStrategyAddress(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress,
        address _deployer
    ) public view override returns (address) {
        bytes32 parameterHash = _hashParams(
            _vault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        );
        bytes memory bytecode = _buildBytecode(_vault, _asset, _name, _deployer);
        return _predictStrategyAddress(parameterHash, _deployer, bytecode);
    }

    function deployStrategy(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    ) external returns (address strategyAddress) {
        bytes32 parameterHash = _hashParams(
            _vault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        );
        bytes memory bytecode = _buildBytecode(_vault, _asset, _name, msg.sender);
        strategyAddress = _deployStrategy(bytecode, parameterHash);
        _recordStrategy(_name, _donationAddress, strategyAddress);
        emit StrategyDeploy(strategyAddress, msg.sender);
    }

    function exposedPredict(
        bytes32 _parameterHash,
        address _deployer,
        bytes memory _bytecode
    ) external view returns (address) {
        return _predictStrategyAddress(_parameterHash, _deployer, _bytecode);
    }

    function exposedDeploy(bytes memory _bytecode, bytes32 _parameterHash) external returns (address) {
        return _deployStrategy(_bytecode, _parameterHash);
    }

    function exposedRecord(string memory _name, address _donationAddress, address _strategyAddress) external {
        _recordStrategy(_name, _donationAddress, _strategyAddress);
    }

    function _hashParams(
        address _vault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    ) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                _vault,
                _asset,
                _name,
                _symbol,
                _management,
                _keeper,
                _emergencyAdmin,
                _donationAddress,
                _enableBurning,
                _tokenizedStrategyAddress
            )
        );
    }

    function _buildBytecode(
        address _vault,
        address _asset,
        string memory _name,
        address _deployer
    ) internal pure returns (bytes memory) {
        return abi.encodePacked(type(DummyStrategy).creationCode, abi.encode(_vault, _asset, _name, _deployer));
    }
}

contract BaseStrategyFactoryTest is Test {
    TestStrategyFactory internal factory;

    address internal deployerA = makeAddr("deployerA");
    address internal deployerB = makeAddr("deployerB");
    address internal vault = makeAddr("vault");
    address internal asset = makeAddr("asset");
    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal donationAddress = makeAddr("donationAddress");
    address internal tokenizedStrategyAddress = makeAddr("tokenizedStrategyAddress");

    function setUp() public {
        factory = new TestStrategyFactory();
    }

    // ---------------------------------------------------------------------
    // computeStrategyAddress / determinism
    // ---------------------------------------------------------------------

    function test_computeStrategyAddress_matchesActualDeployment() public {
        address predicted = factory.computeStrategyAddress(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress,
            deployerA
        );

        vm.prank(deployerA);
        address deployed = factory.deployStrategy(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress
        );

        assertEq(deployed, predicted, "predicted address must match actual deployment address");
        assertGt(predicted.code.length, 0, "code must exist at deployed address");
    }

    function test_computeStrategyAddress_isPureViewNoStateChange() public {
        address predicted1 = factory.computeStrategyAddress(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress,
            deployerA
        );
        address predicted2 = factory.computeStrategyAddress(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress,
            deployerA
        );

        assertEq(predicted1, predicted2, "repeated calls must be idempotent");
        assertEq(predicted1.code.length, 0, "no code should exist before deployment");
        assertEq(factory.getStrategiesByDeployer(deployerA).length, 0, "no strategies should be recorded");
    }

    function test_computeStrategyAddress_differentDeployerYieldsDifferentAddress() public view {
        address predictedA = factory.computeStrategyAddress(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress,
            deployerA
        );
        address predictedB = factory.computeStrategyAddress(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress,
            deployerB
        );

        assertTrue(predictedA != predictedB, "different deployers must yield different addresses");
    }

    function test_computeStrategyAddress_differentParamsYieldDifferentAddress() public view {
        address predicted1 = factory.computeStrategyAddress(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress,
            deployerA
        );
        address predicted2 = factory.computeStrategyAddress(
            vault,
            asset,
            "Strategy B",
            "sB",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress,
            deployerA
        );

        assertTrue(predicted1 != predicted2, "different params must yield different addresses");
    }

    function test_computeStrategyAddress_enableBurningFlagAffectsAddress() public view {
        address predictedFalse = factory.computeStrategyAddress(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress,
            deployerA
        );
        address predictedTrue = factory.computeStrategyAddress(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyAddress,
            deployerA
        );

        assertTrue(predictedFalse != predictedTrue, "enableBurning flag must affect the computed address");
    }

    // ---------------------------------------------------------------------
    // _deployStrategy / duplicate prevention
    // ---------------------------------------------------------------------

    function test_deployStrategy_revertsOnDuplicateDeployment() public {
        vm.startPrank(deployerA);
        address deployed = factory.deployStrategy(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress
        );

        vm.expectRevert(abi.encodeWithSelector(BaseStrategyFactory.StrategyAlreadyExists.selector, deployed));
        factory.deployStrategy(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress
        );
        vm.stopPrank();
    }

    function test_deployStrategy_sameParamsDifferentDeployerSucceeds() public {
        vm.prank(deployerA);
        address deployedA = factory.deployStrategy(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress
        );

        vm.prank(deployerB);
        address deployedB = factory.deployStrategy(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress
        );

        assertTrue(deployedA != deployedB, "same params from different deployers must not collide");
        assertGt(deployedA.code.length, 0);
        assertGt(deployedB.code.length, 0);
    }

    function test_deployStrategy_sameDeployerDifferentParamsSucceeds() public {
        vm.startPrank(deployerA);
        address deployed1 = factory.deployStrategy(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress
        );
        address deployed2 = factory.deployStrategy(
            vault,
            asset,
            "Strategy B",
            "sB",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress
        );
        vm.stopPrank();

        assertTrue(deployed1 != deployed2, "different params from same deployer must not collide");
    }

    function test_deployStrategy_deployedBytecodeMatchesConstructorArgs() public {
        vm.prank(deployerA);
        address deployed = factory.deployStrategy(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress
        );

        DummyStrategy strategy = DummyStrategy(deployed);
        assertEq(strategy.vault(), vault);
        assertEq(strategy.asset(), asset);
        assertEq(strategy.strategyName(), "Strategy A");
        assertEq(strategy.deployerParam(), deployerA);
    }

    function test_exposedDeploy_revertsOnDuplicateWithRawBytecode() public {
        bytes memory bytecode = abi.encodePacked(
            type(DummyStrategy).creationCode,
            abi.encode(vault, asset, "raw", address(this))
        );
        bytes32 parameterHash = keccak256("raw-hash");

        address deployed = factory.exposedDeploy(bytecode, parameterHash);

        vm.expectRevert(abi.encodeWithSelector(BaseStrategyFactory.StrategyAlreadyExists.selector, deployed));
        factory.exposedDeploy(bytecode, parameterHash);
    }

    function test_exposedPredict_matchesExposedDeploy() public {
        bytes memory bytecode = abi.encodePacked(
            type(DummyStrategy).creationCode,
            abi.encode(vault, asset, "raw2", address(this))
        );
        bytes32 parameterHash = keccak256("raw-hash-2");

        address predicted = factory.exposedPredict(parameterHash, address(this), bytecode);
        address deployed = factory.exposedDeploy(bytecode, parameterHash);

        assertEq(predicted, deployed);
    }

    // ---------------------------------------------------------------------
    // _recordStrategy / getStrategiesByDeployer
    // ---------------------------------------------------------------------

    function test_getStrategiesByDeployer_emptyForUnknownDeployer() public view {
        BaseStrategyFactory.StrategyInfo[] memory infos = factory.getStrategiesByDeployer(deployerA);
        assertEq(infos.length, 0);
    }

    function test_recordStrategy_storesCorrectInfo() public {
        uint256 ts = 1_800_000_000;
        vm.warp(ts);

        vm.prank(deployerA);
        address deployed = factory.deployStrategy(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
