        );

        BaseStrategyFactory.StrategyInfo[] memory infos = factory.getStrategiesByDeployer(deployerA);
        assertEq(infos.length, 1);
        assertEq(infos[0].deployerAddress, deployerA);
        assertEq(infos[0].timestamp, ts);
        assertEq(infos[0].vaultTokenName, "Strategy A");
        assertEq(infos[0].donationAddress, donationAddress);

        // sanity: also verify via the public mapping getter directly
        (address deployerAddress_, uint256 timestamp_, string memory vaultTokenName_, address donationAddress_) =
            factory.strategies(deployerA, 0);
        assertEq(deployerAddress_, deployerA);
        assertEq(timestamp_, ts);
        assertEq(vaultTokenName_, "Strategy A");
        assertEq(donationAddress_, donationAddress);
        assertEq(deployed.code.length > 0, true);
    }

    function test_recordStrategy_appendsMultipleStrategiesForSameDeployer() public {
        vm.startPrank(deployerA);
        factory.deployStrategy(
            vault,
            asset,
            "Strategy A",
            "sA",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            false,
            tokenizedStrategyAddress
        );
        factory.deployStrategy(
            vault,
