/// returns for a given strategy instance. Any other, unrecognized call
/// (e.g. an `initialize` call made from the strategy's constructor) is accepted
/// as a harmless no-op so deployment never reverts on an ABI we don't model.
contract MockTokenizedStrategy {
    bytes32 internal constant STORAGE_SLOT = keccak256("mock.tokenized.strategy.storage");

    struct StrategyData {
        uint256 totalAssets;
    }

    function _data() internal pure returns (StrategyData storage d) {
        bytes32 slot = STORAGE_SLOT;
        assembly {
            d.slot := slot
        }
    }

    function totalAssets() external view returns (uint256) {
        return _data().totalAssets;
    }

    function setTotalAssets(uint256 _amount) external {
        _data().totalAssets = _amount;
    }

    fallback() external payable {}

    receive() external payable {}
}

