        vm.expectRevert(bytes("healthCheck"));
        harness.exposed_executeHealthCheck(newTotalAssets);
    }

    function test_executeHealthCheck_defaultProfitLimitAllowsDoubling() public {
        // Default profit limit ratio is MAX_BPS (100%).
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        harness.exposed_executeHealthCheck(currentTotalAssets * 2);
    }

    function test_executeHealthCheck_defaultProfitLimitRevertsAboveDoubling() public {
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        vm.expectRevert(bytes("healthCheck"));
        harness.exposed_executeHealthCheck(currentTotalAssets * 2 + 1);
    }

    /*//////////////////////////////////////////////////////////
                    _executeHealthCheck: loss
    //////////////////////////////////////////////////////////*/

    function test_executeHealthCheck_lossWithinLimit_doesNotRevert() public {
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        vm.prank(management);
        harness.setLossLimitRatio(1_000); // 10%

        // 5% loss, within the 10% limit.
        uint256 newTotalAssets = currentTotalAssets - (currentTotalAssets * 500) / MAX_BPS;
        harness.exposed_executeHealthCheck(newTotalAssets);
    }

    function test_executeHealthCheck_lossAtExactLimit_doesNotRevert() public {
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        vm.prank(management);
        harness.setLossLimitRatio(1_000); // 10%

        uint256 newTotalAssets = currentTotalAssets - (currentTotalAssets * 1_000) / MAX_BPS;
        harness.exposed_executeHealthCheck(newTotalAssets);
    }

    function test_executeHealthCheck_lossAboveLimit_reverts() public {
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        vm.prank(management);
        harness.setLossLimitRatio(500); // 5%

        // 20% loss, above the 5% limit.
        uint256 newTotalAssets = currentTotalAssets - (currentTotalAssets * 2_000) / MAX_BPS;

        vm.expectRevert(bytes("healthCheck"));
        harness.exposed_executeHealthCheck(newTotalAssets);
    }

    function test_executeHealthCheck_defaultLossLimitRevertsOnAnyLoss() public {
        // Default loss limit ratio is 0.
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        vm.expectRevert(bytes("healthCheck"));
        harness.exposed_executeHealthCheck(currentTotalAssets - 1);
    }

    function test_executeHealthCheck_noChangeInAssets_doesNotRevert() public {
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        // Default loss limit is 0 and profit limit is 100%; exact equality
        // triggers neither branch of the check.
        harness.exposed_executeHealthCheck(currentTotalAssets);
    }

    /*//////////////////////////////////////////////////////////
