    //////////////////////////////////////////////////////////*/

    function test_executeHealthCheck_skippedWhenDisabled_andResetsFlag() public {
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        vm.prank(management);
        harness.setDoHealthCheck(false);
        assertFalse(harness.doHealthCheck());

        // Would normally revert (huge loss, default loss limit is 0) but the
        // check is skipped this one time.
        harness.exposed_executeHealthCheck(0);

        // Flag is automatically turned back on after being consumed once.
        assertTrue(harness.doHealthCheck());
    }

    function test_executeHealthCheck_reenabledAfterSkip_revertsOnNextCall() public {
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        vm.prank(management);
        harness.setDoHealthCheck(false);

        // First call is skipped and re-arms the flag.
        harness.exposed_executeHealthCheck(0);
        assertTrue(harness.doHealthCheck());

        // Second call is enforced again and should revert on the same bad loss.
        vm.expectRevert(bytes("healthCheck"));
        harness.exposed_executeHealthCheck(0);
    }

    /*//////////////////////////////////////////////////////////
                        harvestAndReport (onlySelf)
    //////////////////////////////////////////////////////////*/

    function test_harvestAndReport_revertsWhenNotCalledBySelf() public {
        vm.expectRevert();
        harness.harvestAndReport();
    }

    function test_harvestAndReport_revertsWhenCalledByStranger() public {
        vm.prank(stranger);
        vm.expectRevert();
        harness.harvestAndReport();
    }

    function test_harvestAndReport_succeedsWhenWithinLimitsAndCalledBySelf() public {
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        vm.prank(management);
        harness.setProfitLimitRatio(1_000); // 10%

        uint256 reportedAssets = currentTotalAssets + (currentTotalAssets * 500) / MAX_BPS; // 5% profit
        harness.setNextHarvestReport(reportedAssets);

        vm.prank(address(harness));
        uint256 result = harness.harvestAndReport();

        assertEq(result, reportedAssets);
    }

    function test_harvestAndReport_revertsWhenOutsideLimitsEvenIfCalledBySelf() public {
        uint256 currentTotalAssets = 1_000e18;
        _mockTotalAssets(currentTotalAssets);

        vm.prank(management);
        harness.setProfitLimitRatio(1_000); // 10%

        uint256 reportedAssets = currentTotalAssets + (currentTotalAssets * 2_000) / MAX_BPS; // 20% profit
        harness.setNextHarvestReport(reportedAssets);

        vm.prank(address(harness));
        vm.expectRevert(bytes("healthCheck"));
        harness.harvestAndReport();
    }

    /*//////////////////////////////////////////////////////////
                            helpers
    //////////////////////////////////////////////////////////*/

    function _mockTotalAssets(uint256 _value) internal {
        vm.mockCall(address(harness), abi.encodeWithSignature("totalAssets()"), abi.encode(_value));
    }
}

