/// @dev Minimal ERC20 mock used only to satisfy the `_asset` parameter required
///      by the BaseStrategy constructor. None of the actual transfer logic is
///      exercised by these tests since `_deployFunds`/`_freeFunds` are no-ops.
contract MockERC20 {
    string public name = "Mock Token";
    string public symbol = "MOCK";
    uint8 public constant decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address _to, uint256 _amount) external {
        totalSupply += _amount;
        balanceOf[_to] += _amount;
    }

    function approve(address _spender, uint256 _amount) external returns (bool) {
        allowance[msg.sender][_spender] = _amount;
        return true;
    }

    function transfer(address _to, uint256 _amount) external returns (bool) {
        balanceOf[msg.sender] -= _amount;
        balanceOf[_to] += _amount;
        return true;
    }

    function transferFrom(address _from, address _to, uint256 _amount) external returns (bool) {
        allowance[_from][msg.sender] -= _amount;
        balanceOf[_from] -= _amount;
        balanceOf[_to] += _amount;
        return true;
    }
}

/// @dev Stand-in for the shared TokenizedStrategy logic contract. It only needs
///      to have code deployed at its address so that `_tokenizedStrategyAddress`
///      passed into the BaseStrategy constructor is a valid contract reference.
///      No calls in these tests are actually routed through its logic; instead
///      calls the strategy makes back to itself (e.g. `TokenizedStrategy.totalAssets()`
///      / `TokenizedStrategy.management()`) are intercepted with `vm.mockCall`.
contract DummyTokenizedStrategyImplementation {
    fallback() external payable { }
    receive() external payable { }
}

