        nextHarvestReport = _value;
    }

    function _deployFunds(uint256) internal override { }

    function _freeFunds(uint256) internal override { }

    function _harvestAndReport() internal override returns (uint256) {
        return nextHarvestReport;
    }

    /// @dev Directly exercises `_executeHealthCheck` without needing to satisfy
    ///      the `onlySelf` modifier on the external `harvestAndReport()` entrypoint.
    function exposed_executeHealthCheck(uint256 _newTotalAssets) external {
        _executeHealthCheck(_newTotalAssets);
    }
}

