/*//////////////////////////////////////////////////////////////
                            MOCK SAFE
//////////////////////////////////////////////////////////////*/

/// @notice Mock Gnosis Safe module target. Records every call made through
///         `execTransactionFromModule` and, unless `forceFail` is set, actually
///         forwards the call to the target so downstream state changes (and
///         reverts) can be observed/asserted on in tests.
contract MockSafe is IGnosisSafe {
    struct Call {
        address to;
        uint256 value;
        bytes data;
        Enum.Operation operation;
    }

    Call[] public calls;
    bool public forceFail;

    function setForceFail(bool _forceFail) external {
        forceFail = _forceFail;
    }

    function callCount() external view returns (uint256) {
        return calls.length;
    }

    function execTransactionFromModule(
        address to,
        uint256 value,
        bytes memory data,
        Enum.Operation operation
    ) external override returns (bool success) {
        calls.push(Call({ to: to, value: value, data: data, operation: operation }));

        if (forceFail) {
            return false;
        }

        (success, ) = to.call{ value: value }(data);
    }
}

/*//////////////////////////////////////////////////////////////
                          MOCK STRATEGIES
//////////////////////////////////////////////////////////////*/

/// @notice Mock strategy implementing the health-check surface plus report().
contract MockStrategy {
    bool public doHealthCheckReturn;
    bool public doHealthCheckShouldRevert;
    bool public reportShouldRevert;
    uint256 public reportCallCount;
    uint256 public setDoHealthCheckCallCount;

    constructor(bool _doHealthCheckReturn) {
        doHealthCheckReturn = _doHealthCheckReturn;
    }

    function doHealthCheck() external view returns (bool) {
        if (doHealthCheckShouldRevert) {
            revert("doHealthCheck not implemented");
        }
        return doHealthCheckReturn;
    }

    function setDoHealthCheck(bool _enabled) external {
        setDoHealthCheckCallCount++;
        doHealthCheckReturn = _enabled;
    }

    function report() external returns (uint256 profit, uint256 loss) {
        if (reportShouldRevert) {
            revert("report failed");
        }
        reportCallCount++;
        return (0, 0);
    }

    function setDoHealthCheckShouldRevert(bool _shouldRevert) external {
        doHealthCheckShouldRevert = _shouldRevert;
    }

    function setReportShouldRevert(bool _shouldRevert) external {
        reportShouldRevert = _shouldRevert;
    }
}

/// @notice Mock strategy that does NOT implement doHealthCheck() at all, to
///         exercise the try/catch fallback path in callStrategyReport.
contract MockStrategyNoHealthCheck {
