// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.23;

import { Test } from "forge-std/Test.sol";
import { Enum } from "@gnosis.pm/safe-contracts/contracts/common/Enum.sol";
import { KeeperBotGuard, IGnosisSafe } from "src/guards/KeeperBotGuard.sol";

/*//////////////////////////////////////////////////////////////
                          MOCK CONTRACTS
//////////////////////////////////////////////////////////////*/

/// @notice Mimics a Gnosis Safe with a module enabled: forwards the call via a raw
///         `call`, exactly like the real Safe's execTransactionFromModule would.
contract MockSafe is IGnosisSafe {
    bool public forceFail;

    function setForceFail(bool _forceFail) external {
        forceFail = _forceFail;
    }

    function execTransactionFromModule(
        address to,
        uint256 value,
        bytes memory data,
        Enum.Operation /* operation */
    ) external returns (bool success) {
        if (forceFail) {
            return false;
        }
        (success, ) = to.call{ value: value }(data);
    }

    receive() external payable {}
}

/// @notice Mock strategy exposing doHealthCheck/setDoHealthCheck/report with the same
///         selectors the real IBaseHealthCheck strategies use. Deliberately does NOT
///         inherit any interface so tests stay decoupled from that file's exact shape.
contract MockStrategy {
    bool public healthCheckEnabled;
    uint256 public reportCallCount;
    uint256 public setDoHealthCheckCallCount;
    bool public reportShouldRevert;

    constructor(bool _healthCheckEnabled) {
        healthCheckEnabled = _healthCheckEnabled;
    }

    function doHealthCheck() external view returns (bool) {
        return healthCheckEnabled;
    }

    function setDoHealthCheck(bool _enabled) external {
        setDoHealthCheckCallCount++;
        healthCheckEnabled = _enabled;
    }

    function setReportShouldRevert(bool _shouldRevert) external {
        reportShouldRevert = _shouldRevert;
    }

    function report() external returns (uint256, uint256) {
        if (reportShouldRevert) {
            revert("report reverted");
        }
        reportCallCount++;
        return (0, 0);
    }
}

/// @notice Strategy that does not implement doHealthCheck/setDoHealthCheck at all,
///         used to exercise the try/catch fallback path in callStrategyReport.
contract MockStrategyNoHealthCheck {
    uint256 public reportCallCount;

    function report() external returns (uint256, uint256) {
        reportCallCount++;
        return (0, 0);
    }
}

contract KeeperBotGuardTest is Test {
    KeeperBotGuard internal guard;
    MockSafe internal safe;

    address internal owner = makeAddr("owner");
    address internal bot = makeAddr("bot");
    address internal bot2 = makeAddr("bot2");
    address internal other = makeAddr("other");

    event BotAuthorized(address indexed bot, bool authorized);
    event StrategyReportCalled(address indexed strategy, address indexed bot);
    event SafeSet(address indexed safe);

    function setUp() public {
        safe = new MockSafe();
        guard = new KeeperBotGuard(owner, address(safe));
    }

    /*//////////////////////////////////////////////////////////////
                             CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    function test_Constructor_SetsOwnerAndSafe() public view {
        assertEq(guard.owner(), owner);
        assertEq(address(guard.safe()), address(safe));
    }

    function test_Constructor_RevertsIfSafeIsZero() public {
        vm.expectRevert(KeeperBotGuard.KeeperBotGuard__InvalidSafe.selector);
        new KeeperBotGuard(owner, address(0));
    }

    function test_Constructor_EmitsSafeSetEvent() public {
        vm.expectEmit(true, false, false, true);
        emit SafeSet(address(safe));
        new KeeperBotGuard(owner, address(safe));
    }

    function test_Constructor_RevertsIfOwnerIsZero() public {
        // OZ Ownable reverts with OwnableInvalidOwner(address(0))
        vm.expectRevert(
            abi.encodeWithSignature("OwnableInvalidOwner(address)", address(0))
        );
        new KeeperBotGuard(address(0), address(safe));
    }

    /*//////////////////////////////////////////////////////////////
                       setBotAuthorization
    //////////////////////////////////////////////////////////////*/

    function test_SetBotAuthorization_OwnerCanAuthorize() public {
        assertFalse(guard.isBotAuthorized(bot));

        vm.expectEmit(true, false, false, true);
        emit BotAuthorized(bot, true);

        vm.prank(owner);
        guard.setBotAuthorization(bot, true);

        assertTrue(guard.isBotAuthorized(bot));
        assertTrue(guard.authorizedBots(bot));
    }

    function test_SetBotAuthorization_OwnerCanDeauthorize() public {
        vm.prank(owner);
        guard.setBotAuthorization(bot, true);
        assertTrue(guard.isBotAuthorized(bot));

        vm.expectEmit(true, false, false, true);
        emit BotAuthorized(bot, false);

        vm.prank(owner);
        guard.setBotAuthorization(bot, false);

        assertFalse(guard.isBotAuthorized(bot));
    }

    function test_SetBotAuthorization_RevertsForNonOwner() public {
        vm.expectRevert(
            abi.encodeWithSignature("OwnableUnauthorizedAccount(address)", other)
        );
        vm.prank(other);
        guard.setBotAuthorization(bot, true);
    }

    /*//////////////////////////////////////////////////////////////
                    setBotAuthorizationBatch
    //////////////////////////////////////////////////////////////*/

    function test_SetBotAuthorizationBatch_UpdatesAllBots() public {
        address[] memory bots = new address[](2);
        bots[0] = bot;
        bots[1] = bot2;

        bool[] memory authorized = new bool[](2);
        authorized[0] = true;
        authorized[1] = false;

        vm.expectEmit(true, false, false, true);
        emit BotAuthorized(bot, true);
        vm.expectEmit(true, false, false, true);
        emit BotAuthorized(bot2, false);

        vm.prank(owner);
        guard.setBotAuthorizationBatch(bots, authorized);

        assertTrue(guard.isBotAuthorized(bot));
        assertFalse(guard.isBotAuthorized(bot2));
    }

    function test_SetBotAuthorizationBatch_RevertsOnLengthMismatch() public {
        address[] memory bots = new address[](2);
        bots[0] = bot;
        bots[1] = bot2;

        bool[] memory authorized = new bool[](1);
        authorized[0] = true;

        vm.expectRevert(bytes("Array length mismatch"));
        vm.prank(owner);
        guard.setBotAuthorizationBatch(bots, authorized);
    }

    function test_SetBotAuthorizationBatch_RevertsForNonOwner() public {
        address[] memory bots = new address[](1);
        bots[0] = bot;
        bool[] memory authorized = new bool[](1);
        authorized[0] = true;

        vm.expectRevert(
            abi.encodeWithSignature("OwnableUnauthorizedAccount(address)", other)
        );
        vm.prank(other);
        guard.setBotAuthorizationBatch(bots, authorized);
    }

    /*//////////////////////////////////////////////////////////////
                       callStrategyReport
    //////////////////////////////////////////////////////////////*/

    function _authorizeBot() internal {
        vm.prank(owner);
        guard.setBotAuthorization(bot, true);
    }

    function test_CallStrategyReport_RevertsForUnauthorizedBot() public {
        MockStrategy strategy = new MockStrategy(false);

        vm.expectRevert(KeeperBotGuard.KeeperBotGuard__NotAuthorizedBot.selector);
        vm.prank(other);
        guard.callStrategyReport(address(strategy));
    }

    function test_CallStrategyReport_RevertsForZeroStrategy() public {
        _authorizeBot();

        vm.expectRevert(KeeperBotGuard.KeeperBotGuard__InvalidStrategy.selector);
        vm.prank(bot);
        guard.callStrategyReport(address(0));
    }

    function test_CallStrategyReport_HealthCheckInactive_CallsReportOnly() public {
        _authorizeBot();
        MockStrategy strategy = new MockStrategy(false);

        vm.expectEmit(true, true, false, true);
        emit StrategyReportCalled(address(strategy), bot);

        vm.prank(bot);
        guard.callStrategyReport(address(strategy));

        assertEq(strategy.reportCallCount(), 1);
        assertEq(strategy.setDoHealthCheckCallCount(), 0);
        assertFalse(strategy.healthCheckEnabled());
    }

    function test_CallStrategyReport_HealthCheckActive_DisablesThenReports() public {
        _authorizeBot();
        MockStrategy strategy = new MockStrategy(true);

        vm.expectEmit(true, true, false, true);
        emit StrategyReportCalled(address(strategy), bot);

        vm.prank(bot);
        guard.callStrategyReport(address(strategy));

        assertEq(strategy.reportCallCount(), 1);
        assertEq(strategy.setDoHealthCheckCallCount(), 1);
        assertFalse(strategy.healthCheckEnabled());
    }

    function test_CallStrategyReport_NoHealthCheckImplementation_StillReports() public {
        _authorizeBot();
        MockStrategyNoHealthCheck strategy = new MockStrategyNoHealthCheck();

        vm.expectEmit(true, true, false, true);
        emit StrategyReportCalled(address(strategy), bot);

        vm.prank(bot);
        guard.callStrategyReport(address(strategy));

        assertEq(strategy.reportCallCount(), 1);
    }

    function test_CallStrategyReport_RevertsIfReportFails() public {
        _authorizeBot();
        MockStrategy strategy = new MockStrategy(false);
        strategy.setReportShouldRevert(true);

        vm.expectRevert(KeeperBotGuard.KeeperBotGuard__ModuleTransactionFailed.selector);
        vm.prank(bot);
        guard.callStrategyReport(address(strategy));
    }

    function test_CallStrategyReport_RevertsIfSafeExecutionFails() public {
        _authorizeBot();
        MockStrategy strategy = new MockStrategy(false);
        safe.setForceFail(true);

        vm.expectRevert(KeeperBotGuard.KeeperBotGuard__ModuleTransactionFailed.selector);
        vm.prank(bot);
        guard.callStrategyReport(address(strategy));
    }

    function test_CallStrategyReport_RevertsAfterBotDeauthorized() public {
        _authorizeBot();
        MockStrategy strategy = new MockStrategy(false);

        vm.prank(owner);
        guard.setBotAuthorization(bot, false);

        vm.expectRevert(KeeperBotGuard.KeeperBotGuard__NotAuthorizedBot.selector);
        vm.prank(bot);
        guard.callStrategyReport(address(strategy));
    }

    /*//////////////////////////////////////////////////////////////
                            VIEW FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function test_IsBotAuthorized_DefaultsFalse() public view {
        assertFalse(guard.isBotAuthorized(bot));
        assertFalse(guard.isBotAuthorized(other));
