    }

    function test_callStrategyReport_healthCheckActive_disablesThenReports() public {
        MockStrategy strategy = new MockStrategy(true);

        vm.prank(bot);
        vm.expectEmit(true, true, false, true);
        emit StrategyReportCalled(address(strategy), bot);
        guard.callStrategyReport(address(strategy));

        assertEq(strategy.setDoHealthCheckCallCount(), 1);
        assertFalse(strategy.doHealthCheckValue());
        assertEq(strategy.reportCallCount(), 1);
    }

    function test_callStrategyReport_strategyWithoutHealthCheck_stillReports() public {
