        vm.prank(bot);
        vm.expectEmit(true, true, false, true);
        emit StrategyReportCalled(address(strategy), bot);
        guard.callStrategyReport(address(strategy));

        assertEq(strategy.reportCallCount(), 1);
    }

    function test_callStrategyReport_revertsWhenModuleCallFails() public {
        MockStrategy strategy = new MockStrategy(false);
        strategy.setReportReverts(true);

        vm.prank(bot);
        vm.expectRevert(KeeperBotGuard.KeeperBotGuard__ModuleTransactionFailed.selector);
        guard.callStrategyReport(address(strategy));

        assertEq(strategy.reportCallCount(), 0);
    }

    function test_callStrategyReport_anyAuthorizedBotCanCall() public {
        MockStrategy strategy = new MockStrategy(false);

        vm.prank(owner);
        guard.setBotAuthorization(otherBot, true);

        vm.prank(otherBot);
