pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { Create2 } from "@openzeppelin/contracts/utils/Create2.sol";
import { YieldForwarderFactory } from "src/factories/YieldForwarderFactory.sol";
import { YieldForwarder } from "src/core/YieldForwarder.sol";

contract YieldForwarderFactoryTest is Test {
    YieldForwarderFactory internal factory;

    address internal receiver = makeAddr("receiver");
    address internal keeper = makeAddr("keeper");
    address internal deployer = makeAddr("deployer");
    address internal otherDeployer = makeAddr("otherDeployer");

    event YieldForwarderCreated(
        address indexed deployer,
        address indexed forwarderAddress,
        bytes32 indexed salt,
        address receiver,
        address keeper
    );

    error ForwarderAlreadyExists(address existingForwarder);

    function setUp() public {
        factory = new YieldForwarderFactory();
    }

    // ============================================
    // HELPERS - mirror the factory's internal logic
    // ============================================

    function _finalSalt(
        address _receiver,
        address _keeper,
        bytes32 _salt,
        address _deployer
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(keccak256(abi.encode(_receiver, _keeper, _salt)), _deployer));
    }

    function _creationBytecode(address _receiver, address _keeper) internal pure returns (bytes memory) {
        return abi.encodePacked(type(YieldForwarder).creationCode, abi.encode(_receiver, _keeper));
    }

    function _predict(
        address _receiver,
        address _keeper,
        bytes32 _salt,
        address _deployer
    ) internal view returns (address) {
        bytes32 finalSalt = _finalSalt(_receiver, _keeper, _salt, _deployer);
        bytes memory bytecode = _creationBytecode(_receiver, _keeper);
        return Create2.computeAddress(finalSalt, keccak256(bytecode), address(factory));
    }

    // ============================================
    // createYieldForwarder
