    function test_CreateYieldForwarder_DeploysContractWithCode() public {
        bytes32 salt = bytes32(uint256(1));

        vm.prank(deployer);
        address forwarder = factory.createYieldForwarder(receiver, keeper, salt);

        assertGt(forwarder.code.length, 0, "deployed forwarder should have code");
    }

    function test_CreateYieldForwarder_MatchesPredictedAddress() public {
        bytes32 salt = bytes32(uint256(42));

        address predictedBefore = factory.computeYieldForwarderAddress(receiver, keeper, salt, deployer);
        assertEq(predictedBefore.code.length, 0, "predicted address should be empty before deployment");

        vm.prank(deployer);
        address forwarder = factory.createYieldForwarder(receiver, keeper, salt);

        assertEq(forwarder, predictedBefore, "deployed address should match prediction");
        assertEq(forwarder, _predict(receiver, keeper, salt, deployer), "deployed address should match manual computation");
    }

    function test_CreateYieldForwarder_EmitsEvent() public {
        bytes32 salt = bytes32(uint256(7));
        address predicted = factory.computeYieldForwarderAddress(receiver, keeper, salt, deployer);

        vm.expectEmit(true, true, true, true, address(factory));
        emit YieldForwarderCreated(deployer, predicted, salt, receiver, keeper);

        vm.prank(deployer);
        factory.createYieldForwarder(receiver, keeper, salt);
    }

    function test_CreateYieldForwarder_TracksDeployment() public {
        bytes32 salt = bytes32(uint256(3));

        vm.prank(deployer);
        address forwarder = factory.createYieldForwarder(receiver, keeper, salt);

        YieldForwarderFactory.ForwarderInfo[] memory infos = factory.getForwardersByDeployer(deployer);
        assertEq(infos.length, 1, "one forwarder should be tracked");
        assertEq(infos[0].forwarderAddress, forwarder);
        assertEq(infos[0].receiver, receiver);
        assertEq(infos[0].keeper, keeper);
    }

    function test_CreateYieldForwarder_PublicMappingGetter() public {
        bytes32 salt = bytes32(uint256(9));

        vm.prank(deployer);
        address forwarder = factory.createYieldForwarder(receiver, keeper, salt);

        (address forwarderAddress, address storedReceiver, address storedKeeper) = factory.deployerToForwarders(deployer, 0);
        assertEq(forwarderAddress, forwarder);
        assertEq(storedReceiver, receiver);
        assertEq(storedKeeper, keeper);
    }

    function test_CreateYieldForwarder_MultipleDeploymentsAreAppended() public {
        bytes32 saltA = bytes32(uint256(1));
        bytes32 saltB = bytes32(uint256(2));

        vm.startPrank(deployer);
        address forwarderA = factory.createYieldForwarder(receiver, keeper, saltA);
        address forwarderB = factory.createYieldForwarder(receiver, keeper, saltB);
        vm.stopPrank();

        assertTrue(forwarderA != forwarderB, "different salts should produce different addresses");

        YieldForwarderFactory.ForwarderInfo[] memory infos = factory.getForwardersByDeployer(deployer);
        assertEq(infos.length, 2);
        assertEq(infos[0].forwarderAddress, forwarderA);
        assertEq(infos[1].forwarderAddress, forwarderB);
    }

    function test_CreateYieldForwarder_RevertsOnDuplicateDeployment() public {
        bytes32 salt = bytes32(uint256(123));

        vm.prank(deployer);
        address forwarder = factory.createYieldForwarder(receiver, keeper, salt);

        vm.expectRevert(abi.encodeWithSelector(ForwarderAlreadyExists.selector, forwarder));
        vm.prank(deployer);
        factory.createYieldForwarder(receiver, keeper, salt);
    }

    function test_CreateYieldForwarder_SameParamsDifferentDeployerSucceeds() public {
        bytes32 salt = bytes32(uint256(55));

        vm.prank(deployer);
