        vm.prank(otherDeployer);
        address forwarderB = factory.createYieldForwarder(receiver, keeper, salt);

        assertTrue(forwarderA != forwarderB, "different deployers should yield different addresses");

        assertEq(factory.getForwardersByDeployer(deployer).length, 1);
        assertEq(factory.getForwardersByDeployer(otherDeployer).length, 1);
    }

    function test_CreateYieldForwarder_DifferentReceiverProducesDifferentAddress() public {
        bytes32 salt = bytes32(uint256(11));
        address receiver2 = makeAddr("receiver2");

        vm.startPrank(deployer);
        address forwarderA = factory.createYieldForwarder(receiver, keeper, salt);
        address forwarderB = factory.createYieldForwarder(receiver2, keeper, salt);
        vm.stopPrank();

        assertTrue(forwarderA != forwarderB);
    }

    function test_CreateYieldForwarder_DifferentKeeperProducesDifferentAddress() public {
        bytes32 salt = bytes32(uint256(11));
        address keeper2 = makeAddr("keeper2");

        vm.startPrank(deployer);
        address forwarderA = factory.createYieldForwarder(receiver, keeper, salt);
        address forwarderB = factory.createYieldForwarder(receiver, keeper2, salt);
        vm.stopPrank();

        assertTrue(forwarderA != forwarderB);
    }

    function testFuzz_CreateYieldForwarder_PredictionMatchesDeployment(
        address _receiver,
        address _keeper,
        bytes32 _salt,
        address _deployer
    ) public {
        vm.assume(_deployer != address(0));

        address predicted = factory.computeYieldForwarderAddress(_receiver, _keeper, _salt, _deployer);

        vm.prank(_deployer);
        address forwarder = factory.createYieldForwarder(_receiver, _keeper, _salt);

        assertEq(forwarder, predicted);
        assertGt(forwarder.code.length, 0);
    }

    // ============================================
    // computeYieldForwarderAddress
    // ============================================

    function test_ComputeYieldForwarderAddress_MatchesManualComputation() public view {
        bytes32 salt = bytes32(uint256(17));
        address predicted = factory.computeYieldForwarderAddress(receiver, keeper, salt, deployer);
        assertEq(predicted, _predict(receiver, keeper, salt, deployer));
    }

    function test_ComputeYieldForwarderAddress_IsDeterministic() public view {
        bytes32 salt = bytes32(uint256(17));
        address predictedA = factory.computeYieldForwarderAddress(receiver, keeper, salt, deployer);
        address predictedB = factory.computeYieldForwarderAddress(receiver, keeper, salt, deployer);
        assertEq(predictedA, predictedB);
    }

    function test_ComputeYieldForwarderAddress_DifferentSaltsDiffer() public view {
        address predictedA = factory.computeYieldForwarderAddress(receiver, keeper, bytes32(uint256(1)), deployer);
        address predictedB = factory.computeYieldForwarderAddress(receiver, keeper, bytes32(uint256(2)), deployer);
        assertTrue(predictedA != predictedB);
    }

    function test_ComputeYieldForwarderAddress_DifferentDeployersDiffer() public view {
        bytes32 salt = bytes32(uint256(1));
        address predictedA = factory.computeYieldForwarderAddress(receiver, keeper, salt, deployer);
        address predictedB = factory.computeYieldForwarderAddress(receiver, keeper, salt, otherDeployer);
        assertTrue(predictedA != predictedB);
    }

    function test_ComputeYieldForwarderAddress_DoesNotDeploy() public {
        bytes32 salt = bytes32(uint256(1));
        address predicted = factory.computeYieldForwarderAddress(receiver, keeper, salt, deployer);
        assertEq(predicted.code.length, 0, "computing address should not deploy");
    }

    // ============================================
    // getForwardersByDeployer
    // ============================================

    function test_GetForwardersByDeployer_EmptyForUnknownDeployer() public view {
        YieldForwarderFactory.ForwarderInfo[] memory infos = factory.getForwardersByDeployer(deployer);
        assertEq(infos.length, 0);
    }

    function test_GetForwardersByDeployer_DoesNotMixDeployers() public {
        bytes32 saltA = bytes32(uint256(1));
        bytes32 saltB = bytes32(uint256(2));

        vm.prank(deployer);
