        assertEq(kpr, keeper);
    }

    // ============================================
    // FUZZ
    // ============================================

    function testFuzz_computeYieldForwarderAddress_matchesDeployedAddress(
        address _receiver,
        address _keeper,
        bytes32 _salt,
        address _deployer
    ) public {
        vm.assume(_deployer != address(0));
        // Avoid precompiles / factory itself causing unrelated collisions in fuzz runs.
        vm.assume(_deployer.code.length == 0);

        address predicted = factory.computeYieldForwarderAddress(_receiver, _keeper, _salt, _deployer);
        vm.assume(predicted.code.length == 0);

        vm.prank(_deployer);
        address forwarder = factory.createYieldForwarder(_receiver, _keeper, _salt);

        assertEq(forwarder, predicted);
    }

    function testFuzz_createYieldForwarder_revertsOnDuplicate(
        address _receiver,
        address _keeper,
        bytes32 _salt,
        address _deployer
    ) public {
        vm.assume(_deployer != address(0));

        vm.prank(_deployer);
        address forwarder = factory.createYieldForwarder(_receiver, _keeper, _salt);

        vm.expectRevert(abi.encodeWithSelector(YieldForwarderFactory.ForwarderAlreadyExists.selector, forwarder));
        vm.prank(_deployer);
        factory.createYieldForwarder(_receiver, _keeper, _salt);
    }
