// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import { Test } from "forge-std/Test.sol";

import { RegenStakerWithoutDelegateSurrogateVotes } from "src/regen/RegenStakerWithoutDelegateSurrogateVotes.sol";
import {
    RegenStakerBase,
    Staker,
    IERC20,
    DelegationSurrogate,
    IAddressSet,
    IEarningPowerCalculator
} from "src/regen/RegenStakerBase.sol";
import { AccessMode } from "src/constants.sol";

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { ERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";

// =========================================================================
// Mocks
// =========================================================================

/// @dev Simple mintable ERC20 (with permit support) used both as the stake
///      token and the reward token in tests.
contract MockERC20 is ERC20, ERC20Permit {
    constructor(string memory _name, string memory _symbol) ERC20(_name, _symbol) ERC20Permit(_name) { }

    function mint(address _to, uint256 _amount) external {
        _mint(_to, _amount);
    }
}

/// @dev Earning power 1:1 with staked amount; never reports the deposit as
///      qualified for a bump so bumpEarningPower() reverts deterministically.
contract MockEarningPowerCalculator is IEarningPowerCalculator {
    function getEarningPower(uint256 _amountStaked, address, address) external pure returns (uint256) {
        return _amountStaked;
    }

    function getNewEarningPower(uint256 _amountStaked, address, address, uint256)
        external
        pure
        returns (uint256 _newEarningPower, bool _isQualifiedForBump)
    {
        return (_amountStaked, false);
    }
}

/// @dev Minimal, admin-free address set used to back both the allowset and
///      blockset slots in the tests below.
contract MockAddressSet is IAddressSet {
    mapping(address => bool) public isIncludedInSet;

    function setIncluded(address _account, bool _included) external {
        isIncludedInSet[_account] = _included;
    }

    function contains(address _account) external view returns (bool) {
        return isIncludedInSet[_account];
    }
}

// =========================================================================
// Tests
// =========================================================================

contract RegenStakerWithoutDelegateSurrogateVotesTest is Test {
    MockERC20 rewardToken;
    MockERC20 stakeToken;
    MockEarningPowerCalculator calculator;
    RegenStakerWithoutDelegateSurrogateVotes staker;

    address admin = makeAddr("admin");
    address rewardNotifier = makeAddr("rewardNotifier");
    address user1 = makeAddr("user1");
    address user2 = makeAddr("user2");
    address claimer = makeAddr("claimer");

    uint128 constant REWARD_DURATION = 30 days;
    uint128 constant MIN_STAKE = 1e18;
    uint256 constant MAX_BUMP_TIP = 1e17;

    function setUp() public {
        rewardToken = new MockERC20("Reward Token", "RWD");
        stakeToken = new MockERC20("Stake Token", "STK");
        calculator = new MockEarningPowerCalculator();

        staker = _deploy(
            IERC20(address(rewardToken)),
            IERC20(address(stakeToken)),
            IAddressSet(address(0)),
            IAddressSet(address(0)),
            AccessMode.NONE
        );

        vm.prank(admin);
        staker.setRewardNotifier(rewardNotifier, true);

        stakeToken.mint(user1, 1_000_000e18);
        stakeToken.mint(user2, 1_000_000e18);

        vm.prank(user1);
        stakeToken.approve(address(staker), type(uint256).max);
        vm.prank(user2);
        stakeToken.approve(address(staker), type(uint256).max);
    }

    function _deploy(
        IERC20 _rewardToken,
        IERC20 _stakeToken,
        IAddressSet _allowset,
        IAddressSet _blockset,
        AccessMode _mode
    ) internal returns (RegenStakerWithoutDelegateSurrogateVotes) {
        return new RegenStakerWithoutDelegateSurrogateVotes(
            _rewardToken,
            _stakeToken,
            IEarningPowerCalculator(address(calculator)),
            MAX_BUMP_TIP,
            admin,
            REWARD_DURATION,
            MIN_STAKE,
            _allowset,
            _blockset,
            _mode,
            IAddressSet(address(0))
        );
    }

    function _unwrap(Staker.DepositIdentifier _id) internal pure returns (uint256) {
        return Staker.DepositIdentifier.unwrap(_id);
    }

    // ---------------------------------------------------------------
    // Constructor / basic wiring
    // ---------------------------------------------------------------

    function test_Constructor_SetsCoreConfig() public view {
        assertEq(address(staker.REWARD_TOKEN()), address(rewardToken));
        assertEq(address(staker.STAKE_TOKEN()), address(stakeToken));
        assertEq(staker.admin(), admin);
        assertEq(staker.maxBumpTip(), MAX_BUMP_TIP);
        assertEq(staker.totalStaked(), 0);
    }

    // ---------------------------------------------------------------
    // Surrogate override: always self, never per-delegatee
    // ---------------------------------------------------------------

    function test_Surrogates_AlwaysReturnsThisContract() public view {
        assertEq(address(staker.surrogates(address(0))), address(staker));
        assertEq(address(staker.surrogates(user1)), address(staker));
        assertEq(address(staker.surrogates(user2)), address(staker));
    }

    // ---------------------------------------------------------------
    // Staking / withdrawing: tokens move directly to/from the contract
    // ---------------------------------------------------------------

    function test_Stake_TransfersTokensDirectlyIntoContract() public {
        uint256 amount = 10e18;

        vm.prank(user1);
        staker.stake(amount, user1);

        assertEq(stakeToken.balanceOf(address(staker)), amount);
        assertEq(stakeToken.balanceOf(user1), 1_000_000e18 - amount);
        assertEq(staker.totalStaked(), amount);
    }

    function test_Stake_RevertsBelowMinimumStakeAmount() public {
        vm.prank(user1);
        vm.expectRevert();
        staker.stake(MIN_STAKE - 1, user1);
    }

    function test_Stake_SucceedsAtMinimumStakeAmount() public {
        vm.prank(user1);
        staker.stake(MIN_STAKE, user1);

        assertEq(stakeToken.balanceOf(address(staker)), MIN_STAKE);
        assertEq(staker.totalStaked(), MIN_STAKE);
    }

    function test_StakeMore_IncreasesBalanceAndTotalStaked() public {
        uint256 initial = 10e18;
        uint256 more = 5e18;

        vm.startPrank(user1);
        Staker.DepositIdentifier depositId = staker.stake(initial, user1);
        staker.stakeMore(depositId, more);
        vm.stopPrank();

        assertEq(staker.totalStaked(), initial + more);
        assertEq(stakeToken.balanceOf(address(staker)), initial + more);
    }

    function test_Withdraw_TransfersTokensBackToOwnerViaSafeTransfer() public {
        uint256 amount = 50e18;

        vm.prank(user1);
        Staker.DepositIdentifier depositId = staker.stake(amount, user1);

        uint256 balBefore = stakeToken.balanceOf(user1);

        vm.prank(user1);
        staker.withdraw(depositId, amount);

        assertEq(stakeToken.balanceOf(user1), balBefore + amount);
        assertEq(stakeToken.balanceOf(address(staker)), 0);
        assertEq(staker.totalStaked(), 0);
    }

    function test_Withdraw_Partial_LeavesRemainderStaked() public {
        uint256 amount = 50e18;
        uint256 withdrawn = 20e18;

        vm.startPrank(user1);
        Staker.DepositIdentifier depositId = staker.stake(amount, user1);
        staker.withdraw(depositId, withdrawn);
        vm.stopPrank();

        assertEq(staker.totalStaked(), amount - withdrawn);
        assertEq(stakeToken.balanceOf(address(staker)), amount - withdrawn);
    }

    function test_Withdraw_RevertsForNonOwner() public {
        vm.prank(user1);
        Staker.DepositIdentifier depositId = staker.stake(10e18, user1);

        vm.prank(user2);
        vm.expectRevert();
        staker.withdraw(depositId, 10e18);
    }

    function test_Withdraw_RevertsWhenExceedingDepositBalance() public {
        vm.prank(user1);
        Staker.DepositIdentifier depositId = staker.stake(10e18, user1);

        vm.prank(user1);
        vm.expectRevert();
        staker.withdraw(depositId, 11e18);
    }

    // ---------------------------------------------------------------
    // Delegation: always unsupported in this variant
    // ---------------------------------------------------------------

    function test_AlterDelegatee_RevertsWithDelegationNotSupported() public {
        vm.prank(user1);
        Staker.DepositIdentifier depositId = staker.stake(10e18, user1);

        vm.prank(user1);
        vm.expectRevert(RegenStakerWithoutDelegateSurrogateVotes.DelegationNotSupported.selector);
        staker.alterDelegatee(depositId, user2);
    }

    // ---------------------------------------------------------------
    // _validateAndGetRequiredBalance: different-token vs same-token accounting
    // ---------------------------------------------------------------

    function test_NotifyRewardAmount_DifferentToken_RevertsWhenUnfunded() public {
        uint256 rewardAmount = 10e18;

        vm.prank(rewardNotifier);
        vm.expectRevert(abi.encodeWithSignature("InsufficientRewardBalance(uint256,uint256)", 0, rewardAmount));
        staker.notifyRewardAmount(rewardAmount);
    }

    function test_NotifyRewardAmount_DifferentToken_SucceedsWhenFunded() public {
        uint256 rewardAmount = 10e18;
        rewardToken.mint(address(staker), rewardAmount);

        vm.prank(rewardNotifier);
        staker.notifyRewardAmount(rewardAmount);
    }

    function test_NotifyRewardAmount_SameToken_MustCoverStakePlusReward() public {
        MockERC20 sameToken = new MockERC20("Same", "SAME");
        RegenStakerWithoutDelegateSurrogateVotes sameStaker = _deploy(
            IERC20(address(sameToken)),
            IERC20(address(sameToken)),
            IAddressSet(address(0)),
            IAddressSet(address(0)),
            AccessMode.NONE
        );

        vm.prank(admin);
        sameStaker.setRewardNotifier(rewardNotifier, true);

        uint256 stakeAmount = 100e18;
        sameToken.mint(user1, stakeAmount);
        vm.prank(user1);
        sameToken.approve(address(sameStaker), type(uint256).max);
        vm.prank(user1);
        sameStaker.stake(stakeAmount, user1);

        uint256 rewardAmount = 10e18;

        // Contract currently only holds the staked amount; notifying rewards on
        // top of that without additional funding must fail.
        vm.prank(rewardNotifier);
        vm.expectRevert(
            abi.encodeWithSignature(
                "InsufficientRewardBalance(uint256,uint256)", stakeAmount, stakeAmount + rewardAmount
            )
        );
        sameStaker.notifyRewardAmount(rewardAmount);

        // Fund exactly the additional reward amount on top of the stake; now it succeeds.
        sameToken.mint(address(sameStaker), rewardAmount);
        vm.prank(rewardNotifier);
        sameStaker.notifyRewardAmount(rewardAmount);

        assertEq(sameStaker.totalStaked(), stakeAmount);
    }

    // ---------------------------------------------------------------
    // Reward claiming
    // ---------------------------------------------------------------

    function test_ClaimReward_AccruesAndPaysOutToClaimer() public {
        uint256 stakeAmount = 100e18;
        vm.prank(user1);
        Staker.DepositIdentifier depositId = staker.stake(stakeAmount, user1);

        uint256 rewardAmount = 30e18;
        rewardToken.mint(address(staker), rewardAmount);
        vm.prank(rewardNotifier);
        staker.notifyRewardAmount(rewardAmount);

        vm.warp(block.timestamp + REWARD_DURATION);

        uint256 balBefore = rewardToken.balanceOf(user1);

        vm.prank(user1);
        uint256 claimed = staker.claimReward(depositId);

        assertGt(claimed, 0);
        assertLe(claimed, rewardAmount);
        assertEq(rewardToken.balanceOf(user1), balBefore + claimed);
    }

    function test_Stake_WithDistinctClaimer_OnlyClaimerCanClaim() public {
        uint256 stakeAmount = 100e18;
        vm.prank(user1);
        Staker.DepositIdentifier depositId = staker.stake(stakeAmount, user1, claimer);

        uint256 rewardAmount = 30e18;
        rewardToken.mint(address(staker), rewardAmount);
        vm.prank(rewardNotifier);
        staker.notifyRewardAmount(rewardAmount);

        vm.warp(block.timestamp + REWARD_DURATION);

        vm.prank(user1);
        vm.expectRevert();
        staker.claimReward(depositId);

        vm.prank(claimer);
        uint256 claimed = staker.claimReward(depositId);
        assertGt(claimed, 0);
        assertEq(rewardToken.balanceOf(claimer), claimed);
    }

    function test_AlterClaimer_NewClaimerCanClaim() public {
        vm.prank(user1);
        Staker.DepositIdentifier depositId = staker.stake(10e18, user1);

        vm.prank(user1);
        staker.alterClaimer(depositId, claimer);

        rewardToken.mint(address(staker), 10e18);
        vm.prank(rewardNotifier);
        staker.notifyRewardAmount(10e18);
        vm.warp(block.timestamp + REWARD_DURATION);

        vm.prank(claimer);
        uint256 claimed = staker.claimReward(depositId);
        assertGt(claimed, 0);
    }

    // ---------------------------------------------------------------
    // Earning power bump
    // ---------------------------------------------------------------

    function test_BumpEarningPower_RevertsWhenNotQualified() public {
        vm.prank(user1);
        Staker.DepositIdentifier depositId = staker.stake(10e18, user1);

        vm.expectRevert();
        staker.bumpEarningPower(depositId, address(this), 0);
    }

    // ---------------------------------------------------------------
    // Admin access control
    // ---------------------------------------------------------------

    function test_SetAdmin_RevertsForNonAdmin() public {
        vm.prank(user1);
        vm.expectRevert();
        staker.setAdmin(user2);
    }

    function test_SetAdmin_SucceedsForAdmin() public {
        address newAdmin = makeAddr("newAdmin");

        vm.prank(admin);
        staker.setAdmin(newAdmin);

        assertEq(staker.admin(), newAdmin);
    }

    function test_SetRewardNotifier_RevertsForNonAdmin() public {
        vm.prank(user1);
        vm.expectRevert();
        staker.setRewardNotifier(user2, true);
    }

    function test_NotifyRewardAmount_RevertsForDisabledNotifier() public {
        rewardToken.mint(address(staker), 10e18);

        vm.prank(user1);
        vm.expectRevert();
        staker.notifyRewardAmount(10e18);
    }

    // ---------------------------------------------------------------
    // Allowset / blockset access modes
    // ---------------------------------------------------------------

    function test_AllowsetMode_BlocksStakerNotInAllowset() public {
        MockAddressSet allowset = new MockAddressSet();
        RegenStakerWithoutDelegateSurrogateVotes allowStaker = _deploy(
            IERC20(address(rewardToken)),
            IERC20(address(stakeToken)),
            IAddressSet(address(allowset)),
            IAddressSet(address(0)),
            AccessMode.ALLOWSET
        );

        vm.prank(user1);
        stakeToken.approve(address(allowStaker), type(uint256).max);

        vm.prank(user1);
        vm.expectRevert();
        allowStaker.stake(MIN_STAKE, user1);
    }

    function test_AllowsetMode_AllowsStakerOnceIncluded() public {
        MockAddressSet allowset = new MockAddressSet();
        RegenStakerWithoutDelegateSurrogateVotes allowStaker = _deploy(
            IERC20(address(rewardToken)),
            IERC20(address(stakeToken)),
            IAddressSet(address(allowset)),
            IAddressSet(address(0)),
            AccessMode.ALLOWSET
        );

        vm.prank(user1);
        stakeToken.approve(address(allowStaker), type(uint256).max);

        allowset.setIncluded(user1, true);

        vm.prank(user1);
        allowStaker.stake(MIN_STAKE, user1);

        assertEq(stakeToken.balanceOf(address(allowStaker)), MIN_STAKE);
    }

    function test_BlocksetMode_AllowsStakerNotInBlockset() public {
        MockAddressSet blockset = new MockAddressSet();
        RegenStakerWithoutDelegateSurrogateVotes blockStaker = _deploy(
            IERC20(address(rewardToken)),
            IERC20(address(stakeToken)),
            IAddressSet(address(0)),
            IAddressSet(address(blockset)),
            AccessMode.BLOCKSET
        );

        vm.prank(user1);
        stakeToken.approve(address(blockStaker), type(uint256).max);

        vm.prank(user1);
        blockStaker.stake(MIN_STAKE, user1);

        assertEq(stakeToken.balanceOf(address(blockStaker)), MIN_STAKE);
    }

    function test_BlocksetMode_BlocksStakerOnceIncluded() public {
        MockAddressSet blockset = new MockAddressSet();
        RegenStakerWithoutDelegateSurrogateVotes blockStaker = _deploy(
            IERC20(address(rewardToken)),
            IERC20(address(stakeToken)),
            IAddressSet(address(0)),
            IAddressSet(address(blockset)),
            AccessMode.BLOCKSET
        );

        blockset.setIncluded(user2, true);

        vm.prank(user2);
        stakeToken.approve(address(blockStaker), type(uint256).max);

        vm.prank(user2);
        vm.expectRevert();
        blockStaker.stake(MIN_STAKE, user2);
    }
}

