 * surrogates() always returning address(this)).
 *
 * `IAddressSet` is exercised with a minimal best-effort mock
 * (`contains`/`add`/`remove`). If the real interface differs, only the
 * ALLOWSET/BLOCKSET-specific tests below are affected; they are isolated in
 * their own test functions for that reason.
 */

import { Test } from "forge-std/Test.sol";

import { RegenStakerWithoutDelegateSurrogateVotes } from "src/regen/RegenStakerWithoutDelegateSurrogateVotes.sol";
import {
    RegenStakerBase,
    Staker,
    IERC20,
    DelegationSurrogate,
    IAddressSet,
    IEarningPowerCalculator
} from "src/regen/RegenStakerBase.sol";
import { AccessMode } from "src/constants.sol";

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { ERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";

/*//////////////////////////////////////////////////////////////////////
                                   MOCKS
//////////////////////////////////////////////////////////////////////*/

/// @dev Simple mintable ERC20 with permit support (stake token must support IERC20Permit).
contract MockERC20 is ERC20, ERC20Permit {
    constructor(string memory _name, string memory _symbol) ERC20(_name, _symbol) ERC20Permit(_name) { }

    function mint(address _to, uint256 _amount) external {
        _mint(_to, _amount);
    }
}

/// @dev 1:1 earning power calculator by default (earning power == amount staked).
/// Supports a per-staker override so bumpEarningPower can be exercised.
contract MockEarningPowerCalculator is IEarningPowerCalculator {
    mapping(address => uint256) public overrideEarningPower;
    mapping(address => bool) public hasOverride;

    function setOverride(address _staker, uint256 _earningPower) external {
        overrideEarningPower[_staker] = _earningPower;
        hasOverride[_staker] = true;
    }

    function clearOverride(address _staker) external {
        hasOverride[_staker] = false;
    }

    function getEarningPower(uint256 _amountStaked, address _staker, address) external view returns (uint256) {
        if (hasOverride[_staker]) return overrideEarningPower[_staker];
        return _amountStaked;
    }

    function getNewEarningPower(uint256 _amountStaked, address _staker, address, uint256 _oldEarningPower)
        external
        view
        returns (uint256 _newEarningPower, bool _isQualifiedForBump)
    {
        _newEarningPower = hasOverride[_staker] ? overrideEarningPower[_staker] : _amountStaked;
        _isQualifiedForBump = _newEarningPower != _oldEarningPower;
    }
}

/// @dev Minimal best-effort standalone mock for IAddressSet. Not declared `is IAddressSet`
/// on purpose: it is cast to IAddressSet at call sites so the rest of the suite still
/// compiles even if this guessed ABI does not exactly match the real interface.
contract MockAddressSet {
    mapping(address => bool) public members;

    function add(address _account) external {
        members[_account] = true;
    }

    function remove(address _account) external {
        members[_account] = false;
    }

    function contains(address _account) external view returns (bool) {
        return members[_account];
    }
}

/*//////////////////////////////////////////////////////////////////////
                                   TESTS
//////////////////////////////////////////////////////////////////////*/

contract RegenStakerWithoutDelegateSurrogateVotesTest is Test {
    RegenStakerWithoutDelegateSurrogateVotes internal staker;

    MockERC20 internal rewardToken;
    MockERC20 internal stakeToken;
    MockEarningPowerCalculator internal earningPowerCalculator;

    address internal admin = makeAddr("admin");
    address internal rewardNotifier = makeAddr("rewardNotifier");
    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");
    address internal claimer = makeAddr("claimer");
    address internal delegatee = makeAddr("delegatee");

    uint128 internal constant REWARD_DURATION = 30 days;
    uint256 internal constant MAX_BUMP_TIP = 1e18;
    uint256 internal constant INITIAL_MINT = 1_000_000e18;

    function setUp() public virtual {
        rewardToken = new MockERC20("Reward Token", "RWD");
        stakeToken = new MockERC20("Stake Token", "STK");
        earningPowerCalculator = new MockEarningPowerCalculator();

        staker = _deployDefaultStaker();

        vm.prank(admin);
        staker.setRewardNotifier(rewardNotifier, true);

        stakeToken.mint(alice, INITIAL_MINT);
        stakeToken.mint(bob, INITIAL_MINT);

        vm.prank(alice);
        stakeToken.approve(address(staker), type(uint256).max);
        vm.prank(bob);
        stakeToken.approve(address(staker), type(uint256).max);
    }

    /*//////////////////////////////////////////////////////////////////
                                  HELPERS
    //////////////////////////////////////////////////////////////////*/

    function _deployDefaultStaker() internal returns (RegenStakerWithoutDelegateSurrogateVotes) {
        return _deployStakerFull(
            address(rewardToken),
            address(stakeToken),
            0,
            IAddressSet(address(0)),
            IAddressSet(address(0)),
            AccessMode.NONE
        );
    }

    function _deployStakerFull(
        address _rewardTok,
        address _stakeTok,
        uint128 _minimumStake,
        IAddressSet _allowset,
        IAddressSet _blockset,
        AccessMode _mode
    ) internal returns (RegenStakerWithoutDelegateSurrogateVotes) {
        return new RegenStakerWithoutDelegateSurrogateVotes(
            IERC20(_rewardTok),
            IERC20(_stakeTok),
            IEarningPowerCalculator(address(earningPowerCalculator)),
            MAX_BUMP_TIP,
            admin,
            REWARD_DURATION,
            _minimumStake,
            _allowset,
            _blockset,
            _mode,
            IAddressSet(address(0))
        );
    }

    function _notifyReward(uint256 _amount) internal {
        rewardToken.mint(address(staker), _amount);
        vm.prank(rewardNotifier);
        staker.notifyRewardAmount(_amount);
    }

    /*//////////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////////*/

    function test_Constructor_SetsCoreParameters() public {
        assertEq(address(staker.REWARD_TOKEN()), address(rewardToken));
        assertEq(address(staker.STAKE_TOKEN()), address(stakeToken));
        assertEq(staker.admin(), admin);
        assertEq(address(staker.earningPowerCalculator()), address(earningPowerCalculator));
        assertEq(staker.maxBumpTip(), MAX_BUMP_TIP);
        assertEq(staker.totalStaked(), 0);
    }

    /*//////////////////////////////////////////////////////////////////
                          SURROGATE / DELEGATION VARIANT
    //////////////////////////////////////////////////////////////////*/

    function test_Surrogates_AlwaysReturnsContractItself() public {
        assertEq(address(staker.surrogates(alice)), address(staker));
        assertEq(address(staker.surrogates(bob)), address(staker));
        assertEq(address(staker.surrogates(address(0))), address(staker));
    }

    function test_Stake_HoldsTokensDirectlyOnContractNotASeparateSurrogate() public {
        uint256 amount = 100e18;

        vm.prank(alice);
        staker.stake(amount, delegatee);

        assertEq(stakeToken.balanceOf(address(staker)), amount);
        assertEq(stakeToken.balanceOf(alice), INITIAL_MINT - amount);
        assertEq(staker.totalStaked(), amount);
    }

    function test_AlterDelegatee_RevertsWithDelegationNotSupported() public {
        vm.startPrank(alice);
        Staker.DepositIdentifier depositId = staker.stake(100e18, delegatee);

        vm.expectRevert(RegenStakerWithoutDelegateSurrogateVotes.DelegationNotSupported.selector);
        staker.alterDelegatee(depositId, bob);
        vm.stopPrank();
    }

    /*//////////////////////////////////////////////////////////////////
                             STAKE / STAKE MORE
    //////////////////////////////////////////////////////////////////*/

    function test_StakeMore_IncreasesDepositAndTotalStaked() public {
        vm.startPrank(alice);
        Staker.DepositIdentifier depositId = staker.stake(100e18, delegatee);
        staker.stakeMore(depositId, 50e18);
        vm.stopPrank();

        assertEq(stakeToken.balanceOf(address(staker)), 150e18);
        assertEq(staker.totalStaked(), 150e18);
    }

    function test_StakeMore_RevertsForNonOwner() public {
        vm.prank(alice);
        Staker.DepositIdentifier depositId = staker.stake(100e18, delegatee);

        vm.prank(bob);
        vm.expectRevert();
        staker.stakeMore(depositId, 10e18);
    }

    function testFuzz_Stake_AccumulatesAcrossMultipleStakers(uint256 _aliceAmount, uint256 _bobAmount) public {
        _aliceAmount = bound(_aliceAmount, 1, INITIAL_MINT);
        _bobAmount = bound(_bobAmount, 1, INITIAL_MINT);

        vm.prank(alice);
        staker.stake(_aliceAmount, delegatee);

        vm.prank(bob);
        staker.stake(_bobAmount, delegatee);

        assertEq(staker.totalStaked(), _aliceAmount + _bobAmount);
        assertEq(stakeToken.balanceOf(address(staker)), _aliceAmount + _bobAmount);
    }

    /*//////////////////////////////////////////////////////////////////
                                  WITHDRAW
    //////////////////////////////////////////////////////////////////*/

    function test_Withdraw_TransfersTokensDirectlyBackToOwner() public {
        uint256 amount = 100e18;
        uint256 balanceBefore = stakeToken.balanceOf(alice);

        vm.startPrank(alice);
        Staker.DepositIdentifier depositId = staker.stake(amount, delegatee);
        staker.withdraw(depositId, amount);
        vm.stopPrank();

        assertEq(stakeToken.balanceOf(alice), balanceBefore);
        assertEq(stakeToken.balanceOf(address(staker)), 0);
        assertEq(staker.totalStaked(), 0);
    }

    function test_Withdraw_PartialWithdrawalLeavesRemainderStaked() public {
        uint256 amount = 100e18;

        vm.startPrank(alice);
        Staker.DepositIdentifier depositId = staker.stake(amount, delegatee);
        staker.withdraw(depositId, 40e18);
        vm.stopPrank();

        assertEq(stakeToken.balanceOf(address(staker)), 60e18);
        assertEq(staker.totalStaked(), 60e18);
    }

    function test_Withdraw_RevertsWhenAmountExceedsBalance() public {
        vm.startPrank(alice);
        Staker.DepositIdentifier depositId = staker.stake(100e18, delegatee);

        vm.expectRevert();
        staker.withdraw(depositId, 101e18);
        vm.stopPrank();
    }

    function test_Withdraw_RevertsForNonOwner() public {
        vm.prank(alice);
        Staker.DepositIdentifier depositId = staker.stake(100e18, delegatee);

        vm.prank(bob);
        vm.expectRevert();
        staker.withdraw(depositId, 100e18);
    }

    function testFuzz_StakeAndWithdraw_RoundTripPreservesBalances(uint256 _amount) public {
        _amount = bound(_amount, 1, INITIAL_MINT);

        vm.startPrank(alice);
        Staker.DepositIdentifier depositId = staker.stake(_amount, delegatee);
        uint256 balanceBeforeWithdraw = stakeToken.balanceOf(alice);
        staker.withdraw(depositId, _amount);
        vm.stopPrank();

        assertEq(stakeToken.balanceOf(alice), balanceBeforeWithdraw + _amount);
        assertEq(stakeToken.balanceOf(address(staker)), 0);
        assertEq(staker.totalStaked(), 0);
    }

    /*//////////////////////////////////////////////////////////////////
                             MINIMUM STAKE AMOUNT
    //////////////////////////////////////////////////////////////////*/

    function test_Stake_RevertsBelowMinimumStakeAmount() public {
        uint128 minimumStake = 50e18;
        RegenStakerWithoutDelegateSurrogateVotes minStaker = _deployStakerFull(
            address(rewardToken),
            address(stakeToken),
            minimumStake,
            IAddressSet(address(0)),
            IAddressSet(address(0)),
            AccessMode.NONE
        );

        vm.startPrank(alice);
        stakeToken.approve(address(minStaker), type(uint256).max);
        vm.expectRevert();
        minStaker.stake(minimumStake - 1, delegatee);
        vm.stopPrank();
    }

    function test_Stake_SucceedsAtOrAboveMinimumStakeAmount() public {
        uint128 minimumStake = 50e18;
        RegenStakerWithoutDelegateSurrogateVotes minStaker = _deployStakerFull(
            address(rewardToken),
            address(stakeToken),
            minimumStake,
            IAddressSet(address(0)),
            IAddressSet(address(0)),
            AccessMode.NONE
        );

        vm.startPrank(alice);
        stakeToken.approve(address(minStaker), type(uint256).max);
        minStaker.stake(minimumStake, delegatee);
        vm.stopPrank();

        assertEq(minStaker.totalStaked(), minimumStake);
    }

    /*//////////////////////////////////////////////////////////////////
                         ALLOWSET / BLOCKSET ACCESS MODE
             (best-effort IAddressSet mock -- see contract docblock)
    //////////////////////////////////////////////////////////////////*/

    function test_Stake_RevertsWhenCallerNotInAllowset() public {
        MockAddressSet allowset = new MockAddressSet();
        allowset.add(bob); // alice intentionally NOT added

        RegenStakerWithoutDelegateSurrogateVotes allowsetStaker = _deployStakerFull(
            address(rewardToken),
            address(stakeToken),
            0,
            IAddressSet(address(allowset)),
            IAddressSet(address(0)),
            AccessMode.ALLOWSET
        );

        vm.startPrank(alice);
        stakeToken.approve(address(allowsetStaker), type(uint256).max);
        vm.expectRevert();
        allowsetStaker.stake(10e18, delegatee);
        vm.stopPrank();
    }

    function test_Stake_SucceedsWhenCallerInAllowset() public {
        MockAddressSet allowset = new MockAddressSet();
        allowset.add(alice);

        RegenStakerWithoutDelegateSurrogateVotes allowsetStaker = _deployStakerFull(
            address(rewardToken),
            address(stakeToken),
            0,
            IAddressSet(address(allowset)),
            IAddressSet(address(0)),
            AccessMode.ALLOWSET
        );

        vm.startPrank(alice);
        stakeToken.approve(address(allowsetStaker), type(uint256).max);
        allowsetStaker.stake(10e18, delegatee);
        vm.stopPrank();

        assertEq(allowsetStaker.totalStaked(), 10e18);
    }

    function test_Stake_RevertsWhenCallerInBlockset() public {
        MockAddressSet blockset = new MockAddressSet();
        blockset.add(alice);

        RegenStakerWithoutDelegateSurrogateVotes blocksetStaker = _deployStakerFull(
            address(rewardToken),
            address(stakeToken),
            0,
            IAddressSet(address(0)),
            IAddressSet(address(blockset)),
            AccessMode.BLOCKSET
        );

        vm.startPrank(alice);
        stakeToken.approve(address(blocksetStaker), type(uint256).max);
        vm.expectRevert();
        blocksetStaker.stake(10e18, delegatee);
        vm.stopPrank();
    }

    /*//////////////////////////////////////////////////////////////////
                        REWARDS / _validateAndGetRequiredBalance
    //////////////////////////////////////////////////////////////////*/

    function test_NotifyRewardAmount_RevertsForNonAuthorizedNotifier() public {
        rewardToken.mint(address(staker), 1_000e18);

        vm.prank(alice);
        vm.expectRevert();
        staker.notifyRewardAmount(1_000e18);
    }

    function test_NotifyRewardAmount_SucceedsForAuthorizedNotifier() public {
        _notifyReward(1_000e18);
        assertEq(staker.totalRewards(), 1_000e18);
    }

    function test_NotifyRewardAmount_RevertsWhenRewardBalanceInsufficient_DifferentTokenScenario() public {
        uint256 amount = 1_000e18;
        // No reward tokens minted to the contract: currentBalance == 0 < required == amount.
        vm.prank(rewardNotifier);
        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerWithoutDelegateSurrogateVotes.InsufficientRewardBalance.selector, 0, amount
            )
        );
        staker.notifyRewardAmount(amount);
    }

    function test_NotifyRewardAmount_RevertsWhenRewardBalanceInsufficient_SameTokenScenario() public {
        RegenStakerWithoutDelegateSurrogateVotes sameTokenStaker = _deployStakerFull(
            address(stakeToken),
            address(stakeToken),
            0,
            IAddressSet(address(0)),
            IAddressSet(address(0)),
            AccessMode.NONE
        );
        vm.prank(admin);
        sameTokenStaker.setRewardNotifier(rewardNotifier, true);

        uint256 stakeAmount = 500e18;
        stakeToken.mint(alice, stakeAmount);
        vm.startPrank(alice);
        stakeToken.approve(address(sameTokenStaker), type(uint256).max);
        sameTokenStaker.stake(stakeAmount, delegatee);
        vm.stopPrank();

        uint256 rewardAmount = 200e18;
        // currentBalance == stakeAmount (no extra funding); required == stakeAmount + rewardAmount
        // because same-token accounting includes totalStaked.
        vm.prank(rewardNotifier);
        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerWithoutDelegateSurrogateVotes.InsufficientRewardBalance.selector,
                stakeAmount,
                stakeAmount + rewardAmount
            )
        );
        sameTokenStaker.notifyRewardAmount(rewardAmount);
    }

    function test_NotifyRewardAmount_SucceedsWhenBalanceCoversStakeAndReward_SameTokenScenario() public {
        RegenStakerWithoutDelegateSurrogateVotes sameTokenStaker = _deployStakerFull(
            address(stakeToken),
            address(stakeToken),
            0,
            IAddressSet(address(0)),
            IAddressSet(address(0)),
            AccessMode.NONE
        );
        vm.prank(admin);
        sameTokenStaker.setRewardNotifier(rewardNotifier, true);

        uint256 stakeAmount = 500e18;
        stakeToken.mint(alice, stakeAmount);
        vm.startPrank(alice);
        stakeToken.approve(address(sameTokenStaker), type(uint256).max);
        sameTokenStaker.stake(stakeAmount, delegatee);
        vm.stopPrank();

        uint256 rewardAmount = 200e18;
        // Top up exactly enough for stake + reward to be covered.
        stakeToken.mint(address(sameTokenStaker), rewardAmount);

        vm.prank(rewardNotifier);
        sameTokenStaker.notifyRewardAmount(rewardAmount);

        assertEq(sameTokenStaker.totalRewards(), rewardAmount);
    }

    /*//////////////////////////////////////////////////////////////////
                                CLAIM REWARD
    //////////////////////////////////////////////////////////////////*/

    function test_ClaimReward_DistributesNotifiedRewardsOverDuration() public {
        uint256 stakeAmount = 100e18;
        vm.prank(alice);
        Staker.DepositIdentifier depositId = staker.stake(stakeAmount, delegatee);

        uint256 rewardAmount = 1_000e18;
        _notifyReward(rewardAmount);

        vm.warp(block.timestamp + REWARD_DURATION);

        uint256 unclaimed = staker.unclaimedReward(depositId);
        assertApproxEqAbs(unclaimed, rewardAmount, 1e12);

        vm.prank(alice);
        uint256 claimed = staker.claimReward(depositId);

        assertApproxEqAbs(claimed, rewardAmount, 1e12);
        assertEq(rewardToken.balanceOf(alice), claimed);
        assertEq(staker.totalClaimedRewards(), claimed);
    }

    function test_ClaimReward_PaysDesignatedClaimerNotOwner() public {
        vm.prank(alice);
        Staker.DepositIdentifier depositId = staker.stake(100e18, delegatee, claimer);

        _notifyReward(1_000e18);
        vm.warp(block.timestamp + REWARD_DURATION);

        vm.prank(claimer);
        uint256 claimed = staker.claimReward(depositId);

        assertGt(claimed, 0);
        assertEq(rewardToken.balanceOf(claimer), claimed);
        assertEq(rewardToken.balanceOf(alice), 0);
    }

    function test_ClaimReward_RevertsForAddressThatIsNotTheClaimer() public {
        vm.prank(alice);
        Staker.DepositIdentifier depositId = staker.stake(100e18, delegatee, claimer);

        _notifyReward(1_000e18);
        vm.warp(block.timestamp + REWARD_DURATION);

        vm.prank(bob);
        vm.expectRevert();
        staker.claimReward(depositId);
    }

    function test_AlterClaimer_RedirectsFutureRewardClaims() public {
        vm.startPrank(alice);
        Staker.DepositIdentifier depositId = staker.stake(100e18, delegatee);
        staker.alterClaimer(depositId, claimer);
        vm.stopPrank();

        _notifyReward(1_000e18);
        vm.warp(block.timestamp + REWARD_DURATION);

        vm.prank(claimer);
        uint256 claimed = staker.claimReward(depositId);

        assertGt(claimed, 0);
        assertEq(rewardToken.balanceOf(claimer), claimed);
    }

    /*//////////////////////////////////////////////////////////////////
                              BUMP EARNING POWER
    //////////////////////////////////////////////////////////////////*/

    function test_BumpEarningPower_PaysTipFromUnclaimedRewardsToTipReceiver() public {
        uint256 stakeAmount = 100e18;
        vm.prank(alice);
        Staker.DepositIdentifier depositId = staker.stake(stakeAmount, delegatee);

        _notifyReward(1_000e18);
        vm.warp(block.timestamp + REWARD_DURATION);

        // Simulate an external qualification change for alice's earning power.
        earningPowerCalculator.setOverride(alice, 40e18);

        address tipReceiver = makeAddr("tipReceiver");
        uint256 tip = 1e17;

        vm.prank(bob);
        staker.bumpEarningPower(depositId, tipReceiver, tip);

        assertEq(rewardToken.balanceOf(tipReceiver), tip);
    }

    /*//////////////////////////////////////////////////////////////////
                              ADMIN ACCESS CONTROL
    //////////////////////////////////////////////////////////////////*/

    function test_SetAdmin_RevertsForNonAdmin() public {
        vm.prank(alice);
        vm.expectRevert();
        staker.setAdmin(alice);
    }

    function test_SetAdmin_UpdatesAdminWhenCalledByAdmin() public {
        vm.prank(admin);
        staker.setAdmin(bob);
        assertEq(staker.admin(), bob);
    }

    function test_SetRewardNotifier_RevertsForNonAdmin() public {
        vm.prank(alice);
        vm.expectRevert();
        staker.setRewardNotifier(alice, true);
    }

    function test_SetMaxBumpTip_RevertsForNonAdmin() public {
        vm.prank(alice);
        vm.expectRevert();
        staker.setMaxBumpTip(2e18);
    }

    function test_SetMaxBumpTip_UpdatesWhenCalledByAdmin() public {
        vm.prank(admin);
        staker.setMaxBumpTip(2e18);
        assertEq(staker.maxBumpTip(), 2e18);
    }

    function test_SetEarningPowerCalculator_RevertsForNonAdmin() public {
        MockEarningPowerCalculator newCalc = new MockEarningPowerCalculator();

        vm.prank(alice);
        vm.expectRevert();
        staker.setEarningPowerCalculator(address(newCalc));
    }

    function test_SetEarningPowerCalculator_UpdatesWhenCalledByAdmin() public {
        MockEarningPowerCalculator newCalc = new MockEarningPowerCalculator();

        vm.prank(admin);
        staker.setEarningPowerCalculator(address(newCalc));

        assertEq(address(staker.earningPowerCalculator()), address(newCalc));
    }
}
