contract MorphoCompounderStrategyTest is Test {
    MockERC20 internal asset;
    MockCompounderVault internal vault;
    PermissiveTokenizedStrategyImpl internal tsImpl;
    MorphoCompounderStrategyHarness internal strategy;

    address internal management = address(0x1001);
    address internal keeper = address(0x1002);
    address internal emergencyAdmin = address(0x1003);
    address internal donationAddress = address(0x1004);

    function setUp() public {
        asset = new MockERC20();
        vault = new MockCompounderVault(address(asset));
        tsImpl = new PermissiveTokenizedStrategyImpl();

        strategy = new MorphoCompounderStrategyHarness(
            address(vault),
            address(asset),
            "Test Morpho Compounder Strategy",
            "tsMORPHO",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            address(tsImpl)
        );
    }

    /*//////////////////////////////////////////////////////////
                          CONSTRUCTOR
