        MockERC20 otherAsset = new MockERC20();
        MockCompounderVault mismatchedVault = new MockCompounderVault(address(otherAsset));

        vm.expectRevert(bytes("Asset mismatch with compounder vault"));
        new MorphoCompounderStrategyHarness(
            address(mismatchedVault),
            address(asset),
            "Bad Strategy",
            "BAD",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            address(tsImpl)
        );
    }

    /*//////////////////////////////////////////////////////////
                     availableDepositLimit
    //////////////////////////////////////////////////////////*/

    function test_availableDepositLimit_subtractsIdleBalance() public {
        vault.setMaxDeposit(1_000e18);
        asset.mint(address(strategy), 300e18);

        assertEq(strategy.availableDepositLimit(address(0)), 700e18);
    }

    function test_availableDepositLimit_returnsZeroWhenIdleExceedsVaultLimit() public {
        vault.setMaxDeposit(100e18);
        asset.mint(address(strategy), 300e18);

        assertEq(strategy.availableDepositLimit(address(0)), 0);
    }

    function test_availableDepositLimit_zeroIdleReturnsFullVaultLimit() public {
        vault.setMaxDeposit(1_000e18);

        assertEq(strategy.availableDepositLimit(address(0)), 1_000e18);
    }

    function test_availableDepositLimit_preservesInfiniteSentinel() public {
        vault.setMaxDeposit(type(uint256).max);
        asset.mint(address(strategy), 300e18);

        // Must NOT be clobbered into (type(uint256).max - idle).
        assertEq(strategy.availableDepositLimit(address(0)), type(uint256).max);
    }

    function testFuzz_availableDepositLimit(uint256 vaultLimit, uint256 idle) public {
        vaultLimit = bound(vaultLimit, 0, type(uint256).max - 1);
        idle = bound(idle, 0, type(uint128).max);

        vault.setMaxDeposit(vaultLimit);
        if (idle > 0) asset.mint(address(strategy), idle);

        uint256 expected = vaultLimit > idle ? vaultLimit - idle : 0;
        assertEq(strategy.availableDepositLimit(address(0)), expected);
    }

    /*//////////////////////////////////////////////////////////
                     availableWithdrawLimit
    //////////////////////////////////////////////////////////*/

    function test_availableWithdrawLimit_sumsIdleAndVaultMax() public {
        vault.setMaxWithdraw(500e18);
        asset.mint(address(strategy), 50e18);

        assertEq(strategy.availableWithdrawLimit(address(0)), 550e18);
    }

    function test_availableWithdrawLimit_overflowGuardReturnsMax() public {
        vault.setMaxWithdraw(type(uint256).max - 10);
        asset.mint(address(strategy), 20);

        assertEq(strategy.availableWithdrawLimit(address(0)), type(uint256).max);
    }

    function testFuzz_availableWithdrawLimit(uint256 vaultMax, uint256 idle) public {
        vaultMax = bound(vaultMax, 0, type(uint256).max);
        idle = bound(idle, 0, type(uint128).max);

        vault.setMaxWithdraw(vaultMax);
        if (idle > 0) asset.mint(address(strategy), idle);

        uint256 expected;
        if (vaultMax > type(uint256).max - idle) {
            expected = type(uint256).max;
        } else {
            expected = idle + vaultMax;
        }
        assertEq(strategy.availableWithdrawLimit(address(0)), expected);
    }

    /*//////////////////////////////////////////////////////////
                          _deployFunds
    //////////////////////////////////////////////////////////*/

    function test_deployFunds_depositsIntoVaultAndClearsAllowance() public {
        asset.mint(address(strategy), 1_000e18);

        strategy.exposed_deployFunds(1_000e18);

        assertEq(asset.balanceOf(address(vault)), 1_000e18);
        assertEq(asset.balanceOf(address(strategy)), 0);
        assertEq(vault.balanceOf(address(strategy)), 1_000e18);
        // Approval must be cleared after the deposit call, per natspec.
        assertEq(asset.allowance(address(strategy), address(vault)), 0);
    }

    function test_deployFunds_revertsOnZeroSharesMinted() public {
        asset.mint(address(strategy), 1_000e18);
        vault.setForceZeroShares(true);

        vm.expectRevert(bytes("MorphoCompounderStrategy: zero shares minted"));
        strategy.exposed_deployFunds(1_000e18);
    }

    function test_deployFunds_zeroAmountRevertsViaZeroShareGuard() public {
        // Depositing 0 assets yields 0 shares from the 1:1 mock, which must
        // trip the same zero-share guard as an explicit forced-zero vault.
        vm.expectRevert(bytes("MorphoCompounderStrategy: zero shares minted"));
        strategy.exposed_deployFunds(0);
    }

    function test_deployFunds_revertsOnInsufficientIdleBalance() public {
        vm.expectRevert(bytes("insufficient balance"));
        strategy.exposed_deployFunds(100e18);
    }

    function testFuzz_deployFunds_mintsSharesOneToOne(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        asset.mint(address(strategy), amount);

        strategy.exposed_deployFunds(amount);

        assertEq(vault.balanceOf(address(strategy)), amount);
        assertEq(asset.allowance(address(strategy), address(vault)), 0);
    }

    /*//////////////////////////////////////////////////////////
                          _freeFunds
    //////////////////////////////////////////////////////////*/

    function test_freeFunds_withdrawsFromVaultWithFullMaxLoss() public {
        asset.mint(address(vault), 500e18);
        vault.seedShares(address(strategy), 500e18);

        strategy.exposed_freeFunds(200e18);

        assertEq(asset.balanceOf(address(strategy)), 200e18);
        assertEq(vault.balanceOf(address(strategy)), 300e18);
        // _freeFunds must always request 100% max loss (10_000 bps) so
        // withdrawals never revert due to the caller's loss tolerance.
        assertEq(vault.lastWithdrawMaxLoss(), 10_000);
        assertEq(vault.withdrawCallCount(), 1);
    }

    function test_freeFunds_revertsWhenInsufficientShares() public {
        asset.mint(address(vault), 1_000e18);
        vault.seedShares(address(strategy), 100e18);

        vm.expectRevert(bytes("insufficient shares"));
        strategy.exposed_freeFunds(200e18);
    }

    /*//////////////////////////////////////////////////////////
                       _emergencyWithdraw
    //////////////////////////////////////////////////////////*/

    function test_emergencyWithdraw_delegatesToFreeFunds() public {
        asset.mint(address(vault), 500e18);
        vault.seedShares(address(strategy), 500e18);

        strategy.exposed_emergencyWithdraw(150e18);

        assertEq(asset.balanceOf(address(strategy)), 150e18);
        assertEq(vault.balanceOf(address(strategy)), 350e18);
        assertEq(vault.lastWithdrawMaxLoss(), 10_000);
        assertEq(vault.withdrawCallCount(), 1);
    }

    /*//////////////////////////////////////////////////////////
                       _harvestAndReport
    //////////////////////////////////////////////////////////*/

    function test_harvestAndReport_sumsVaultValueAndIdle() public {
        vault.seedShares(address(strategy), 400e18);
        asset.mint(address(strategy), 50e18);

        assertEq(strategy.exposed_harvestAndReport(), 450e18);
    }

    function test_harvestAndReport_zeroPositionReturnsIdleOnly() public {
        asset.mint(address(strategy), 42e18);

        assertEq(strategy.exposed_harvestAndReport(), 42e18);
    }

    function test_harvestAndReport_usesPreviewRedeemNotRawConversion() public {
        vault.seedShares(address(strategy), 400e18);
        // Simulate a vault that charges an exit fee: previewRedeem returns
        // less than a naive 1:1 convertToAssets would.
        vault.setPreviewRedeemOverride(380e18);

        assertEq(strategy.exposed_harvestAndReport(), 380e18);
    }

    function test_harvestAndReport_overflowGuardReturnsMax() public {
        vault.seedShares(address(strategy), 1);
        vault.setPreviewRedeemOverride(type(uint256).max);
        asset.mint(address(strategy), 10);

        assertEq(strategy.exposed_harvestAndReport(), type(uint256).max);
    }

    function testFuzz_harvestAndReport(uint256 vaultAssets, uint256 idle) public {
        vaultAssets = bound(vaultAssets, 0, type(uint256).max - 1);
        idle = bound(idle, 0, type(uint128).max);

        vault.seedShares(address(strategy), 1);
        vault.setPreviewRedeemOverride(vaultAssets);
        if (idle > 0) asset.mint(address(strategy), idle);

        uint256 expected =
            vaultAssets > type(uint256).max - idle ? type(uint256).max : vaultAssets + idle;
        assertEq(strategy.exposed_harvestAndReport(), expected);
    }
}
