// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import { Test } from "forge-std/Test.sol";
import { IERC20 } from "@openzeppelin/contracts/interfaces/IERC20.sol";
import { MorphoCompounderStrategy } from "src/strategies/yieldDonating/MorphoCompounderStrategy.sol";

/*//////////////////////////////////////////////////////////////
                            MOCKS
//////////////////////////////////////////////////////////////*/

/// @dev Minimal ERC20 mock. Deliberately does NOT `is IERC20` so that the
///      real strategy contract's `IERC20(asset)` casts only need matching
///      selectors, not full interface conformance.
contract MockERC20 {
    string public name = "Mock Asset";
    string public symbol = "mAST";
    uint8 public decimals = 18;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
        emit Transfer(address(0), to, amount);
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            require(allowed >= amount, "insufficient allowance");
            allowance[from][msg.sender] = allowed - amount;
        }
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(balanceOf[from] >= amount, "insufficient balance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
    }
}

/// @dev Stand-in for the external Morpho compounder vault. Exposes only the
///      subset of the ITokenizedStrategy surface that MorphoCompounderStrategy
///      actually calls, with configurable behaviour for edge-case testing.
contract MockCompounderVault {
    address public immutable assetAddr;

    mapping(address => uint256) public balanceOf;

    uint256 public maxDepositLimit = type(uint256).max;
    uint256 public maxWithdrawLimit = type(uint256).max;

    bool public forceZeroShares;
    bool public useOverridePreviewRedeem;
    uint256 public previewRedeemOverrideValue;

    uint256 public lastWithdrawMaxLoss;
    uint256 public withdrawCallCount;

    constructor(address _asset) {
        assetAddr = _asset;
    }

    function asset() external view returns (address) {
        return assetAddr;
    }

    function setMaxDeposit(uint256 v) external {
        maxDepositLimit = v;
    }

    function setMaxWithdraw(uint256 v) external {
        maxWithdrawLimit = v;
    }

    function setForceZeroShares(bool v) external {
        forceZeroShares = v;
    }

    function setPreviewRedeemOverride(uint256 v) external {
        previewRedeemOverrideValue = v;
        useOverridePreviewRedeem = true;
    }

    function seedShares(address owner, uint256 shares) external {
        balanceOf[owner] += shares;
    }

    function maxDeposit(address) external view returns (uint256) {
        return maxDepositLimit;
    }

    function maxWithdraw(address) external view returns (uint256) {
        return maxWithdrawLimit;
    }

    /// @dev 1:1 asset<->share accounting unless `forceZeroShares` is set.
    function deposit(uint256 assets, address receiver) external returns (uint256 shares) {
        IERC20(assetAddr).transferFrom(msg.sender, address(this), assets);
        shares = forceZeroShares ? 0 : assets;
        balanceOf[receiver] += shares;
    }

    /// @dev 1:1 asset<->share accounting; records the maxLoss argument so
    ///      tests can assert the strategy always requests 100% (10_000 bps).
    function withdraw(
        uint256 assets,
        address receiver,
        address owner,
        uint256 maxLoss
    ) external returns (uint256 shares) {
        lastWithdrawMaxLoss = maxLoss;
        withdrawCallCount += 1;

        shares = assets;
        require(balanceOf[owner] >= shares, "insufficient shares");
        balanceOf[owner] -= shares;

        IERC20(assetAddr).transfer(receiver, assets);
    }

    function previewRedeem(uint256 shares) external view returns (uint256) {
        if (useOverridePreviewRedeem) return previewRedeemOverrideValue;
        return shares;
    }
}

/// @dev Permissive stand-in for the `_tokenizedStrategyAddress` implementation
///      that BaseStrategy/BaseHealthCheck delegatecalls into during
///      construction (and would fall back to for un-overridden calls like
///      `deposit`/`report`/`balanceOf`). It accepts any calldata and returns
///      a large block of zeroed bytes so any `initialize(...)` selector and
///      return-decoding used by the real base contracts succeeds harmlessly.
///      Tests below never rely on this contract's dispatch producing
///      meaningful ERC-4626 share accounting — they exercise
///      MorphoCompounderStrategy's own directly-defined functions
///      (availableDepositLimit/availableWithdrawLimit) and its internal
///      hooks (via the harness below), none of which cross into this proxy.
contract PermissiveTokenizedStrategyImpl {
    fallback() external payable {
        assembly {
            // Freshly-touched memory is zero-initialized by the EVM, so
            // returning an untouched region yields a big buffer of zero
            // bytes without needing to explicitly zero it.
            let ptr := mload(0x40)
            return(ptr, 1024)
        }
    }

    receive() external payable { }
}

/*//////////////////////////////////////////////////////////////
                            HARNESS
//////////////////////////////////////////////////////////////*/

/// @dev Exposes MorphoCompounderStrategy's internal hooks directly. Because
///      these wrappers live in the same contract (via inheritance), calling
///      them does NOT go through BaseStrategy's fallback/delegatecall
///      dispatch — it's a normal internal call, so behaviour is identical to
///      how the real TokenizedStrategy would invoke these hooks, without
///      requiring a faithful reimplementation of that proxy machinery.
