import { IERC20 } from "@openzeppelin/contracts/interfaces/IERC20.sol";

/*//////////////////////////////////////////////////////////////
                            MOCKS
//////////////////////////////////////////////////////////////*/

contract MockERC20 is ERC20 {
    uint8 private immutable _dec;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _dec = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _dec;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Minimal stand-in for the shared "TokenizedStrategy" implementation contract that
///      BaseStrategy/BaseHealthCheck bootstrap their proxy storage against during construction.
///      Construction only cares that the low-level (delegate)call succeeds, not what it returns,
///      so a fallback that accepts and "succeeds" on any calldata is sufficient to let
///      MorphoCompounderStrategy deploy. None of the behaviour actually under test here
///      (`_deployFunds`, `_freeFunds`, `_harvestAndReport`, `_emergencyWithdraw`,
///      `availableDepositLimit`, `availableWithdrawLimit`) routes through this stub — those are
///      defined directly on MorphoCompounderStrategy.
contract AlwaysSucceedsStub {
    fallback() external payable {
        assembly {
            return(0, 1024)
        }
    }
}

/// @dev Fully-controllable mock of the Morpho compounder vault. Implements only the
///      ITokenizedStrategy surface that MorphoCompounderStrategy actually calls, with knobs to
///      simulate profit/loss, zero-share mints, capacity limits and downstream reverts.
contract MockCompounderVault {
    IERC20 public immutable assetToken;

    mapping(address => uint256) public balanceOf;
    uint256 public totalShares;

    uint256 public exchangeRate = 1e18; // assets per share, scaled by 1e18 (1e18 == 1:1)
    bool public zeroSharesMode;
    bool public revertOnDeposit;
    bool public revertOnWithdraw;

    bool public useMaxDepositOverride;
    uint256 public maxDepositOverride;

    bool public useMaxWithdrawOverride;
    uint256 public maxWithdrawOverride;

    bool public usePreviewRedeemOverride;
    uint256 public previewRedeemOverride;

    constructor(address _asset) {
        assetToken = IERC20(_asset);
    }

    function asset() external view returns (address) {
        return address(assetToken);
    }

    function maxDeposit(address) external view returns (uint256) {
        if (useMaxDepositOverride) return maxDepositOverride;
        return type(uint256).max;
    }

    function maxWithdraw(address owner) external view returns (uint256) {
        if (useMaxWithdrawOverride) return maxWithdrawOverride;
        return previewRedeem(balanceOf[owner]);
    }

    function deposit(uint256 assets, address receiver) external returns (uint256 shares) {
        require(!revertOnDeposit, "MockVault: deposit disabled");
        assetToken.transferFrom(msg.sender, address(this), assets);
        if (zeroSharesMode) {
            return 0;
        }
        shares = (assets * 1e18) / exchangeRate;
        balanceOf[receiver] += shares;
        totalShares += shares;
    }

    function withdraw(uint256 assets, address receiver, address owner, uint256 /*maxLoss*/ )
        external
        returns (uint256 sharesBurned)
    {
        require(!revertOnWithdraw, "MockVault: withdraw disabled");
        sharesBurned = (assets * 1e18) / exchangeRate;
        if (sharesBurned * exchangeRate < assets * 1e18) {
            sharesBurned += 1; // round up, mirroring a real vault's conservative burn
        }
        require(balanceOf[owner] >= sharesBurned, "MockVault: insufficient shares");
        balanceOf[owner] -= sharesBurned;
        totalShares -= sharesBurned;
        assetToken.transfer(receiver, assets);
    }

    function previewRedeem(uint256 shares) public view returns (uint256) {
        if (usePreviewRedeemOverride) return previewRedeemOverride;
        return (shares * exchangeRate) / 1e18;
    }

    // ---- test configuration helpers ----

    function setExchangeRate(uint256 rate) external {
        exchangeRate = rate;
    }

    function setZeroSharesMode(bool v) external {
        zeroSharesMode = v;
    }

    function setRevertOnDeposit(bool v) external {
        revertOnDeposit = v;
    }

    function setRevertOnWithdraw(bool v) external {
        revertOnWithdraw = v;
    }

    function setMaxDepositOverride(uint256 v) external {
        maxDepositOverride = v;
        useMaxDepositOverride = true;
    }

    function setMaxWithdrawOverride(uint256 v) external {
        maxWithdrawOverride = v;
        useMaxWithdrawOverride = true;
    }

    function setPreviewRedeemOverride(uint256 v) external {
        previewRedeemOverride = v;
        usePreviewRedeemOverride = true;
    }
}

/// @dev Exposes MorphoCompounderStrategy's internal hooks so they can be exercised directly and
///      in isolation, without needing to route deposit/withdraw/report calls through the
///      TokenizedStrategy proxy/fallback machinery.
contract MorphoCompounderStrategyHarness is MorphoCompounderStrategy {
    constructor(
        address _compounderVault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    )
        MorphoCompounderStrategy(
            _compounderVault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
