    function harness_deployFunds(uint256 _amount) external {
        _deployFunds(_amount);
    }

    function harness_freeFunds(uint256 _amount) external {
        _freeFunds(_amount);
    }

    function harness_harvestAndReport() external view returns (uint256) {
        return _harvestAndReport();
    }

    function harness_emergencyWithdraw(uint256 _amount) external {
        _emergencyWithdraw(_amount);
    }
}

