        idle = bound(idle, 0, type(uint128).max);

        vault.setPreviewRedeemReturn(vaultAssets);
        if (idle > 0) token.mint(address(harness), idle);

        uint256 expected = vaultAssets > type(uint256).max - idle ? type(uint256).max : vaultAssets + idle;
        assertEq(harness.exposed_harvestAndReport(), expected);
    }
