/// @dev Minimal ERC20 with a public mint, used as the underlying asset.
contract MockERC20 is ERC20 {
    constructor(string memory _name, string memory _symbol) ERC20(_name, _symbol) { }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Stand-in for the TokenizedStrategy implementation contract. It only
///      needs to have code deployed at its address so that any delegatecall
///      performed during construction of the strategy under test (as part of
///      the BaseHealthCheck / BaseStrategy initialization) succeeds trivially.
contract DummyTokenizedStrategy {
    fallback() external payable { }
    receive() external payable { }
}

/// @dev Configurable stand-in for a Morpho (ERC-4626-like) compounder vault.
///      Implements only the subset of ITokenizedStrategy that
///      MorphoCompounderStrategy actually calls, with knobs to force every
///      branch (sentinel max values, zero-share mints, partial withdrawals).
contract MockCompounderVault {
    address public assetAddr;

    uint256 public maxDepositReturn = type(uint256).max;
    uint256 public maxWithdrawReturn;
    uint256 public previewRedeemReturn;
    bool public forceZeroShares;

    bool public useWithdrawOverride;
    uint256 public withdrawReturnAmount;

    mapping(address => uint256) public balanceOf;

    // recorded call data for assertions
    uint256 public lastDepositAmount;
    address public lastDepositReceiver;
    uint256 public allowanceAtDepositTime;

    uint256 public lastWithdrawAmount;
    address public lastWithdrawReceiver;
    address public lastWithdrawOwner;
    uint256 public lastWithdrawMaxLoss;

    constructor(address _asset) {
        assetAddr = _asset;
    }

    function asset() external view returns (address) {
        return assetAddr;
    }

    function setMaxDeposit(uint256 v) external {
        maxDepositReturn = v;
    }

    function setMaxWithdraw(uint256 v) external {
        maxWithdrawReturn = v;
    }

    function setPreviewRedeemReturn(uint256 v) external {
        previewRedeemReturn = v;
    }

    function setForceZeroShares(bool v) external {
        forceZeroShares = v;
    }

    function setWithdrawOverride(bool use, uint256 amt) external {
        useWithdrawOverride = use;
        withdrawReturnAmount = amt;
    }

    function setBalance(address who, uint256 v) external {
        balanceOf[who] = v;
    }

    function maxDeposit(address) external view returns (uint256) {
        return maxDepositReturn;
    }

    function maxWithdraw(address) external view returns (uint256) {
        return maxWithdrawReturn;
    }

    function previewRedeem(uint256) external view returns (uint256) {
        return previewRedeemReturn;
    }

    function deposit(uint256 assets, address receiver) external returns (uint256 shares) {
        allowanceAtDepositTime = IERC20(assetAddr).allowance(msg.sender, address(this));
        lastDepositAmount = assets;
        lastDepositReceiver = receiver;

        require(IERC20(assetAddr).transferFrom(msg.sender, address(this), assets), "transferFrom failed");

        shares = forceZeroShares ? 0 : assets;
        balanceOf[receiver] += shares;
    }

    function withdraw(uint256 assets, address receiver, address owner, uint256 maxLoss) external returns (uint256 shares) {
        lastWithdrawAmount = assets;
        lastWithdrawReceiver = receiver;
        lastWithdrawOwner = owner;
        lastWithdrawMaxLoss = maxLoss;

        uint256 toSend = useWithdrawOverride ? withdrawReturnAmount : assets;
        if (toSend > 0) {
            require(IERC20(assetAddr).transfer(receiver, toSend), "transfer failed");
        }

        shares = assets;
        if (balanceOf[owner] >= shares) {
            balanceOf[owner] -= shares;
        } else {
            balanceOf[owner] = 0;
        }
    }
}

