// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.0;

import { Test } from "forge-std/Test.sol";
import { YearnV3Strategy } from "src/strategies/yieldDonating/YearnV3Strategy.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/interfaces/IERC20.sol";

/*//////////////////////////////////////////////////////////////////////
                                MOCKS
//////////////////////////////////////////////////////////////////////*/

/// @dev Simple mintable ERC20 used both as the strategy's underlying asset
///      and (with a different address) as a mismatched asset in negative tests.
contract MockERC20 is ERC20 {
    uint8 private immutable _customDecimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _customDecimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _customDecimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Minimal stand-in for the TokenizedStrategy implementation contract that
///      BaseHealthCheck's constructor delegatecalls into to initialize shared
///      accounting storage. It accepts any call and returns a zero-filled buffer
///      so the constructor's initialization delegatecall succeeds regardless of
///      the exact selector/calldata used, without needing the real periphery
///      source. It is never relied upon for behavior beyond allowing deployment
///      to succeed.
contract MockTokenizedStrategyImplementation {
    fallback(bytes calldata) external payable returns (bytes memory) {
        return new bytes(256);
    }

    receive() external payable {}
}

/// @dev Mock Yearn v3 vault implementing only the subset of the
///      ITokenizedStrategy surface that YearnV3Strategy actually calls:
///      asset, maxDeposit, maxWithdraw, deposit, withdraw, balanceOf, previewRedeem.
///      Share accounting is a simple 1:1-at-genesis internal vault so tests can
///      simulate profit/loss and force edge-case return values via overrides.
contract MockYearnVault {
    using SafeERC20 for IERC20;

    IERC20 public immutable assetToken;

    uint256 public totalShares;
    uint256 public totalAssetsHeld;
    mapping(address => uint256) public balanceOf;

    bool public useMaxDepositOverride;
    uint256 public maxDepositOverride;

    bool public useMaxWithdrawOverride;
    uint256 public maxWithdrawOverride;

    bool public usePreviewRedeemOverride;
    uint256 public previewRedeemOverride;

    bool public forceZeroShares;

    uint256 public lastMaxLoss;

    constructor(address _asset) {
        assetToken = IERC20(_asset);
    }

    function asset() external view returns (address) {
        return address(assetToken);
    }

    function maxDeposit(address) external view returns (uint256) {
        if (useMaxDepositOverride) return maxDepositOverride;
        return type(uint256).max;
    }

    function maxWithdraw(address owner_) external view returns (uint256) {
        if (useMaxWithdrawOverride) return maxWithdrawOverride;
        return _convertToAssets(balanceOf[owner_]);
    }

    function deposit(uint256 assets, address receiver) external returns (uint256 shares) {
        assetToken.safeTransferFrom(msg.sender, address(this), assets);
        shares = forceZeroShares ? 0 : _convertToShares(assets);
        balanceOf[receiver] += shares;
        totalShares += shares;
        totalAssetsHeld += assets;
    }

    function withdraw(
        uint256 assets,
        address receiver,
        address owner_,
        uint256 maxLoss
    ) external returns (uint256 sharesBurned) {
        lastMaxLoss = maxLoss;
        sharesBurned = _convertToShares(assets);
        if (sharesBurned > balanceOf[owner_]) sharesBurned = balanceOf[owner_];
        balanceOf[owner_] -= sharesBurned;
        totalShares -= sharesBurned;

        uint256 toSend = assets > totalAssetsHeld ? totalAssetsHeld : assets;
        totalAssetsHeld -= toSend;
        assetToken.safeTransfer(receiver, toSend);
    }

    function previewRedeem(uint256 shares) external view returns (uint256) {
        if (usePreviewRedeemOverride) return previewRedeemOverride;
        return _convertToAssets(shares);
    }

    /// @dev Simulates yield accrual/loss inside the vault, changing the share price.
    function simulateYield(int256 delta) external {
        if (delta >= 0) {
            totalAssetsHeld += uint256(delta);
        } else {
            uint256 loss = uint256(-delta);
            totalAssetsHeld = loss > totalAssetsHeld ? 0 : totalAssetsHeld - loss;
        }
    }

    function setMaxDeposit(uint256 v) external {
        maxDepositOverride = v;
        useMaxDepositOverride = true;
    }

    function clearMaxDepositOverride() external {
        useMaxDepositOverride = false;
    }

    function setMaxWithdraw(uint256 v) external {
        maxWithdrawOverride = v;
        useMaxWithdrawOverride = true;
    }

    function setPreviewRedeem(uint256 v) external {
        previewRedeemOverride = v;
        usePreviewRedeemOverride = true;
    }

    function setForceZeroShares(bool v) external {
        forceZeroShares = v;
    }

    function _convertToAssets(uint256 shares) internal view returns (uint256) {
        if (totalShares == 0) return shares;
        return (shares * totalAssetsHeld) / totalShares;
    }

    function _convertToShares(uint256 assets) internal view returns (uint256) {
        if (totalShares == 0 || totalAssetsHeld == 0) return assets;
        return (assets * totalShares) / totalAssetsHeld;
    }
}

