// ---------------------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------------------

contract YearnV3StrategyTest is Test {
    MockERC20 internal token;
    MockYearnVault internal vault;
    address internal tokenizedStrategyImpl;

    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal donationAddress = makeAddr("donationAddress");

    YearnV3StrategyHarness internal harness;

    function setUp() public {
        token = new MockERC20("Mock USDC", "mUSDC", 6);
        vault = new MockYearnVault(address(token));
        tokenizedStrategyImpl = address(new NoopFallback());

        harness = _deployHarness(address(vault), address(token));
    }

    function _deployHarness(address _vault, address _asset) internal returns (YearnV3StrategyHarness) {
        return new YearnV3StrategyHarness(
            _vault,
            _asset,
            "Test Yearn Strategy",
            "tYS",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyImpl
        );
    }

    // -------------------------------------------------------------------------------
    // Constructor
    // -------------------------------------------------------------------------------

    function test_Constructor_SetsImmutableYearnVault() public view {
        assertEq(harness.yearnVault(), address(vault), "yearnVault immutable not set correctly");
    }

    function test_Constructor_RevertsOnAssetMismatch() public {
        MockERC20 otherAsset = new MockERC20("Other", "OTH", 18);

        vm.expectRevert(bytes("Asset mismatch with compounder vault"));
        _deployHarness(address(vault), address(otherAsset));
    }

    // -------------------------------------------------------------------------------
    // availableDepositLimit
    // -------------------------------------------------------------------------------

    function test_AvailableDepositLimit_PreservesInfiniteSentinel() public {
        vault.setMaxDeposit(type(uint256).max);
        // Idle balance present should NOT clobber the sentinel.
        token.mint(address(harness), 1_000e6);

        assertEq(harness.availableDepositLimit(address(0)), type(uint256).max);
    }

    function test_AvailableDepositLimit_SubtractsIdleBalance() public {
        vault.setMaxDeposit(1_000e6);
        token.mint(address(harness), 300e6);

        assertEq(harness.availableDepositLimit(address(0)), 700e6);
    }

    function test_AvailableDepositLimit_ReturnsZero_WhenIdleEqualsVaultLimit() public {
        vault.setMaxDeposit(500e6);
        token.mint(address(harness), 500e6);

        assertEq(harness.availableDepositLimit(address(0)), 0);
    }

    function test_AvailableDepositLimit_ReturnsZero_WhenIdleExceedsVaultLimit() public {
        vault.setMaxDeposit(100e6);
        token.mint(address(harness), 500e6);

        assertEq(harness.availableDepositLimit(address(0)), 0);
    }

    function testFuzz_AvailableDepositLimit(uint256 vaultLimit, uint256 idle) public {
        vaultLimit = bound(vaultLimit, 0, type(uint128).max);
        idle = bound(idle, 0, type(uint128).max);

        vault.setMaxDeposit(vaultLimit);
        token.mint(address(harness), idle);

        uint256 expected = vaultLimit > idle ? vaultLimit - idle : 0;
        assertEq(harness.availableDepositLimit(address(0)), expected);
    }

    // -------------------------------------------------------------------------------
    // availableWithdrawLimit
    // -------------------------------------------------------------------------------

    function test_AvailableWithdrawLimit_SumsIdleAndVaultMax() public {
        vault.setMaxWithdraw(200e6);
        token.mint(address(harness), 50e6);

        assertEq(harness.availableWithdrawLimit(address(0)), 250e6);
    }

    function test_AvailableWithdrawLimit_ZeroWhenBothZero() public view {
        assertEq(harness.availableWithdrawLimit(address(0)), 0);
    }

    function test_AvailableWithdrawLimit_ReturnsMaxSentinel_OnOverflow() public {
        vault.setMaxWithdraw(type(uint256).max - 10);
        token.mint(address(harness), 20);

        assertEq(harness.availableWithdrawLimit(address(0)), type(uint256).max);
    }

    function test_AvailableWithdrawLimit_NoOverflow_ExactBoundary() public {
        vault.setMaxWithdraw(type(uint256).max - 10);
        token.mint(address(harness), 10);

        // idle == max - vaultMax exactly => sum == type(uint256).max, not the "overflow" branch,
        // but the arithmetic result is identical to the sentinel value.
        assertEq(harness.availableWithdrawLimit(address(0)), type(uint256).max);
    }

    function testFuzz_AvailableWithdrawLimit(uint256 vaultMax, uint256 idle) public {
        vault.setMaxWithdraw(vaultMax);
        idle = bound(idle, 0, type(uint128).max);
        token.mint(address(harness), idle);

        uint256 result = harness.availableWithdrawLimit(address(0));
        if (vaultMax > type(uint256).max - idle) {
            assertEq(result, type(uint256).max);
        } else {
            assertEq(result, idle + vaultMax);
        }
    }

    // -------------------------------------------------------------------------------
    // _deployFunds
    // -------------------------------------------------------------------------------

    function test_DeployFunds_DepositsIntoVaultAndClearsAllowance() public {
        uint256 amount = 1_000e6;
        token.mint(address(harness), amount);

        harness.exposed_deployFunds(amount);

        assertEq(token.balanceOf(address(harness)), 0, "idle balance should be deposited");
        assertEq(token.balanceOf(address(vault)), amount, "vault should hold deposited assets");
        assertEq(vault.balanceOf(address(harness)), amount, "strategy should be credited shares (1:1 mock)");
        assertEq(token.allowance(address(harness), address(vault)), 0, "allowance must be cleared after deposit");
    }

    function test_DeployFunds_RevertsOnZeroSharesMinted() public {
        uint256 amount = 1_000e6;
        token.mint(address(harness), amount);
        vault.setDepositSharesOverride(0);

        vm.expectRevert(bytes("YearnV3Strategy: zero shares minted"));
        harness.exposed_deployFunds(amount);
    }

    function test_DeployFunds_RevertsOnZeroSharesMinted_LeavesNoStandingAllowance() public {
        uint256 amount = 1_000e6;
        token.mint(address(harness), amount);
        vault.setDepositSharesOverride(0);

        vm.expectRevert(bytes("YearnV3Strategy: zero shares minted"));
        harness.exposed_deployFunds(amount);

        // Whole call reverted, so allowance/state changes from within _deployFunds are rolled back.
        assertEq(token.allowance(address(harness), address(vault)), 0);
        assertEq(token.balanceOf(address(harness)), amount);
    }

    // -------------------------------------------------------------------------------
    // _freeFunds / _emergencyWithdraw
    // -------------------------------------------------------------------------------

    function test_FreeFunds_WithdrawsFromVaultWithFullLossTolerance() public {
        uint256 amount = 1_000e6;
        token.mint(address(harness), amount);
        harness.exposed_deployFunds(amount);

        harness.exposed_freeFunds(amount);

        assertEq(token.balanceOf(address(harness)), amount, "assets should be returned to strategy");
        assertEq(vault.balanceOf(address(harness)), 0, "shares should be burned");
        assertEq(vault.lastWithdrawMaxLoss(), 10_000, "must accept 100% loss (10000 bps)");
        assertEq(vault.lastWithdrawReceiver(), address(harness));
        assertEq(vault.lastWithdrawOwner(), address(harness));
    }

    function test_FreeFunds_AcceptsPartialReturnOnVaultLoss() public {
        uint256 amount = 1_000e6;
        token.mint(address(harness), amount);
        harness.exposed_deployFunds(amount);

        // Simulate the target vault only returning half the requested assets (a loss),
        // which _freeFunds must not revert on since maxLoss=10000 is passed through.
        vault.setWithdrawAssetsOverride(amount / 2);

        harness.exposed_freeFunds(amount);

        assertEq(token.balanceOf(address(harness)), amount / 2, "only partial assets returned on loss");
    }

    function test_EmergencyWithdraw_DelegatesToFreeFundsWithFullLossTolerance() public {
        uint256 amount = 1_000e6;
        token.mint(address(harness), amount);
        harness.exposed_deployFunds(amount);

        harness.exposed_emergencyWithdraw(amount);

        assertEq(token.balanceOf(address(harness)), amount);
        assertEq(vault.balanceOf(address(harness)), 0);
        assertEq(vault.lastWithdrawMaxLoss(), 10_000, "emergency withdraw must also accept 100% loss");
    }

    // -------------------------------------------------------------------------------
    // _harvestAndReport
    // -------------------------------------------------------------------------------

    function test_HarvestAndReport_ReturnsZero_WhenEmpty() public view {
        assertEq(harness.exposed_harvestAndReport(), 0);
    }

    function test_HarvestAndReport_CountsIdleOnly() public {
        token.mint(address(harness), 123e6);
        assertEq(harness.exposed_harvestAndReport(), 123e6);
    }

    function test_HarvestAndReport_CountsVaultValuePlusIdle() public {
        uint256 deposited = 1_000e6;
        token.mint(address(harness), deposited);
        harness.exposed_deployFunds(deposited);

        // Simulate the vault having accrued yield: previewRedeem now returns more than deposited.
        vault.setPreviewRedeemOverride(1_100e6);

        // Leave some idle assets too.
        token.mint(address(harness), 50e6);

        assertEq(harness.exposed_harvestAndReport(), 1_150e6);
    }

    function test_HarvestAndReport_UsesPreviewRedeemNotConvertToAssets() public {
        uint256 deposited = 1_000e6;
        token.mint(address(harness), deposited);
        harness.exposed_deployFunds(deposited);

        // previewRedeem override simulates a fee-charging vault returning less than the naive
        // 1:1 convertToAssets-style value would suggest.
        vault.setPreviewRedeemOverride(900e6);

        assertEq(harness.exposed_harvestAndReport(), 900e6);
    }

    function test_HarvestAndReport_ReturnsMaxSentinel_OnOverflow() public {
        uint256 deposited = 1_000e6;
        token.mint(address(harness), deposited);
        harness.exposed_deployFunds(deposited);

        vault.setPreviewRedeemOverride(type(uint256).max - 10);
        token.mint(address(harness), 20);

        assertEq(harness.exposed_harvestAndReport(), type(uint256).max);
    }

    function testFuzz_HarvestAndReport(uint256 vaultAssets, uint256 idle) public {
        vaultAssets = bound(vaultAssets, 0, type(uint256).max);
        idle = bound(idle, 0, type(uint128).max);

        vault.setPreviewRedeemOverride(vaultAssets);
        token.mint(address(harness), idle);

        uint256 result = harness.exposed_harvestAndReport();
        if (vaultAssets > type(uint256).max - idle) {
            assertEq(result, type(uint256).max);
        } else {
            assertEq(result, vaultAssets + idle);
        }
    }
}
