        token.mint(address(harness), deposited);
        harness.exposed_deployFunds(deposited);

        // previewRedeem override simulates a fee-charging vault returning less than the naive
        // 1:1 convertToAssets-style value would suggest.
        vault.setPreviewRedeemOverride(900e6);

        assertEq(harness.exposed_harvestAndReport(), 900e6);
    }

    function test_HarvestAndReport_ReturnsMaxSentinel_OnOverflow() public {
        uint256 deposited = 1_000e6;
        token.mint(address(harness), deposited);
        harness.exposed_deployFunds(deposited);

        vault.setPreviewRedeemOverride(type(uint256).max - 10);
        token.mint(address(harness), 20);

        assertEq(harness.exposed_harvestAndReport(), type(uint256).max);
    }

    function testFuzz_HarvestAndReport(uint256 vaultAssets, uint256 idle) public {
        vaultAssets = bound(vaultAssets, 0, type(uint256).max);
        idle = bound(idle, 0, type(uint128).max);

        vault.setPreviewRedeemOverride(vaultAssets);
        token.mint(address(harness), idle);

        uint256 result = harness.exposed_harvestAndReport();
        if (vaultAssets > type(uint256).max - idle) {
            assertEq(result, type(uint256).max);
        } else {
            assertEq(result, vaultAssets + idle);
        }
    }
}

