// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.18;

/**
 * @title YearnV3StrategyTest
 * @notice Foundry unit tests for YearnV3Strategy.
 *
 * @dev Testing approach / assumptions:
 *      YearnV3Strategy inherits BaseHealthCheck, which (following the standard Yearn V3
 *      "tokenized strategy" pattern) forwards management/accounting calls via a fallback
 *      that `delegatecall`s into a shared `TokenizedStrategy` implementation contract whose
 *      address is passed into the constructor as `_tokenizedStrategyAddress`. Deploying a
 *      fully faithful TokenizedStrategy implementation is out of scope for unit-testing the
 *      logic that actually lives in YearnV3Strategy itself. Instead, these tests:
 *
 *        1. Use a no-op fallback stub as `_tokenizedStrategyAddress` so construction succeeds
 *           without requiring a full TokenizedStrategy re-implementation.
 *        2. Use a `Harness` contract that inherits YearnV3Strategy and exposes thin external
 *           wrappers around its `internal` functions (`_deployFunds`, `_freeFunds`,
 *           `_emergencyWithdraw`, `_harvestAndReport`) so they can be exercised directly.
 *        3. Test the `public` view overrides (`availableDepositLimit`, `availableWithdrawLimit`)
 *           directly, since they are defined on YearnV3Strategy itself and not proxied.
 *        4. Use a lightweight mock Yearn v3 vault implementing exactly the subset of
 *           `ITokenizedStrategy` that YearnV3Strategy calls (asset, maxDeposit, maxWithdraw,
 *           deposit, withdraw, balanceOf, previewRedeem), with overridable behavior so
 *           edge cases (zero shares, overflow sentinels, partial-loss withdrawals) can be
 *           deterministically forced.
 */

import { Test } from "forge-std/Test.sol";
import { IERC20 } from "@openzeppelin/contracts/interfaces/IERC20.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import { YearnV3Strategy } from "src/strategies/yieldDonating/YearnV3Strategy.sol";

// ---------------------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------------------

/// @notice Minimal mintable ERC20 used as the strategy's underlying asset.
contract MockERC20 is ERC20 {
    uint8 private immutable _decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _decimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @notice No-op fallback stub used as the `_tokenizedStrategyAddress` so that BaseHealthCheck's
///         constructor-time initialization call (delegatecall or otherwise) succeeds trivially.
contract NoopFallback {
    fallback() external payable {
        // intentionally does nothing, returns empty data, never reverts
    }

    receive() external payable {}
}

/// @notice Mock Yearn v3 vault implementing exactly the ITokenizedStrategy surface used by
///         YearnV3Strategy, with overridable behavior for deterministic edge-case testing.
contract MockYearnVault {
    IERC20 public immutable assetToken;

    mapping(address => uint256) public balanceOf;
    uint256 public totalShares;

    uint256 public maxDepositLimit = type(uint256).max;
    uint256 public maxWithdrawLimit = type(uint256).max;

    bool public overrideDepositShares;
    uint256 public depositSharesOverride;

    bool public overrideWithdrawAssets;
    uint256 public withdrawAssetsOverride;

    bool public overridePreviewRedeem;
    uint256 public previewRedeemOverrideValue;

    uint256 public lastWithdrawMaxLoss;
    address public lastWithdrawReceiver;
    address public lastWithdrawOwner;

    constructor(address _asset) {
        assetToken = IERC20(_asset);
    }

    function asset() external view returns (address) {
        return address(assetToken);
    }

    function maxDeposit(address) external view returns (uint256) {
        return maxDepositLimit;
    }

    function maxWithdraw(address) external view returns (uint256) {
        return maxWithdrawLimit;
    }

    function setMaxDeposit(uint256 v) external {
        maxDepositLimit = v;
    }

    function setMaxWithdraw(uint256 v) external {
        maxWithdrawLimit = v;
    }

    function setDepositSharesOverride(uint256 v) external {
        depositSharesOverride = v;
        overrideDepositShares = true;
    }

    function setWithdrawAssetsOverride(uint256 v) external {
        withdrawAssetsOverride = v;
        overrideWithdrawAssets = true;
    }

    function setPreviewRedeemOverride(uint256 v) external {
        previewRedeemOverrideValue = v;
        overridePreviewRedeem = true;
    }

    function deposit(uint256 assets, address receiver) external returns (uint256 shares) {
        require(assetToken.transferFrom(msg.sender, address(this), assets), "transferFrom failed");
        shares = overrideDepositShares ? depositSharesOverride : assets;
        balanceOf[receiver] += shares;
        totalShares += shares;
    }

    function withdraw(
        uint256 assets,
        address receiver,
        address owner,
        uint256 maxLoss
    ) external returns (uint256 sharesBurned) {
        lastWithdrawMaxLoss = maxLoss;
        lastWithdrawReceiver = receiver;
        lastWithdrawOwner = owner;

        sharesBurned = assets > balanceOf[owner] ? balanceOf[owner] : assets;
        balanceOf[owner] -= sharesBurned;
        totalShares -= sharesBurned;

        uint256 toSend = overrideWithdrawAssets ? withdrawAssetsOverride : assets;
        if (toSend > 0) {
            require(assetToken.transfer(receiver, toSend), "transfer failed");
        }
    }

    function previewRedeem(uint256 shares) external view returns (uint256) {
        if (overridePreviewRedeem) return previewRedeemOverrideValue;
        if (totalShares == 0) return 0;
        return (shares * assetToken.balanceOf(address(this))) / totalShares;
    }
}

/// @notice Exposes YearnV3Strategy's internal hooks for direct unit testing.
contract YearnV3StrategyHarness is YearnV3Strategy {
    constructor(
        address _yearnVault,
        address _asset,
        string memory _name,
        string memory _symbol,
        address _management,
        address _keeper,
        address _emergencyAdmin,
        address _donationAddress,
        bool _enableBurning,
        address _tokenizedStrategyAddress
    )
        YearnV3Strategy(
            _yearnVault,
            _asset,
            _name,
            _symbol,
            _management,
            _keeper,
            _emergencyAdmin,
            _donationAddress,
            _enableBurning,
            _tokenizedStrategyAddress
        )
    {}

    function exposed_deployFunds(uint256 amount) external {
        _deployFunds(amount);
    }

    function exposed_freeFunds(uint256 amount) external {
        _freeFunds(amount);
    }

    function exposed_emergencyWithdraw(uint256 amount) external {
        _emergencyWithdraw(amount);
    }

    function exposed_harvestAndReport() external view returns (uint256) {
        return _harvestAndReport();
    }
}

// ---------------------------------------------------------------------------------------
