        assertEq(harness.exposed_harvestAndReport(), type(uint256).max);
    }

    function testFuzz_HarvestAndReport(uint256 vaultAssets, uint256 idle) public {
        vaultAssets = bound(vaultAssets, 0, type(uint256).max);
        idle = bound(idle, 0, type(uint128).max);

        vault.setPreviewRedeemOverride(vaultAssets);
