// SPDX-License-Identifier: AGPL-3.0
pragma solidity ^0.8.0;

import { Test } from "forge-std/Test.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/interfaces/IERC20.sol";

import { YearnV3Strategy } from "src/strategies/yieldDonating/YearnV3Strategy.sol";
import { ITokenizedStrategy } from "src/core/interfaces/ITokenizedStrategy.sol";
// NOTE: this is the shared "logic" contract that BaseHealthCheck/BaseStrategy delegatecalls into
// (the standard Yearn V3 tokenized-strategy pattern). If the concrete implementation lives at a
// different path in this repo, update this single import accordingly.
import { TokenizedStrategy } from "src/core/TokenizedStrategy.sol";

/*//////////////////////////////////////////////////////////////
                            MOCK ASSET
//////////////////////////////////////////////////////////////*/

contract MockERC20 is ERC20 {
    uint8 private immutable _customDecimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _customDecimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _customDecimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/*//////////////////////////////////////////////////////////////
                       MOCK YEARN V3 VAULT
//////////////////////////////////////////////////////////////*/

/// @notice Minimal stand-in for the Yearn v3 vault the strategy deposits into.
/// @dev Implements exactly the surface `YearnV3Strategy` calls through `ITokenizedStrategy`:
///      asset, maxDeposit, maxWithdraw, deposit, withdraw, balanceOf, previewRedeem.
contract MockYearnVault {
    IERC20 public immutable assetToken;

    mapping(address => uint256) public balanceOf;
    uint256 public totalSupply;
    uint256 public totalAssets;

    uint256 public maxDepositLimit = type(uint256).max;
    bool public overrideMaxWithdraw;
    uint256 public maxWithdrawValue;
    bool public mintZeroShares;
    bool public rejectDeposits;

    constructor(address _asset) {
        assetToken = IERC20(_asset);
    }

    function asset() external view returns (address) {
        return address(assetToken);
    }

    function setMaxDeposit(uint256 _limit) external {
        maxDepositLimit = _limit;
    }

    function setMaxWithdrawOverride(uint256 _value) external {
        overrideMaxWithdraw = true;
        maxWithdrawValue = _value;
    }

    function setMintZeroShares(bool _flag) external {
        mintZeroShares = _flag;
    }

    function setRejectDeposits(bool _flag) external {
        rejectDeposits = _flag;
    }

    function maxDeposit(address) external view returns (uint256) {
        return maxDepositLimit;
    }

    function maxWithdraw(address _owner) external view returns (uint256) {
        if (overrideMaxWithdraw) return maxWithdrawValue;
        return _convertToAssets(balanceOf[_owner]);
    }

    function deposit(uint256 _assets, address _receiver) external returns (uint256 shares) {
        require(!rejectDeposits, "MockYearnVault: deposits rejected");
        assetToken.transferFrom(msg.sender, address(this), _assets);
        shares = mintZeroShares ? 0 : _convertToShares(_assets);
        balanceOf[_receiver] += shares;
        totalSupply += shares;
        totalAssets += _assets;
    }

    function withdraw(
        uint256 _assets,
        address _receiver,
        address _owner,
        uint256 /*_maxLoss*/
    ) external returns (uint256 sharesBurned) {
        sharesBurned = _convertToSharesRoundUp(_assets);
        uint256 ownerBalance = balanceOf[_owner];
        if (sharesBurned > ownerBalance) sharesBurned = ownerBalance;

        balanceOf[_owner] = ownerBalance - sharesBurned;
        totalSupply -= sharesBurned;

        uint256 assetsOut = _assets > totalAssets ? totalAssets : _assets;
        totalAssets -= assetsOut;
        assetToken.transfer(_receiver, assetsOut);
    }

    function previewRedeem(uint256 _shares) external view returns (uint256) {
        return _convertToAssets(_shares);
    }

    /// @notice Simulates yield accruing inside the Yearn vault (raises share price).
    function donateYield(uint256 _amount) external {
        assetToken.transferFrom(msg.sender, address(this), _amount);
        totalAssets += _amount;
    }

    /// @notice Simulates a loss inside the Yearn vault (lowers share price).
    function simulateLoss(uint256 _amount) external {
        require(_amount <= totalAssets, "MockYearnVault: loss exceeds assets");
        totalAssets -= _amount;
        assetToken.transfer(address(0xdEaD), _amount);
    }

    function _convertToShares(uint256 _assets) internal view returns (uint256) {
        if (totalSupply == 0 || totalAssets == 0) return _assets;
        return (_assets * totalSupply) / totalAssets;
    }

    function _convertToAssets(uint256 _shares) internal view returns (uint256) {
        if (totalSupply == 0) return _shares;
        return (_shares * totalAssets) / totalSupply;
    }

    function _convertToSharesRoundUp(uint256 _assets) internal view returns (uint256) {
        if (totalSupply == 0 || totalAssets == 0) return _assets;
        return (_assets * totalSupply + totalAssets - 1) / totalAssets;
