                            TEST SUITE
//////////////////////////////////////////////////////////////*/

contract YearnV3StrategyTest is Test {
    MockERC20 internal asset;
    MockYearnVault internal yearnVault;
    YearnV3Strategy internal strategyImpl;
    ITokenizedStrategy internal strategy;
    address internal tokenizedStrategyLogic;

    address internal management = makeAddr("management");
    address internal keeper = makeAddr("keeper");
    address internal emergencyAdmin = makeAddr("emergencyAdmin");
    address internal donationAddress = makeAddr("donationAddress");
    address internal user = makeAddr("user");
    address internal otherUser = makeAddr("otherUser");

    uint256 internal constant INITIAL_MINT = 1_000_000e6;

    function setUp() public {
        asset = new MockERC20("Mock USDC", "mUSDC", 6);
        yearnVault = new MockYearnVault(address(asset));
        tokenizedStrategyLogic = address(new TokenizedStrategy());

        strategyImpl = new YearnV3Strategy(
            address(yearnVault),
            address(asset),
            "Octant Yearn USDC Strategy",
            "osYearnUSDC",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyLogic
        );
        strategy = ITokenizedStrategy(address(strategyImpl));

        vm.label(address(asset), "asset");
        vm.label(address(yearnVault), "yearnVault");
        vm.label(address(strategyImpl), "strategy");
    }

    /*//////////////////////////////////////////////////////////
                         HELPERS
    //////////////////////////////////////////////////////////*/

    function _mintAndDeposit(address _depositor, uint256 _amount) internal returns (uint256 shares) {
        asset.mint(_depositor, _amount);
        vm.startPrank(_depositor);
        asset.approve(address(strategyImpl), _amount);
        shares = strategy.deposit(_amount, _depositor);
        vm.stopPrank();
    }

    /*//////////////////////////////////////////////////////////
                       CONSTRUCTOR TESTS
    //////////////////////////////////////////////////////////*/

    function test_constructor_setsYearnVault() public view {
        assertEq(strategyImpl.yearnVault(), address(yearnVault));
    }

    function test_constructor_setsAssetFromVault() public view {
        assertEq(strategy.asset(), address(asset));
    }

    function test_constructor_revertsOnAssetMismatch() public {
        MockERC20 otherAsset = new MockERC20("Other", "OTH", 18);
        MockYearnVault vaultOnOtherAsset = new MockYearnVault(address(otherAsset));

        vm.expectRevert("Asset mismatch with compounder vault");
        new YearnV3Strategy(
            address(vaultOnOtherAsset),
            address(asset),
            "Bad Strategy",
            "bad",
            management,
            keeper,
            emergencyAdmin,
            donationAddress,
            true,
            tokenizedStrategyLogic
        );
    }

    /*//////////////////////////////////////////////////////////
                    availableDepositLimit TESTS
    //////////////////////////////////////////////////////////*/

    function test_availableDepositLimit_subtractsIdleBalance() public {
        yearnVault.setMaxDeposit(1_000e6);
        asset.mint(address(strategyImpl), 200e6);

        assertEq(strategyImpl.availableDepositLimit(user), 800e6);
    }

    function test_availableDepositLimit_returnsZeroWhenIdleExceedsVaultLimit() public {
        yearnVault.setMaxDeposit(100e6);
        asset.mint(address(strategyImpl), 500e6);

        assertEq(strategyImpl.availableDepositLimit(user), 0);
    }

    function test_availableDepositLimit_preservesInfiniteSentinel() public {
        yearnVault.setMaxDeposit(type(uint256).max);
        asset.mint(address(strategyImpl), 123e6);

        assertEq(strategyImpl.availableDepositLimit(user), type(uint256).max);
    }

    function test_availableDepositLimit_noIdleBalance() public {
        yearnVault.setMaxDeposit(500e6);

        assertEq(strategyImpl.availableDepositLimit(user), 500e6);
    }

    /*//////////////////////////////////////////////////////////
                   availableWithdrawLimit TESTS
    //////////////////////////////////////////////////////////*/

    function test_availableWithdrawLimit_sumsIdleAndVaultMax() public {
        asset.mint(address(strategyImpl), 50e6);
        yearnVault.setMaxWithdrawOverride(150e6);

        assertEq(strategyImpl.availableWithdrawLimit(user), 200e6);
    }

    function test_availableWithdrawLimit_saturatesOnOverflow() public {
        asset.mint(address(strategyImpl), 10);
        yearnVault.setMaxWithdrawOverride(type(uint256).max - 1);

        assertEq(strategyImpl.availableWithdrawLimit(user), type(uint256).max);
    }

    function test_availableWithdrawLimit_zeroWhenEmpty() public view {
        assertEq(strategyImpl.availableWithdrawLimit(user), 0);
    }

    /*//////////////////////////////////////////////////////////
                        DEPOSIT / _deployFunds
    //////////////////////////////////////////////////////////*/

    function test_deposit_deploysFundsIntoYearnVault() public {
        uint256 amount = 1_000e6;
        _mintAndDeposit(user, amount);

        assertEq(asset.balanceOf(address(strategyImpl)), 0, "idle assets should be fully deployed");
        assertGt(yearnVault.balanceOf(address(strategyImpl)), 0, "strategy should hold yearn vault shares");
        assertEq(
            asset.allowance(address(strategyImpl), address(yearnVault)),
            0,
            "allowance should be cleared after deposit"
        );
    }

    function test_deposit_revertsWhenVaultMintsZeroShares() public {
        yearnVault.setMintZeroShares(true);

        asset.mint(user, 1_000e6);
        vm.startPrank(user);
        asset.approve(address(strategyImpl), 1_000e6);
        vm.expectRevert("YearnV3Strategy: zero shares minted");
        strategy.deposit(1_000e6, user);
        vm.stopPrank();
    }

    /*//////////////////////////////////////////////////////////
                       WITHDRAW / _freeFunds
    //////////////////////////////////////////////////////////*/

    function test_withdraw_freesFundsFromYearnVault() public {
        uint256 amount = 1_000e6;
        _mintAndDeposit(user, amount);

        uint256 vaultSharesBefore = yearnVault.balanceOf(address(strategyImpl));

        vm.prank(user);
        strategy.withdraw(400e6, user, user, 10_000);

        assertEq(asset.balanceOf(user), 400e6, "user should receive withdrawn assets");
        assertLt(yearnVault.balanceOf(address(strategyImpl)), vaultSharesBefore, "vault position should shrink");
    }

    function test_redeem_fullWithdrawalReturnsAllAssets() public {
        uint256 amount = 1_000e6;
        uint256 shares = _mintAndDeposit(user, amount);

        vm.prank(user);
        strategy.redeem(shares, user, user, 10_000);

        assertApproxEqAbs(asset.balanceOf(user), amount, 1);
    }

    /*//////////////////////////////////////////////////////////
                    REPORT / _harvestAndReport
    //////////////////////////////////////////////////////////*/

    function test_harvestAndReport_sumsIdleAndVaultAssets() public {
        uint256 amount = 1_000e6;
        _mintAndDeposit(user, amount);

        // leave some idle assets on the strategy directly (simulating a partial deploy)
        asset.mint(address(strategyImpl), 100e6);

        assertEq(strategy.totalAssets(), amount + 100e6);
    }

    function test_report_mintsProfitSharesToDonationAddress() public {
        uint256 amount = 10_000e6;
        _mintAndDeposit(user, amount);

        uint256 donationBalanceBefore = strategy.balanceOf(donationAddress);

        // simulate yield accruing inside the Yearn vault
        uint256 profitAmount = 500e6;
        asset.mint(address(this), profitAmount);
        asset.approve(address(yearnVault), profitAmount);
        yearnVault.donateYield(profitAmount);

        vm.prank(keeper);
        (uint256 profit, uint256 loss) = strategy.report();

        assertGt(profit, 0, "report should recognize donated yield as profit");
        assertEq(loss, 0);
        assertGt(strategy.balanceOf(donationAddress), donationBalanceBefore, "profit should be minted to donation address");
    }

    function test_report_revertsForNonKeeper() public {
        uint256 amount = 1_000e6;
        _mintAndDeposit(user, amount);

        vm.prank(otherUser);
        vm.expectRevert();
        strategy.report();
    }

    /*//////////////////////////////////////////////////////////
                      EMERGENCY WITHDRAW
    //////////////////////////////////////////////////////////*/

    function test_emergencyWithdraw_afterShutdownPullsFundsFromVault() public {
        uint256 amount = 1_000e6;
        _mintAndDeposit(user, amount);

        vm.prank(emergencyAdmin);
        strategy.shutdownStrategy();
        assertTrue(strategy.isShutdown());

        vm.prank(emergencyAdmin);
        strategy.emergencyWithdraw(amount);

        assertEq(asset.balanceOf(address(strategyImpl)), amount, "assets should be pulled back to idle");
    }

    function test_emergencyWithdraw_toleratesFullLossFromVault() public {
        uint256 amount = 1_000e6;
        _mintAndDeposit(user, amount);

        // simulate the Yearn vault losing all of the strategy's position
        yearnVault.simulateLoss(yearnVault.totalAssets());

        vm.prank(emergencyAdmin);
        strategy.shutdownStrategy();

        // should not revert even though the underlying vault suffered a 100% loss
        vm.prank(emergencyAdmin);
        strategy.emergencyWithdraw(amount);

        assertEq(asset.balanceOf(address(strategyImpl)), 0);
    }
}

