    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount, "insufficient balance");
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }
}

/// @notice Minimal interface used by the test harness to withdraw ERC20 tokens.
interface IERC20Like {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/// @notice Stand-in for `LinearAllowanceSingletonForGnosisSafe`. It intentionally does
/// NOT inherit from the real contract (whose internals are out of scope for this suite);
/// instead its address is explicitly cast to `LinearAllowanceSingletonForGnosisSafe` when
/// passed into `LinearAllowanceExecutor`. Solidity resolves such calls purely by selector,
/// so this works as long as the function signatures match the ones the executor actually
/// calls (which is all that `LinearAllowanceExecutor` can ever depend on).
contract MockAllowanceModule {
    // ---- executeAllowanceTransfer config/recording ----
    uint256 public transferReturnAmount;
    bool public revertOnExecute;

    address public lastSafe;
    address public lastToken;
    address public lastTo;
    address public lastCaller;
    uint256 public executeCallCount;

    // ---- executeAllowanceTransfers config/recording ----
    uint256[] public transfersReturnAmounts;
    bool public revertOnExecuteMultiple;
    uint256 public executeMultipleCallCount;
    address[] internal _lastSafes;
    address[] internal _lastTokens;
    address[] internal _lastTos;

    // ---- view-function config (getTotalUnspent / getMaxWithdrawableAmount) ----
    uint256 public constant SENTINEL = type(uint256).max;
    address public expectedSafe;
    address public expectedDelegate;
    address public expectedToken;
    uint256 public totalUnspentValue;
    uint256 public maxWithdrawableValue;

    receive() external payable {}

    function setTransferReturnAmount(uint256 amt) external {
        transferReturnAmount = amt;
    }

    function setRevertOnExecute(bool v) external {
        revertOnExecute = v;
    }

    function setTransfersReturnAmounts(uint256[] calldata amts) external {
        delete transfersReturnAmounts;
        for (uint256 i = 0; i < amts.length; i++) {
            transfersReturnAmounts.push(amts[i]);
        }
    }

    function setRevertOnExecuteMultiple(bool v) external {
        revertOnExecuteMultiple = v;
    }

    function setExpectedUnspentQuery(address safe, address delegate, address token, uint256 value) external {
        expectedSafe = safe;
        expectedDelegate = delegate;
        expectedToken = token;
        totalUnspentValue = value;
    }

    function setMaxWithdrawableValue(uint256 value) external {
        maxWithdrawableValue = value;
    }

    function executeAllowanceTransfer(address safe, address token, address payable to) external returns (uint256) {
        require(!revertOnExecute, "MockAllowanceModule: forced revert");
        lastSafe = safe;
        lastToken = token;
        lastTo = to;
        lastCaller = msg.sender;
        executeCallCount++;

        uint256 amount = transferReturnAmount;
        if (amount > 0) {
            if (token == address(0)) {
                (bool ok, ) = to.call{ value: amount }("");
                require(ok, "mock: eth send failed");
            } else {
                MockERC20(token).mint(to, amount);
            }
        }
        return amount;
    }

    function executeAllowanceTransfers(
        address[] calldata safes,
        address[] calldata tokens,
        address[] calldata tos
    ) external returns (uint256[] memory) {
        require(!revertOnExecuteMultiple, "MockAllowanceModule: forced revert multi");
        delete _lastSafes;
        delete _lastTokens;
        delete _lastTos;

        for (uint256 i = 0; i < safes.length; i++) {
            _lastSafes.push(safes[i]);
            _lastTokens.push(tokens[i]);
            _lastTos.push(tos[i]);

            if (i < transfersReturnAmounts.length && transfersReturnAmounts[i] > 0) {
                if (tokens[i] == address(0)) {
                    (bool ok, ) = payable(tos[i]).call{ value: transfersReturnAmounts[i] }("");
                    require(ok, "mock: eth send failed");
                } else {
                    MockERC20(tokens[i]).mint(tos[i], transfersReturnAmounts[i]);
                }
            }
        }
        executeMultipleCallCount++;
        return transfersReturnAmounts;
    }

    function getTotalUnspent(address safe, address delegate, address token) external view returns (uint256) {
        if (safe == expectedSafe && delegate == expectedDelegate && token == expectedToken) {
            return totalUnspentValue;
        }
        return SENTINEL;
    }

    function getMaxWithdrawableAmount(address safe, address delegate, address token) external view returns (uint256) {
        if (safe == expectedSafe && delegate == expectedDelegate && token == expectedToken) {
            return maxWithdrawableValue;
        }
        return SENTINEL;
    }

    function lastSafes() external view returns (address[] memory) {
        return _lastSafes;
    }

    function lastTokens() external view returns (address[] memory) {
        return _lastTokens;
    }

    function lastTos() external view returns (address[] memory) {
        return _lastTos;
    }
}

/// @notice Stand-in for an address-set contract. Cast to `IAddressSet` when passed to the
/// executor, so it only needs to satisfy the surface `_validateModule` actually calls.
contract MockAddressSet {
    mapping(address => bool) public isMember;

    function add(address a) external {
        isMember[a] = true;
    }

    function remove(address a) external {
        isMember[a] = false;
    }

    function contains(address a) external view returns (bool) {
        return isMember[a];
    }
}

/// @notice Minimal concrete implementation of the abstract executor, sufficient to exercise
/// all inherited/abstract behavior under test. Uses a trivial owner-gated access control
/// scheme and treats `address(0)` as the native-token sentinel for withdrawals.
contract TestLinearAllowanceExecutor is LinearAllowanceExecutor {
    address public owner;

    constructor(address _owner) {
        owner = _owner;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "TestExecutor: not owner");
        _;
    }

    function assignModuleAddressSet(IAddressSet addressSet) external override onlyOwner {
        _assignModuleAddressSet(addressSet);
    }

    function setModuleAccessMode(AccessMode mode) external override onlyOwner {
        _setModuleAccessMode(mode);
    }

    receive() external payable override {}

    function withdraw(address token, uint256 amount, address payable to) external override onlyOwner {
        if (token == address(0)) {
            (bool ok, ) = to.call{ value: amount }("");
            require(ok, "TestExecutor: eth withdraw failed");
        } else {
            require(IERC20Like(token).transfer(to, amount), "TestExecutor: token withdraw failed");
        }
    }
}

/*//////////////////////////////////////////////////////////////////////////
                                    TESTS
//////////////////////////////////////////////////////////////////////////*/

contract LinearAllowanceExecutorTest is Test {
    // Local mirrors of the events declared on LinearAllowanceExecutor, used only for
    // vm.expectEmit / emit comparisons.
    event ModuleAccessModeSet(AccessMode indexed mode);
    event ModuleAddressSetAssigned(IAddressSet indexed addressSet);

    TestLinearAllowanceExecutor internal executor;
    MockAllowanceModule internal module;
    MockAddressSet internal addressSet;
    MockERC20 internal token;

    address internal owner = makeAddr("owner");
    address internal stranger = makeAddr("stranger");
    address internal safe = makeAddr("safe");
    address internal recipient = makeAddr("recipient");

    address internal constant NATIVE = address(0);

    function setUp() public {
        vm.prank(owner);
        executor = new TestLinearAllowanceExecutor(owner);

        module = new MockAllowanceModule();
        addressSet = new MockAddressSet();
        token = new MockERC20();
    }

    function _module() internal view returns (LinearAllowanceSingletonForGnosisSafe) {
        return LinearAllowanceSingletonForGnosisSafe(address(module));
    }

    /*//////////////////////////////////////////////////////////////////
                                DEFAULT STATE
    //////////////////////////////////////////////////////////////////*/

    function test_defaultState_isNoneModeWithNoAddressSet() public view {
        assertEq(uint8(executor.moduleAccessMode()), uint8(AccessMode.NONE));
        assertEq(address(executor.moduleAddressSet()), address(0));
    }

    /*//////////////////////////////////////////////////////////////////
                        assignModuleAddressSet / setModuleAccessMode
    //////////////////////////////////////////////////////////////////*/

    function test_assignModuleAddressSet_setsStateAndEmits() public {
        vm.expectEmit(true, false, false, true, address(executor));
        emit ModuleAddressSetAssigned(IAddressSet(address(addressSet)));

        vm.prank(owner);
        executor.assignModuleAddressSet(IAddressSet(address(addressSet)));

        assertEq(address(executor.moduleAddressSet()), address(addressSet));
    }

    function test_assignModuleAddressSet_revertsForNonOwner() public {
        vm.prank(stranger);
        vm.expectRevert(bytes("TestExecutor: not owner"));
        executor.assignModuleAddressSet(IAddressSet(address(addressSet)));
    }

    function test_setModuleAccessMode_setsStateAndEmits() public {
        vm.expectEmit(true, false, false, true, address(executor));
        emit ModuleAccessModeSet(AccessMode.ALLOWSET);

        vm.prank(owner);
        executor.setModuleAccessMode(AccessMode.ALLOWSET);

        assertEq(uint8(executor.moduleAccessMode()), uint8(AccessMode.ALLOWSET));
    }

    function test_setModuleAccessMode_revertsForNonOwner() public {
        vm.prank(stranger);
        vm.expectRevert(bytes("TestExecutor: not owner"));
        executor.setModuleAccessMode(AccessMode.BLOCKSET);
    }

    /*//////////////////////////////////////////////////////////////////
                        _validateModule via executeAllowanceTransfer
    //////////////////////////////////////////////////////////////////*/

    function test_validateModule_noneMode_allowsAnyModuleEvenWithNoAddressSet() public {
        // moduleAccessMode defaults to NONE and moduleAddressSet defaults to address(0);
        // this must not attempt to call .contains() on the zero address.
        uint256 amount = executor.executeAllowanceTransfer(_module(), safe, NATIVE);
        assertEq(amount, 0);
        assertEq(module.executeCallCount(), 1);
    }

    function test_validateModule_allowset_allowsListedModule() public {
        addressSet.add(address(module));

        vm.prank(owner);
        executor.assignModuleAddressSet(IAddressSet(address(addressSet)));
        vm.prank(owner);
        executor.setModuleAccessMode(AccessMode.ALLOWSET);

        executor.executeAllowanceTransfer(_module(), safe, NATIVE);
        assertEq(module.executeCallCount(), 1);
    }

    function test_validateModule_allowset_revertsForUnlistedModule() public {
        vm.prank(owner);
        executor.assignModuleAddressSet(IAddressSet(address(addressSet)));
        vm.prank(owner);
        executor.setModuleAccessMode(AccessMode.ALLOWSET);

        vm.expectRevert(abi.encodeWithSelector(NotInAllowset.selector, address(module)));
        executor.executeAllowanceTransfer(_module(), safe, NATIVE);
    }

    function test_validateModule_blockset_revertsForListedModule() public {
        addressSet.add(address(module));

        vm.prank(owner);
        executor.assignModuleAddressSet(IAddressSet(address(addressSet)));
        vm.prank(owner);
        executor.setModuleAccessMode(AccessMode.BLOCKSET);

        vm.expectRevert(abi.encodeWithSelector(InBlockset.selector, address(module)));
        executor.executeAllowanceTransfer(_module(), safe, NATIVE);
    }

    function test_validateModule_blockset_allowsUnlistedModule() public {
        vm.prank(owner);
        executor.assignModuleAddressSet(IAddressSet(address(addressSet)));
        vm.prank(owner);
        executor.setModuleAccessMode(AccessMode.BLOCKSET);

        executor.executeAllowanceTransfer(_module(), safe, NATIVE);
        assertEq(module.executeCallCount(), 1);
    }

    /*//////////////////////////////////////////////////////////////////
                            executeAllowanceTransfer
    //////////////////////////////////////////////////////////////////*/

    function test_executeAllowanceTransfer_forwardsParamsAndForcesRecipientToSelf() public {
        executor.executeAllowanceTransfer(_module(), safe, address(token));

        assertEq(module.lastSafe(), safe);
        assertEq(module.lastToken(), address(token));
        assertEq(module.lastTo(), address(executor));
        assertEq(module.lastCaller(), address(executor));
    }

    function test_executeAllowanceTransfer_returnsModuleAmountAndMovesEth() public {
        uint256 amount = 3 ether;
        module.setTransferReturnAmount(amount);
        vm.deal(address(module), amount);

        uint256 returned = executor.executeAllowanceTransfer(_module(), safe, NATIVE);

        assertEq(returned, amount);
        assertEq(address(executor).balance, amount);
    }

    function test_executeAllowanceTransfer_returnsModuleAmountAndMovesErc20() public {
        uint256 amount = 1_000e18;
        module.setTransferReturnAmount(amount);

        uint256 returned = executor.executeAllowanceTransfer(_module(), safe, address(token));

        assertEq(returned, amount);
        assertEq(token.balanceOf(address(executor)), amount);
    }

    function test_executeAllowanceTransfer_revertsWhenModuleReverts() public {
        module.setRevertOnExecute(true);

        vm.expectRevert(bytes("MockAllowanceModule: forced revert"));
        executor.executeAllowanceTransfer(_module(), safe, NATIVE);
    }

    function testFuzz_executeAllowanceTransfer_erc20AmountPassThrough(uint96 amount) public {
        module.setTransferReturnAmount(amount);

        uint256 returned = executor.executeAllowanceTransfer(_module(), safe, address(token));

        assertEq(returned, amount);
        assertEq(token.balanceOf(address(executor)), amount);
    }

    /*//////////////////////////////////////////////////////////////////
                            executeAllowanceTransfers
    //////////////////////////////////////////////////////////////////*/

    function test_executeAllowanceTransfers_forcesAllRecipientsToSelf() public {
        address[] memory safes = new address[](2);
        safes[0] = safe;
        safes[1] = makeAddr("safe2");

        address[] memory tokens = new address[](2);
        tokens[0] = NATIVE;
        tokens[1] = address(token);

        uint256[] memory amounts = new uint256[](2);
        amounts[0] = 1 ether;
        amounts[1] = 500e18;
        module.setTransfersReturnAmounts(amounts);
        vm.deal(address(module), amounts[0]);

        uint256[] memory returned = executor.executeAllowanceTransfers(_module(), safes, tokens);

        assertEq(returned.length, 2);
        assertEq(returned[0], amounts[0]);
        assertEq(returned[1], amounts[1]);

        address[] memory tos = module.lastTos();
        assertEq(tos.length, 2);
        assertEq(tos[0], address(executor));
        assertEq(tos[1], address(executor));

        assertEq(address(executor).balance, amounts[0]);
        assertEq(token.balanceOf(address(executor)), amounts[1]);
    }

    function test_executeAllowanceTransfers_forwardsSafesAndTokens() public {
        address[] memory safes = new address[](2);
        safes[0] = makeAddr("safeA");
        safes[1] = makeAddr("safeB");

        address[] memory tokens = new address[](2);
        tokens[0] = address(token);
        tokens[1] = NATIVE;

        executor.executeAllowanceTransfers(_module(), safes, tokens);

        address[] memory recordedSafes = module.lastSafes();
        address[] memory recordedTokens = module.lastTokens();
        assertEq(recordedSafes[0], safes[0]);
        assertEq(recordedSafes[1], safes[1]);
        assertEq(recordedTokens[0], tokens[0]);
        assertEq(recordedTokens[1], tokens[1]);
    }

    function test_executeAllowanceTransfers_revertsWhenModuleReverts() public {
        module.setRevertOnExecuteMultiple(true);

        address[] memory safes = new address[](1);
        safes[0] = safe;
        address[] memory tokens = new address[](1);
        tokens[0] = NATIVE;

        vm.expectRevert(bytes("MockAllowanceModule: forced revert multi"));
        executor.executeAllowanceTransfers(_module(), safes, tokens);
    }

    function test_executeAllowanceTransfers_revertsOnMismatchedArrayLengths() public {
        address[] memory safes = new address[](2);
        safes[0] = safe;
        safes[1] = makeAddr("safe2");
        address[] memory tokens = new address[](1);
        tokens[0] = NATIVE;

        vm.expectRevert(stdError.indexOOBError);
        executor.executeAllowanceTransfers(_module(), safes, tokens);
    }

    function test_executeAllowanceTransfers_appliesModuleValidation() public {
        vm.prank(owner);
        executor.assignModuleAddressSet(IAddressSet(address(addressSet)));
        vm.prank(owner);
        executor.setModuleAccessMode(AccessMode.ALLOWSET);

        address[] memory safes = new address[](1);
        safes[0] = safe;
        address[] memory tokens = new address[](1);
        tokens[0] = NATIVE;

        vm.expectRevert(abi.encodeWithSelector(NotInAllowset.selector, address(module)));
        executor.executeAllowanceTransfers(_module(), safes, tokens);
    }

    /*//////////////////////////////////////////////////////////////////
                                getTotalUnspent
    //////////////////////////////////////////////////////////////////*/

    function test_getTotalUnspent_passesExecutorAsDelegateAndReturnsValue() public {
        module.setExpectedUnspentQuery(safe, address(executor), address(token), 42e18);

        uint256 unspent = executor.getTotalUnspent(_module(), safe, address(token));
        assertEq(unspent, 42e18);
    }

    function test_getTotalUnspent_doesNotUseCallerAsDelegate() public {
        // Expectation is keyed on address(executor), never on the calling EOA/contract.
        module.setExpectedUnspentQuery(safe, address(this), address(token), 1e18);

        uint256 unspent = executor.getTotalUnspent(_module(), safe, address(token));
        assertEq(unspent, module.SENTINEL());
    }

    /*//////////////////////////////////////////////////////////////////
                            getMaxWithdrawableAmount
    //////////////////////////////////////////////////////////////////*/

    function test_getMaxWithdrawableAmount_passesExecutorAsDelegateAndReturnsValue() public {
        module.setExpectedUnspentQuery(safe, address(executor), NATIVE, 7 ether);
        module.setMaxWithdrawableValue(7 ether);

        uint256 max = executor.getMaxWithdrawableAmount(_module(), safe, NATIVE);
        assertEq(max, 7 ether);
    }

    /*//////////////////////////////////////////////////////////////////
                                receive / withdraw
    //////////////////////////////////////////////////////////////////*/

    function test_receive_acceptsPlainEthTransfers() public {
        (bool ok, ) = address(executor).call{ value: 1 ether }("");
        assertTrue(ok);
        assertEq(address(executor).balance, 1 ether);
    }

    function test_withdraw_eth_byOwner() public {
        vm.deal(address(executor), 2 ether);

        vm.prank(owner);
        executor.withdraw(NATIVE, 1 ether, payable(recipient));

        assertEq(recipient.balance, 1 ether);
        assertEq(address(executor).balance, 1 ether);
    }

    function test_withdraw_erc20_byOwner() public {
        token.mint(address(executor), 100e18);

        vm.prank(owner);
        executor.withdraw(address(token), 40e18, payable(recipient));

        assertEq(token.balanceOf(recipient), 40e18);
        assertEq(token.balanceOf(address(executor)), 60e18);
    }

    function test_withdraw_revertsForNonOwner() public {
        vm.deal(address(executor), 1 ether);

        vm.prank(stranger);
        vm.expectRevert(bytes("TestExecutor: not owner"));
        executor.withdraw(NATIVE, 1 ether, payable(recipient));
    }
}

