    address public owner;

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    function assignModuleAddressSet(IAddressSet addressSet) external override onlyOwner {
        _assignModuleAddressSet(addressSet);
    }

    function setModuleAccessMode(AccessMode mode) external override onlyOwner {
        _setModuleAccessMode(mode);
    }

    receive() external payable override {}

    function withdraw(address token, uint256 amount, address payable to) external override onlyOwner {
        if (token == address(0)) {
            (bool ok, ) = to.call{ value: amount }("");
            require(ok, "eth transfer failed");
        } else {
            require(MockERC20(token).transfer(to, amount), "token transfer failed");
        }
    }
}

/// ------------------------------------------------------------------------
/// Tests
/// ------------------------------------------------------------------------

contract LinearAllowanceExecutorTest is Test {
    TestableExecutor internal executor;
    MockAllowanceModule internal mockModule;
    MockAddressSet internal mockAddressSet;
    MockERC20 internal mockToken;

    address internal nonOwner = address(0xBEEF);
    address internal safe1 = address(0x5AFE1);
    address internal safe2 = address(0x5AFE2);

    event ModuleAccessModeSet(AccessMode indexed mode);
    event ModuleAddressSetAssigned(IAddressSet indexed addressSet);

    function setUp() public {
        executor = new TestableExecutor(); // test contract == owner
        mockModule = new MockAllowanceModule();
        mockAddressSet = new MockAddressSet();
        mockToken = new MockERC20();

        mockModule.setExpectedDelegate(address(executor));
    }

    function _module() internal view returns (LinearAllowanceSingletonForGnosisSafe) {
        return LinearAllowanceSingletonForGnosisSafe(address(mockModule));
    }

    /// ---------------------------------------------------------------
    /// Initial state
    /// ---------------------------------------------------------------

    function test_InitialState() public view {
        assertEq(uint256(executor.moduleAccessMode()), uint256(AccessMode.NONE));
        assertEq(address(executor.moduleAddressSet()), address(0));
    }

    /// ---------------------------------------------------------------
    /// setModuleAccessMode
    /// ---------------------------------------------------------------

    function test_SetModuleAccessMode_None() public {
        vm.expectEmit(true, false, false, true, address(executor));
        emit ModuleAccessModeSet(AccessMode.NONE);
        executor.setModuleAccessMode(AccessMode.NONE);
        assertEq(uint256(executor.moduleAccessMode()), uint256(AccessMode.NONE));
    }

    function test_SetModuleAccessMode_Allowset() public {
        vm.expectEmit(true, false, false, true, address(executor));
        emit ModuleAccessModeSet(AccessMode.ALLOWSET);
        executor.setModuleAccessMode(AccessMode.ALLOWSET);
        assertEq(uint256(executor.moduleAccessMode()), uint256(AccessMode.ALLOWSET));
    }

    function test_SetModuleAccessMode_Blockset() public {
        vm.expectEmit(true, false, false, true, address(executor));
        emit ModuleAccessModeSet(AccessMode.BLOCKSET);
        executor.setModuleAccessMode(AccessMode.BLOCKSET);
        assertEq(uint256(executor.moduleAccessMode()), uint256(AccessMode.BLOCKSET));
    }

    function test_SetModuleAccessMode_RevertsForNonOwner() public {
        vm.prank(nonOwner);
        vm.expectRevert(bytes("not owner"));
        executor.setModuleAccessMode(AccessMode.ALLOWSET);
    }

    /// ---------------------------------------------------------------
    /// assignModuleAddressSet
    /// ---------------------------------------------------------------

    function test_AssignModuleAddressSet_UpdatesStateAndEmits() public {
        vm.expectEmit(true, false, false, true, address(executor));
        emit ModuleAddressSetAssigned(IAddressSet(address(mockAddressSet)));
        executor.assignModuleAddressSet(IAddressSet(address(mockAddressSet)));
        assertEq(address(executor.moduleAddressSet()), address(mockAddressSet));
    }

    function test_AssignModuleAddressSet_RevertsForNonOwner() public {
        vm.prank(nonOwner);
        vm.expectRevert(bytes("not owner"));
        executor.assignModuleAddressSet(IAddressSet(address(mockAddressSet)));
    }

    /// ---------------------------------------------------------------
    /// _validateModule (via executeAllowanceTransfer)
    /// ---------------------------------------------------------------

    function test_ValidateModule_NoneMode_AllowsAnyModule() public {
        // Even a module present in the (unused) address set is allowed under NONE.
        mockAddressSet.setContains(address(mockModule), true);
        executor.assignModuleAddressSet(IAddressSet(address(mockAddressSet)));
        executor.setModuleAccessMode(AccessMode.NONE);

        mockModule.setSingleReturnAmount(0);
        uint256 amount = executor.executeAllowanceTransfer(_module(), safe1, address(0));
        assertEq(amount, 0);
    }

    function test_ValidateModule_AllowsetMode_AllowsListedModule() public {
        mockAddressSet.setContains(address(mockModule), true);
        executor.assignModuleAddressSet(IAddressSet(address(mockAddressSet)));
        executor.setModuleAccessMode(AccessMode.ALLOWSET);

        uint256 amount = executor.executeAllowanceTransfer(_module(), safe1, address(0));
        assertEq(amount, 0);
    }

    function test_ValidateModule_AllowsetMode_RevertsForUnlistedModule() public {
        mockAddressSet.setContains(address(mockModule), false);
        executor.assignModuleAddressSet(IAddressSet(address(mockAddressSet)));
        executor.setModuleAccessMode(AccessMode.ALLOWSET);

        vm.expectRevert(abi.encodeWithSelector(NotInAllowset.selector, address(mockModule)));
        executor.executeAllowanceTransfer(_module(), safe1, address(0));
