    function test_ValidateModule_BlocksetMode_AllowsUnlistedModule() public {
        mockAddressSet.setContains(address(mockModule), false);
        executor.assignModuleAddressSet(IAddressSet(address(mockAddressSet)));
        executor.setModuleAccessMode(AccessMode.BLOCKSET);

        uint256 amount = executor.executeAllowanceTransfer(_module(), safe1, address(0));
        assertEq(amount, 0);
