        mockAddressSet.setContains(address(mockModule), true);
        executor.assignModuleAddressSet(IAddressSet(address(mockAddressSet)));
        executor.setModuleAccessMode(AccessMode.BLOCKSET);

        vm.expectRevert(abi.encodeWithSelector(InBlockset.selector, address(mockModule)));
        executor.executeAllowanceTransfer(_module(), safe1, address(0));
    }

