        mockAddressSet.setContains(address(mockModule), false);
        executor.assignModuleAddressSet(IAddressSet(address(mockAddressSet)));
        executor.setModuleAccessMode(AccessMode.ALLOWSET);

        address[] memory safes = new address[](1);
        safes[0] = safe1;
        address[] memory tokens = new address[](1);
        tokens[0] = address(0);

        vm.expectRevert(abi.encodeWithSelector(NotInAllowset.selector, address(mockModule)));
        executor.executeAllowanceTransfers(_module(), safes, tokens);
    }

    /// ---------------------------------------------------------------
    /// executeAllowanceTransfer
    /// ---------------------------------------------------------------

    function test_ExecuteAllowanceTransfer_ETH_Success() public {
        uint256 amount = 1 ether;
        vm.deal(address(mockModule), amount);
        mockModule.setSingleReturnAmount(amount);

        uint256 returned = executor.executeAllowanceTransfer(_module(), safe1, address(0));

        assertEq(returned, amount);
        assertEq(address(executor).balance, amount);
        assertEq(address(mockModule).balance, 0);
        assertEq(mockModule.lastSafe(), safe1);
        assertEq(mockModule.lastToken(), address(0));
        assertEq(mockModule.lastTo(), address(executor));
        assertEq(mockModule.lastDelegate(), address(executor));
    }

