        uint256 amount = 500e18;
        mockToken.mint(address(mockModule), amount);
        mockModule.setSingleReturnAmount(amount);

        uint256 returned = executor.executeAllowanceTransfer(_module(), safe1, address(mockToken));

        assertEq(returned, amount);
        assertEq(mockToken.balanceOf(address(executor)), amount);
        assertEq(mockToken.balanceOf(address(mockModule)), 0);
        assertEq(mockModule.lastToken(), address(mockToken));
    }

