        safes[0] = safe1;
        safes[1] = safe2;

        address[] memory tokens = new address[](2);
        tokens[0] = address(0);
        tokens[1] = address(mockToken);

        uint256 ethAmount = 0.5 ether;
        uint256 tokenAmount = 100e18;

        vm.deal(address(mockModule), ethAmount);
        mockToken.mint(address(mockModule), tokenAmount);

        uint256[] memory amounts = new uint256[](2);
        amounts[0] = ethAmount;
        amounts[1] = tokenAmount;
        mockModule.setMultiReturnAmounts(amounts);

        uint256[] memory returned = executor.executeAllowanceTransfers(_module(), safes, tokens);

        assertEq(returned.length, 2);
        assertEq(returned[0], ethAmount);
        assertEq(returned[1], tokenAmount);
        assertEq(address(executor).balance, ethAmount);
        assertEq(mockToken.balanceOf(address(executor)), tokenAmount);
    }

    function test_ExecuteAllowanceTransfers_ForcesAllRecipientsToSelf() public {
        address[] memory safes = new address[](2);
        safes[0] = safe1;
        safes[1] = safe2;

        address[] memory tokens = new address[](2);
        tokens[0] = address(0);
        tokens[1] = address(mockToken);

        executor.executeAllowanceTransfers(_module(), safes, tokens);

        assertEq(mockModule.lastTos(0), address(executor));
        assertEq(mockModule.lastTos(1), address(executor));
    }

