    }

    /// ---------------------------------------------------------------
    /// receive()
    /// ---------------------------------------------------------------

    function test_Receive_AcceptsETH() public {
        vm.deal(address(this), 1 ether);
        (bool ok, ) = address(executor).call{ value: 1 ether }("");
        assertTrue(ok);
        assertEq(address(executor).balance, 1 ether);
    }

    /// ---------------------------------------------------------------
    /// withdraw
    /// ---------------------------------------------------------------

    function test_Withdraw_ETH_Success() public {
        vm.deal(address(executor), 1 ether);
        address payable recipient = payable(address(0xCAFE));

        executor.withdraw(address(0), 0.4 ether, recipient);

        assertEq(recipient.balance, 0.4 ether);
        assertEq(address(executor).balance, 0.6 ether);
    }

    function test_Withdraw_ERC20_Success() public {
        mockToken.mint(address(executor), 1000e18);
        address payable recipient = payable(address(0xCAFE));

        executor.withdraw(address(mockToken), 300e18, recipient);

        assertEq(mockToken.balanceOf(recipient), 300e18);
        assertEq(mockToken.balanceOf(address(executor)), 700e18);
    }

    function test_Withdraw_RevertsForNonOwner() public {
        vm.deal(address(executor), 1 ether);
        vm.prank(nonOwner);
        vm.expectRevert(bytes("not owner"));
        executor.withdraw(address(0), 0.1 ether, payable(nonOwner));
    }
}

