// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

import { Test } from "forge-std/Test.sol";

import { LinearAllowanceExecutor } from "src/zodiac-core/LinearAllowanceExecutor.sol";
import { LinearAllowanceSingletonForGnosisSafe } from "src/zodiac-core/modules/LinearAllowanceSingletonForGnosisSafe.sol";
import { IAddressSet } from "src/utils/IAddressSet.sol";
import { NotInAllowset, InBlockset } from "src/errors.sol";
import { AccessMode } from "src/constants.sol";

/// ------------------------------------------------------------------------
/// Test doubles
/// ------------------------------------------------------------------------

/// @dev Minimal ERC20 used to exercise token transfer paths without pulling
/// in an external dependency. Deliberately unguarded (mint is unrestricted)
/// since it only ever exists inside the test environment.
contract MockERC20 {
    string public name = "Mock Token";
    string public symbol = "MTK";
    uint8 public decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
}

/// @dev Stand-in for `LinearAllowanceSingletonForGnosisSafe`. `LinearAllowanceExecutor`
/// only ever interacts with the module through the four functions below, so this
/// mock only needs to match those selectors byte-for-byte. Instances of this
/// contract are explicitly cast to `LinearAllowanceSingletonForGnosisSafe` at the
/// call site in tests -- the cast is purely a compile-time type annotation, the
/// bytecode actually executed is this mock's.
contract MockAllowanceModule {
    // -- executeAllowanceTransfer config/records --
    uint256 public singleReturnAmount;
    bool public shouldRevertSingle;
    address public lastSafe;
    address public lastToken;
    address public lastTo;
    address public lastDelegate;

    // -- executeAllowanceTransfers config/records --
    uint256[] public multiReturnAmounts;
    bool public shouldRevertMulti;
    address[] public lastSafes;
    address[] public lastTokens;
    address[] public lastTos;

    // -- view getters config --
    uint256 public totalUnspentReturn;
    uint256 public maxWithdrawableReturn;
    address public expectedDelegate;

    receive() external payable {}

    function setSingleReturnAmount(uint256 amt) external {
        singleReturnAmount = amt;
    }

    function setShouldRevertSingle(bool v) external {
        shouldRevertSingle = v;
    }

    function setShouldRevertMulti(bool v) external {
        shouldRevertMulti = v;
    }

    function setMultiReturnAmounts(uint256[] calldata amts) external {
        delete multiReturnAmounts;
        for (uint256 i = 0; i < amts.length; i++) {
            multiReturnAmounts.push(amts[i]);
        }
    }

    function setTotalUnspentReturn(uint256 v) external {
        totalUnspentReturn = v;
    }

    function setMaxWithdrawableReturn(uint256 v) external {
        maxWithdrawableReturn = v;
    }

    function setExpectedDelegate(address d) external {
        expectedDelegate = d;
    }

    function executeAllowanceTransfer(address safe, address token, address payable to) external returns (uint256) {
        require(!shouldRevertSingle, "mock: forced revert");
        lastSafe = safe;
        lastToken = token;
        lastTo = to;
        lastDelegate = msg.sender;

        uint256 amount = singleReturnAmount;
        if (amount > 0) {
            _sendFunds(token, to, amount);
        }
        return amount;
    }

    function executeAllowanceTransfers(
        address[] calldata safes,
        address[] calldata tokens,
        address[] calldata tos
    ) external returns (uint256[] memory) {
        require(!shouldRevertMulti, "mock: forced revert");
        delete lastSafes;
        delete lastTokens;
        delete lastTos;

        uint256[] memory amounts = new uint256[](safes.length);
        for (uint256 i = 0; i < safes.length; i++) {
            lastSafes.push(safes[i]);
            lastTokens.push(tokens[i]);
            lastTos.push(tos[i]);

            uint256 amt = i < multiReturnAmounts.length ? multiReturnAmounts[i] : 0;
            amounts[i] = amt;
            if (amt > 0) {
                _sendFunds(tokens[i], tos[i], amt);
            }
        }
        lastDelegate = msg.sender;
        return amounts;
    }

    function getTotalUnspent(address, address delegate, address) external view returns (uint256) {
        require(delegate == expectedDelegate, "mock: unexpected delegate");
        return totalUnspentReturn;
    }

    function getMaxWithdrawableAmount(address, address delegate, address) external view returns (uint256) {
        require(delegate == expectedDelegate, "mock: unexpected delegate");
        return maxWithdrawableReturn;
    }

    function _sendFunds(address token, address to, uint256 amount) internal {
        if (token == address(0)) {
            (bool ok, ) = to.call{ value: amount }("");
            require(ok, "mock: eth send failed");
        } else {
            require(MockERC20(token).transfer(to, amount), "mock: token send failed");
        }
    }
}

/// @dev Simple owner-gated address set backing store, matching the single
/// `contains(address) -> bool` selector that `_validateModule` relies on.
contract MockAddressSet {
    mapping(address => bool) private _contains;

    function setContains(address addr, bool val) external {
        _contains[addr] = val;
    }

    function contains(address addr) external view returns (bool) {
        return _contains[addr];
    }
}

/// @dev Minimal concrete implementation of the abstract executor, restricted
/// to the deployer ("owner") for the admin-only entry points, so access
/// control behavior can be exercised.
contract TestableExecutor is LinearAllowanceExecutor {
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    function assignModuleAddressSet(IAddressSet addressSet) external override onlyOwner {
        _assignModuleAddressSet(addressSet);
    }

    function setModuleAccessMode(AccessMode mode) external override onlyOwner {
        _setModuleAccessMode(mode);
    }

    receive() external payable override {}

    function withdraw(address token, uint256 amount, address payable to) external override onlyOwner {
        if (token == address(0)) {
            (bool ok, ) = to.call{ value: amount }("");
            require(ok, "eth transfer failed");
        } else {
            require(MockERC20(token).transfer(to, amount), "token transfer failed");
        }
    }
}

