// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

import { Test } from "forge-std/Test.sol";

import { LinearAllowanceExecutor } from "src/zodiac-core/LinearAllowanceExecutor.sol";
import { LinearAllowanceSingletonForGnosisSafe } from "src/zodiac-core/modules/LinearAllowanceSingletonForGnosisSafe.sol";
import { IAddressSet } from "src/utils/IAddressSet.sol";
import { NotInAllowset, InBlockset } from "src/errors.sol";
import { AccessMode } from "src/constants.sol";

/// @dev Minimal ERC20 used only to exercise ERC20 fund flows into the executor.
contract MockERC20 {
    mapping(address => uint256) public balanceOf;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "MockERC20: insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

/// @dev Minimal address-set stand-in. Only `contains` is invoked by `_validateModule`,
/// so we do not need to fully implement IAddressSet - the address is cast to the
/// interface type at the call site, and Solidity dispatches purely on selector/ABI.
contract MockAddressSet {
    mapping(address => bool) public isMember;

    function setMember(address account, bool member) external {
        isMember[account] = member;
    }

    function contains(address account) external view returns (bool) {
        return isMember[account];
    }
}

/// @dev Stand-in for LinearAllowanceSingletonForGnosisSafe implementing exactly the four
/// external functions that LinearAllowanceExecutor calls, with matching signatures
/// (inferred directly from the call sites in the contract under test, which had to
/// type-check against the real module). Cast to LinearAllowanceSingletonForGnosisSafe
/// when used, exactly like the executor does.
contract MockAllowanceModule {
    // -- single transfer bookkeeping --
    address public lastSafeSingle;
    address public lastTokenSingle;
    address public lastToSingle;
    uint256 public callCountSingle;
    uint256 public singleReturnAmount;
    bool public revertSingle;
    bool public sendEthOnTransfer;
    address public erc20ToSendOnTransfer;

    // -- batch transfer bookkeeping --
    address[] public lastSafesBatch;
    address[] public lastTokensBatch;
    address[] public lastTosBatch;
    uint256 public callCountBatch;
    uint256[] public batchReturnAmounts;
    bool public revertBatch;

    // -- view getters --
    address public expectedSafeForUnspent;
    address public expectedDelegateForUnspent;
    address public expectedTokenForUnspent;
    uint256 public unspentReturn;

    address public expectedSafeForMaxWithdrawable;
    address public expectedDelegateForMaxWithdrawable;
    address public expectedTokenForMaxWithdrawable;
    uint256 public maxWithdrawableReturn;

    receive() external payable {}

    // -- configuration --

    function setSingleReturnAmount(uint256 amount) external {
        singleReturnAmount = amount;
    }

    function setBatchReturnAmounts(uint256[] calldata amounts) external {
        delete batchReturnAmounts;
        for (uint256 i = 0; i < amounts.length; i++) {
            batchReturnAmounts.push(amounts[i]);
        }
    }

    function setRevertSingle(bool r) external {
        revertSingle = r;
    }

    function setRevertBatch(bool r) external {
        revertBatch = r;
    }

    function setSendEthOnTransfer(bool s) external {
        sendEthOnTransfer = s;
    }

    function setErc20ToSendOnTransfer(address token) external {
        erc20ToSendOnTransfer = token;
    }

    function setUnspentExpectation(address safe, address delegate, address token, uint256 ret) external {
        expectedSafeForUnspent = safe;
        expectedDelegateForUnspent = delegate;
        expectedTokenForUnspent = token;
        unspentReturn = ret;
    }

    function setMaxWithdrawableExpectation(address safe, address delegate, address token, uint256 ret) external {
        expectedSafeForMaxWithdrawable = safe;
        expectedDelegateForMaxWithdrawable = delegate;
        expectedTokenForMaxWithdrawable = token;
        maxWithdrawableReturn = ret;
    }

    function lastTosBatchLength() external view returns (uint256) {
        return lastTosBatch.length;
    }

    function lastTosBatchAt(uint256 i) external view returns (address) {
        return lastTosBatch[i];
    }

    // -- functions matching LinearAllowanceSingletonForGnosisSafe's ABI --

    function executeAllowanceTransfer(address safe, address token, address payable to) external returns (uint256) {
        require(!revertSingle, "MockAllowanceModule: forced revert");
        lastSafeSingle = safe;
        lastTokenSingle = token;
        lastToSingle = to;
        callCountSingle++;

        if (sendEthOnTransfer && singleReturnAmount > 0) {
            (bool ok,) = to.call{ value: singleReturnAmount }("");
            require(ok, "MockAllowanceModule: eth send failed");
        }
        if (erc20ToSendOnTransfer != address(0) && singleReturnAmount > 0) {
            MockERC20(erc20ToSendOnTransfer).transfer(to, singleReturnAmount);
        }
        token; // silence unused-var warning when neither branch above applies
        return singleReturnAmount;
    }

    function executeAllowanceTransfers(address[] calldata safes, address[] calldata tokens, address[] calldata tos)
        external
        returns (uint256[] memory)
    {
        require(!revertBatch, "MockAllowanceModule: forced revert");
        delete lastSafesBatch;
        delete lastTokensBatch;
        delete lastTosBatch;
        for (uint256 i = 0; i < safes.length; i++) {
            lastSafesBatch.push(safes[i]);
        }
        for (uint256 i = 0; i < tokens.length; i++) {
            lastTokensBatch.push(tokens[i]);
        }
        for (uint256 i = 0; i < tos.length; i++) {
            lastTosBatch.push(tos[i]);
        }
        callCountBatch++;
        return batchReturnAmounts;
    }

    function getTotalUnspent(address safe, address delegate, address token) external view returns (uint256) {
        require(
            safe == expectedSafeForUnspent && delegate == expectedDelegateForUnspent
                && token == expectedTokenForUnspent,
            "MockAllowanceModule: unexpected getTotalUnspent args"
        );
        return unspentReturn;
    }

    function getMaxWithdrawableAmount(address safe, address delegate, address token) external view returns (uint256) {
        require(
            safe == expectedSafeForMaxWithdrawable && delegate == expectedDelegateForMaxWithdrawable
                && token == expectedTokenForMaxWithdrawable,
            "MockAllowanceModule: unexpected getMaxWithdrawableAmount args"
        );
        return maxWithdrawableReturn;
    }
}

/// @dev Concrete harness implementing the abstract hooks left to derived contracts.
/// No access control is added here on purpose: LinearAllowanceExecutor itself does not
/// enforce any, leaving that to inheriting contracts, and these tests target the base
/// contract's own logic.
contract ExecutorHarness is LinearAllowanceExecutor {
    receive() external payable override {}

    function assignModuleAddressSet(IAddressSet addressSet) external override {
        _assignModuleAddressSet(addressSet);
    }

    function setModuleAccessMode(AccessMode mode) external override {
        _setModuleAccessMode(mode);
    }

    function withdraw(address token, uint256 amount, address payable to) external override {
        if (token == address(0)) {
            (bool ok,) = to.call{ value: amount }("");
            require(ok, "ExecutorHarness: eth withdraw failed");
        } else {
            require(MockERC20(token).transfer(to, amount), "ExecutorHarness: erc20 withdraw failed");
        }
    }
}

contract LinearAllowanceExecutorTest is Test {
    // Redeclared with identical signatures so vm.expectEmit / emit works without
    // inheriting the (abstract) contract under test.
