        if (inSet) {
            vm.expectRevert(abi.encodeWithSelector(InBlockset.selector, address(mockModuleImpl)));
            harness.executeAllowanceTransfer(module, safe, erc20);
        } else {
            uint256 amount = harness.executeAllowanceTransfer(module, safe, erc20);
