    }

    // ----------------------------------------------------------------
    // executeAllowanceTransfer
    // ----------------------------------------------------------------

    function test_ExecuteAllowanceTransfer_ForwardsArgsAndForcesRecipientToSelf() public {
        mockModuleImpl.setSingleReturnAmount(123);

