        mockModuleImpl.setErc20ToSendOnTransfer(address(token));
        mockModuleImpl.setSingleReturnAmount(50 ether);

        uint256 amount = harness.executeAllowanceTransfer(module, safe, address(token));

        assertEq(amount, 50 ether);
        assertEq(token.balanceOf(address(harness)), 50 ether);
    }

    // ----------------------------------------------------------------
    // executeAllowanceTransfers (batch)
    // ----------------------------------------------------------------

    function test_ExecuteAllowanceTransfers_ForcesEveryRecipientToSelf() public {
        address[] memory safes = new address[](3);
        safes[0] = makeAddr("safe0");
        safes[1] = makeAddr("safe1");
        safes[2] = makeAddr("safe2");

        address[] memory tokens = new address[](3);
        tokens[0] = makeAddr("token0");
        tokens[1] = makeAddr("token1");
        tokens[2] = makeAddr("token2");

        uint256[] memory presetAmounts = new uint256[](3);
        presetAmounts[0] = 1;
        presetAmounts[1] = 2;
        presetAmounts[2] = 3;
        mockModuleImpl.setBatchReturnAmounts(presetAmounts);

        uint256[] memory amounts = harness.executeAllowanceTransfers(module, safes, tokens);

        assertEq(amounts.length, 3);
        assertEq(amounts[0], 1);
        assertEq(amounts[1], 2);
        assertEq(amounts[2], 3);

        assertEq(mockModuleImpl.lastTosBatchLength(), 3);
        for (uint256 i = 0; i < 3; i++) {
            assertEq(mockModuleImpl.lastTosBatchAt(i), address(harness));
            assertEq(mockModuleImpl.lastSafesBatch(i), safes[i]);
            assertEq(mockModuleImpl.lastTokensBatch(i), tokens[i]);
        }
        assertEq(mockModuleImpl.callCountBatch(), 1);
    }

    function test_ExecuteAllowanceTransfers_ValidatesModuleBeforeCalling() public {
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.ALLOWSET);
        mockSetImpl.setMember(address(mockModuleImpl), false);

        address[] memory safes = new address[](1);
        safes[0] = safe;
        address[] memory tokens = new address[](1);
        tokens[0] = erc20;

        vm.expectRevert(abi.encodeWithSelector(NotInAllowset.selector, address(mockModuleImpl)));
        harness.executeAllowanceTransfers(module, safes, tokens);
        assertEq(mockModuleImpl.callCountBatch(), 0);
    }

    function test_ExecuteAllowanceTransfers_BubblesUpModuleRevert() public {
        mockModuleImpl.setRevertBatch(true);
        address[] memory safes = new address[](1);
        safes[0] = safe;
        address[] memory tokens = new address[](1);
        tokens[0] = erc20;

        vm.expectRevert(bytes("MockAllowanceModule: forced revert"));
        harness.executeAllowanceTransfers(module, safes, tokens);
    }

    function test_ExecuteAllowanceTransfers_DoesNotValidateArrayLengths() public {
        // safes and tokens intentionally have mismatched lengths; the executor itself
        // performs no length validation (that responsibility belongs to the module).
        address[] memory safes = new address[](3);
        safes[0] = makeAddr("s0");
        safes[1] = makeAddr("s1");
        safes[2] = makeAddr("s2");

        address[] memory tokens = new address[](1);
        tokens[0] = erc20;

        harness.executeAllowanceTransfers(module, safes, tokens);

        assertEq(mockModuleImpl.lastTosBatchLength(), 3);
        for (uint256 i = 0; i < 3; i++) {
            assertEq(mockModuleImpl.lastTosBatchAt(i), address(harness));
        }
    }

    function test_ExecuteAllowanceTransfers_EmptyArrays() public {
        address[] memory safes = new address[](0);
        address[] memory tokens = new address[](0);

        uint256[] memory amounts = harness.executeAllowanceTransfers(module, safes, tokens);
        assertEq(amounts.length, 0);
        assertEq(mockModuleImpl.lastTosBatchLength(), 0);
        assertEq(mockModuleImpl.callCountBatch(), 1);
    }

    // ----------------------------------------------------------------
    // getTotalUnspent / getMaxWithdrawableAmount
    // ----------------------------------------------------------------

    function test_GetTotalUnspent_ForwardsSelfAsDelegate() public {
        mockModuleImpl.setUnspentExpectation(safe, address(harness), erc20, 42);
        uint256 unspent = harness.getTotalUnspent(module, safe, erc20);
        assertEq(unspent, 42);
    }

    function test_GetTotalUnspent_DoesNotValidateModule() public {
        // ALLOWSET with the module excluded from the set - view getters must still work,
        // since only executeAllowanceTransfer(s) invoke _validateModule.
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.ALLOWSET);
        mockSetImpl.setMember(address(mockModuleImpl), false);

        mockModuleImpl.setUnspentExpectation(safe, address(harness), erc20, 77);
        uint256 unspent = harness.getTotalUnspent(module, safe, erc20);
        assertEq(unspent, 77);
    }

    function test_GetMaxWithdrawableAmount_ForwardsSelfAsDelegate() public {
        mockModuleImpl.setMaxWithdrawableExpectation(safe, address(harness), erc20, 999);
        uint256 max = harness.getMaxWithdrawableAmount(module, safe, erc20);
        assertEq(max, 999);
    }

    function test_GetMaxWithdrawableAmount_DoesNotValidateModule() public {
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.BLOCKSET);
        mockSetImpl.setMember(address(mockModuleImpl), true);

        mockModuleImpl.setMaxWithdrawableExpectation(safe, address(harness), erc20, 555);
        uint256 max = harness.getMaxWithdrawableAmount(module, safe, erc20);
        assertEq(max, 555);
    }

    // ----------------------------------------------------------------
    // receive() / withdraw()
    // ----------------------------------------------------------------

    function test_Receive_AcceptsPlainEthTransfer() public {
        uint256 before = address(harness).balance;
        (bool ok,) = address(harness).call{ value: 1 ether }("");
        assertTrue(ok);
        assertEq(address(harness).balance, before + 1 ether);
    }

    function test_EndToEnd_PullEthThenWithdraw() public {
        mockModuleImpl.setSendEthOnTransfer(true);
        mockModuleImpl.setSingleReturnAmount(3 ether);
        vm.deal(address(mockModuleImpl), 10 ether);

        harness.executeAllowanceTransfer(module, safe, address(0));
        assertEq(address(harness).balance, 3 ether);

        address payable recipient = payable(makeAddr("recipient"));
        harness.withdraw(address(0), 3 ether, recipient);

        assertEq(address(harness).balance, 0);
        assertEq(recipient.balance, 3 ether);
    }

    function test_EndToEnd_PullErc20ThenWithdraw() public {
        token.mint(address(mockModuleImpl), 1_000 ether);
        mockModuleImpl.setErc20ToSendOnTransfer(address(token));
        mockModuleImpl.setSingleReturnAmount(40 ether);

        harness.executeAllowanceTransfer(module, safe, address(token));
        assertEq(token.balanceOf(address(harness)), 40 ether);

        address payable recipient = payable(makeAddr("recipient"));
        harness.withdraw(address(token), 40 ether, recipient);

        assertEq(token.balanceOf(address(harness)), 0);
        assertEq(token.balanceOf(recipient), 40 ether);
    }
}

