// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

import { Test } from "forge-std/Test.sol";

import { LinearAllowanceExecutor } from "src/zodiac-core/LinearAllowanceExecutor.sol";
import { LinearAllowanceSingletonForGnosisSafe } from "src/zodiac-core/modules/LinearAllowanceSingletonForGnosisSafe.sol";
import { IAddressSet } from "src/utils/IAddressSet.sol";
import { NotInAllowset, InBlockset } from "src/errors.sol";
import { AccessMode } from "src/constants.sol";

/// @dev Minimal ERC20 used only to exercise ERC20 fund flows into the executor.
contract MockERC20 {
    mapping(address => uint256) public balanceOf;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "MockERC20: insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

/// @dev Minimal address-set stand-in. Only `contains` is invoked by `_validateModule`,
/// so we do not need to fully implement IAddressSet - the address is cast to the
/// interface type at the call site, and Solidity dispatches purely on selector/ABI.
contract MockAddressSet {
    mapping(address => bool) public isMember;

    function setMember(address account, bool member) external {
        isMember[account] = member;
    }

    function contains(address account) external view returns (bool) {
        return isMember[account];
    }
}

/// @dev Stand-in for LinearAllowanceSingletonForGnosisSafe implementing exactly the four
/// external functions that LinearAllowanceExecutor calls, with matching signatures
/// (inferred directly from the call sites in the contract under test, which had to
/// type-check against the real module). Cast to LinearAllowanceSingletonForGnosisSafe
/// when used, exactly like the executor does.
contract MockAllowanceModule {
    // -- single transfer bookkeeping --
    address public lastSafeSingle;
    address public lastTokenSingle;
    address public lastToSingle;
    uint256 public callCountSingle;
    uint256 public singleReturnAmount;
    bool public revertSingle;
    bool public sendEthOnTransfer;
    address public erc20ToSendOnTransfer;

    // -- batch transfer bookkeeping --
    address[] public lastSafesBatch;
    address[] public lastTokensBatch;
    address[] public lastTosBatch;
    uint256 public callCountBatch;
    uint256[] public batchReturnAmounts;
    bool public revertBatch;

    // -- view getters --
    address public expectedSafeForUnspent;
    address public expectedDelegateForUnspent;
    address public expectedTokenForUnspent;
    uint256 public unspentReturn;

    address public expectedSafeForMaxWithdrawable;
    address public expectedDelegateForMaxWithdrawable;
    address public expectedTokenForMaxWithdrawable;
    uint256 public maxWithdrawableReturn;

    receive() external payable {}

    // -- configuration --

    function setSingleReturnAmount(uint256 amount) external {
        singleReturnAmount = amount;
    }

    function setBatchReturnAmounts(uint256[] calldata amounts) external {
        delete batchReturnAmounts;
        for (uint256 i = 0; i < amounts.length; i++) {
            batchReturnAmounts.push(amounts[i]);
        }
    }

    function setRevertSingle(bool r) external {
        revertSingle = r;
    }

    function setRevertBatch(bool r) external {
        revertBatch = r;
    }

    function setSendEthOnTransfer(bool s) external {
        sendEthOnTransfer = s;
    }

    function setErc20ToSendOnTransfer(address token) external {
        erc20ToSendOnTransfer = token;
    }

    function setUnspentExpectation(address safe, address delegate, address token, uint256 ret) external {
        expectedSafeForUnspent = safe;
        expectedDelegateForUnspent = delegate;
        expectedTokenForUnspent = token;
        unspentReturn = ret;
    }

    function setMaxWithdrawableExpectation(address safe, address delegate, address token, uint256 ret) external {
        expectedSafeForMaxWithdrawable = safe;
        expectedDelegateForMaxWithdrawable = delegate;
        expectedTokenForMaxWithdrawable = token;
        maxWithdrawableReturn = ret;
    }

    function lastTosBatchLength() external view returns (uint256) {
        return lastTosBatch.length;
    }

    function lastTosBatchAt(uint256 i) external view returns (address) {
        return lastTosBatch[i];
    }

    // -- functions matching LinearAllowanceSingletonForGnosisSafe's ABI --

    function executeAllowanceTransfer(address safe, address token, address payable to) external returns (uint256) {
        require(!revertSingle, "MockAllowanceModule: forced revert");
        lastSafeSingle = safe;
        lastTokenSingle = token;
        lastToSingle = to;
        callCountSingle++;

        if (sendEthOnTransfer && singleReturnAmount > 0) {
            (bool ok,) = to.call{ value: singleReturnAmount }("");
            require(ok, "MockAllowanceModule: eth send failed");
        }
        if (erc20ToSendOnTransfer != address(0) && singleReturnAmount > 0) {
            MockERC20(erc20ToSendOnTransfer).transfer(to, singleReturnAmount);
        }
        token; // silence unused-var warning when neither branch above applies
        return singleReturnAmount;
    }

    function executeAllowanceTransfers(address[] calldata safes, address[] calldata tokens, address[] calldata tos)
        external
        returns (uint256[] memory)
    {
        require(!revertBatch, "MockAllowanceModule: forced revert");
        delete lastSafesBatch;
        delete lastTokensBatch;
        delete lastTosBatch;
        for (uint256 i = 0; i < safes.length; i++) {
            lastSafesBatch.push(safes[i]);
        }
        for (uint256 i = 0; i < tokens.length; i++) {
            lastTokensBatch.push(tokens[i]);
        }
        for (uint256 i = 0; i < tos.length; i++) {
            lastTosBatch.push(tos[i]);
        }
        callCountBatch++;
        return batchReturnAmounts;
    }

    function getTotalUnspent(address safe, address delegate, address token) external view returns (uint256) {
        require(
            safe == expectedSafeForUnspent && delegate == expectedDelegateForUnspent
                && token == expectedTokenForUnspent,
            "MockAllowanceModule: unexpected getTotalUnspent args"
        );
        return unspentReturn;
    }

    function getMaxWithdrawableAmount(address safe, address delegate, address token) external view returns (uint256) {
        require(
            safe == expectedSafeForMaxWithdrawable && delegate == expectedDelegateForMaxWithdrawable
                && token == expectedTokenForMaxWithdrawable,
            "MockAllowanceModule: unexpected getMaxWithdrawableAmount args"
        );
        return maxWithdrawableReturn;
    }
}

/// @dev Concrete harness implementing the abstract hooks left to derived contracts.
/// No access control is added here on purpose: LinearAllowanceExecutor itself does not
/// enforce any, leaving that to inheriting contracts, and these tests target the base
/// contract's own logic.
contract ExecutorHarness is LinearAllowanceExecutor {
    receive() external payable override {}

    function assignModuleAddressSet(IAddressSet addressSet) external override {
        _assignModuleAddressSet(addressSet);
    }

    function setModuleAccessMode(AccessMode mode) external override {
        _setModuleAccessMode(mode);
    }

    function withdraw(address token, uint256 amount, address payable to) external override {
        if (token == address(0)) {
            (bool ok,) = to.call{ value: amount }("");
            require(ok, "ExecutorHarness: eth withdraw failed");
        } else {
            require(MockERC20(token).transfer(to, amount), "ExecutorHarness: erc20 withdraw failed");
        }
    }
}

contract LinearAllowanceExecutorTest is Test {
    // Redeclared with identical signatures so vm.expectEmit / emit works without
    // inheriting the (abstract) contract under test.
    event ModuleAccessModeSet(AccessMode indexed mode);
    event ModuleAddressSetAssigned(IAddressSet indexed addressSet);

    ExecutorHarness internal harness;
    MockAllowanceModule internal mockModuleImpl;
    MockAddressSet internal mockSetImpl;
    MockERC20 internal token;

    LinearAllowanceSingletonForGnosisSafe internal module;
    IAddressSet internal addressSet;

    address internal safe = makeAddr("safe");
    address internal erc20 = makeAddr("erc20-placeholder");

    function setUp() public {
        harness = new ExecutorHarness();
        mockModuleImpl = new MockAllowanceModule();
        mockSetImpl = new MockAddressSet();
        token = new MockERC20();

        module = LinearAllowanceSingletonForGnosisSafe(payable(address(mockModuleImpl)));
        addressSet = IAddressSet(address(mockSetImpl));
    }

    // ----------------------------------------------------------------
    // Initial state
    // ----------------------------------------------------------------

    function test_InitialState_IsUnrestricted() public view {
        assertEq(uint8(harness.moduleAccessMode()), uint8(AccessMode.NONE));
        assertEq(address(harness.moduleAddressSet()), address(0));
    }

    // ----------------------------------------------------------------
    // setModuleAccessMode / assignModuleAddressSet
    // ----------------------------------------------------------------

    function test_SetModuleAccessMode_UpdatesStateAndEmits() public {
        vm.expectEmit(true, false, false, false);
        emit ModuleAccessModeSet(AccessMode.ALLOWSET);
        harness.setModuleAccessMode(AccessMode.ALLOWSET);
        assertEq(uint8(harness.moduleAccessMode()), uint8(AccessMode.ALLOWSET));

        vm.expectEmit(true, false, false, false);
        emit ModuleAccessModeSet(AccessMode.BLOCKSET);
        harness.setModuleAccessMode(AccessMode.BLOCKSET);
        assertEq(uint8(harness.moduleAccessMode()), uint8(AccessMode.BLOCKSET));

        vm.expectEmit(true, false, false, false);
        emit ModuleAccessModeSet(AccessMode.NONE);
        harness.setModuleAccessMode(AccessMode.NONE);
        assertEq(uint8(harness.moduleAccessMode()), uint8(AccessMode.NONE));
    }

    function test_AssignModuleAddressSet_UpdatesStateAndEmits() public {
        vm.expectEmit(true, false, false, false);
        emit ModuleAddressSetAssigned(addressSet);
        harness.assignModuleAddressSet(addressSet);
        assertEq(address(harness.moduleAddressSet()), address(mockSetImpl));

        // Can be reset back to the zero address.
        vm.expectEmit(true, false, false, false);
        emit ModuleAddressSetAssigned(IAddressSet(address(0)));
        harness.assignModuleAddressSet(IAddressSet(address(0)));
        assertEq(address(harness.moduleAddressSet()), address(0));
    }

    // ----------------------------------------------------------------
    // _validateModule via executeAllowanceTransfer
    // ----------------------------------------------------------------

    function test_ValidateModule_NoneMode_AllowsModuleRegardlessOfSet(bool inSet) public {
        mockSetImpl.setMember(address(mockModuleImpl), inSet);
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.NONE);

        mockModuleImpl.setSingleReturnAmount(1 ether);
        uint256 amount = harness.executeAllowanceTransfer(module, safe, erc20);
        assertEq(amount, 1 ether);
    }

    function test_ValidateModule_NoneMode_WorksEvenWithNoAddressSetAssigned() public {
        // moduleAddressSet is still the zero address; NONE mode must never touch it.
        harness.setModuleAccessMode(AccessMode.NONE);
        mockModuleImpl.setSingleReturnAmount(5);
        uint256 amount = harness.executeAllowanceTransfer(module, safe, erc20);
        assertEq(amount, 5);
    }

    function test_ValidateModule_Allowset_RevertsWhenModuleNotInSet() public {
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.ALLOWSET);
        mockSetImpl.setMember(address(mockModuleImpl), false);

        vm.expectRevert(abi.encodeWithSelector(NotInAllowset.selector, address(mockModuleImpl)));
        harness.executeAllowanceTransfer(module, safe, erc20);
    }

    function test_ValidateModule_Allowset_SucceedsWhenModuleInSet() public {
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.ALLOWSET);
        mockSetImpl.setMember(address(mockModuleImpl), true);

        mockModuleImpl.setSingleReturnAmount(7);
        uint256 amount = harness.executeAllowanceTransfer(module, safe, erc20);
        assertEq(amount, 7);
    }

    function test_ValidateModule_Blockset_RevertsWhenModuleInSet() public {
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.BLOCKSET);
        mockSetImpl.setMember(address(mockModuleImpl), true);

        vm.expectRevert(abi.encodeWithSelector(InBlockset.selector, address(mockModuleImpl)));
        harness.executeAllowanceTransfer(module, safe, erc20);
    }

    function test_ValidateModule_Blockset_SucceedsWhenModuleNotInSet() public {
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.BLOCKSET);
        mockSetImpl.setMember(address(mockModuleImpl), false);

        mockModuleImpl.setSingleReturnAmount(9);
        uint256 amount = harness.executeAllowanceTransfer(module, safe, erc20);
        assertEq(amount, 9);
    }

    function testFuzz_ValidateModule_AllowsetAndBlocksetAreComplementary(bool inSet) public {
        harness.assignModuleAddressSet(addressSet);
        mockSetImpl.setMember(address(mockModuleImpl), inSet);
        mockModuleImpl.setSingleReturnAmount(1);

        harness.setModuleAccessMode(AccessMode.ALLOWSET);
        if (inSet) {
            uint256 amount = harness.executeAllowanceTransfer(module, safe, erc20);
            assertEq(amount, 1);
        } else {
            vm.expectRevert(abi.encodeWithSelector(NotInAllowset.selector, address(mockModuleImpl)));
            harness.executeAllowanceTransfer(module, safe, erc20);
        }

        harness.setModuleAccessMode(AccessMode.BLOCKSET);
        if (inSet) {
            vm.expectRevert(abi.encodeWithSelector(InBlockset.selector, address(mockModuleImpl)));
            harness.executeAllowanceTransfer(module, safe, erc20);
        } else {
            uint256 amount = harness.executeAllowanceTransfer(module, safe, erc20);
            assertEq(amount, 1);
        }
    }

    // ----------------------------------------------------------------
    // executeAllowanceTransfer
    // ----------------------------------------------------------------

    function test_ExecuteAllowanceTransfer_ForwardsArgsAndForcesRecipientToSelf() public {
        mockModuleImpl.setSingleReturnAmount(123);

        uint256 amount = harness.executeAllowanceTransfer(module, safe, erc20);

        assertEq(amount, 123);
        assertEq(mockModuleImpl.lastSafeSingle(), safe);
        assertEq(mockModuleImpl.lastTokenSingle(), erc20);
        assertEq(mockModuleImpl.lastToSingle(), address(harness));
        assertEq(mockModuleImpl.callCountSingle(), 1);
    }

    function test_ExecuteAllowanceTransfer_BubblesUpModuleRevert() public {
        mockModuleImpl.setRevertSingle(true);
        vm.expectRevert(bytes("MockAllowanceModule: forced revert"));
        harness.executeAllowanceTransfer(module, safe, erc20);
    }

    function test_ExecuteAllowanceTransfer_ReceivesEth() public {
        mockModuleImpl.setSendEthOnTransfer(true);
        mockModuleImpl.setSingleReturnAmount(2 ether);
        vm.deal(address(mockModuleImpl), 10 ether);

        uint256 before = address(harness).balance;
        uint256 amount = harness.executeAllowanceTransfer(module, safe, address(0));

        assertEq(amount, 2 ether);
        assertEq(address(harness).balance, before + 2 ether);
    }

    function test_ExecuteAllowanceTransfer_ReceivesErc20() public {
        token.mint(address(mockModuleImpl), 1_000 ether);
        mockModuleImpl.setErc20ToSendOnTransfer(address(token));
        mockModuleImpl.setSingleReturnAmount(50 ether);

        uint256 amount = harness.executeAllowanceTransfer(module, safe, address(token));

        assertEq(amount, 50 ether);
        assertEq(token.balanceOf(address(harness)), 50 ether);
    }

    // ----------------------------------------------------------------
    // executeAllowanceTransfers (batch)
    // ----------------------------------------------------------------

    function test_ExecuteAllowanceTransfers_ForcesEveryRecipientToSelf() public {
        address[] memory safes = new address[](3);
        safes[0] = makeAddr("safe0");
        safes[1] = makeAddr("safe1");
        safes[2] = makeAddr("safe2");

        address[] memory tokens = new address[](3);
        tokens[0] = makeAddr("token0");
        tokens[1] = makeAddr("token1");
        tokens[2] = makeAddr("token2");

        uint256[] memory presetAmounts = new uint256[](3);
        presetAmounts[0] = 1;
        presetAmounts[1] = 2;
        presetAmounts[2] = 3;
        mockModuleImpl.setBatchReturnAmounts(presetAmounts);

        uint256[] memory amounts = harness.executeAllowanceTransfers(module, safes, tokens);

        assertEq(amounts.length, 3);
        assertEq(amounts[0], 1);
        assertEq(amounts[1], 2);
        assertEq(amounts[2], 3);

        assertEq(mockModuleImpl.lastTosBatchLength(), 3);
        for (uint256 i = 0; i < 3; i++) {
            assertEq(mockModuleImpl.lastTosBatchAt(i), address(harness));
            assertEq(mockModuleImpl.lastSafesBatch(i), safes[i]);
            assertEq(mockModuleImpl.lastTokensBatch(i), tokens[i]);
        }
        assertEq(mockModuleImpl.callCountBatch(), 1);
    }

    function test_ExecuteAllowanceTransfers_ValidatesModuleBeforeCalling() public {
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.ALLOWSET);
        mockSetImpl.setMember(address(mockModuleImpl), false);

        address[] memory safes = new address[](1);
        safes[0] = safe;
        address[] memory tokens = new address[](1);
        tokens[0] = erc20;

        vm.expectRevert(abi.encodeWithSelector(NotInAllowset.selector, address(mockModuleImpl)));
        harness.executeAllowanceTransfers(module, safes, tokens);
        assertEq(mockModuleImpl.callCountBatch(), 0);
    }

    function test_ExecuteAllowanceTransfers_BubblesUpModuleRevert() public {
        mockModuleImpl.setRevertBatch(true);
        address[] memory safes = new address[](1);
        safes[0] = safe;
        address[] memory tokens = new address[](1);
        tokens[0] = erc20;

        vm.expectRevert(bytes("MockAllowanceModule: forced revert"));
        harness.executeAllowanceTransfers(module, safes, tokens);
    }

    function test_ExecuteAllowanceTransfers_DoesNotValidateArrayLengths() public {
        // safes and tokens intentionally have mismatched lengths; the executor itself
        // performs no length validation (that responsibility belongs to the module).
        address[] memory safes = new address[](3);
        safes[0] = makeAddr("s0");
        safes[1] = makeAddr("s1");
        safes[2] = makeAddr("s2");

        address[] memory tokens = new address[](1);
        tokens[0] = erc20;

        harness.executeAllowanceTransfers(module, safes, tokens);

        assertEq(mockModuleImpl.lastTosBatchLength(), 3);
        for (uint256 i = 0; i < 3; i++) {
            assertEq(mockModuleImpl.lastTosBatchAt(i), address(harness));
        }
    }

    function test_ExecuteAllowanceTransfers_EmptyArrays() public {
        address[] memory safes = new address[](0);
        address[] memory tokens = new address[](0);

        uint256[] memory amounts = harness.executeAllowanceTransfers(module, safes, tokens);
        assertEq(amounts.length, 0);
        assertEq(mockModuleImpl.lastTosBatchLength(), 0);
        assertEq(mockModuleImpl.callCountBatch(), 1);
    }

    // ----------------------------------------------------------------
    // getTotalUnspent / getMaxWithdrawableAmount
    // ----------------------------------------------------------------

    function test_GetTotalUnspent_ForwardsSelfAsDelegate() public {
        mockModuleImpl.setUnspentExpectation(safe, address(harness), erc20, 42);
        uint256 unspent = harness.getTotalUnspent(module, safe, erc20);
        assertEq(unspent, 42);
    }

    function test_GetTotalUnspent_DoesNotValidateModule() public {
        // ALLOWSET with the module excluded from the set - view getters must still work,
        // since only executeAllowanceTransfer(s) invoke _validateModule.
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.ALLOWSET);
        mockSetImpl.setMember(address(mockModuleImpl), false);

        mockModuleImpl.setUnspentExpectation(safe, address(harness), erc20, 77);
        uint256 unspent = harness.getTotalUnspent(module, safe, erc20);
        assertEq(unspent, 77);
    }

    function test_GetMaxWithdrawableAmount_ForwardsSelfAsDelegate() public {
        mockModuleImpl.setMaxWithdrawableExpectation(safe, address(harness), erc20, 999);
        uint256 max = harness.getMaxWithdrawableAmount(module, safe, erc20);
        assertEq(max, 999);
    }

    function test_GetMaxWithdrawableAmount_DoesNotValidateModule() public {
        harness.assignModuleAddressSet(addressSet);
        harness.setModuleAccessMode(AccessMode.BLOCKSET);
        mockSetImpl.setMember(address(mockModuleImpl), true);

        mockModuleImpl.setMaxWithdrawableExpectation(safe, address(harness), erc20, 555);
        uint256 max = harness.getMaxWithdrawableAmount(module, safe, erc20);
        assertEq(max, 555);
    }

    // ----------------------------------------------------------------
    // receive() / withdraw()
    // ----------------------------------------------------------------

    function test_Receive_AcceptsPlainEthTransfer() public {
        uint256 before = address(harness).balance;
        (bool ok,) = address(harness).call{ value: 1 ether }("");
        assertTrue(ok);
        assertEq(address(harness).balance, before + 1 ether);
