        assertTrue(calc.supportsInterface(type(IAccessControlledEarningPowerCalculator).interfaceId));
    }

    function test_SupportsInterface_ERC165() public view {
        assertTrue(calc.supportsInterface(type(IERC165).interfaceId));
    }

