        assertFalse(calc.supportsInterface(bytes4(0x12345678)));
    }

    function test_SupportsInterface_FFFFFFFF_ReturnsFalse() public view {
        // Per ERC-165 spec, 0xffffffff must always return false.
        assertFalse(calc.supportsInterface(0xffffffff));
    }
