        calculator.setBlockset(IAddressSet(address(newBlockset)));

        assertEq(calculator.getEarningPower(1_000, alice, delegatee), 0);
    }

    // ============================================
    // setAccessMode
    // ============================================

    function test_SetAccessMode_OwnerCanSet() public {
        vm.expectEmit(true, false, false, true);
        emit AccessModeSet(AccessMode.BLOCKSET);

        vm.prank(owner);
        calculator.setAccessMode(AccessMode.BLOCKSET);

        assertEq(uint8(calculator.accessMode()), uint8(AccessMode.BLOCKSET));
    }

    function test_SetAccessMode_RevertsForNonOwner() public {
        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, stranger));
        vm.prank(stranger);
        calculator.setAccessMode(AccessMode.ALLOWSET);
    }

    function test_SetAccessMode_IsNonRetroactive_OnlyAffectsFutureReads() public {
        // Start in NONE, alice has full power.
        assertEq(calculator.getEarningPower(1_000, alice, delegatee), 1_000);

        // Switch to ALLOWSET without adding alice - her computed power drops immediately
        // because getEarningPower is a pure view recompute, not a stored value.
        vm.prank(owner);
        calculator.setAccessMode(AccessMode.ALLOWSET);

        assertEq(calculator.getEarningPower(1_000, alice, delegatee), 0);
    }

    // ============================================
    // supportsInterface
    // ============================================

    function test_SupportsInterface_AccessControlledEarningPowerCalculator() public view {
        assertTrue(
            calculator.supportsInterface(type(IAccessControlledEarningPowerCalculator).interfaceId)
        );
    }

    function test_SupportsInterface_ERC165() public view {
        assertTrue(calculator.supportsInterface(type(IERC165).interfaceId));
    }

    function test_SupportsInterface_RandomInterfaceReturnsFalse() public view {
        assertFalse(calculator.supportsInterface(bytes4(0xdeadbeef)));
    }

    // ============================================
    // Ownership
    // ============================================

    function test_Ownership_TransferAllowsNewOwnerToManageConfig() public {
        address newOwner = makeAddr("newOwner");

        vm.prank(owner);
        calculator.transferOwnership(newOwner);

        assertEq(calculator.owner(), newOwner);

        vm.prank(newOwner);
        calculator.setAccessMode(AccessMode.BLOCKSET);
        assertEq(uint8(calculator.accessMode()), uint8(AccessMode.BLOCKSET));

        vm.expectRevert(abi.encodeWithSelector(Ownable.OwnableUnauthorizedAccount.selector, owner));
        vm.prank(owner);
        calculator.setAccessMode(AccessMode.NONE);
    }
}
