contract RegenStakerFactoryTest is Test {
    // Mirror of the event declared on RegenStakerFactory, needed for vm.expectEmit matching.
    event StakerDeploy(
        address indexed deployer,
        address indexed admin,
        address indexed stakerAddress,
        bytes32 salt,
        RegenStakerFactory.RegenStakerVariant variant,
        address calculatorAddress
    );

    RegenStakerFactory internal factory;

    bytes internal codeWithoutDelegation;
    bytes internal codeWithDelegation;
    bytes32 internal hashWithoutDelegation;
    bytes32 internal hashWithDelegation;

    address internal constant REWARDS_TOKEN = address(0x1001);
    address internal constant STAKE_TOKEN = address(0x1002);
    address internal constant STAKER_ALLOWSET = address(0x1003);
    address internal constant STAKER_BLOCKSET = address(0x1004);
    address internal constant ALLOC_ALLOWSET = address(0x1005);
    address internal constant CALCULATOR = address(0x1006);
    address internal constant DEFAULT_ADMIN = address(0xA11CE);

    address internal deployerA = address(0xD001);
    address internal deployerB = address(0xD002);

    function setUp() public {
        codeWithoutDelegation = type(MockRegenStakerWithoutDelegation).creationCode;
        codeWithDelegation = type(MockRegenStakerWithDelegation).creationCode;

        hashWithoutDelegation = keccak256(codeWithoutDelegation);
        hashWithDelegation = keccak256(codeWithDelegation);

        // Constructor order: (WITH_DELEGATION hash, WITHOUT_DELEGATION hash)
        factory = new RegenStakerFactory(hashWithDelegation, hashWithoutDelegation);
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    function _defaultParams(address admin_) internal pure returns (RegenStakerFactory.CreateStakerParams memory) {
        return
            RegenStakerFactory.CreateStakerParams({
                rewardsToken: IERC20(REWARDS_TOKEN),
                stakeToken: IERC20(STAKE_TOKEN),
                admin: admin_,
                stakerAllowset: IAddressSet(STAKER_ALLOWSET),
                stakerBlockset: IAddressSet(STAKER_BLOCKSET),
                stakerAccessMode: AccessMode(0),
                allocationMechanismAllowset: IAddressSet(ALLOC_ALLOWSET),
                earningPowerCalculator: IEarningPowerCalculator(CALCULATOR),
                maxBumpTip: 1e18,
                minimumStakeAmount: 100,
                rewardDuration: 7 days
            });
    }

    /// @dev Mirrors RegenStakerFactory._encodeConstructorParams exactly.
    function _encodeConstructorParams(
        RegenStakerFactory.CreateStakerParams memory params
    ) internal pure returns (bytes memory) {
        return
            abi.encode(
                params.rewardsToken,
                params.stakeToken,
                params.earningPowerCalculator,
                params.maxBumpTip,
                params.admin,
                params.rewardDuration,
                params.minimumStakeAmount,
                params.stakerAllowset,
                params.stakerBlockset,
                params.stakerAccessMode,
                params.allocationMechanismAllowset
            );
    }

    function _fullBytecode(
        bytes memory code,
        RegenStakerFactory.CreateStakerParams memory params
    ) internal pure returns (bytes memory) {
        return bytes.concat(code, _encodeConstructorParams(params));
    }

    // ---------------------------------------------------------------------
    // Constructor / initial state
    // ---------------------------------------------------------------------

    function test_ConstructorStoresCanonicalHashes() public view {
        assertEq(
            factory.canonicalBytecodeHash(RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION),
            hashWithDelegation
        );
        assertEq(
            factory.canonicalBytecodeHash(RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION),
            hashWithoutDelegation
        );
    }

    function test_GetStakersByDeployer_EmptyForUnknownDeployer() public view {
        assertEq(factory.getStakersByDeployer(deployerA).length, 0);
    }

    // ---------------------------------------------------------------------
    // Successful deployments
    // ---------------------------------------------------------------------

    function test_CreateStakerWithoutDelegation_Success() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("salt-without-delegation");

        vm.prank(deployerA);
        address stakerAddress = factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);

        assertTrue(stakerAddress != address(0));
        assertTrue(stakerAddress.code.length > 0);

        MockRegenStakerWithoutDelegation deployed = MockRegenStakerWithoutDelegation(stakerAddress);
        assertEq(address(deployed.rewardsToken()), REWARDS_TOKEN);
        assertEq(address(deployed.stakeToken()), STAKE_TOKEN);
        assertEq(address(deployed.earningPowerCalculator()), CALCULATOR);
        assertEq(deployed.maxBumpTip(), 1e18);
        assertEq(deployed.admin(), DEFAULT_ADMIN);
        assertEq(deployed.rewardDuration(), 7 days);
        assertEq(deployed.minimumStakeAmount(), 100);
        assertEq(address(deployed.stakerAllowset()), STAKER_ALLOWSET);
        assertEq(address(deployed.stakerBlockset()), STAKER_BLOCKSET);
        assertEq(address(deployed.allocationMechanismAllowset()), ALLOC_ALLOWSET);
        assertFalse(deployed.DELEGATION_VARIANT());
    }

    function test_CreateStakerWithDelegation_Success() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("salt-with-delegation");

        vm.prank(deployerA);
        address stakerAddress = factory.createStakerWithDelegation(params, salt, codeWithDelegation);

        assertTrue(stakerAddress != address(0));
        assertTrue(stakerAddress.code.length > 0);
        assertTrue(MockRegenStakerWithDelegation(stakerAddress).DELEGATION_VARIANT());
    }

    function test_CreateStaker_RecordsStakerInfo() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("record-info");

        vm.warp(12345);
        vm.prank(deployerA);
        address stakerAddress = factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);

        RegenStakerFactory.StakerInfo[] memory infos = factory.getStakersByDeployer(deployerA);
        assertEq(infos.length, 1);
        assertEq(infos[0].deployerAddress, deployerA);
        assertEq(infos[0].timestamp, 12345);
        assertEq(infos[0].admin, DEFAULT_ADMIN);
        assertEq(infos[0].stakerAddress, stakerAddress);
        assertEq(uint256(infos[0].variant), uint256(RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION));
        assertEq(infos[0].calculatorAddress, CALCULATOR);
        assertEq(infos[0].salt, salt);
    }

    function test_CreateStaker_MultipleDeploymentsAppendToArray() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);

        vm.startPrank(deployerA);
        address first = factory.createStakerWithoutDelegation(params, keccak256("s1"), codeWithoutDelegation);
        address second = factory.createStakerWithDelegation(params, keccak256("s2"), codeWithDelegation);
        vm.stopPrank();

        RegenStakerFactory.StakerInfo[] memory infos = factory.getStakersByDeployer(deployerA);
        assertEq(infos.length, 2);
        assertEq(infos[0].stakerAddress, first);
        assertEq(infos[1].stakerAddress, second);
        assertEq(
            uint256(infos[0].variant),
            uint256(RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION)
        );
        assertEq(uint256(infos[1].variant), uint256(RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION));
    }

    function test_CreateStaker_EmitsStakerDeployEvent() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("event-salt");

        address predicted = factory.predictStakerAddress(
            salt,
            deployerA,
            _fullBytecode(codeWithoutDelegation, params)
        );

        vm.expectEmit(true, true, true, true, address(factory));
        emit StakerDeploy(
            deployerA,
            DEFAULT_ADMIN,
            predicted,
            salt,
            RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION,
            CALCULATOR
        );

        vm.prank(deployerA);
        address stakerAddress = factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);
        assertEq(stakerAddress, predicted);
    }

    // ---------------------------------------------------------------------
    // Bytecode validation failures
    // ---------------------------------------------------------------------

    function test_CreateStakerWithoutDelegation_RevertsOnEmptyBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        vm.expectRevert(RegenStakerFactory.InvalidBytecode.selector);
        factory.createStakerWithoutDelegation(params, keccak256("s"), "");
    }

    function test_CreateStakerWithDelegation_RevertsOnEmptyBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        vm.expectRevert(RegenStakerFactory.InvalidBytecode.selector);
        factory.createStakerWithDelegation(params, keccak256("s"), "");
    }

    function test_CreateStakerWithoutDelegation_RevertsOnWrongBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 providedHash = keccak256(codeWithDelegation);

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION,
                providedHash,
                hashWithoutDelegation
            )
        );
        factory.createStakerWithoutDelegation(params, keccak256("s"), codeWithDelegation);
    }

    function test_CreateStakerWithDelegation_RevertsOnWrongBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 providedHash = keccak256(codeWithoutDelegation);

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION,
                providedHash,
                hashWithDelegation
            )
        );
        factory.createStakerWithDelegation(params, keccak256("s"), codeWithoutDelegation);
    }

    function test_CreateStaker_RevertsOnGarbageBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes memory garbage = hex"6080604052";

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION,
                keccak256(garbage),
                hashWithoutDelegation
            )
        );
        factory.createStakerWithoutDelegation(params, keccak256("s"), garbage);
    }

    // ---------------------------------------------------------------------
    // CREATE2 address prediction
    // ---------------------------------------------------------------------

    function test_PredictStakerAddress_MatchesActualDeployment() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("predict-salt");
        bytes memory fullBytecode = _fullBytecode(codeWithoutDelegation, params);

        address predicted = factory.predictStakerAddress(salt, deployerA, fullBytecode);

        vm.prank(deployerA);
        address actual = factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);

        assertEq(actual, predicted);
    }

    function test_PredictStakerAddress_MatchesManualCreate2Computation() public view {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("manual-predict-salt");
        bytes memory fullBytecode = _fullBytecode(codeWithoutDelegation, params);

        address predicted = factory.predictStakerAddress(salt, deployerA, fullBytecode);

        bytes32 finalSalt = keccak256(abi.encode(salt, deployerA));
        address manual = Create2.computeAddress(finalSalt, keccak256(fullBytecode), address(factory));

        assertEq(predicted, manual);
    }

    function test_PredictStakerAddress_DiffersPerDeployer() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("shared-salt");
        bytes memory fullBytecode = _fullBytecode(codeWithoutDelegation, params);

        address predictedA = factory.predictStakerAddress(salt, deployerA, fullBytecode);
        address predictedB = factory.predictStakerAddress(salt, deployerB, fullBytecode);

        assertTrue(predictedA != predictedB);
    }

    function testFuzz_PredictStakerAddress_IsDeterministic(bytes32 salt, address deployer) public view {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes memory fullBytecode = _fullBytecode(codeWithoutDelegation, params);

        address first = factory.predictStakerAddress(salt, deployer, fullBytecode);
        address second = factory.predictStakerAddress(salt, deployer, fullBytecode);

        assertEq(first, second);
    }

    // ---------------------------------------------------------------------
    // Salt / deployer interaction
    // ---------------------------------------------------------------------

    function test_SameRawSalt_DifferentDeployers_BothSucceed() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("shared-salt-2");

        vm.prank(deployerA);
        address stakerA = factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);

        vm.prank(deployerB);
        address stakerB = factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);

        assertTrue(stakerA != stakerB);
        assertEq(factory.getStakersByDeployer(deployerA).length, 1);
        assertEq(factory.getStakersByDeployer(deployerB).length, 1);
    }

    function test_SameRawSalt_SameDeployer_SameParams_SecondDeploymentReverts() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("duplicate-salt");

        vm.prank(deployerA);
        factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);

        // Same deployer + same salt + same bytecode => identical CREATE2 address,
        // which already has code deployed, so the second deployment must revert.
        vm.expectRevert();
        vm.prank(deployerA);
        factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);
    }

    function test_SameRawSalt_SameDeployer_DifferentParams_BothSucceed() public {
        bytes32 salt = keccak256("duplicate-salt-diff-params");

        RegenStakerFactory.CreateStakerParams memory params1 = _defaultParams(DEFAULT_ADMIN);
        RegenStakerFactory.CreateStakerParams memory params2 = _defaultParams(address(0xBEEF));

        vm.prank(deployerA);
        address first = factory.createStakerWithoutDelegation(params1, salt, codeWithoutDelegation);

        // Different constructor params => different init code => different CREATE2 address,
        // even though the raw salt and deployer are identical.
        vm.prank(deployerA);
        address second = factory.createStakerWithoutDelegation(params2, salt, codeWithoutDelegation);

        assertTrue(first != second);
        assertEq(factory.getStakersByDeployer(deployerA).length, 2);
    }
}

