        bytes memory fullBytecode = _fullBytecode(codeWithoutDelegation, params);

        address predicted = factory.predictStakerAddress(salt, deployerA, fullBytecode);

        bytes32 finalSalt = keccak256(abi.encode(salt, deployerA));
        address manual = Create2.computeAddress(finalSalt, keccak256(fullBytecode), address(factory));

        assertEq(predicted, manual);
    }

    function test_PredictStakerAddress_DiffersPerDeployer() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("shared-salt");
        bytes memory fullBytecode = _fullBytecode(codeWithoutDelegation, params);

        address predictedA = factory.predictStakerAddress(salt, deployerA, fullBytecode);
        address predictedB = factory.predictStakerAddress(salt, deployerB, fullBytecode);

        assertTrue(predictedA != predictedB);
    }

    function testFuzz_PredictStakerAddress_IsDeterministic(bytes32 salt, address deployer) public view {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes memory fullBytecode = _fullBytecode(codeWithoutDelegation, params);

        address first = factory.predictStakerAddress(salt, deployer, fullBytecode);
        address second = factory.predictStakerAddress(salt, deployer, fullBytecode);

        assertEq(first, second);
    }

    // ---------------------------------------------------------------------
    // Salt / deployer interaction
    // ---------------------------------------------------------------------

    function test_SameRawSalt_DifferentDeployers_BothSucceed() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("shared-salt-2");

        vm.prank(deployerA);
        address stakerA = factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);

        vm.prank(deployerB);
        address stakerB = factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);

        assertTrue(stakerA != stakerB);
        assertEq(factory.getStakersByDeployer(deployerA).length, 1);
        assertEq(factory.getStakersByDeployer(deployerB).length, 1);
    }

    function test_SameRawSalt_SameDeployer_SameParams_SecondDeploymentReverts() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams(DEFAULT_ADMIN);
        bytes32 salt = keccak256("duplicate-salt");

        vm.prank(deployerA);
        factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);

        // Same deployer + same salt + same bytecode => identical CREATE2 address,
        // which already has code deployed, so the second deployment must revert.
        vm.expectRevert();
        vm.prank(deployerA);
        factory.createStakerWithoutDelegation(params, salt, codeWithoutDelegation);
    }

    function test_SameRawSalt_SameDeployer_DifferentParams_BothSucceed() public {
        bytes32 salt = keccak256("duplicate-salt-diff-params");

        RegenStakerFactory.CreateStakerParams memory params1 = _defaultParams(DEFAULT_ADMIN);
        RegenStakerFactory.CreateStakerParams memory params2 = _defaultParams(address(0xBEEF));

        vm.prank(deployerA);
        address first = factory.createStakerWithoutDelegation(params1, salt, codeWithoutDelegation);

        // Different constructor params => different init code => different CREATE2 address,
        // even though the raw salt and deployer are identical.
        vm.prank(deployerA);
        address second = factory.createStakerWithoutDelegation(params2, salt, codeWithoutDelegation);

        assertTrue(first != second);
        assertEq(factory.getStakersByDeployer(deployerA).length, 2);
    }
}

