        withDelegationCode = type(MockWithDelegationStaker).creationCode;

        noDelegationHash = keccak256(noDelegationCode);
        withDelegationHash = keccak256(withDelegationCode);

        // constructor(regenStakerBytecodeHash /* WITH_DELEGATION */, noDelegationBytecodeHash /* WITHOUT_DELEGATION */)
        factory = new RegenStakerFactory(withDelegationHash, noDelegationHash);
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    function _defaultParams() internal view returns (RegenStakerFactory.CreateStakerParams memory) {
        return
            RegenStakerFactory.CreateStakerParams({
                rewardsToken: IERC20(makeAddr("rewardsToken")),
                stakeToken: IERC20(makeAddr("stakeToken")),
                admin: admin,
                stakerAllowset: IAddressSet(makeAddr("stakerAllowset")),
                stakerBlockset: IAddressSet(makeAddr("stakerBlockset")),
                stakerAccessMode: AccessMode(0),
                allocationMechanismAllowset: IAddressSet(makeAddr("allocationAllowset")),
                earningPowerCalculator: IEarningPowerCalculator(makeAddr("calculator")),
                maxBumpTip: 1 ether,
                minimumStakeAmount: 100,
                rewardDuration: 30 days
            });
    }

    /// @dev Mirrors RegenStakerFactory._encodeConstructorParams exactly, so tests
    ///      can independently compute the full deployment bytecode.
    function _encodeConstructorParams(
        RegenStakerFactory.CreateStakerParams memory params
    ) internal pure returns (bytes memory) {
        return
            abi.encode(
                params.rewardsToken,
                params.stakeToken,
                params.earningPowerCalculator,
                params.maxBumpTip,
                params.admin,
                params.rewardDuration,
                params.minimumStakeAmount,
                params.stakerAllowset,
                params.stakerBlockset,
                params.stakerAccessMode,
                params.allocationMechanismAllowset
            );
    }

    function _computeCreate2Address(
        bytes32 salt,
        address deployer,
        bytes memory bytecode
    ) internal view returns (address) {
        bytes32 finalSalt = keccak256(abi.encode(salt, deployer));
        bytes32 hash = keccak256(
            abi.encodePacked(bytes1(0xff), address(factory), finalSalt, keccak256(bytecode))
        );
        return address(uint160(uint256(hash)));
    }

