// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

import { Test } from "forge-std/Test.sol";
import { RegenStakerFactory } from "src/factories/RegenStakerFactory.sol";
import { IERC20, IAddressSet, IEarningPowerCalculator } from "src/regen/RegenStaker.sol";
import { AccessMode } from "src/constants.sol";

/// @dev Minimal contract used as the "canonical" WITHOUT_DELEGATION bytecode.
///      It intentionally has an empty constructor so that the ABI-encoded
///      constructor params appended by the factory are simply ignored by the
///      EVM during creation (no CODECOPY/decoding happens for a 0-arg ctor).
contract MockNoDelegationStaker {
    uint256 public constant VARIANT_MARKER = 1;
}

/// @dev Minimal contract used as the "canonical" WITH_DELEGATION bytecode.
///      Distinct storage/bytecode from MockNoDelegationStaker so the two
///      creation-code hashes differ.
contract MockWithDelegationStaker {
    uint256 public constant VARIANT_MARKER = 2;
    uint256 public constant EXTRA_MARKER = 42;
}

contract RegenStakerFactoryTest is Test {
    // Re-declared locally so vm.expectEmit can match topics/data against the
    // factory's real event (event signatures are content-addressed, not
    // contract-addressed).
    event StakerDeploy(
        address indexed deployer,
        address indexed admin,
        address indexed stakerAddress,
        bytes32 salt,
        RegenStakerFactory.RegenStakerVariant variant,
        address calculatorAddress
    );

    RegenStakerFactory internal factory;

    bytes internal noDelegationCode;
    bytes internal withDelegationCode;
    bytes32 internal noDelegationHash;
    bytes32 internal withDelegationHash;

    address internal admin = makeAddr("admin");
    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");

    function setUp() public {
        noDelegationCode = type(MockNoDelegationStaker).creationCode;
        withDelegationCode = type(MockWithDelegationStaker).creationCode;

        noDelegationHash = keccak256(noDelegationCode);
        withDelegationHash = keccak256(withDelegationCode);

        // constructor(regenStakerBytecodeHash /* WITH_DELEGATION */, noDelegationBytecodeHash /* WITHOUT_DELEGATION */)
        factory = new RegenStakerFactory(withDelegationHash, noDelegationHash);
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    function _defaultParams() internal view returns (RegenStakerFactory.CreateStakerParams memory) {
        return
            RegenStakerFactory.CreateStakerParams({
                rewardsToken: IERC20(makeAddr("rewardsToken")),
                stakeToken: IERC20(makeAddr("stakeToken")),
                admin: admin,
                stakerAllowset: IAddressSet(makeAddr("stakerAllowset")),
                stakerBlockset: IAddressSet(makeAddr("stakerBlockset")),
                stakerAccessMode: AccessMode(0),
                allocationMechanismAllowset: IAddressSet(makeAddr("allocationAllowset")),
                earningPowerCalculator: IEarningPowerCalculator(makeAddr("calculator")),
                maxBumpTip: 1 ether,
                minimumStakeAmount: 100,
                rewardDuration: 30 days
            });
    }

    /// @dev Mirrors RegenStakerFactory._encodeConstructorParams exactly, so tests
    ///      can independently compute the full deployment bytecode.
    function _encodeConstructorParams(
        RegenStakerFactory.CreateStakerParams memory params
    ) internal pure returns (bytes memory) {
        return
            abi.encode(
                params.rewardsToken,
                params.stakeToken,
                params.earningPowerCalculator,
                params.maxBumpTip,
                params.admin,
                params.rewardDuration,
                params.minimumStakeAmount,
                params.stakerAllowset,
                params.stakerBlockset,
                params.stakerAccessMode,
                params.allocationMechanismAllowset
            );
    }

    function _computeCreate2Address(
        bytes32 salt,
        address deployer,
        bytes memory bytecode
    ) internal view returns (address) {
        bytes32 finalSalt = keccak256(abi.encode(salt, deployer));
        bytes32 hash = keccak256(
            abi.encodePacked(bytes1(0xff), address(factory), finalSalt, keccak256(bytecode))
        );
        return address(uint160(uint256(hash)));
    }

    // ---------------------------------------------------------------------
    // Constructor / canonical hash storage
    // ---------------------------------------------------------------------

    function test_Constructor_StoresCanonicalHashesForBothVariants() public view {
        assertEq(
            factory.canonicalBytecodeHash(RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION),
            withDelegationHash
        );
        assertEq(
            factory.canonicalBytecodeHash(RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION),
            noDelegationHash
        );
    }

    // ---------------------------------------------------------------------
    // Bytecode validation - InvalidBytecode
    // ---------------------------------------------------------------------

    function test_RevertWhen_WithoutDelegation_EmptyBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        vm.expectRevert(RegenStakerFactory.InvalidBytecode.selector);
        factory.createStakerWithoutDelegation(params, bytes32(uint256(1)), "");
    }

    function test_RevertWhen_WithDelegation_EmptyBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        vm.expectRevert(RegenStakerFactory.InvalidBytecode.selector);
        factory.createStakerWithDelegation(params, bytes32(uint256(1)), "");
    }

    // ---------------------------------------------------------------------
    // Bytecode validation - UnauthorizedBytecode
    // ---------------------------------------------------------------------

    function test_RevertWhen_WithoutDelegation_WrongBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        bytes memory garbage = abi.encodePacked(hex"6080604052", uint256(1234));

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION,
                keccak256(garbage),
                noDelegationHash
            )
        );
        factory.createStakerWithoutDelegation(params, bytes32(uint256(1)), garbage);
    }

    function test_RevertWhen_WithDelegation_WrongBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        bytes memory garbage = abi.encodePacked(hex"6080604052", uint256(5678));

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION,
                keccak256(garbage),
                withDelegationHash
            )
        );
        factory.createStakerWithDelegation(params, bytes32(uint256(1)), garbage);
    }

    function test_RevertWhen_CrossedVariantBytecode_NoDelegationCodeToWithDelegationFn() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION,
                noDelegationHash,
                withDelegationHash
            )
        );
        factory.createStakerWithDelegation(params, bytes32(uint256(1)), noDelegationCode);
    }

    function test_RevertWhen_CrossedVariantBytecode_WithDelegationCodeToNoDelegationFn() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION,
                withDelegationHash,
                noDelegationHash
            )
        );
        factory.createStakerWithoutDelegation(params, bytes32(uint256(1)), withDelegationCode);
    }

    // ---------------------------------------------------------------------
    // Successful deployment - WITHOUT_DELEGATION
    // ---------------------------------------------------------------------

    function test_CreateStakerWithoutDelegation_DeploysAtPredictedAddress() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        bytes32 salt = bytes32(uint256(42));

        bytes memory fullBytecode = bytes.concat(noDelegationCode, _encodeConstructorParams(params));
        address predictedViaFactory = factory.predictStakerAddress(salt, alice, fullBytecode);
        address predictedManually = _computeCreate2Address(salt, alice, fullBytecode);
        assertEq(predictedViaFactory, predictedManually);

        vm.prank(alice);
        address deployed = factory.createStakerWithoutDelegation(params, salt, noDelegationCode);

        assertEq(deployed, predictedViaFactory);
        assertGt(deployed.code.length, 0);
    }

    function test_CreateStakerWithoutDelegation_EmitsStakerDeployEvent() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        bytes32 salt = bytes32(uint256(7));
        bytes memory fullBytecode = bytes.concat(noDelegationCode, _encodeConstructorParams(params));
        address predicted = factory.predictStakerAddress(salt, alice, fullBytecode);

        vm.expectEmit(true, true, true, true, address(factory));
        emit StakerDeploy(
            alice,
            params.admin,
            predicted,
            salt,
            RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION,
            address(params.earningPowerCalculator)
        );

        vm.prank(alice);
        factory.createStakerWithoutDelegation(params, salt, noDelegationCode);
    }

    function test_CreateStakerWithoutDelegation_RecordsStakerInfo() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        bytes32 salt = bytes32(uint256(99));

        uint256 deployTime = 1_800_000_000;
        vm.warp(deployTime);

        vm.prank(alice);
        address deployed = factory.createStakerWithoutDelegation(params, salt, noDelegationCode);

        RegenStakerFactory.StakerInfo[] memory infos = factory.getStakersByDeployer(alice);
        assertEq(infos.length, 1);
        assertEq(infos[0].deployerAddress, alice);
        assertEq(infos[0].timestamp, deployTime);
        assertEq(infos[0].admin, params.admin);
        assertEq(infos[0].stakerAddress, deployed);
        assertEq(uint8(infos[0].variant), uint8(RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION));
        assertEq(infos[0].calculatorAddress, address(params.earningPowerCalculator));
        assertEq(infos[0].salt, salt);

        // Cross-check against the public array getter directly.
        (
            address deployerAddress,
            uint256 timestamp,
            address recordedAdmin,
            address stakerAddress,
            RegenStakerFactory.RegenStakerVariant variant,
            address calculatorAddress,
            bytes32 recordedSalt
        ) = factory.stakers(alice, 0);

        assertEq(deployerAddress, alice);
        assertEq(timestamp, deployTime);
        assertEq(recordedAdmin, params.admin);
        assertEq(stakerAddress, deployed);
        assertEq(uint8(variant), uint8(RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION));
        assertEq(calculatorAddress, address(params.earningPowerCalculator));
        assertEq(recordedSalt, salt);
    }

    // ---------------------------------------------------------------------
    // Successful deployment - WITH_DELEGATION
    // ---------------------------------------------------------------------

    function test_CreateStakerWithDelegation_DeploysAtPredictedAddress() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        bytes32 salt = bytes32(uint256(1001));

        bytes memory fullBytecode = bytes.concat(withDelegationCode, _encodeConstructorParams(params));
        address predicted = factory.predictStakerAddress(salt, bob, fullBytecode);

        vm.prank(bob);
        address deployed = factory.createStakerWithDelegation(params, salt, withDelegationCode);

        assertEq(deployed, predicted);
        assertGt(deployed.code.length, 0);
    }

    function test_CreateStakerWithDelegation_EmitsStakerDeployEvent() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        bytes32 salt = bytes32(uint256(2002));
        bytes memory fullBytecode = bytes.concat(withDelegationCode, _encodeConstructorParams(params));
        address predicted = factory.predictStakerAddress(salt, bob, fullBytecode);

        vm.expectEmit(true, true, true, true, address(factory));
        emit StakerDeploy(
            bob,
            params.admin,
            predicted,
            salt,
            RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION,
            address(params.earningPowerCalculator)
        );

        vm.prank(bob);
        factory.createStakerWithDelegation(params, salt, withDelegationCode);
    }

    // ---------------------------------------------------------------------
    // Salt / deployer semantics
    // ---------------------------------------------------------------------

    function test_RevertWhen_SameSenderReusesSalt() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        bytes32 salt = bytes32(uint256(555));

        vm.prank(alice);
        factory.createStakerWithoutDelegation(params, salt, noDelegationCode);

        // Second deployment to the same CREATE2 address must fail because
        // the target already has code.
        vm.expectRevert();
        vm.prank(alice);
        factory.createStakerWithoutDelegation(params, salt, noDelegationCode);
    }

    function test_SameSaltDifferentSenders_ProduceDifferentAddresses() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        bytes32 salt = bytes32(uint256(777));

        vm.prank(alice);
        address deployedAlice = factory.createStakerWithoutDelegation(params, salt, noDelegationCode);

        vm.prank(bob);
        address deployedBob = factory.createStakerWithoutDelegation(params, salt, noDelegationCode);

        assertTrue(deployedAlice != deployedBob);
    }

    function test_GetStakersByDeployer_AccumulatesMultipleDeployments() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();

        vm.startPrank(alice);
        address d1 = factory.createStakerWithoutDelegation(params, bytes32(uint256(1)), noDelegationCode);
        address d2 = factory.createStakerWithDelegation(params, bytes32(uint256(2)), withDelegationCode);
        vm.stopPrank();

        RegenStakerFactory.StakerInfo[] memory infos = factory.getStakersByDeployer(alice);
        assertEq(infos.length, 2);
        assertEq(infos[0].stakerAddress, d1);
        assertEq(uint8(infos[0].variant), uint8(RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION));
        assertEq(infos[1].stakerAddress, d2);
        assertEq(uint8(infos[1].variant), uint8(RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION));
    }

    function test_GetStakersByDeployer_EmptyForUnknownDeployer() public view {
        RegenStakerFactory.StakerInfo[] memory infos = factory.getStakersByDeployer(makeAddr("nobody"));
        assertEq(infos.length, 0);
    }

    // ---------------------------------------------------------------------
    // Trust-boundary behavior: factory does NOT validate constructor params
    // ---------------------------------------------------------------------

    function test_DeploymentSucceeds_WithZeroAdminAndCalculator() public {
        RegenStakerFactory.CreateStakerParams memory params = _defaultParams();
        params.admin = address(0);
        params.earningPowerCalculator = IEarningPowerCalculator(address(0));

        vm.prank(alice);
        address deployed = factory.createStakerWithoutDelegation(params, bytes32(uint256(31337)), noDelegationCode);
        assertGt(deployed.code.length, 0);

        RegenStakerFactory.StakerInfo[] memory infos = factory.getStakersByDeployer(alice);
        assertEq(infos[0].admin, address(0));
        assertEq(infos[0].calculatorAddress, address(0));
    }

    // ---------------------------------------------------------------------
    // predictStakerAddress - pure CREATE2 computation
    // ---------------------------------------------------------------------

    function testFuzz_PredictStakerAddress_MatchesCreate2Formula(
        bytes32 salt,
        address deployer,
        bytes memory bytecode
    ) public view {
        address expected = _computeCreate2Address(salt, deployer, bytecode);
        assertEq(factory.predictStakerAddress(salt, deployer, bytecode), expected);
    }

    function test_PredictStakerAddress_DiffersByDeployer() public view {
        bytes32 salt = bytes32(uint256(9));
        bytes memory bytecode = noDelegationCode;

        address predictedAlice = factory.predictStakerAddress(salt, alice, bytecode);
        address predictedBob = factory.predictStakerAddress(salt, bob, bytecode);

        assertTrue(predictedAlice != predictedBob);
    }

    function test_PredictStakerAddress_DiffersBySalt() public view {
        bytes memory bytecode = noDelegationCode;

        address predicted1 = factory.predictStakerAddress(bytes32(uint256(1)), alice, bytecode);
        address predicted2 = factory.predictStakerAddress(bytes32(uint256(2)), alice, bytecode);

        assertTrue(predicted1 != predicted2);
    }
}

