// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

import { Test } from "forge-std/Test.sol";
import { RegenStakerFactory } from "src/factories/RegenStakerFactory.sol";
import { IERC20, IAddressSet, IEarningPowerCalculator } from "src/regen/RegenStaker.sol";
import { AccessMode } from "src/constants.sol";

/// @dev Minimal deployment target used purely to produce deterministic,
///      distinguishable bytecode for the WITHOUT_DELEGATION variant. Its
///      constructor signature mirrors RegenStakerFactory._encodeConstructorParams
///      exactly so the factory's constructor-args encoding can be exercised
///      end-to-end without depending on the real (heavier) RegenStaker contracts.
contract MockDeployTargetNoDelegation {
    IERC20 public rewardsToken;
    IERC20 public stakeToken;
    IEarningPowerCalculator public earningPowerCalculator;
    uint256 public maxBumpTip;
    address public admin;
    uint256 public rewardDuration;
    uint256 public minimumStakeAmount;
    IAddressSet public stakerAllowset;
    IAddressSet public stakerBlockset;
    AccessMode public stakerAccessMode;
    IAddressSet public allocationMechanismAllowset;

    constructor(
        IERC20 _rewardsToken,
        IERC20 _stakeToken,
        IEarningPowerCalculator _earningPowerCalculator,
        uint256 _maxBumpTip,
        address _admin,
        uint256 _rewardDuration,
        uint256 _minimumStakeAmount,
        IAddressSet _stakerAllowset,
        IAddressSet _stakerBlockset,
        AccessMode _stakerAccessMode,
        IAddressSet _allocationMechanismAllowset
    ) {
        rewardsToken = _rewardsToken;
        stakeToken = _stakeToken;
        earningPowerCalculator = _earningPowerCalculator;
        maxBumpTip = _maxBumpTip;
        admin = _admin;
        rewardDuration = _rewardDuration;
        minimumStakeAmount = _minimumStakeAmount;
        stakerAllowset = _stakerAllowset;
        stakerBlockset = _stakerBlockset;
        stakerAccessMode = _stakerAccessMode;
        allocationMechanismAllowset = _allocationMechanismAllowset;
    }
}

/// @dev Identical field layout to MockDeployTargetNoDelegation but a distinct
///      contract (and therefore distinct creation code / hash), standing in
///      for the WITH_DELEGATION variant.
contract MockDeployTargetWithDelegation {
    IERC20 public rewardsToken;
    IERC20 public stakeToken;
    IEarningPowerCalculator public earningPowerCalculator;
    uint256 public maxBumpTip;
    address public admin;
    uint256 public rewardDuration;
    uint256 public minimumStakeAmount;
    IAddressSet public stakerAllowset;
    IAddressSet public stakerBlockset;
    AccessMode public stakerAccessMode;
    IAddressSet public allocationMechanismAllowset;
    bool public constant DELEGATION_SUPPORTED = true;

    constructor(
        IERC20 _rewardsToken,
        IERC20 _stakeToken,
        IEarningPowerCalculator _earningPowerCalculator,
        uint256 _maxBumpTip,
        address _admin,
        uint256 _rewardDuration,
        uint256 _minimumStakeAmount,
        IAddressSet _stakerAllowset,
        IAddressSet _stakerBlockset,
        AccessMode _stakerAccessMode,
        IAddressSet _allocationMechanismAllowset
    ) {
        rewardsToken = _rewardsToken;
        stakeToken = _stakeToken;
        earningPowerCalculator = _earningPowerCalculator;
        maxBumpTip = _maxBumpTip;
        admin = _admin;
        rewardDuration = _rewardDuration;
        minimumStakeAmount = _minimumStakeAmount;
        stakerAllowset = _stakerAllowset;
        stakerBlockset = _stakerBlockset;
        stakerAccessMode = _stakerAccessMode;
        allocationMechanismAllowset = _allocationMechanismAllowset;
    }
}

contract RegenStakerFactoryTest is Test {
    // Mirrors RegenStakerFactory.StakerDeploy so it can be used with vm.expectEmit.
    // The ABI topic0 selector depends only on the canonicalized type signature
    // (address,address,address,bytes32,uint8,address), so the qualified enum
    // name used here does not need to match the source's local `RegenStakerVariant`.
    event StakerDeploy(
        address indexed deployer,
        address indexed admin,
        address indexed stakerAddress,
        bytes32 salt,
        RegenStakerFactory.RegenStakerVariant variant,
        address calculatorAddress
    );

    RegenStakerFactory internal factory;

    bytes internal noDelegationCode;
    bytes internal withDelegationCode;
    bytes32 internal noDelegationHash;
    bytes32 internal withDelegationHash;

    address internal deployer = makeAddr("deployer");
    address internal otherDeployer = makeAddr("otherDeployer");
    address internal admin = makeAddr("admin");
    address internal rewardsTokenAddr = makeAddr("rewardsToken");
    address internal stakeTokenAddr = makeAddr("stakeToken");
    address internal calculatorAddr = makeAddr("calculator");
    address internal stakerAllowsetAddr = makeAddr("stakerAllowset");
    address internal stakerBlocksetAddr = makeAddr("stakerBlockset");
    address internal allocationAllowsetAddr = makeAddr("allocationAllowset");

    function setUp() public {
        noDelegationCode = type(MockDeployTargetNoDelegation).creationCode;
        withDelegationCode = type(MockDeployTargetWithDelegation).creationCode;
        noDelegationHash = keccak256(noDelegationCode);
        withDelegationHash = keccak256(withDelegationCode);

        // Constructor order: (regenStakerBytecodeHash = WITH_DELEGATION, noDelegationBytecodeHash = WITHOUT_DELEGATION)
        factory = new RegenStakerFactory(withDelegationHash, noDelegationHash);
    }

    function _params() internal view returns (RegenStakerFactory.CreateStakerParams memory) {
        return
            RegenStakerFactory.CreateStakerParams({
                rewardsToken: IERC20(rewardsTokenAddr),
                stakeToken: IERC20(stakeTokenAddr),
                admin: admin,
                stakerAllowset: IAddressSet(stakerAllowsetAddr),
                stakerBlockset: IAddressSet(stakerBlocksetAddr),
                stakerAccessMode: AccessMode(0),
                allocationMechanismAllowset: IAddressSet(allocationAllowsetAddr),
                earningPowerCalculator: IEarningPowerCalculator(calculatorAddr),
                maxBumpTip: 1 ether,
                minimumStakeAmount: 100,
                rewardDuration: 7 days
            });
    }

    function _constructorArgs(
        RegenStakerFactory.CreateStakerParams memory params
    ) internal pure returns (bytes memory) {
        return
            abi.encode(
                params.rewardsToken,
                params.stakeToken,
                params.earningPowerCalculator,
                params.maxBumpTip,
                params.admin,
                params.rewardDuration,
                params.minimumStakeAmount,
                params.stakerAllowset,
                params.stakerBlockset,
                params.stakerAccessMode,
                params.allocationMechanismAllowset
            );
    }

    function _fullBytecode(
        bytes memory code,
        RegenStakerFactory.CreateStakerParams memory params
    ) internal pure returns (bytes memory) {
        return bytes.concat(code, _constructorArgs(params));
    }

    /* -------------------------------------------------------------------- */
    /*                                Constructor                            */
    /* -------------------------------------------------------------------- */

    function test_constructor_setsCanonicalHashes() public {
        assertEq(
            factory.canonicalBytecodeHash(RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION),
            withDelegationHash
        );
        assertEq(
            factory.canonicalBytecodeHash(RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION),
            noDelegationHash
        );
    }

    /* -------------------------------------------------------------------- */
    /*                          createStakerWithoutDelegation                 */
    /* -------------------------------------------------------------------- */

    function test_createStakerWithoutDelegation_deploysExpectedAddress() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes32 salt = keccak256("salt-1");

        address predicted = factory.predictStakerAddress(salt, deployer, _fullBytecode(noDelegationCode, params));

        vm.prank(deployer);
        address stakerAddress = factory.createStakerWithoutDelegation(params, salt, noDelegationCode);

        assertEq(stakerAddress, predicted);
        assertGt(stakerAddress.code.length, 0);

        MockDeployTargetNoDelegation deployed = MockDeployTargetNoDelegation(stakerAddress);
        assertEq(address(deployed.rewardsToken()), rewardsTokenAddr);
        assertEq(address(deployed.stakeToken()), stakeTokenAddr);
        assertEq(address(deployed.earningPowerCalculator()), calculatorAddr);
        assertEq(deployed.maxBumpTip(), params.maxBumpTip);
        assertEq(deployed.admin(), admin);
        assertEq(deployed.rewardDuration(), params.rewardDuration);
        assertEq(deployed.minimumStakeAmount(), params.minimumStakeAmount);
        assertEq(address(deployed.stakerAllowset()), stakerAllowsetAddr);
        assertEq(address(deployed.stakerBlockset()), stakerBlocksetAddr);
        assertEq(address(deployed.allocationMechanismAllowset()), allocationAllowsetAddr);
    }

    function test_createStakerWithoutDelegation_recordsStakerInfo() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes32 salt = keccak256("salt-info");

        vm.warp(12345);
        vm.prank(deployer);
        address stakerAddress = factory.createStakerWithoutDelegation(params, salt, noDelegationCode);

        RegenStakerFactory.StakerInfo[] memory infos = factory.getStakersByDeployer(deployer);
        assertEq(infos.length, 1);
        assertEq(infos[0].deployerAddress, deployer);
        assertEq(infos[0].timestamp, 12345);
        assertEq(infos[0].admin, admin);
        assertEq(infos[0].stakerAddress, stakerAddress);
        assertEq(uint8(infos[0].variant), uint8(RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION));
        assertEq(infos[0].calculatorAddress, calculatorAddr);
        assertEq(infos[0].salt, salt);
    }

    function test_createStakerWithoutDelegation_emitsStakerDeploy() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes32 salt = keccak256("salt-event");
        address predicted = factory.predictStakerAddress(salt, deployer, _fullBytecode(noDelegationCode, params));

        vm.expectEmit(true, true, true, true, address(factory));
        emit StakerDeploy(
            deployer,
            admin,
            predicted,
            salt,
            RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION,
            calculatorAddr
        );

        vm.prank(deployer);
        factory.createStakerWithoutDelegation(params, salt, noDelegationCode);
    }

    function test_createStakerWithoutDelegation_revertsOnEmptyBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        vm.expectRevert(RegenStakerFactory.InvalidBytecode.selector);
        factory.createStakerWithoutDelegation(params, keccak256("salt"), "");
    }

    function test_createStakerWithoutDelegation_revertsOnWrongVariantBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes memory wrongCode = withDelegationCode; // valid for the OTHER variant

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION,
                keccak256(wrongCode),
                noDelegationHash
            )
        );
        factory.createStakerWithoutDelegation(params, keccak256("salt"), wrongCode);
    }

    function test_createStakerWithoutDelegation_revertsOnArbitraryGarbageBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes memory garbage = hex"deadbeef";

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITHOUT_DELEGATION,
                keccak256(garbage),
                noDelegationHash
            )
        );
        factory.createStakerWithoutDelegation(params, keccak256("salt"), garbage);
    }

    /* -------------------------------------------------------------------- */
    /*                           createStakerWithDelegation                   */
    /* -------------------------------------------------------------------- */

    function test_createStakerWithDelegation_deploysExpectedAddress() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes32 salt = keccak256("salt-delegation");

        address predicted = factory.predictStakerAddress(salt, deployer, _fullBytecode(withDelegationCode, params));

        vm.prank(deployer);
        address stakerAddress = factory.createStakerWithDelegation(params, salt, withDelegationCode);

        assertEq(stakerAddress, predicted);
        assertGt(stakerAddress.code.length, 0);
        assertTrue(MockDeployTargetWithDelegation(stakerAddress).DELEGATION_SUPPORTED());
    }

    function test_createStakerWithDelegation_recordsCorrectVariant() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes32 salt = keccak256("salt-delegation-variant");

        vm.prank(deployer);
        factory.createStakerWithDelegation(params, salt, withDelegationCode);

        RegenStakerFactory.StakerInfo[] memory infos = factory.getStakersByDeployer(deployer);
        assertEq(infos.length, 1);
        assertEq(uint8(infos[0].variant), uint8(RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION));
    }

    function test_createStakerWithDelegation_revertsOnEmptyBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        vm.expectRevert(RegenStakerFactory.InvalidBytecode.selector);
        factory.createStakerWithDelegation(params, keccak256("salt"), "");
    }

    function test_createStakerWithDelegation_revertsOnWrongVariantBytecode() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes memory wrongCode = noDelegationCode; // valid for the OTHER variant

        vm.expectRevert(
            abi.encodeWithSelector(
                RegenStakerFactory.UnauthorizedBytecode.selector,
                RegenStakerFactory.RegenStakerVariant.WITH_DELEGATION,
                keccak256(wrongCode),
                withDelegationHash
            )
        );
        factory.createStakerWithDelegation(params, keccak256("salt"), wrongCode);
    }

    /* -------------------------------------------------------------------- */
    /*                            predictStakerAddress                        */
    /* -------------------------------------------------------------------- */

    function test_predictStakerAddress_matchesActualDeployment() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes32 salt = keccak256("predict-salt");
        bytes memory fullBytecode = _fullBytecode(noDelegationCode, params);

        address predicted = factory.predictStakerAddress(salt, deployer, fullBytecode);

        vm.prank(deployer);
        address actual = factory.createStakerWithoutDelegation(params, salt, noDelegationCode);

        assertEq(actual, predicted);
    }

    function test_predictStakerAddress_differsByDeployer() public {
