        address predictedForDeployer = factory.predictStakerAddress(salt, deployer, fullBytecode);
        address predictedForOther = factory.predictStakerAddress(salt, otherDeployer, fullBytecode);

        assertTrue(predictedForDeployer != predictedForOther);
    }

    /* -------------------------------------------------------------------- */
    /*                       Salt / deployer collision semantics              */
    /* -------------------------------------------------------------------- */

    function test_sameSalt_differentDeployers_produceDifferentAddresses() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();
        bytes32 salt = keccak256("shared-salt");

        vm.prank(deployer);
        address addr1 = factory.createStakerWithoutDelegation(params, salt, noDelegationCode);

        vm.prank(otherDeployer);
