    /* -------------------------------------------------------------------- */
    /*                            getStakersByDeployer                        */
    /* -------------------------------------------------------------------- */

    function test_getStakersByDeployer_accumulatesMultipleDeployments() public {
        RegenStakerFactory.CreateStakerParams memory params = _params();

        vm.startPrank(deployer);
        address addr1 = factory.createStakerWithoutDelegation(params, keccak256("s1"), noDelegationCode);
        address addr2 = factory.createStakerWithDelegation(params, keccak256("s2"), withDelegationCode);
