/// @dev Minimal PSM mock. Holds reserves of both `gem` and `dai` and
///      replicates the tin/tout fee math used by the real LitePSM.
///      `shortChange` simulates a PSM that only partially consumes the
///      gem it's given, to exercise PSMSwapper's leftover-flush logic.
contract MockPSM {
    uint256 internal constant WAD = 1e18;

    IERC20 public gem;
    IERC20 public dai;
    uint256 public conversionFactor;

    uint256 public tin;
    uint256 public tout;
    bool public shortChange;

    constructor(IERC20 _gem, IERC20 _dai, uint256 _conversionFactor) {
        gem = _gem;
        dai = _dai;
        conversionFactor = _conversionFactor;
    }

    function setFees(uint256 _tin, uint256 _tout) external {
        tin = _tin;
        tout = _tout;
    }

    function setShortChange(bool v) external {
        shortChange = v;
    }

    function sellGem(address usr, uint256 gemAmt) external returns (uint256 daiOutWad) {
        uint256 pull = shortChange ? gemAmt / 2 : gemAmt;
        require(gem.transferFrom(msg.sender, address(this), pull), "gem pull failed");

        uint256 gross = pull * conversionFactor;
        uint256 fee = (gross * tin) / WAD;
        daiOutWad = gross - fee;

        require(dai.transfer(usr, daiOutWad), "dai payout failed");
    }

    function buyGem(address usr, uint256 gemAmt) external returns (uint256 daiInWad) {
        daiInWad = (gemAmt * conversionFactor * (WAD + tout)) / WAD;
        require(dai.transferFrom(msg.sender, address(this), daiInWad), "dai pull failed");
        require(gem.transfer(usr, gemAmt), "gem payout failed");
    }
}

/*//////////////////////////////////////////////////////////////////////
                            MOCK DAI/USDS EXCHANGE
//////////////////////////////////////////////////////////////////////*/

/// @dev Minimal DaiUsds converter mock, normally 1:1. `broken` simulates a
///      converter that shorts the output by 1 wei, to exercise
///      PSMSwapper's NonOneToOneConversion guard.
contract MockExchange {
    IERC20 public dai;
    IERC20 public usds;
    bool public broken;

    constructor(IERC20 _dai, IERC20 _usds) {
        dai = _dai;
        usds = _usds;
    }

    function setBroken(bool v) external {
        broken = v;
    }

    function daiToUsds(address usr, uint256 wad) external {
        require(dai.transferFrom(msg.sender, address(this), wad), "dai pull failed");
        uint256 out = broken ? wad - 1 : wad;
        require(usds.transfer(usr, out), "usds payout failed");
    }

    function usdsToDai(address usr, uint256 wad) external {
        require(usds.transferFrom(msg.sender, address(this), wad), "usds pull failed");
        uint256 out = broken ? wad - 1 : wad;
        require(dai.transfer(usr, out), "dai payout failed");
    }
}

