    }

    function test_Constructor_AllowsZeroConversionFactorForNonBuyGemRoutes() public {
        PSMSwapper s = new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(usdc), address(dai), 0);
        assertEq(s.conversionFactor(), 0);
    }

    function test_Constructor_SetsImmutables() public view {
        assertEq(buySwapper.protocol(), address(psm));
        assertEq(uint256(buySwapper.route()), uint256(PSMSwapper.Route.BUY_GEM));
        assertEq(buySwapper.tokenIn(), address(dai));
        assertEq(buySwapper.tokenOut(), address(usdc));
        assertEq(buySwapper.conversionFactor(), CONVERSION_FACTOR);
    }

    /*//////////////////////////////////////////////////////////////////
                            TOKEN VALIDATION (swap)
    //////////////////////////////////////////////////////////////////*/

    function test_Swap_RevertsOnTokenInMismatch() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        sellSwapper.swap(address(dai), address(dai), 100e6, 0, user);
    }

    function test_Swap_RevertsOnTokenOutMismatch() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        sellSwapper.swap(address(usdc), address(usdc), 100e6, 0, user);
    }

    /*//////////////////////////////////////////////////////////////////
                                SELL_GEM
    //////////////////////////////////////////////////////////////////*/

    function test_SellGem_Success_NoFee() public {
        uint256 amountIn = 1_000e6;
        _mintAndApprove(usdc, user, address(sellSwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = sellSwapper.swap(address(usdc), address(dai), amountIn, 1_000e18, user);

        assertEq(amountOut, 1_000e18);
        assertEq(dai.balanceOf(user), 1_000e18);
        assertEq(usdc.balanceOf(user), 0);
        assertEq(usdc.balanceOf(address(sellSwapper)), 0, "swapper must hold no residual tokenIn");
