        _mintAndApprove(dai, user, address(buySwapper), amountIn);

        uint256 daiBalBefore = dai.balanceOf(user);

        vm.prank(user);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, 5_000e6, user);

        assertEq(amountOut, 5_000e6);
        assertEq(usdc.balanceOf(user), 5_000e6);
        assertEq(daiBalBefore - dai.balanceOf(user), amountIn, "exact division: full amountIn consumed");
        assertEq(dai.balanceOf(address(buySwapper)), 0);
    }

    function test_BuyGem_Success_WithToutFee() public {
        psm.setFees(0, 0.02e18); // 2% tout fee
        uint256 amountIn = 1_020e18; // chosen so gemAmt divides evenly: 1000e6 gem
        _mintAndApprove(dai, user, address(buySwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, 1_000e6, user);

        assertEq(amountOut, 1_000e6);
