        uint256 amountIn = 5_000e18 + 999_999; // small remainder below 1e12 granularity
        _mintAndApprove(dai, user, address(buySwapper), amountIn);

        uint256 daiBalBefore = dai.balanceOf(user);

        vm.prank(user);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, 5_000e6, user);

        uint256 expectedGemAmt = (amountIn * WAD) / (CONVERSION_FACTOR * WAD);
        uint256 expectedPulled = (expectedGemAmt * CONVERSION_FACTOR * WAD) / WAD;

        assertEq(amountOut, expectedGemAmt);
        assertLt(expectedPulled, amountIn, "sanity: this amountIn should leave a remainder");
        assertEq(daiBalBefore - dai.balanceOf(user), expectedPulled, "only exact charge pulled from caller");
        assertEq(dai.balanceOf(address(buySwapper)), 0, "no residual left in swapper");
