// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import { PSMSwapper } from "src/swappers/PSMSwapper.sol";

/*//////////////////////////////////////////////////////////////////////
                                MOCK TOKENS
//////////////////////////////////////////////////////////////////////*/

contract MockToken is ERC20 {
    uint8 private immutable _dec;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _dec = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _dec;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/*//////////////////////////////////////////////////////////////////////
                                MOCK PSM
//////////////////////////////////////////////////////////////////////*/

/// @dev Minimal PSM mock. Holds reserves of both `gem` and `dai` and
///      replicates the tin/tout fee math used by the real LitePSM.
///      `shortChange` simulates a PSM that only partially consumes the
///      gem it's given, to exercise PSMSwapper's leftover-flush logic.
contract MockPSM {
    uint256 internal constant WAD = 1e18;

    IERC20 public gem;
    IERC20 public dai;
    uint256 public conversionFactor;

    uint256 public tin;
    uint256 public tout;
    bool public shortChange;

    constructor(IERC20 _gem, IERC20 _dai, uint256 _conversionFactor) {
        gem = _gem;
        dai = _dai;
        conversionFactor = _conversionFactor;
    }

    function setFees(uint256 _tin, uint256 _tout) external {
        tin = _tin;
        tout = _tout;
    }

    function setShortChange(bool v) external {
        shortChange = v;
    }

    function sellGem(address usr, uint256 gemAmt) external returns (uint256 daiOutWad) {
        uint256 pull = shortChange ? gemAmt / 2 : gemAmt;
        require(gem.transferFrom(msg.sender, address(this), pull), "gem pull failed");

        uint256 gross = pull * conversionFactor;
        uint256 fee = (gross * tin) / WAD;
        daiOutWad = gross - fee;

        require(dai.transfer(usr, daiOutWad), "dai payout failed");
    }

    function buyGem(address usr, uint256 gemAmt) external returns (uint256 daiInWad) {
        daiInWad = (gemAmt * conversionFactor * (WAD + tout)) / WAD;
        require(dai.transferFrom(msg.sender, address(this), daiInWad), "dai pull failed");
        require(gem.transfer(usr, gemAmt), "gem payout failed");
    }
}

/*//////////////////////////////////////////////////////////////////////
                            MOCK DAI/USDS EXCHANGE
//////////////////////////////////////////////////////////////////////*/

/// @dev Minimal DaiUsds converter mock, normally 1:1. `broken` simulates a
///      converter that shorts the output by 1 wei, to exercise
///      PSMSwapper's NonOneToOneConversion guard.
contract MockExchange {
    IERC20 public dai;
    IERC20 public usds;
    bool public broken;

    constructor(IERC20 _dai, IERC20 _usds) {
        dai = _dai;
        usds = _usds;
    }

    function setBroken(bool v) external {
        broken = v;
    }

    function daiToUsds(address usr, uint256 wad) external {
        require(dai.transferFrom(msg.sender, address(this), wad), "dai pull failed");
        uint256 out = broken ? wad - 1 : wad;
        require(usds.transfer(usr, out), "usds payout failed");
    }

    function usdsToDai(address usr, uint256 wad) external {
        require(usds.transferFrom(msg.sender, address(this), wad), "usds pull failed");
        uint256 out = broken ? wad - 1 : wad;
        require(dai.transfer(usr, out), "dai payout failed");
    }
}

/*//////////////////////////////////////////////////////////////////////
                                TEST SUITE
//////////////////////////////////////////////////////////////////////*/

contract PSMSwapperTest is Test {
    uint256 internal constant WAD = 1e18;
    uint256 internal constant CONVERSION_FACTOR = 1e12; // USDC (6 dec) <-> DAI/USDS (18 dec)

    MockToken internal usdc;
    MockToken internal dai;
    MockToken internal usds;

    MockPSM internal psm;
    MockExchange internal exchange;

    PSMSwapper internal sellSwapper; // USDC -> DAI
    PSMSwapper internal buySwapper; // DAI -> USDC
    PSMSwapper internal daiToUsdsSwapper; // DAI -> USDS
    PSMSwapper internal usdsToDaiSwapper; // USDS -> DAI

    address internal user = makeAddr("user");

    function setUp() public {
        usdc = new MockToken("USD Coin", "USDC", 6);
        dai = new MockToken("Dai", "DAI", 18);
        usds = new MockToken("USDS", "USDS", 18);

        psm = new MockPSM(IERC20(address(usdc)), IERC20(address(dai)), CONVERSION_FACTOR);
        exchange = new MockExchange(IERC20(address(dai)), IERC20(address(usds)));

        // Fund protocol reserves.
        usdc.mint(address(psm), 10_000_000e6);
        dai.mint(address(psm), 10_000_000e18);
        dai.mint(address(exchange), 10_000_000e18);
        usds.mint(address(exchange), 10_000_000e18);

        sellSwapper = new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(usdc), address(dai), 0);
        buySwapper =
            new PSMSwapper(address(psm), PSMSwapper.Route.BUY_GEM, address(dai), address(usdc), CONVERSION_FACTOR);
        daiToUsdsSwapper =
            new PSMSwapper(address(exchange), PSMSwapper.Route.DAI_TO_USDS, address(dai), address(usds), 0);
        usdsToDaiSwapper =
            new PSMSwapper(address(exchange), PSMSwapper.Route.USDS_TO_DAI, address(usds), address(dai), 0);
    }

    /*//////////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////////*/

    function test_Constructor_RevertsOnZeroProtocol() public {
        vm.expectRevert(PSMSwapper.InvalidProtocol.selector);
        new PSMSwapper(address(0), PSMSwapper.Route.SELL_GEM, address(usdc), address(dai), 0);
    }

    function test_Constructor_RevertsOnZeroTokenIn() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(0), address(dai), 0);
    }

    function test_Constructor_RevertsOnZeroTokenOut() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(usdc), address(0), 0);
    }

    function test_Constructor_RevertsOnZeroConversionFactorForBuyGem() public {
        vm.expectRevert(PSMSwapper.InvalidConversionFactor.selector);
        new PSMSwapper(address(psm), PSMSwapper.Route.BUY_GEM, address(dai), address(usdc), 0);
    }

    function test_Constructor_AllowsZeroConversionFactorForNonBuyGemRoutes() public {
        PSMSwapper s = new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(usdc), address(dai), 0);
        assertEq(s.conversionFactor(), 0);
    }

    function test_Constructor_SetsImmutables() public view {
        assertEq(buySwapper.protocol(), address(psm));
        assertEq(uint256(buySwapper.route()), uint256(PSMSwapper.Route.BUY_GEM));
        assertEq(buySwapper.tokenIn(), address(dai));
        assertEq(buySwapper.tokenOut(), address(usdc));
        assertEq(buySwapper.conversionFactor(), CONVERSION_FACTOR);
    }

    /*//////////////////////////////////////////////////////////////////
                            TOKEN VALIDATION (swap)
    //////////////////////////////////////////////////////////////////*/

    function test_Swap_RevertsOnTokenInMismatch() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        sellSwapper.swap(address(dai), address(dai), 100e6, 0, user);
    }

    function test_Swap_RevertsOnTokenOutMismatch() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        sellSwapper.swap(address(usdc), address(usdc), 100e6, 0, user);
    }

    /*//////////////////////////////////////////////////////////////////
                                SELL_GEM
    //////////////////////////////////////////////////////////////////*/

    function test_SellGem_Success_NoFee() public {
        uint256 amountIn = 1_000e6;
        _mintAndApprove(usdc, user, address(sellSwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = sellSwapper.swap(address(usdc), address(dai), amountIn, 1_000e18, user);

        assertEq(amountOut, 1_000e18);
        assertEq(dai.balanceOf(user), 1_000e18);
        assertEq(usdc.balanceOf(user), 0);
        assertEq(usdc.balanceOf(address(sellSwapper)), 0, "swapper must hold no residual tokenIn");
    }

    function test_SellGem_Success_WithTinFee() public {
        psm.setFees(0.01e18, 0); // 1% tin fee
        uint256 amountIn = 1_000e6;
        _mintAndApprove(usdc, user, address(sellSwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = sellSwapper.swap(address(usdc), address(dai), amountIn, 990e18, user);

        assertEq(amountOut, 990e18);
        assertEq(dai.balanceOf(user), 990e18);
    }

    function test_SellGem_RevertsOnInsufficientOutput() public {
        psm.setFees(0.01e18, 0); // amountOut will be 990e18
        uint256 amountIn = 1_000e6;
        _mintAndApprove(usdc, user, address(sellSwapper), amountIn);

        vm.prank(user);
        vm.expectRevert(abi.encodeWithSelector(PSMSwapper.InsufficientOutput.selector, 1_000e18, 990e18));
        sellSwapper.swap(address(usdc), address(dai), amountIn, 1_000e18, user);
    }

    function test_SellGem_FlushesLeftoverWhenProtocolUndersConsumes() public {
        psm.setShortChange(true); // PSM only pulls half of what's offered
        uint256 amountIn = 1_000e6;
        _mintAndApprove(usdc, user, address(sellSwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = sellSwapper.swap(address(usdc), address(dai), amountIn, 500e18, user);

        assertEq(amountOut, 500e18, "only half was actually sold");
        assertEq(dai.balanceOf(user), 500e18);
        // Net USDC spent by user should be only the half actually consumed by the PSM;
        // the other half must have been flushed back.
        assertEq(usdc.balanceOf(user), 500e6, "leftover gem must be flushed back to caller");
        assertEq(usdc.balanceOf(address(sellSwapper)), 0, "swapper must not retain residual balance");
    }

    /*//////////////////////////////////////////////////////////////////
                                BUY_GEM
    //////////////////////////////////////////////////////////////////*/

    function test_BuyGem_Success_NoFee_ExactDivision() public {
        uint256 amountIn = 5_000e18; // divisible by conversionFactor, no remainder
        _mintAndApprove(dai, user, address(buySwapper), amountIn);

        uint256 daiBalBefore = dai.balanceOf(user);

        vm.prank(user);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, 5_000e6, user);

        assertEq(amountOut, 5_000e6);
        assertEq(usdc.balanceOf(user), 5_000e6);
        assertEq(daiBalBefore - dai.balanceOf(user), amountIn, "exact division: full amountIn consumed");
        assertEq(dai.balanceOf(address(buySwapper)), 0);
    }

    function test_BuyGem_Success_WithToutFee() public {
        psm.setFees(0, 0.02e18); // 2% tout fee
        uint256 amountIn = 1_020e18; // chosen so gemAmt divides evenly: 1000e6 gem
        _mintAndApprove(dai, user, address(buySwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, 1_000e6, user);

        assertEq(amountOut, 1_000e6);
        assertEq(usdc.balanceOf(user), 1_000e6);
    }

    function test_BuyGem_OnlyPullsExactCharge_RemainderStaysWithCaller() public {
        // amountIn deliberately not a multiple of conversionFactor -> gemAmt floors,
        // remainder must never leave the caller's wallet.
        uint256 amountIn = 5_000e18 + 999_999; // small remainder below 1e12 granularity
        _mintAndApprove(dai, user, address(buySwapper), amountIn);

        uint256 daiBalBefore = dai.balanceOf(user);

        vm.prank(user);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, 5_000e6, user);

        uint256 expectedGemAmt = (amountIn * WAD) / (CONVERSION_FACTOR * WAD);
        uint256 expectedPulled = (expectedGemAmt * CONVERSION_FACTOR * WAD) / WAD;

        assertEq(amountOut, expectedGemAmt);
        assertLt(expectedPulled, amountIn, "sanity: this amountIn should leave a remainder");
        assertEq(daiBalBefore - dai.balanceOf(user), expectedPulled, "only exact charge pulled from caller");
        assertEq(dai.balanceOf(address(buySwapper)), 0, "no residual left in swapper");
    }

    function test_BuyGem_RevertsWhenGemAmtRoundsToZero() public {
        uint256 amountIn = 1; // far below conversionFactor granularity
        _mintAndApprove(dai, user, address(buySwapper), amountIn);

        vm.prank(user);
        vm.expectRevert(abi.encodeWithSelector(PSMSwapper.InsufficientOutput.selector, 1, 0));
        buySwapper.swap(address(dai), address(usdc), amountIn, 0, user);
    }

    /*//////////////////////////////////////////////////////////////////
                                DAI_TO_USDS
    //////////////////////////////////////////////////////////////////*/

    function test_DaiToUsds_Success_1to1() public {
        uint256 amountIn = 1_234.56e18;
        _mintAndApprove(dai, user, address(daiToUsdsSwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, 0, user);

        assertEq(amountOut, amountIn);
        assertEq(usds.balanceOf(user), amountIn);
        assertEq(dai.balanceOf(user), 0);
    }

    function test_DaiToUsds_MinAmountOutIsOverriddenToAmountIn() public {
        // Caller passes a huge minAmountOut; contract overrides it to amountIn
        // internally for 1:1 routes, so the call must still succeed.
        uint256 amountIn = 100e18;
        _mintAndApprove(dai, user, address(daiToUsdsSwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, type(uint256).max, user);

        assertEq(amountOut, amountIn);
    }

    function test_DaiToUsds_RevertsOnNonOneToOneConversion() public {
        exchange.setBroken(true);
        uint256 amountIn = 100e18;
        _mintAndApprove(dai, user, address(daiToUsdsSwapper), amountIn);

        vm.prank(user);
        vm.expectRevert(abi.encodeWithSelector(PSMSwapper.NonOneToOneConversion.selector, amountIn, amountIn - 1));
        daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, 0, user);
    }

    /*//////////////////////////////////////////////////////////////////
                                USDS_TO_DAI
    //////////////////////////////////////////////////////////////////*/

    function test_UsdsToDai_Success_1to1() public {
        uint256 amountIn = 777e18;
        _mintAndApprove(usds, user, address(usdsToDaiSwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = usdsToDaiSwapper.swap(address(usds), address(dai), amountIn, 0, user);

        assertEq(amountOut, amountIn);
        assertEq(dai.balanceOf(user), amountIn);
        assertEq(usds.balanceOf(user), 0);
    }

    function test_UsdsToDai_RevertsOnNonOneToOneConversion() public {
        exchange.setBroken(true);
        uint256 amountIn = 50e18;
        _mintAndApprove(usds, user, address(usdsToDaiSwapper), amountIn);

        vm.prank(user);
        vm.expectRevert(abi.encodeWithSelector(PSMSwapper.NonOneToOneConversion.selector, amountIn, amountIn - 1));
        usdsToDaiSwapper.swap(address(usds), address(dai), amountIn, 0, user);
    }

    /*//////////////////////////////////////////////////////////////////
                                    FUZZ
    //////////////////////////////////////////////////////////////////*/

    function testFuzz_BuyGem_NeverPullsMoreThanAmountIn(uint256 amountIn) public {
        amountIn = bound(amountIn, 1, 1_000_000e18);
        _mintAndApprove(dai, user, address(buySwapper), amountIn);

        uint256 daiBalBefore = dai.balanceOf(user);

        vm.prank(user);
        try buySwapper.swap(address(dai), address(usdc), amountIn, 0, user) returns (uint256 amountOut) {
            uint256 pulled = daiBalBefore - dai.balanceOf(user);
            assertLe(pulled, amountIn, "must never pull more than offered");
            assertEq(usdc.balanceOf(user), amountOut);
            assertEq(dai.balanceOf(address(buySwapper)), 0);
        } catch (bytes memory reason) {
            // Only acceptable failure mode for tiny amounts is the zero-gemAmt guard.
            assertEq(bytes4(reason), PSMSwapper.InsufficientOutput.selector);
        }
    }

    function testFuzz_SellGem_OutputNeverExceedsInput(uint256 amountIn, uint256 tin) public {
        amountIn = bound(amountIn, 1, 1_000_000e6);
        tin = bound(tin, 0, WAD); // up to 100% fee
        psm.setFees(tin, 0);
        _mintAndApprove(usdc, user, address(sellSwapper), amountIn);

        vm.prank(user);
        uint256 amountOut = sellSwapper.swap(address(usdc), address(dai), amountIn, 0, user);

        assertLe(amountOut, amountIn * CONVERSION_FACTOR);
        assertEq(usdc.balanceOf(address(sellSwapper)), 0);
    }

    /*//////////////////////////////////////////////////////////////////
                                    HELPERS
    //////////////////////////////////////////////////////////////////*/

    function _mintAndApprove(MockToken token, address owner, address spender, uint256 amount) internal {
        token.mint(owner, amount);
        vm.prank(owner);
        token.approve(spender, amount);
    }
}

