    function test_SellGem_FlushesLeftoverWhenProtocolUndersConsumes() public {
        psm.setShortChange(true); // PSM only pulls half of what's offered
        uint256 amountIn = 1_000e6;
        _mintAndApprove(usdc, user, address(sellSwapper), amountIn);

