        uint256 amountOut = daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, type(uint256).max, user);

        assertEq(amountOut, amountIn);
    }

    function test_DaiToUsds_RevertsOnNonOneToOneConversion() public {
