        vm.expectRevert(abi.encodeWithSelector(PSMSwapper.NonOneToOneConversion.selector, amountIn, amountIn - 1));
        usdsToDaiSwapper.swap(address(usds), address(dai), amountIn, 0, user);
    }

    /*//////////////////////////////////////////////////////////////////
                                    FUZZ
    //////////////////////////////////////////////////////////////////*/

    function testFuzz_BuyGem_NeverPullsMoreThanAmountIn(uint256 amountIn) public {
        amountIn = bound(amountIn, 1, 1_000_000e18);
        _mintAndApprove(dai, user, address(buySwapper), amountIn);

        uint256 daiBalBefore = dai.balanceOf(user);

        vm.prank(user);
        try buySwapper.swap(address(dai), address(usdc), amountIn, 0, user) returns (uint256 amountOut) {
