            assertLe(pulled, amountIn, "must never pull more than offered");
            assertEq(usdc.balanceOf(user), amountOut);
            assertEq(dai.balanceOf(address(buySwapper)), 0);
        } catch (bytes memory reason) {
            // Only acceptable failure mode for tiny amounts is the zero-gemAmt guard.
            assertEq(bytes4(reason), PSMSwapper.InsufficientOutput.selector);
