// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import {Test} from "forge-std/Test.sol";
import {PSMSwapper} from "src/swappers/PSMSwapper.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

// ============================================================
// MOCK TOKENS
// ============================================================

contract MockERC20 is ERC20 {
    uint8 private immutable _decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _decimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

// ============================================================
// MOCK PSM
// ============================================================

/// @dev Mimics Sky Protocol LitePSM sellGem/buyGem semantics closely enough to
///      exercise PSMSwapper's fee/rounding logic. Exposes "pull bps" knobs so
///      tests can simulate a PSM that doesn't consume the full amount handed
///      to it, which is what exercises PSMSwapper's leftover-refund path.
contract MockPSM {
    uint256 internal constant WAD = 1e18;

    address public immutable gem;
    address public immutable dai;
    uint256 public immutable to18ConversionFactor;

    uint256 public tin;
    uint256 public tout;

    /// @dev basis points (out of 10_000) of the "owed" amount actually pulled via transferFrom.
    uint256 public sellGemPullBps = 10_000;
    uint256 public buyGemPullBps = 10_000;

    constructor(address _gem, address _dai, uint256 _to18ConversionFactor) {
        gem = _gem;
        dai = _dai;
        to18ConversionFactor = _to18ConversionFactor;
    }

    function setFees(uint256 _tin, uint256 _tout) external {
        tin = _tin;
        tout = _tout;
    }

    function setSellGemPullBps(uint256 bps) external {
        sellGemPullBps = bps;
    }

    function setBuyGemPullBps(uint256 bps) external {
        buyGemPullBps = bps;
    }

    function sellGem(address usr, uint256 gemAmt) external returns (uint256 daiOutWad) {
        uint256 pull = (gemAmt * sellGemPullBps) / 10_000;
        IERC20(gem).transferFrom(msg.sender, address(this), pull);
        daiOutWad = (gemAmt * to18ConversionFactor * (WAD - tin)) / WAD;
        IERC20(dai).transfer(usr, daiOutWad);
    }

    function buyGem(address usr, uint256 gemAmt) external returns (uint256 daiInWad) {
        uint256 owed = (gemAmt * to18ConversionFactor * (WAD + tout)) / WAD;
        uint256 pull = (owed * buyGemPullBps) / 10_000;
        IERC20(dai).transferFrom(msg.sender, address(this), pull);
        daiInWad = owed;
        IERC20(gem).transfer(usr, gemAmt);
    }
}

// ============================================================
// MOCK DAI <-> USDS EXCHANGE
// ============================================================

contract MockDaiUsdsExchange {
    address public immutable dai;
    address public immutable usds;

    /// @dev basis points knobs to simulate imperfect 1:1 conversions / partial pulls.
    uint256 public daiToUsdsOutBps = 10_000;
    uint256 public daiToUsdsPullBps = 10_000;
    uint256 public usdsToDaiOutBps = 10_000;
    uint256 public usdsToDaiPullBps = 10_000;

    constructor(address _dai, address _usds) {
        dai = _dai;
        usds = _usds;
    }

    function setDaiToUsdsBps(uint256 pullBps, uint256 outBps) external {
        daiToUsdsPullBps = pullBps;
        daiToUsdsOutBps = outBps;
    }

    function setUsdsToDaiBps(uint256 pullBps, uint256 outBps) external {
        usdsToDaiPullBps = pullBps;
        usdsToDaiOutBps = outBps;
    }

    function daiToUsds(address usr, uint256 wad) external {
        uint256 pull = (wad * daiToUsdsPullBps) / 10_000;
        IERC20(dai).transferFrom(msg.sender, address(this), pull);
        uint256 out = (wad * daiToUsdsOutBps) / 10_000;
        IERC20(usds).transfer(usr, out);
    }

    function usdsToDai(address usr, uint256 wad) external {
        uint256 pull = (wad * usdsToDaiPullBps) / 10_000;
        IERC20(usds).transferFrom(msg.sender, address(this), pull);
        uint256 out = (wad * usdsToDaiOutBps) / 10_000;
        IERC20(dai).transfer(usr, out);
    }
}

// ============================================================
// TESTS
// ============================================================

contract PSMSwapperTest is Test {
    uint256 internal constant WAD = 1e18;
    uint256 internal constant CONVERSION_FACTOR = 1e12; // 6 -> 18 decimals

    MockERC20 internal gem; // USDC-like, 6 decimals
    MockERC20 internal dai; // 18 decimals
    MockERC20 internal usds; // 18 decimals

    MockPSM internal psm;
    MockDaiUsdsExchange internal exchange;

    PSMSwapper internal sellGemSwapper;
    PSMSwapper internal buyGemSwapper;
    PSMSwapper internal daiToUsdsSwapper;
    PSMSwapper internal usdsToDaiSwapper;

    address internal user = makeAddr("user");
    address internal receiver = makeAddr("receiver");

    function setUp() public {
        gem = new MockERC20("USD Coin", "USDC", 6);
        dai = new MockERC20("Dai", "DAI", 18);
        usds = new MockERC20("USDS", "USDS", 18);

        psm = new MockPSM(address(gem), address(dai), CONVERSION_FACTOR);
        exchange = new MockDaiUsdsExchange(address(dai), address(usds));

        // Fund protocols with liquidity to pay out swaps.
        gem.mint(address(psm), 10_000_000e6);
        dai.mint(address(psm), 10_000_000e18);
        dai.mint(address(exchange), 10_000_000e18);
        usds.mint(address(exchange), 10_000_000e18);

        // Fund the user.
        gem.mint(user, 1_000_000e6);
        dai.mint(user, 1_000_000e18);
        usds.mint(user, 1_000_000e18);

        sellGemSwapper =
            new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(gem), address(dai), 0);
        buyGemSwapper = new PSMSwapper(
            address(psm), PSMSwapper.Route.BUY_GEM, address(dai), address(gem), CONVERSION_FACTOR
        );
        daiToUsdsSwapper =
            new PSMSwapper(address(exchange), PSMSwapper.Route.DAI_TO_USDS, address(dai), address(usds), 0);
        usdsToDaiSwapper =
            new PSMSwapper(address(exchange), PSMSwapper.Route.USDS_TO_DAI, address(usds), address(dai), 0);
    }

    // ============================================================
    // CONSTRUCTOR
    // ============================================================

    function test_Constructor_RevertsOnZeroProtocol() public {
        vm.expectRevert(PSMSwapper.InvalidProtocol.selector);
        new PSMSwapper(address(0), PSMSwapper.Route.SELL_GEM, address(gem), address(dai), 0);
    }

    function test_Constructor_RevertsOnZeroTokenIn() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(0), address(dai), 0);
    }

    function test_Constructor_RevertsOnZeroTokenOut() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(gem), address(0), 0);
    }

    function test_Constructor_RevertsOnZeroConversionFactorForBuyGem() public {
        vm.expectRevert(PSMSwapper.InvalidConversionFactor.selector);
        new PSMSwapper(address(psm), PSMSwapper.Route.BUY_GEM, address(dai), address(gem), 0);
    }

    function test_Constructor_AllowsZeroConversionFactorForNonBuyGemRoutes() public {
        PSMSwapper s1 =
            new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(gem), address(dai), 0);
        assertEq(s1.conversionFactor(), 0);

        PSMSwapper s2 =
            new PSMSwapper(address(exchange), PSMSwapper.Route.DAI_TO_USDS, address(dai), address(usds), 0);
        assertEq(s2.conversionFactor(), 0);

        PSMSwapper s3 =
            new PSMSwapper(address(exchange), PSMSwapper.Route.USDS_TO_DAI, address(usds), address(dai), 0);
        assertEq(s3.conversionFactor(), 0);
    }

    function test_Constructor_SetsImmutables() public view {
        assertEq(sellGemSwapper.protocol(), address(psm));
        assertEq(uint256(sellGemSwapper.route()), uint256(PSMSwapper.Route.SELL_GEM));
        assertEq(sellGemSwapper.tokenIn(), address(gem));
        assertEq(sellGemSwapper.tokenOut(), address(dai));
        assertEq(sellGemSwapper.conversionFactor(), 0);

        assertEq(buyGemSwapper.protocol(), address(psm));
        assertEq(uint256(buyGemSwapper.route()), uint256(PSMSwapper.Route.BUY_GEM));
        assertEq(buyGemSwapper.tokenIn(), address(dai));
        assertEq(buyGemSwapper.tokenOut(), address(gem));
        assertEq(buyGemSwapper.conversionFactor(), CONVERSION_FACTOR);

        assertEq(daiToUsdsSwapper.protocol(), address(exchange));
        assertEq(uint256(daiToUsdsSwapper.route()), uint256(PSMSwapper.Route.DAI_TO_USDS));

        assertEq(usdsToDaiSwapper.protocol(), address(exchange));
        assertEq(uint256(usdsToDaiSwapper.route()), uint256(PSMSwapper.Route.USDS_TO_DAI));
    }

    // ============================================================
    // GENERIC INPUT VALIDATION
    // ============================================================

    function test_Swap_RevertsOnTokenInMismatch() public {
        vm.startPrank(user);
        gem.approve(address(sellGemSwapper), 1000e6);
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        sellGemSwapper.swap(address(dai), address(dai), 1000e6, 0, receiver);
        vm.stopPrank();
    }

    function test_Swap_RevertsOnTokenOutMismatch() public {
        vm.startPrank(user);
        gem.approve(address(sellGemSwapper), 1000e6);
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        sellGemSwapper.swap(address(gem), address(gem), 1000e6, 0, receiver);
        vm.stopPrank();
    }

    // ============================================================
    // SELL_GEM
    // ============================================================

    function test_SellGem_Success() public {
        uint256 amountIn = 1000e6;
        uint256 expectedOut = amountIn * CONVERSION_FACTOR; // tin = 0

        uint256 userBalBefore = gem.balanceOf(user);

        vm.startPrank(user);
        gem.approve(address(sellGemSwapper), amountIn);
        uint256 amountOut = sellGemSwapper.swap(address(gem), address(dai), amountIn, expectedOut, receiver);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
        assertEq(dai.balanceOf(receiver), expectedOut);
        assertEq(gem.balanceOf(user), userBalBefore - amountIn);
        assertEq(gem.balanceOf(address(sellGemSwapper)), 0);
        assertEq(dai.balanceOf(address(sellGemSwapper)), 0);
        assertEq(gem.allowance(address(sellGemSwapper), address(psm)), 0);
    }

    function test_SellGem_RevertsOnInsufficientOutput() public {
        uint256 amountIn = 1000e6;
        uint256 actualOut = amountIn * CONVERSION_FACTOR;
        uint256 minAmountOut = actualOut + 1;

        vm.startPrank(user);
        gem.approve(address(sellGemSwapper), amountIn);
        vm.expectRevert(
            abi.encodeWithSelector(PSMSwapper.InsufficientOutput.selector, minAmountOut, actualOut)
        );
        sellGemSwapper.swap(address(gem), address(dai), amountIn, minAmountOut, receiver);
        vm.stopPrank();
    }

    function test_SellGem_LeftoverRefundedToCaller() public {
        uint256 amountIn = 1000e6;
        psm.setSellGemPullBps(9000); // PSM only actually pulls 90% of the gem it's handed

        uint256 userBalBefore = gem.balanceOf(user);
        uint256 expectedPulled = (amountIn * 9000) / 10_000;
        uint256 expectedRefund = amountIn - expectedPulled;
        uint256 expectedOut = amountIn * CONVERSION_FACTOR; // dai payout unaffected by gem pull%

        vm.startPrank(user);
        gem.approve(address(sellGemSwapper), amountIn);
        uint256 amountOut = sellGemSwapper.swap(address(gem), address(dai), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
        assertEq(dai.balanceOf(receiver), expectedOut);
        // user paid net (amountIn - refund) == expectedPulled
        assertEq(gem.balanceOf(user), userBalBefore - expectedPulled);
        assertEq(gem.balanceOf(user), userBalBefore - amountIn + expectedRefund);
        assertEq(gem.balanceOf(address(sellGemSwapper)), 0);
        assertEq(gem.balanceOf(address(psm)) - (10_000_000e6), expectedPulled);
    }

    function testFuzz_SellGem(uint256 amountIn) public {
        amountIn = bound(amountIn, 1, 1_000_000e6);

        uint256 userBalBefore = gem.balanceOf(user);
        uint256 expectedOut = amountIn * CONVERSION_FACTOR;

        vm.startPrank(user);
        gem.approve(address(sellGemSwapper), amountIn);
        uint256 amountOut = sellGemSwapper.swap(address(gem), address(dai), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
        assertEq(gem.balanceOf(user), userBalBefore - amountIn);
        assertEq(dai.balanceOf(receiver), expectedOut);
    }

    // ============================================================
    // BUY_GEM
    // ============================================================

    function _expectedBuyGem(uint256 amountIn, uint256 tout)
        internal
        pure
        returns (uint256 gemAmt, uint256 actualPulled)
    {
        gemAmt = (amountIn * WAD) / (CONVERSION_FACTOR * (WAD + tout));
        actualPulled = (gemAmt * CONVERSION_FACTOR * (WAD + tout)) / WAD;
    }

    function test_BuyGem_Success_ZeroFee_ExactDivision() public {
        uint256 amountIn = 1000e18;
        (uint256 gemAmt, uint256 actualPulled) = _expectedBuyGem(amountIn, 0);
        assertEq(actualPulled, amountIn); // evenly divisible, no remainder

        uint256 userBalBefore = dai.balanceOf(user);

        vm.startPrank(user);
        dai.approve(address(buyGemSwapper), amountIn);
        uint256 amountOut = buyGemSwapper.swap(address(dai), address(gem), amountIn, gemAmt, receiver);
        vm.stopPrank();

        assertEq(amountOut, gemAmt);
        assertEq(gem.balanceOf(receiver), gemAmt);
        assertEq(dai.balanceOf(user), userBalBefore - actualPulled);
        assertEq(dai.balanceOf(address(buyGemSwapper)), 0);
        assertEq(dai.allowance(address(buyGemSwapper), address(psm)), 0);
    }

    function test_BuyGem_PullsOnlyExactCharge_RemainderStaysWithCaller() public {
        // amountIn deliberately not a multiple of CONVERSION_FACTOR -> floor division leaves a remainder.
        uint256 amountIn = 1000e18 + 999_999_999_999;
        (uint256 gemAmt, uint256 actualPulled) = _expectedBuyGem(amountIn, 0);
        assertLt(actualPulled, amountIn);

        uint256 userBalBefore = dai.balanceOf(user);

        vm.startPrank(user);
        dai.approve(address(buyGemSwapper), amountIn);
        uint256 amountOut = buyGemSwapper.swap(address(dai), address(gem), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, gemAmt);
        // Caller was only charged the exact PSM charge, not the full amountIn.
        assertEq(userBalBefore - dai.balanceOf(user), actualPulled);
        assertEq(dai.balanceOf(address(buyGemSwapper)), 0);
        // Unspent allowance remains with the caller.
        assertEq(dai.allowance(user, address(buyGemSwapper)), amountIn - actualPulled);
    }

    function test_BuyGem_WithNonZeroFee() public {
        uint256 tout = 0.01e18; // 1%
        psm.setFees(0, tout);

        uint256 amountIn = 1010e18;
        (uint256 gemAmt, uint256 actualPulled) = _expectedBuyGem(amountIn, tout);
        assertGt(gemAmt, 0);

        uint256 userBalBefore = dai.balanceOf(user);

        vm.startPrank(user);
        dai.approve(address(buyGemSwapper), amountIn);
        uint256 amountOut = buyGemSwapper.swap(address(dai), address(gem), amountIn, gemAmt, receiver);
        vm.stopPrank();

        assertEq(amountOut, gemAmt);
        assertEq(gem.balanceOf(receiver), gemAmt);
        assertEq(userBalBefore - dai.balanceOf(user), actualPulled);
    }

    function test_BuyGem_RevertsWhenGemAmtRoundsToZero() public {
        uint256 amountIn = 1; // far smaller than CONVERSION_FACTOR -> gemAmt floors to 0

        vm.startPrank(user);
        dai.approve(address(buyGemSwapper), amountIn);
        vm.expectRevert(abi.encodeWithSelector(PSMSwapper.InsufficientOutput.selector, 1, 0));
        buyGemSwapper.swap(address(dai), address(gem), amountIn, 0, receiver);
        vm.stopPrank();
    }

    function test_BuyGem_RevertsOnInsufficientOutput() public {
        uint256 amountIn = 1000e18;
        (uint256 gemAmt,) = _expectedBuyGem(amountIn, 0);
        uint256 minAmountOut = gemAmt + 1;

        vm.startPrank(user);
        dai.approve(address(buyGemSwapper), amountIn);
        vm.expectRevert(
            abi.encodeWithSelector(PSMSwapper.InsufficientOutput.selector, minAmountOut, gemAmt)
        );
        buyGemSwapper.swap(address(dai), address(gem), amountIn, minAmountOut, receiver);
        vm.stopPrank();
    }

    function test_BuyGem_LeftoverRefundedToCaller() public {
        uint256 amountIn = 1000e18;
        (uint256 gemAmt, uint256 actualPulled) = _expectedBuyGem(amountIn, 0);
        psm.setBuyGemPullBps(9000); // PSM only actually pulls 90% of what the swapper approved/pulled

        uint256 userBalBefore = dai.balanceOf(user);
        uint256 expectedPsmPull = (actualPulled * 9000) / 10_000;
        uint256 expectedRefund = actualPulled - expectedPsmPull;

        vm.startPrank(user);
        dai.approve(address(buyGemSwapper), amountIn);
        uint256 amountOut = buyGemSwapper.swap(address(dai), address(gem), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, gemAmt);
        assertEq(gem.balanceOf(receiver), gemAmt);
        assertEq(dai.balanceOf(address(buyGemSwapper)), 0);
        // Net cost to user = amountPulled from them minus refunded leftover.
        assertEq(userBalBefore - dai.balanceOf(user), actualPulled - expectedRefund);
    }

    function testFuzz_BuyGem(uint256 amountIn) public {
        amountIn = bound(amountIn, CONVERSION_FACTOR, 1_000_000e18);
        (uint256 gemAmt, uint256 actualPulled) = _expectedBuyGem(amountIn, 0);
        vm.assume(gemAmt > 0);

        uint256 userBalBefore = dai.balanceOf(user);

        vm.startPrank(user);
        dai.approve(address(buyGemSwapper), amountIn);
        uint256 amountOut = buyGemSwapper.swap(address(dai), address(gem), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, gemAmt);
        assertEq(userBalBefore - dai.balanceOf(user), actualPulled);
    }

    // ============================================================
    // DAI_TO_USDS
    // ============================================================

    function test_DaiToUsds_Success() public {
        uint256 amountIn = 500e18;
        uint256 userBalBefore = dai.balanceOf(user);

        vm.startPrank(user);
        dai.approve(address(daiToUsdsSwapper), amountIn);
        uint256 amountOut = daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, amountIn);
        assertEq(usds.balanceOf(receiver), amountIn);
        assertEq(dai.balanceOf(user), userBalBefore - amountIn);
        assertEq(dai.balanceOf(address(daiToUsdsSwapper)), 0);
    }

    function test_DaiToUsds_CallerMinAmountOutIsIgnoredWhenConversionIsExact() public {
        uint256 amountIn = 500e18;

        vm.startPrank(user);
        dai.approve(address(daiToUsdsSwapper), amountIn);
        // A minAmountOut far above amountIn would normally revert, but the
        // function overrides minAmountOut to amountIn internally for 1:1 routes.
        uint256 amountOut =
            daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, type(uint256).max, receiver);
        vm.stopPrank();

        assertEq(amountOut, amountIn);
    }

    function test_DaiToUsds_RevertsOnNonOneToOneConversion() public {
        uint256 amountIn = 500e18;
        exchange.setDaiToUsdsBps(10_000, 9900); // only pays out 99%
        uint256 actualOut = (amountIn * 9900) / 10_000;

        vm.startPrank(user);
        dai.approve(address(daiToUsdsSwapper), amountIn);
        vm.expectRevert(
            abi.encodeWithSelector(PSMSwapper.NonOneToOneConversion.selector, amountIn, actualOut)
        );
        daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, 0, receiver);
        vm.stopPrank();
    }

    function test_DaiToUsds_LeftoverRefundedToCaller() public {
        uint256 amountIn = 500e18;
        exchange.setDaiToUsdsBps(9000, 10_000); // exchange only pulls 90% of the dai handed to it, still pays out 100%

        uint256 userBalBefore = dai.balanceOf(user);
        uint256 expectedPulled = (amountIn * 9000) / 10_000;

        vm.startPrank(user);
        dai.approve(address(daiToUsdsSwapper), amountIn);
        uint256 amountOut = daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, amountIn);
        assertEq(usds.balanceOf(receiver), amountIn);
        assertEq(dai.balanceOf(address(daiToUsdsSwapper)), 0);
        assertEq(userBalBefore - dai.balanceOf(user), expectedPulled);
    }

    // ============================================================
    // USDS_TO_DAI
    // ============================================================

    function test_UsdsToDai_Success() public {
        uint256 amountIn = 500e18;
        uint256 userBalBefore = usds.balanceOf(user);

        vm.startPrank(user);
        usds.approve(address(usdsToDaiSwapper), amountIn);
        uint256 amountOut = usdsToDaiSwapper.swap(address(usds), address(dai), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, amountIn);
        assertEq(dai.balanceOf(receiver), amountIn);
        assertEq(usds.balanceOf(user), userBalBefore - amountIn);
        assertEq(usds.balanceOf(address(usdsToDaiSwapper)), 0);
    }

    function test_UsdsToDai_RevertsOnNonOneToOneConversion() public {
        uint256 amountIn = 500e18;
        exchange.setUsdsToDaiBps(10_000, 9950); // only pays out 99.5%
        uint256 actualOut = (amountIn * 9950) / 10_000;

        vm.startPrank(user);
        usds.approve(address(usdsToDaiSwapper), amountIn);
        vm.expectRevert(
            abi.encodeWithSelector(PSMSwapper.NonOneToOneConversion.selector, amountIn, actualOut)
        );
        usdsToDaiSwapper.swap(address(usds), address(dai), amountIn, 0, receiver);
        vm.stopPrank();
    }

    function test_UsdsToDai_LeftoverRefundedToCaller() public {
        uint256 amountIn = 500e18;
        exchange.setUsdsToDaiBps(8000, 10_000); // exchange only pulls 80% of usds handed to it

        uint256 userBalBefore = usds.balanceOf(user);
        uint256 expectedPulled = (amountIn * 8000) / 10_000;

        vm.startPrank(user);
        usds.approve(address(usdsToDaiSwapper), amountIn);
        uint256 amountOut = usdsToDaiSwapper.swap(address(usds), address(dai), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, amountIn);
        assertEq(dai.balanceOf(receiver), amountIn);
        assertEq(usds.balanceOf(address(usdsToDaiSwapper)), 0);
        assertEq(userBalBefore - usds.balanceOf(user), expectedPulled);
    }

    function testFuzz_UsdsToDai(uint256 amountIn) public {
        amountIn = bound(amountIn, 1, 1_000_000e18);
        uint256 userBalBefore = usds.balanceOf(user);

        vm.startPrank(user);
        usds.approve(address(usdsToDaiSwapper), amountIn);
        uint256 amountOut = usdsToDaiSwapper.swap(address(usds), address(dai), amountIn, 0, receiver);
        vm.stopPrank();

        assertEq(amountOut, amountIn);
        assertEq(usds.balanceOf(user), userBalBefore - amountIn);
        assertEq(dai.balanceOf(receiver), amountIn);
    }
}

