// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import {Test} from "forge-std/Test.sol";
import {PSMSwapper} from "src/swappers/PSMSwapper.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

// ============================================================
// MOCK TOKENS
// ============================================================

contract MockERC20 is ERC20 {
    uint8 private immutable _decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _decimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

// ============================================================
// MOCK PSM
// ============================================================

/// @dev Mimics Sky Protocol LitePSM sellGem/buyGem semantics closely enough to
///      exercise PSMSwapper's fee/rounding logic. Exposes "pull bps" knobs so
///      tests can simulate a PSM that doesn't consume the full amount handed
///      to it, which is what exercises PSMSwapper's leftover-refund path.
contract MockPSM {
    uint256 internal constant WAD = 1e18;

    address public immutable gem;
    address public immutable dai;
    uint256 public immutable to18ConversionFactor;

    uint256 public tin;
    uint256 public tout;

    /// @dev basis points (out of 10_000) of the "owed" amount actually pulled via transferFrom.
    uint256 public sellGemPullBps = 10_000;
    uint256 public buyGemPullBps = 10_000;

    constructor(address _gem, address _dai, uint256 _to18ConversionFactor) {
        gem = _gem;
        dai = _dai;
        to18ConversionFactor = _to18ConversionFactor;
    }

    function setFees(uint256 _tin, uint256 _tout) external {
        tin = _tin;
        tout = _tout;
    }

    function setSellGemPullBps(uint256 bps) external {
        sellGemPullBps = bps;
    }

    function setBuyGemPullBps(uint256 bps) external {
        buyGemPullBps = bps;
    }

    function sellGem(address usr, uint256 gemAmt) external returns (uint256 daiOutWad) {
        uint256 pull = (gemAmt * sellGemPullBps) / 10_000;
        IERC20(gem).transferFrom(msg.sender, address(this), pull);
        daiOutWad = (gemAmt * to18ConversionFactor * (WAD - tin)) / WAD;
        IERC20(dai).transfer(usr, daiOutWad);
    }

    function buyGem(address usr, uint256 gemAmt) external returns (uint256 daiInWad) {
        uint256 owed = (gemAmt * to18ConversionFactor * (WAD + tout)) / WAD;
        uint256 pull = (owed * buyGemPullBps) / 10_000;
        IERC20(dai).transferFrom(msg.sender, address(this), pull);
        daiInWad = owed;
        IERC20(gem).transfer(usr, gemAmt);
    }
}

// ============================================================
// MOCK DAI <-> USDS EXCHANGE
// ============================================================

contract MockDaiUsdsExchange {
    address public immutable dai;
    address public immutable usds;

    /// @dev basis points knobs to simulate imperfect 1:1 conversions / partial pulls.
    uint256 public daiToUsdsOutBps = 10_000;
    uint256 public daiToUsdsPullBps = 10_000;
    uint256 public usdsToDaiOutBps = 10_000;
    uint256 public usdsToDaiPullBps = 10_000;

    constructor(address _dai, address _usds) {
        dai = _dai;
        usds = _usds;
    }

    function setDaiToUsdsBps(uint256 pullBps, uint256 outBps) external {
        daiToUsdsPullBps = pullBps;
        daiToUsdsOutBps = outBps;
    }

    function setUsdsToDaiBps(uint256 pullBps, uint256 outBps) external {
        usdsToDaiPullBps = pullBps;
        usdsToDaiOutBps = outBps;
    }

    function daiToUsds(address usr, uint256 wad) external {
        uint256 pull = (wad * daiToUsdsPullBps) / 10_000;
        IERC20(dai).transferFrom(msg.sender, address(this), pull);
        uint256 out = (wad * daiToUsdsOutBps) / 10_000;
        IERC20(usds).transfer(usr, out);
    }

    function usdsToDai(address usr, uint256 wad) external {
        uint256 pull = (wad * usdsToDaiPullBps) / 10_000;
        IERC20(usds).transferFrom(msg.sender, address(this), pull);
        uint256 out = (wad * usdsToDaiOutBps) / 10_000;
        IERC20(dai).transfer(usr, out);
    }
}

