// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { PSMSwapper } from "src/swappers/PSMSwapper.sol";

// ============================================
// MOCKS
// ============================================

/// @dev Simple mintable ERC20 with configurable decimals, used to stand in for
///      USDC (6 decimals) / DAI / USDS (18 decimals) in tests.
contract MockERC20 is ERC20 {
    uint8 private immutable _decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_) ERC20(name_, symbol_) {
        _decimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Mimics the relevant surface of Sky Protocol's LitePSM:
///      sellGem(usr, gemAmt) pulls `gemAmt` gem from msg.sender and pays out
///      `gemAmt * conversionFactor` DAI/USDS minus the tin fee to `usr`.
///      buyGem(usr, gemAmt) pulls `gemAmt * conversionFactor * (1+tout)` DAI/USDS
///      from msg.sender and pays out `gemAmt` gem to `usr`.
contract MockPSM {
    IERC20 public immutable gem;
    IERC20 public immutable dai;
    uint256 public immutable conversionFactor;
    uint256 internal constant WAD = 1e18;

    uint256 public tin;
    uint256 public tout;

    constructor(IERC20 _gem, IERC20 _dai, uint256 _conversionFactor) {
        gem = _gem;
        dai = _dai;
        conversionFactor = _conversionFactor;
    }

    function setFees(uint256 _tin, uint256 _tout) external {
        tin = _tin;
        tout = _tout;
    }

    function sellGem(address usr, uint256 gemAmt) external returns (uint256 daiOutWad) {
        gem.transferFrom(msg.sender, address(this), gemAmt);
        uint256 gemWad = gemAmt * conversionFactor;
        uint256 fee = (gemWad * tin) / WAD;
        daiOutWad = gemWad - fee;
        dai.transfer(usr, daiOutWad);
    }

    function buyGem(address usr, uint256 gemAmt) external returns (uint256 daiInWad) {
        uint256 gemWad = gemAmt * conversionFactor;
        daiInWad = (gemWad * (WAD + tout)) / WAD;
        dai.transferFrom(msg.sender, address(this), daiInWad);
        gem.transfer(usr, gemAmt);
    }
}

/// @dev Faulty/malicious PSM stand-in that only pulls half of the gem it is
///      offered in sellGem, used to force a nonzero leftover so we can assert
///      the swapper's defense-in-depth flush-back-to-caller behavior.
contract PartialPullPSM {
    IERC20 public immutable gem;
    IERC20 public immutable dai;
    uint256 public immutable conversionFactor;

    constructor(IERC20 _gem, IERC20 _dai, uint256 _conversionFactor) {
        gem = _gem;
        dai = _dai;
        conversionFactor = _conversionFactor;
    }

    function sellGem(address usr, uint256 gemAmt) external returns (uint256 daiOutWad) {
        uint256 pulled = gemAmt / 2;
        gem.transferFrom(msg.sender, address(this), pulled);
        daiOutWad = pulled * conversionFactor;
        dai.transfer(usr, daiOutWad);
    }

    function tout() external pure returns (uint256) {
        return 0;
    }

    function buyGem(address, uint256) external pure returns (uint256) {
        return 0;
    }
}

/// @dev Mimics the DaiUsds converter. `brokenRate` lets us simulate a
///      non-1:1 output to exercise NonOneToOneConversion.
contract MockExchange {
    IERC20 public immutable dai;
    IERC20 public immutable usds;
    bool public brokenRate;

    constructor(IERC20 _dai, IERC20 _usds) {
        dai = _dai;
        usds = _usds;
    }

    function setBrokenRate(bool b) external {
        brokenRate = b;
    }

    function daiToUsds(address usr, uint256 wad) external {
        dai.transferFrom(msg.sender, address(this), wad);
        uint256 outAmt = brokenRate ? wad - 1 : wad;
        usds.transfer(usr, outAmt);
    }

    function usdsToDai(address usr, uint256 wad) external {
        usds.transferFrom(msg.sender, address(this), wad);
        uint256 outAmt = brokenRate ? wad - 1 : wad;
        dai.transfer(usr, outAmt);
    }
}

// ============================================
// TESTS
// ============================================

contract PSMSwapperTest is Test {
    uint256 internal constant WAD = 1e18;
    uint256 internal constant USDC_CONVERSION_FACTOR = 1e12;

    MockERC20 internal usdc;
    MockERC20 internal dai;
    MockERC20 internal usds;

    MockPSM internal psm; // usdc <-> dai
    MockExchange internal exchange; // dai <-> usds

    PSMSwapper internal sellSwapper; // usdc -> dai
    PSMSwapper internal buySwapper; // dai -> usdc
    PSMSwapper internal daiToUsdsSwapper; // dai -> usds
    PSMSwapper internal usdsToDaiSwapper; // usds -> dai

    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");

    function setUp() public {
        usdc = new MockERC20("USD Coin", "USDC", 6);
        dai = new MockERC20("Dai Stablecoin", "DAI", 18);
        usds = new MockERC20("USDS Stablecoin", "USDS", 18);

        psm = new MockPSM(IERC20(address(usdc)), IERC20(address(dai)), USDC_CONVERSION_FACTOR);
        exchange = new MockExchange(IERC20(address(dai)), IERC20(address(usds)));

        // Fund protocol mocks with liquidity so they can pay out swaps.
        dai.mint(address(psm), 10_000_000e18);
        usdc.mint(address(psm), 10_000_000e6);
        dai.mint(address(exchange), 10_000_000e18);
        usds.mint(address(exchange), 10_000_000e18);

        sellSwapper =
            new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(usdc), address(dai), 0);
        buySwapper = new PSMSwapper(
            address(psm), PSMSwapper.Route.BUY_GEM, address(dai), address(usdc), USDC_CONVERSION_FACTOR
        );
        daiToUsdsSwapper =
            new PSMSwapper(address(exchange), PSMSwapper.Route.DAI_TO_USDS, address(dai), address(usds), 0);
        usdsToDaiSwapper =
            new PSMSwapper(address(exchange), PSMSwapper.Route.USDS_TO_DAI, address(usds), address(dai), 0);

        // Fund the user and set approvals.
        usdc.mint(alice, 1_000_000e6);
        dai.mint(alice, 1_000_000e18);
        usds.mint(alice, 1_000_000e18);

        vm.startPrank(alice);
        usdc.approve(address(sellSwapper), type(uint256).max);
        dai.approve(address(buySwapper), type(uint256).max);
        dai.approve(address(daiToUsdsSwapper), type(uint256).max);
        usds.approve(address(usdsToDaiSwapper), type(uint256).max);
        vm.stopPrank();
    }

    // ============================================
    // CONSTRUCTOR
    // ============================================

    function test_constructor_setsImmutables() public view {
        assertEq(sellSwapper.protocol(), address(psm));
        assertEq(uint256(sellSwapper.route()), uint256(PSMSwapper.Route.SELL_GEM));
        assertEq(sellSwapper.tokenIn(), address(usdc));
        assertEq(sellSwapper.tokenOut(), address(dai));
        assertEq(sellSwapper.conversionFactor(), 0);

        assertEq(buySwapper.conversionFactor(), USDC_CONVERSION_FACTOR);
    }

    function test_constructor_revertsOnZeroProtocol() public {
        vm.expectRevert(PSMSwapper.InvalidProtocol.selector);
        new PSMSwapper(address(0), PSMSwapper.Route.SELL_GEM, address(usdc), address(dai), 0);
    }

    function test_constructor_revertsOnZeroTokenIn() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(0), address(dai), 0);
    }

    function test_constructor_revertsOnZeroTokenOut() public {
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(usdc), address(0), 0);
    }

    function test_constructor_revertsOnZeroConversionFactorForBuyGem() public {
        vm.expectRevert(PSMSwapper.InvalidConversionFactor.selector);
        new PSMSwapper(address(psm), PSMSwapper.Route.BUY_GEM, address(dai), address(usdc), 0);
    }

    function test_constructor_allowsZeroConversionFactorForNonBuyGemRoutes() public {
        // SELL_GEM
        new PSMSwapper(address(psm), PSMSwapper.Route.SELL_GEM, address(usdc), address(dai), 0);
        // DAI_TO_USDS
        new PSMSwapper(address(exchange), PSMSwapper.Route.DAI_TO_USDS, address(dai), address(usds), 0);
        // USDS_TO_DAI
        new PSMSwapper(address(exchange), PSMSwapper.Route.USDS_TO_DAI, address(usds), address(dai), 0);
    }

    // ============================================
    // TOKEN VALIDATION
    // ============================================

    function test_swap_revertsOnWrongTokenIn() public {
        vm.prank(alice);
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        sellSwapper.swap(address(dai), address(dai), 1000e6, 0, bob);
    }

    function test_swap_revertsOnWrongTokenOut() public {
        vm.prank(alice);
        vm.expectRevert(PSMSwapper.InvalidToken.selector);
        sellSwapper.swap(address(usdc), address(usdc), 1000e6, 0, bob);
    }

    // ============================================
    // SELL_GEM
    // ============================================

    function test_sellGem_zeroFee_fullConversion() public {
        uint256 amountIn = 1000e6;
        uint256 expectedOut = amountIn * USDC_CONVERSION_FACTOR;

        uint256 aliceUsdcBefore = usdc.balanceOf(alice);

        vm.prank(alice);
        uint256 amountOut = sellSwapper.swap(address(usdc), address(dai), amountIn, expectedOut, bob);

        assertEq(amountOut, expectedOut);
        assertEq(dai.balanceOf(bob), expectedOut);
        assertEq(usdc.balanceOf(alice), aliceUsdcBefore - amountIn);
        assertEq(usdc.balanceOf(address(sellSwapper)), 0);
        assertEq(dai.balanceOf(address(sellSwapper)), 0);
        assertEq(usdc.allowance(address(sellSwapper), address(psm)), 0);
    }

    function test_sellGem_withFee_reducesOutput() public {
        uint256 tin = 1e16; // 1%
        psm.setFees(tin, 0);

        uint256 amountIn = 1000e6;
        uint256 gemWad = amountIn * USDC_CONVERSION_FACTOR;
        uint256 expectedOut = gemWad - (gemWad * tin) / WAD;

        vm.prank(alice);
        uint256 amountOut = sellSwapper.swap(address(usdc), address(dai), amountIn, expectedOut, bob);

        assertEq(amountOut, expectedOut);
        assertLt(amountOut, gemWad);
        assertEq(dai.balanceOf(bob), expectedOut);
    }

    function test_sellGem_revertsOnInsufficientOutput() public {
        uint256 tin = 1e16; // 1%
        psm.setFees(tin, 0);

        uint256 amountIn = 1000e6;
        uint256 gemWad = amountIn * USDC_CONVERSION_FACTOR;
        uint256 actualOut = gemWad - (gemWad * tin) / WAD;
        uint256 minAmountOut = actualOut + 1;

        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(PSMSwapper.InsufficientOutput.selector, minAmountOut, actualOut)
        );
        sellSwapper.swap(address(usdc), address(dai), amountIn, minAmountOut, bob);
    }

    function test_sellGem_flushesLeftoverToCaller_whenProtocolUnderPulls() public {
        PartialPullPSM partialPsm =
            new PartialPullPSM(IERC20(address(usdc)), IERC20(address(dai)), USDC_CONVERSION_FACTOR);
        dai.mint(address(partialPsm), 1_000_000e18);

        PSMSwapper partialSwapper =
            new PSMSwapper(address(partialPsm), PSMSwapper.Route.SELL_GEM, address(usdc), address(dai), 0);

        uint256 amountIn = 1000e6;
        vm.prank(alice);
        usdc.approve(address(partialSwapper), amountIn);

        uint256 aliceUsdcBefore = usdc.balanceOf(alice);

        vm.prank(alice);
        uint256 amountOut = partialSwapper.swap(address(usdc), address(dai), amountIn, 0, bob);

        uint256 expectedPulled = amountIn / 2;
        assertEq(amountOut, expectedPulled * USDC_CONVERSION_FACTOR);
        // Only half of amountIn was actually consumed; the other half is
        // flushed back to alice (the caller), not to bob (the receiver).
        assertEq(usdc.balanceOf(alice), aliceUsdcBefore - expectedPulled);
        assertEq(usdc.balanceOf(address(partialSwapper)), 0);
        assertEq(dai.balanceOf(address(partialSwapper)), 0);
    }

    function testFuzz_sellGem(uint256 amountIn) public {
        amountIn = bound(amountIn, 1, 500_000e6);
        usdc.mint(alice, amountIn);
        vm.prank(alice);
        usdc.approve(address(sellSwapper), amountIn);

        uint256 expectedOut = amountIn * USDC_CONVERSION_FACTOR;

        vm.prank(alice);
        uint256 amountOut = sellSwapper.swap(address(usdc), address(dai), amountIn, 0, bob);

        assertEq(amountOut, expectedOut);
        assertEq(usdc.balanceOf(address(sellSwapper)), 0);
    }

    // ============================================
    // BUY_GEM
    // ============================================

    function test_buyGem_zeroFee_exactConversion() public {
        uint256 amountIn = 1000e18; // exactly divisible by conversionFactor
        uint256 expectedGem = amountIn / USDC_CONVERSION_FACTOR;

        uint256 aliceDaiBefore = dai.balanceOf(alice);

        vm.prank(alice);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, expectedGem, bob);

        assertEq(amountOut, expectedGem);
        assertEq(usdc.balanceOf(bob), expectedGem);
        // Fully divisible input -> the entire amountIn is pulled, none left with alice.
        assertEq(dai.balanceOf(alice), aliceDaiBefore - amountIn);
        assertEq(dai.balanceOf(address(buySwapper)), 0);
        assertEq(usdc.balanceOf(address(buySwapper)), 0);
    }

    function test_buyGem_roundingRemainderStaysWithCaller() public {
        uint256 amountIn = 1000e18 + 500; // not evenly divisible by 1e12
        uint256 expectedGem = amountIn / USDC_CONVERSION_FACTOR;
        uint256 actualPulled = expectedGem * USDC_CONVERSION_FACTOR;
        assertLt(actualPulled, amountIn);

        uint256 aliceDaiBefore = dai.balanceOf(alice);

        vm.prank(alice);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, expectedGem, bob);

        assertEq(amountOut, expectedGem);
        // Only actualPulled was taken from alice; the floor-division remainder
        // was never pulled via transferFrom (it stays in alice's wallet).
        assertEq(dai.balanceOf(alice), aliceDaiBefore - actualPulled);
        assertEq(dai.balanceOf(address(buySwapper)), 0);
    }

    function test_buyGem_withFee() public {
        uint256 tout = 5e16; // 5%
        psm.setFees(0, tout);

        uint256 amountIn = 1050e18;
        uint256 expectedGem = (amountIn * WAD) / (USDC_CONVERSION_FACTOR * (WAD + tout));
        uint256 actualPulled = (expectedGem * USDC_CONVERSION_FACTOR * (WAD + tout)) / WAD;

        uint256 aliceDaiBefore = dai.balanceOf(alice);

        vm.prank(alice);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, expectedGem, bob);

        assertEq(amountOut, expectedGem);
        assertEq(usdc.balanceOf(bob), expectedGem);
        assertEq(dai.balanceOf(alice), aliceDaiBefore - actualPulled);
    }

    function test_buyGem_revertsWhenGemAmountRoundsToZero() public {
        uint256 amountIn = USDC_CONVERSION_FACTOR - 1; // < 1e12 -> gemAmt floors to 0

        vm.prank(alice);
        vm.expectRevert(abi.encodeWithSelector(PSMSwapper.InsufficientOutput.selector, 1, 0));
        buySwapper.swap(address(dai), address(usdc), amountIn, 0, bob);
    }

    function test_buyGem_revertsOnInsufficientOutput() public {
        uint256 amountIn = 1000e18;
        uint256 expectedGem = amountIn / USDC_CONVERSION_FACTOR;

        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(
                PSMSwapper.InsufficientOutput.selector, expectedGem + 1, expectedGem
            )
        );
        buySwapper.swap(address(dai), address(usdc), amountIn, expectedGem + 1, bob);
    }

    function testFuzz_buyGem(uint256 amountIn) public {
        amountIn = bound(amountIn, USDC_CONVERSION_FACTOR, 500_000e18);
        dai.mint(alice, amountIn);
        vm.prank(alice);
        dai.approve(address(buySwapper), amountIn);

        uint256 expectedGem = amountIn / USDC_CONVERSION_FACTOR;

        vm.prank(alice);
        uint256 amountOut = buySwapper.swap(address(dai), address(usdc), amountIn, expectedGem, bob);

        assertEq(amountOut, expectedGem);
        assertEq(dai.balanceOf(address(buySwapper)), 0);
        assertEq(usdc.balanceOf(address(buySwapper)), 0);
    }

    // ============================================
    // DAI_TO_USDS
    // ============================================

    function test_daiToUsds_oneToOne() public {
        uint256 amountIn = 1000e18;
        uint256 aliceDaiBefore = dai.balanceOf(alice);

        vm.prank(alice);
        uint256 amountOut = daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, 0, bob);

        assertEq(amountOut, amountIn);
        assertEq(usds.balanceOf(bob), amountIn);
        assertEq(dai.balanceOf(alice), aliceDaiBefore - amountIn);
        assertEq(dai.balanceOf(address(daiToUsdsSwapper)), 0);
    }

    function test_daiToUsds_minAmountOutIsOverriddenByExactAmountIn() public {
        uint256 amountIn = 1000e18;

        // Passing minAmountOut = 0 must not weaken the check: the contract
        // internally overrides it to require an exact 1:1 amountIn output.
        vm.prank(alice);
        uint256 amountOut = daiToUsdsSwapper.swap(address(dai), address(usds), amountIn, 0, bob);
        assertEq(amountOut, amountIn);
    }

    function test_daiToUsds_revertsOnNonOneToOne() public {
        exchange.setBrokenRate(true);

        PSMSwapper brokenSwapper = new PSMSwapper(
            address(exchange), PSMSwapper.Route.DAI_TO_USDS, address(dai), address(usds), 0
        );

        uint256 amountIn = 1000e18;
        vm.prank(alice);
        dai.approve(address(brokenSwapper), amountIn);

        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(PSMSwapper.NonOneToOneConversion.selector, amountIn, amountIn - 1)
        );
        brokenSwapper.swap(address(dai), address(usds), amountIn, 0, bob);
    }

    // ============================================
    // USDS_TO_DAI
    // ============================================

    function test_usdsToDai_oneToOne() public {
        uint256 amountIn = 1000e18;
        uint256 aliceUsdsBefore = usds.balanceOf(alice);

        vm.prank(alice);
        uint256 amountOut = usdsToDaiSwapper.swap(address(usds), address(dai), amountIn, 0, bob);

        assertEq(amountOut, amountIn);
        assertEq(dai.balanceOf(bob), amountIn);
        assertEq(usds.balanceOf(alice), aliceUsdsBefore - amountIn);
        assertEq(usds.balanceOf(address(usdsToDaiSwapper)), 0);
    }

    function test_usdsToDai_revertsOnNonOneToOne() public {
        exchange.setBrokenRate(true);

        PSMSwapper brokenSwapper = new PSMSwapper(
            address(exchange), PSMSwapper.Route.USDS_TO_DAI, address(usds), address(dai), 0
        );

        uint256 amountIn = 1000e18;
        vm.prank(alice);
        usds.approve(address(brokenSwapper), amountIn);

        vm.prank(alice);
        vm.expectRevert(
            abi.encodeWithSelector(PSMSwapper.NonOneToOneConversion.selector, amountIn, amountIn - 1)
        );
        brokenSwapper.swap(address(usds), address(dai), amountIn, 0, bob);
    }

    // ============================================
    // GENERAL / RECEIVER
    // ============================================

    function test_swap_receiverCanDifferFromCaller() public {
        uint256 amountIn = 1000e6;

        assertEq(dai.balanceOf(bob), 0);

        vm.prank(alice);
        sellSwapper.swap(address(usdc), address(dai), amountIn, 0, bob);

        assertGt(dai.balanceOf(bob), 0);
        assertEq(dai.balanceOf(alice), 0);
    }
}

