// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import { Test } from "forge-std/Test.sol";
import { LinearAllowanceSingletonForGnosisSafe } from "src/zodiac-core/modules/LinearAllowanceSingletonForGnosisSafe.sol";
import { NATIVE_TOKEN } from "src/constants.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/// @notice Minimal mintable ERC20 used to fund mock Safes in tests.
contract MockERC20 is ERC20 {
    constructor() ERC20("Mock Token", "MOCK") {}

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @notice ERC20 whose `transfer` reports success without ever moving balances.
/// @dev Used to exercise the singleton's post-transfer balance verification
///      (the "primary security control" mentioned in the contract's NatSpec).
contract SilentFailERC20 is IERC20 {
    mapping(address => uint256) private _balances;
    uint256 private _totalSupply;

    function mint(address to, uint256 amount) external {
        _balances[to] += amount;
        _totalSupply += amount;
    }

    function totalSupply() external view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function transfer(address, uint256) external pure returns (bool) {
        // Silently "succeeds" without moving funds.
        return true;
    }

    function allowance(address, address) external pure returns (uint256) {
        return 0;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

/// @notice Minimal stand-in for a Gnosis Safe exposing `execTransactionFromModule`.
/// @dev Executes a raw call and reports success based purely on whether the
///      low-level call reverted, mirroring real Safe module-execution semantics.
contract MockSafe {
    bool public forceExecFail;

    receive() external payable {}

    function setForceExecFail(bool fail_) external {
        forceExecFail = fail_;
    }

    function execTransactionFromModule(
        address to,
        uint256 value,
        bytes memory data,
        uint8 /* operation */
    ) external returns (bool success) {
        if (forceExecFail) {
            return false;
        }
        (success, ) = to.call{ value: value }(data);
    }
}

/// @notice Recipient that attempts to reenter `executeAllowanceTransfer` from its
///         native-token `receive()` hook, to prove the nonReentrant guard holds.
contract MaliciousReentrantReceiver {
    LinearAllowanceSingletonForGnosisSafe public immutable singleton;
    address public safeTarget;
    address public tokenTarget;
    bool public attemptedReentrancy;

    constructor(LinearAllowanceSingletonForGnosisSafe _singleton) {
        singleton = _singleton;
    }

    function setTarget(address _safe, address _token) external {
        safeTarget = _safe;
        tokenTarget = _token;
    }

    receive() external payable {
        if (!attemptedReentrancy) {
            attemptedReentrancy = true;
            singleton.executeAllowanceTransfer(safeTarget, tokenTarget, payable(address(this)));
        }
    }
}

contract LinearAllowanceSingletonForGnosisSafeTest is Test {
    LinearAllowanceSingletonForGnosisSafe internal singleton;
    MockSafe internal safe;
    MockSafe internal safe2;
    MockERC20 internal token;

    address internal delegate = makeAddr("delegate");
    address internal delegate2 = makeAddr("delegate2");
    address internal recipient = makeAddr("recipient");
    address internal stranger = makeAddr("stranger");

    function setUp() public {
        singleton = new LinearAllowanceSingletonForGnosisSafe();
        safe = new MockSafe();
        safe2 = new MockSafe();
        token = new MockERC20();

        vm.deal(address(safe), 1000 ether);
        vm.deal(address(safe2), 1000 ether);
        token.mint(address(safe), 1_000_000 ether);
        token.mint(address(safe2), 1_000_000 ether);
    }

    // ---------------------------------------------------------------
    // setAllowance / setAllowances
    // ---------------------------------------------------------------

    function test_SetAllowance_EmitsEventAndDoesNotAccrueImmediately() public {
        vm.prank(address(safe));
        vm.expectEmit(true, true, true, true, address(singleton));
        emit LinearAllowanceSingletonForGnosisSafe.AllowanceSet(address(safe), delegate, address(token), 100 ether);
        singleton.setAllowance(delegate, address(token), 100 ether);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);
    }

    function test_SetAllowance_RevertsOnZeroDelegate() public {
        vm.prank(address(safe));
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.AddressZeroForArgument.selector, "delegate")
        );
        singleton.setAllowance(address(0), address(token), 100 ether);
    }

    function test_SetAllowances_Batch() public {
        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](2);
        uint192[] memory rates = new uint192[](2);

        delegates[0] = delegate;
        delegates[1] = delegate2;
        tokens[0] = address(token);
        tokens[1] = NATIVE_TOKEN;
        rates[0] = 100 ether;
        rates[1] = 1 ether;

        vm.prank(address(safe));
        singleton.setAllowances(delegates, tokens, rates);

        vm.warp(block.timestamp + 1 days);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 100 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate2, NATIVE_TOKEN), 1 ether);
    }

    function test_SetAllowances_RevertsOnLengthMismatch() public {
        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](1);
        uint192[] memory rates = new uint192[](2);

        vm.prank(address(safe));
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.ArrayLengthsMismatch.selector, 2, 1, 2)
        );
        singleton.setAllowances(delegates, tokens, rates);
    }

    function test_SetAllowance_PreservesAccruedUnspentOnRateChange() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.warp(block.timestamp + 12 hours);

        uint256 accruedBeforeChange = singleton.getTotalUnspent(address(safe), delegate, address(token));
        assertEq(accruedBeforeChange, 50 ether);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 200 ether);

        // Changing the rate must not lose already-accrued allowance.
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 50 ether);

        vm.warp(block.timestamp + 1 days);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 50 ether + 200 ether);
    }

    // ---------------------------------------------------------------
    // Accrual math
    // ---------------------------------------------------------------

    function test_Accrual_LinearOverTime() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.warp(block.timestamp + 6 hours);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 25 ether);

        vm.warp(block.timestamp + 18 hours);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 100 ether);
    }

    function testFuzz_Accrual_MatchesFormula(uint64 dripRate, uint32 elapsed) public {
        vm.assume(dripRate > 0);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), dripRate);

        vm.warp(block.timestamp + elapsed);

        uint256 expected = (uint256(elapsed) * dripRate) / 1 days;
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), expected);
    }

    // ---------------------------------------------------------------
    // revokeAllowance / revokeAllowances
    // ---------------------------------------------------------------

    function test_RevokeAllowance_ZeroesUnspentAndEmits() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.warp(block.timestamp + 1 days);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 100 ether);

        vm.prank(address(safe));
        vm.expectEmit(true, true, true, true, address(singleton));
        emit LinearAllowanceSingletonForGnosisSafe.AllowanceRevoked(address(safe), delegate, address(token), 100 ether);
        singleton.revokeAllowance(delegate, address(token));

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);

        // No further accrual after revoke, even after time passes.
        vm.warp(block.timestamp + 1 days);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);
    }

    function test_RevokeAllowance_RevertsOnZeroDelegate() public {
        vm.prank(address(safe));
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.AddressZeroForArgument.selector, "delegate")
        );
        singleton.revokeAllowance(address(0), address(token));
    }

    function test_RevokeAllowances_Batch() public {
        vm.startPrank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        singleton.setAllowance(delegate2, NATIVE_TOKEN, 1 ether);
        vm.stopPrank();

        vm.warp(block.timestamp + 1 days);

        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](2);
        delegates[0] = delegate;
        delegates[1] = delegate2;
        tokens[0] = address(token);
        tokens[1] = NATIVE_TOKEN;

        vm.prank(address(safe));
        singleton.revokeAllowances(delegates, tokens);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);
        assertEq(singleton.getTotalUnspent(address(safe), delegate2, NATIVE_TOKEN), 0);
    }

    function test_RevokeAllowances_RevertsOnLengthMismatch() public {
        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](1);

        vm.prank(address(safe));
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.ArrayLengthsMismatch.selector, 2, 1, 0)
        );
        singleton.revokeAllowances(delegates, tokens);
    }

    function test_RevokedAllowance_CannotBeExecuted() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        vm.warp(block.timestamp + 1 days);

        vm.prank(address(safe));
        singleton.revokeAllowance(delegate, address(token));

        vm.prank(delegate);
        vm.expectRevert(
            abi.encodeWithSelector(
                LinearAllowanceSingletonForGnosisSafe.NoAllowanceToTransfer.selector,
                address(safe),
                delegate,
                address(token)
            )
        );
        singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
    }

    // ---------------------------------------------------------------
    // executeAllowanceTransfer - ERC20
    // ---------------------------------------------------------------

    function test_ExecuteAllowanceTransfer_ERC20_Success() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.warp(block.timestamp + 1 days);

        vm.prank(delegate);
        vm.expectEmit(true, true, true, true, address(singleton));
        emit LinearAllowanceSingletonForGnosisSafe.AllowanceTransferred(
            address(safe),
            delegate,
            address(token),
            recipient,
            100 ether
        );
        uint256 transferred = singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));

        assertEq(transferred, 100 ether);
        assertEq(token.balanceOf(recipient), 100 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);
    }

    function test_ExecuteAllowanceTransfer_CarriesOverPartialSpend() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.warp(block.timestamp + 12 hours); // 50 accrued

        // Drain the safe's balance down to 30 to force a capped (partial) transfer.
        vm.prank(address(safe));
        token.transfer(stranger, token.balanceOf(address(safe)) - 30 ether);

        vm.prank(delegate);
        uint256 firstTransfer = singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
        assertEq(firstTransfer, 30 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 20 ether);

        // Top the safe back up and let more accrue.
        token.mint(address(safe), 1000 ether);
        vm.warp(block.timestamp + 1 days); // +100 accrued -> 120 total unspent

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 120 ether);

        vm.prank(delegate);
        uint256 secondTransfer = singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
        assertEq(secondTransfer, 120 ether);
        assertEq(token.balanceOf(recipient), 150 ether);
    }

    function test_ExecuteAllowanceTransfer_CappedBySafeBalance() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        // Drain safe's token balance down to 10.
        vm.prank(address(safe));
        token.transfer(stranger, token.balanceOf(address(safe)) - 10 ether);

        vm.warp(block.timestamp + 1 days); // 100 accrued, but only 10 available in safe

        vm.prank(delegate);
        uint256 transferred = singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));

        assertEq(transferred, 10 ether);
        assertEq(token.balanceOf(recipient), 10 ether);
        // Remaining 90 stays unspent for whenever the safe is topped back up.
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 90 ether);
    }

    function test_ExecuteAllowanceTransfer_RevertsWhenNothingAccrued() public {
        vm.prank(delegate);
        vm.expectRevert(
            abi.encodeWithSelector(
                LinearAllowanceSingletonForGnosisSafe.NoAllowanceToTransfer.selector,
                address(safe),
                delegate,
                address(token)
            )
        );
        singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsWhenSafeBalanceIsZero() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.prank(address(safe));
        token.transfer(stranger, token.balanceOf(address(safe)));

        vm.warp(block.timestamp + 1 days);

        vm.prank(delegate);
        vm.expectRevert(
            abi.encodeWithSelector(
                LinearAllowanceSingletonForGnosisSafe.ZeroTransfer.selector,
                address(safe),
                delegate,
                address(token)
            )
        );
        singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsOnZeroSafeAddress() public {
        vm.prank(delegate);
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.AddressZeroForArgument.selector, "safe")
        );
        singleton.executeAllowanceTransfer(address(0), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsOnZeroToAddress() public {
        vm.prank(delegate);
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.AddressZeroForArgument.selector, "to")
        );
        singleton.executeAllowanceTransfer(address(safe), address(token), payable(address(0)));
    }

    function test_ExecuteAllowanceTransfer_RevertsWhenUnauthorizedDelegateHasNoAllowance() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        vm.warp(block.timestamp + 1 days);

        vm.prank(stranger);
        vm.expectRevert(
            abi.encodeWithSelector(
                LinearAllowanceSingletonForGnosisSafe.NoAllowanceToTransfer.selector,
                address(safe),
                stranger,
                address(token)
            )
        );
        singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsWhenSafeModuleCallFails() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        vm.warp(block.timestamp + 1 days);

        safe.setForceExecFail(true);

        vm.prank(delegate);
        vm.expectRevert(LinearAllowanceSingletonForGnosisSafe.SafeTransactionFailed.selector);
        singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsWhenTokenDoesNotActuallyMoveFunds() public {
        SilentFailERC20 badToken = new SilentFailERC20();
        badToken.mint(address(safe), 1000 ether);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(badToken), 100 ether);
        vm.warp(block.timestamp + 1 days);

        vm.prank(delegate);
        vm.expectRevert(
            abi.encodeWithSelector(
                LinearAllowanceSingletonForGnosisSafe.TransferFailed.selector,
                address(safe),
                delegate,
                address(badToken)
            )
        );
        singleton.executeAllowanceTransfer(address(safe), address(badToken), payable(recipient));
    }

    // ---------------------------------------------------------------
    // executeAllowanceTransfer - native token (ETH)
    // ---------------------------------------------------------------

    function test_ExecuteAllowanceTransfer_NativeToken_Success() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 10 ether);

        vm.warp(block.timestamp + 1 days);

        vm.prank(delegate);
        uint256 transferred = singleton.executeAllowanceTransfer(address(safe), NATIVE_TOKEN, payable(recipient));

        assertEq(transferred, 10 ether);
        assertEq(recipient.balance, 10 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, NATIVE_TOKEN), 0);
    }

    function test_ExecuteAllowanceTransfer_NativeToken_CappedBySafeBalance() public {
        vm.deal(address(safe), 5 ether);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 10 ether);

        vm.warp(block.timestamp + 1 days);

        vm.prank(delegate);
        uint256 transferred = singleton.executeAllowanceTransfer(address(safe), NATIVE_TOKEN, payable(recipient));

        assertEq(transferred, 5 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, NATIVE_TOKEN), 5 ether);
    }

    function test_ExecuteAllowanceTransfer_ReentrancyGuardBlocksReentrantCall() public {
        MaliciousReentrantReceiver attacker = new MaliciousReentrantReceiver(singleton);
        attacker.setTarget(address(safe), NATIVE_TOKEN);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 10 ether);
        vm.warp(block.timestamp + 1 days);

        vm.prank(delegate);
        vm.expectRevert(LinearAllowanceSingletonForGnosisSafe.SafeTransactionFailed.selector);
        singleton.executeAllowanceTransfer(address(safe), NATIVE_TOKEN, payable(address(attacker)));
    }

    // ---------------------------------------------------------------
    // executeAllowanceTransfers (batch)
    // ---------------------------------------------------------------

    function test_ExecuteAllowanceTransfers_Batch() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.prank(address(safe2));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 5 ether);

        vm.warp(block.timestamp + 1 days);

        address[] memory safes = new address[](2);
        address[] memory tokens = new address[](2);
        address[] memory tos = new address[](2);

        safes[0] = address(safe);
        safes[1] = address(safe2);
        tokens[0] = address(token);
        tokens[1] = NATIVE_TOKEN;
        tos[0] = recipient;
        tos[1] = recipient;

        vm.prank(delegate);
        uint256[] memory amounts = singleton.executeAllowanceTransfers(safes, tokens, tos);

        assertEq(amounts.length, 2);
        assertEq(amounts[0], 100 ether);
        assertEq(amounts[1], 5 ether);
        assertEq(token.balanceOf(recipient), 100 ether);
        assertEq(recipient.balance, 5 ether);
    }

    function test_ExecuteAllowanceTransfers_RevertsOnLengthMismatch() public {
        address[] memory safes = new address[](2);
        address[] memory tokens = new address[](1);
        address[] memory tos = new address[](2);

        vm.prank(delegate);
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.ArrayLengthsMismatch.selector, 2, 1, 2)
        );
        singleton.executeAllowanceTransfers(safes, tokens, tos);
    }

    // ---------------------------------------------------------------
    // View helpers
    // ---------------------------------------------------------------

    function test_GetBalance_Native() public view {
        assertEq(singleton.getBalance(address(safe), NATIVE_TOKEN), address(safe).balance);
    }

    function test_GetBalance_ERC20() public view {
        assertEq(singleton.getBalance(address(safe), address(token)), token.balanceOf(address(safe)));
    }

    function test_GetMaxWithdrawableAmount_ZeroWhenNoAllowance() public view {
        assertEq(singleton.getMaxWithdrawableAmount(address(safe), delegate, address(token)), 0);
    }

    function test_GetMaxWithdrawableAmount_ReturnsUnspentWhenBalanceSufficient() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        vm.warp(block.timestamp + 1 days);

        assertEq(singleton.getMaxWithdrawableAmount(address(safe), delegate, address(token)), 100 ether);
    }

    function test_GetMaxWithdrawableAmount_CappedBySafeBalance() public {
        vm.prank(address(safe));
        token.transfer(stranger, token.balanceOf(address(safe)) - 1 ether);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        vm.warp(block.timestamp + 1 days);

        assertEq(singleton.getMaxWithdrawableAmount(address(safe), delegate, address(token)), 1 ether);
    }

    function test_MultipleDelegatesHaveIndependentAllowances() public {
        vm.startPrank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        singleton.setAllowance(delegate2, address(token), 50 ether);
        vm.stopPrank();

        vm.warp(block.timestamp + 1 days);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 100 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate2, address(token)), 50 ether);
    }

    function test_MultipleTokensHaveIndependentAllowances() public {
        vm.startPrank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        singleton.setAllowance(delegate, NATIVE_TOKEN, 5 ether);
        vm.stopPrank();

        vm.warp(block.timestamp + 1 days);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 100 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, NATIVE_TOKEN), 5 ether);
    }

    function test_MultipleSafesHaveIndependentAllowances() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.prank(address(safe2));
        singleton.setAllowance(delegate, address(token), 10 ether);

        vm.warp(block.timestamp + 1 days);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 100 ether);
        assertEq(singleton.getTotalUnspent(address(safe2), delegate, address(token)), 10 ether);
    }
}

