        _balances[to] += amount;
        _totalSupply += amount;
    }

    function totalSupply() external view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function transfer(address, uint256) external pure returns (bool) {
        // Silently "succeeds" without moving funds.
        return true;
    }

    function allowance(address, address) external pure returns (uint256) {
        return 0;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

/// @notice Minimal stand-in for a Gnosis Safe exposing `execTransactionFromModule`.
/// @dev Executes a raw call and reports success based purely on whether the
///      low-level call reverted, mirroring real Safe module-execution semantics.
contract MockSafe {
    bool public forceExecFail;

    receive() external payable {}

    function setForceExecFail(bool fail_) external {
        forceExecFail = fail_;
    }

    function execTransactionFromModule(
        address to,
        uint256 value,
        bytes memory data,
        uint8 /* operation */
    ) external returns (bool success) {
        if (forceExecFail) {
            return false;
        }
        (success, ) = to.call{ value: value }(data);
    }
}

/// @notice Recipient that attempts to reenter `executeAllowanceTransfer` from its
///         native-token `receive()` hook, to prove the nonReentrant guard holds.
contract MaliciousReentrantReceiver {
    LinearAllowanceSingletonForGnosisSafe public immutable singleton;
    address public safeTarget;
    address public tokenTarget;
    bool public attemptedReentrancy;

    constructor(LinearAllowanceSingletonForGnosisSafe _singleton) {
        singleton = _singleton;
    }

    function setTarget(address _safe, address _token) external {
        safeTarget = _safe;
        tokenTarget = _token;
    }

    receive() external payable {
        if (!attemptedReentrancy) {
            attemptedReentrancy = true;
            singleton.executeAllowanceTransfer(safeTarget, tokenTarget, payable(address(this)));
        }
    }
}

contract LinearAllowanceSingletonForGnosisSafeTest is Test {
    LinearAllowanceSingletonForGnosisSafe internal singleton;
    MockSafe internal safe;
    MockSafe internal safe2;
    MockERC20 internal token;

    address internal delegate = makeAddr("delegate");
    address internal delegate2 = makeAddr("delegate2");
    address internal recipient = makeAddr("recipient");
    address internal stranger = makeAddr("stranger");

    function setUp() public {
        singleton = new LinearAllowanceSingletonForGnosisSafe();
        safe = new MockSafe();
        safe2 = new MockSafe();
        token = new MockERC20();

        vm.deal(address(safe), 1000 ether);
        vm.deal(address(safe2), 1000 ether);
        token.mint(address(safe), 1_000_000 ether);
        token.mint(address(safe2), 1_000_000 ether);
    }

    // ---------------------------------------------------------------
    // setAllowance / setAllowances
    // ---------------------------------------------------------------

    function test_SetAllowance_EmitsEventAndDoesNotAccrueImmediately() public {
        vm.prank(address(safe));
        vm.expectEmit(true, true, true, true, address(singleton));
        emit LinearAllowanceSingletonForGnosisSafe.AllowanceSet(address(safe), delegate, address(token), 100 ether);
        singleton.setAllowance(delegate, address(token), 100 ether);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);
    }

    function test_SetAllowance_RevertsOnZeroDelegate() public {
        vm.prank(address(safe));
