// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

import { Test } from "forge-std/Test.sol";
import { LinearAllowanceSingletonForGnosisSafe } from "src/zodiac-core/modules/LinearAllowanceSingletonForGnosisSafe.sol";
import { NATIVE_TOKEN } from "src/constants.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/*//////////////////////////////////////////////////////////////////////////
                                MOCK CONTRACTS
//////////////////////////////////////////////////////////////////////////*/

/// @notice Minimal Gnosis-Safe-like mock that faithfully forwards module calls,
///         mirroring the real Safe's `execTransactionFromModule` for Call operations.
contract MockSafe {
    receive() external payable {}

    function execTransactionFromModule(
        address to,
        uint256 value,
        bytes memory data,
        uint8 operation
    ) external returns (bool success) {
        require(operation == 0, "MockSafe: only Call supported");
        (success, ) = to.call{ value: value }(data);
    }
}

/// @notice Safe stand-in that always reports transaction failure, used to exercise
///         the `SafeTransactionFailed` revert path.
contract AlwaysFailingSafe {
    receive() external payable {}

    function execTransactionFromModule(
        address,
        uint256,
        bytes memory,
        uint8
    ) external pure returns (bool) {
        return false;
    }
}

/// @notice Minimal mintable ERC20 used to fund Safes and verify transfers.
contract MockERC20 is IERC20 {
    string public name = "Mock Token";
    string public symbol = "MOCK";
    uint8 public decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) public override balanceOf;
    mapping(address => mapping(address => uint256)) public override allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }

    function transfer(address to, uint256 amount) external virtual override returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external override returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external override returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }
}

/// @notice ERC20 that silently skims a fee on transfer, used to exercise the
///         `TransferFailed` post-balance-check revert path (fee-on-transfer tokens
///         are explicitly unsupported by the module).
contract FeeOnTransferERC20 is MockERC20 {
    uint256 public constant FEE_BPS = 1000; // 10%

    function transfer(address to, uint256 amount) external override returns (bool) {
        uint256 fee = (amount * FEE_BPS) / 10_000;
        uint256 sent = amount - fee;
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += sent;
        emit Transfer(msg.sender, to, sent);
        return true;
    }
}

/// @notice Malicious delegate/recipient used to attempt a reentrant call into
///         `executeAllowanceTransfer` while receiving its own native-token payout.
contract MaliciousDelegate {
    LinearAllowanceSingletonForGnosisSafe public immutable module;
    address public immutable safeAddr;
    address public immutable token;
    bool public attacked;

    constructor(LinearAllowanceSingletonForGnosisSafe _module, address _safeAddr, address _token) {
        module = _module;
        safeAddr = _safeAddr;
        token = _token;
    }

    function attack() external returns (uint256) {
        return module.executeAllowanceTransfer(safeAddr, token, payable(address(this)));
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            // Reentrant call — must be blocked by the nonReentrant guard.
            module.executeAllowanceTransfer(safeAddr, token, payable(address(this)));
        }
    }
}

/*//////////////////////////////////////////////////////////////////////////
                                    TESTS
//////////////////////////////////////////////////////////////////////////*/

contract LinearAllowanceSingletonForGnosisSafeTest is Test {
    LinearAllowanceSingletonForGnosisSafe internal module;

    MockSafe internal safe;
    MockSafe internal safe2;
    MockERC20 internal token;

    address internal delegate = makeAddr("delegate");
    address internal delegate2 = makeAddr("delegate2");
    address internal recipient = makeAddr("recipient");
    address internal stranger = makeAddr("stranger");

    uint192 internal constant DAY_RATE = 100e18; // 100 tokens / ETH per day

    // Local mirrors of the module's events (types/order taken from the emit sites).
    event AllowanceSet(address indexed safe, address indexed delegate, address indexed token, uint192 dripRatePerDay);
    event AllowanceRevoked(address indexed safe, address indexed delegate, address indexed token, uint256 totalUnspentAtRevocation);
    event AllowanceTransferred(
        address indexed safe,
        address indexed delegate,
        address indexed token,
        address to,
        uint256 transferAmount
    );

    function setUp() public {
        module = new LinearAllowanceSingletonForGnosisSafe();
        safe = new MockSafe();
        safe2 = new MockSafe();
        token = new MockERC20();

        vm.deal(address(safe), 1000 ether);
        vm.deal(address(safe2), 1000 ether);
        token.mint(address(safe), 1_000_000e18);
        token.mint(address(safe2), 1_000_000e18);
    }

    /*//////////////////////////////////////////////////////////////////////
                                setAllowance
    //////////////////////////////////////////////////////////////////////*/

    function test_SetAllowance_EmitsEvent_NoImmediateAccrual() public {
        vm.expectEmit(true, true, true, true, address(module));
        emit AllowanceSet(address(safe), delegate, address(token), DAY_RATE);

        vm.prank(address(safe));
        module.setAllowance(delegate, address(token), DAY_RATE);

        // No time has passed since the rate was set, so nothing has accrued yet.
        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), 0);
    }

    function test_SetAllowance_RevertsForZeroDelegate() public {
        vm.expectRevert(abi.encodeWithSignature("AddressZeroForArgument(string)", "delegate"));
        vm.prank(address(safe));
        module.setAllowance(address(0), address(token), DAY_RATE);
    }

    function test_SetAllowances_Batch() public {
        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](2);
        uint192[] memory rates = new uint192[](2);

        delegates[0] = delegate;
        delegates[1] = delegate2;
        tokens[0] = address(token);
        tokens[1] = NATIVE_TOKEN;
        rates[0] = DAY_RATE;
        rates[1] = 1 ether;

        vm.prank(address(safe));
        module.setAllowances(delegates, tokens, rates);

        vm.warp(block.timestamp + 1 days);

        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), DAY_RATE);
        assertEq(module.getTotalUnspent(address(safe), delegate2, NATIVE_TOKEN), 1 ether);
    }

    function test_SetAllowances_RevertsOnArrayLengthMismatch() public {
        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](1);
        uint192[] memory rates = new uint192[](2);

        vm.expectRevert(abi.encodeWithSignature("ArrayLengthsMismatch(uint256,uint256,uint256)", 2, 1, 2));
        vm.prank(address(safe));
        module.setAllowances(delegates, tokens, rates);
    }

    function test_SetAllowance_RateChange_PreservesPreviouslyAccruedUnspent() public {
        vm.startPrank(address(safe));
        module.setAllowance(delegate, address(token), DAY_RATE); // 100e18/day
        vm.warp(block.timestamp + 12 hours);

        // Banks 50e18 as unspent, then switches drip rate to 50e18/day.
        module.setAllowance(delegate, address(token), 50e18);
        vm.stopPrank();

        vm.warp(block.timestamp + 1 days);

        // 50e18 banked + 50e18 accrued at the new rate over 24h.
        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), 100e18);
    }

    /*//////////////////////////////////////////////////////////////////////
                                Linear accrual
    //////////////////////////////////////////////////////////////////////*/

    function test_Accrual_IsLinearOverTime() public {
        vm.prank(address(safe));
        module.setAllowance(delegate, address(token), DAY_RATE);

        vm.warp(block.timestamp + 12 hours);
        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), 50e18);

        vm.warp(block.timestamp + 12 hours);
        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), 100e18);
    }

    function test_Accrual_CarriesOverAfterPartialSpend() public {
        vm.prank(address(safe));
        module.setAllowance(delegate, address(token), DAY_RATE);

        vm.warp(block.timestamp + 1 days); // 100e18 available

        vm.prank(delegate);
        module.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
        // Spent everything, 0 left unspent.
        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), 0);

        vm.warp(block.timestamp + 1 days);
        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), DAY_RATE);
    }

    function testFuzz_Accrual_MatchesFormula(uint96 dripRate, uint32 timeElapsed) public {
        dripRate = uint96(bound(dripRate, 0, 1e24));
        timeElapsed = uint32(bound(timeElapsed, 0, 3650 days));

        vm.prank(address(safe));
        module.setAllowance(delegate, address(token), uint192(dripRate));

        vm.warp(block.timestamp + timeElapsed);

        uint256 expected = (uint256(timeElapsed) * dripRate) / 1 days;
        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), expected);
    }

    /*//////////////////////////////////////////////////////////////////////
                                revokeAllowance
    //////////////////////////////////////////////////////////////////////*/

    function test_RevokeAllowance_ZeroesUnspentAndStopsAccrual() public {
        vm.prank(address(safe));
        module.setAllowance(delegate, address(token), DAY_RATE);

        vm.warp(block.timestamp + 12 hours); // 50e18 accrued but unbooked

        vm.expectEmit(true, true, true, true, address(module));
        emit AllowanceRevoked(address(safe), delegate, address(token), 50e18);

        vm.prank(address(safe));
        module.revokeAllowance(delegate, address(token));

        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), 0);

        // Drip rate is zeroed too, so no further accrual happens.
        vm.warp(block.timestamp + 1 days);
        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), 0);

        vm.expectRevert(
            abi.encodeWithSignature(
                "NoAllowanceToTransfer(address,address,address)",
                address(safe),
                delegate,
                address(token)
            )
        );
        vm.prank(delegate);
        module.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
    }

    function test_RevokeAllowance_RevertsForZeroDelegate() public {
        vm.expectRevert(abi.encodeWithSignature("AddressZeroForArgument(string)", "delegate"));
        vm.prank(address(safe));
        module.revokeAllowance(address(0), address(token));
    }

    function test_RevokeAllowances_Batch() public {
        vm.startPrank(address(safe));
        module.setAllowance(delegate, address(token), DAY_RATE);
        module.setAllowance(delegate2, NATIVE_TOKEN, 1 ether);
        vm.stopPrank();

        vm.warp(block.timestamp + 1 days);

        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](2);
        delegates[0] = delegate;
        delegates[1] = delegate2;
        tokens[0] = address(token);
        tokens[1] = NATIVE_TOKEN;

        vm.prank(address(safe));
        module.revokeAllowances(delegates, tokens);

        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), 0);
        assertEq(module.getTotalUnspent(address(safe), delegate2, NATIVE_TOKEN), 0);
    }

    function test_RevokeAllowances_RevertsOnArrayLengthMismatch() public {
        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](1);

        vm.expectRevert(abi.encodeWithSignature("ArrayLengthsMismatch(uint256,uint256,uint256)", 2, 1, 0));
        vm.prank(address(safe));
        module.revokeAllowances(delegates, tokens);
    }

    /*//////////////////////////////////////////////////////////////////////
                            executeAllowanceTransfer
    //////////////////////////////////////////////////////////////////////*/

    function test_ExecuteAllowanceTransfer_TransfersErc20() public {
        vm.prank(address(safe));
        module.setAllowance(delegate, address(token), DAY_RATE);
        vm.warp(block.timestamp + 1 days);

        uint256 safeBalBefore = token.balanceOf(address(safe));

        vm.expectEmit(true, true, true, true, address(module));
        emit AllowanceTransferred(address(safe), delegate, address(token), recipient, DAY_RATE);

        vm.prank(delegate);
        uint256 amount = module.executeAllowanceTransfer(address(safe), address(token), payable(recipient));

        assertEq(amount, DAY_RATE);
        assertEq(token.balanceOf(recipient), DAY_RATE);
        assertEq(token.balanceOf(address(safe)), safeBalBefore - DAY_RATE);
        assertEq(module.getTotalUnspent(address(safe), delegate, address(token)), 0);
    }

    function test_ExecuteAllowanceTransfer_TransfersNativeToken() public {
        vm.prank(address(safe));
        module.setAllowance(delegate, NATIVE_TOKEN, 1 ether);
        vm.warp(block.timestamp + 1 days);

        uint256 recipientBalBefore = recipient.balance;

        vm.prank(delegate);
        uint256 amount = module.executeAllowanceTransfer(address(safe), NATIVE_TOKEN, payable(recipient));

        assertEq(amount, 1 ether);
        assertEq(recipient.balance, recipientBalBefore + 1 ether);
    }

    function test_ExecuteAllowanceTransfer_RevertsWhenNoAllowanceSet() public {
        vm.expectRevert(
            abi.encodeWithSignature(
                "NoAllowanceToTransfer(address,address,address)",
                address(safe),
                delegate,
                address(token)
            )
        );
        vm.prank(delegate);
        module.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_StrangerCannotDrainAnotherDelegatesAllowance() public {
        vm.prank(address(safe));
        module.setAllowance(delegate, address(token), DAY_RATE);
        vm.warp(block.timestamp + 1 days);

        vm.expectRevert(
            abi.encodeWithSignature(
                "NoAllowanceToTransfer(address,address,address)",
                address(safe),
                stranger,
                address(token)
            )
        );
        vm.prank(stranger);
        module.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsZeroTransfer_WhenSafeHasNoBalance() public {
        MockSafe emptySafe = new MockSafe(); // funded with nothing

        vm.prank(address(emptySafe));
        module.setAllowance(delegate, address(token), DAY_RATE);
        vm.warp(block.timestamp + 1 days);

        vm.expectRevert(
            abi.encodeWithSignature(
                "ZeroTransfer(address,address,address)",
                address(emptySafe),
                delegate,
                address(token)
            )
        );
        vm.prank(delegate);
        module.executeAllowanceTransfer(address(emptySafe), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_LimitedBySafeBalance() public {
        MockSafe poorSafe = new MockSafe();
        token.mint(address(poorSafe), 10e18); // less than the accrued allowance

        vm.prank(address(poorSafe));
        module.setAllowance(delegate, address(token), DAY_RATE); // accrues 100e18/day
        vm.warp(block.timestamp + 1 days);

        vm.prank(delegate);
        uint256 amount = module.executeAllowanceTransfer(address(poorSafe), address(token), payable(recipient));

        assertEq(amount, 10e18);
        assertEq(token.balanceOf(address(poorSafe)), 0);
        // The remaining 90e18 stays unspent for when the Safe is topped up.
        assertEq(module.getTotalUnspent(address(poorSafe), delegate, address(token)), 90e18);
    }

    function test_ExecuteAllowanceTransfer_RevertsForZeroSafeAddress() public {
        vm.expectRevert(abi.encodeWithSignature("AddressZeroForArgument(string)", "safe"));
        vm.prank(delegate);
        module.executeAllowanceTransfer(address(0), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsForZeroRecipientAddress() public {
        vm.prank(address(safe));
        module.setAllowance(delegate, address(token), DAY_RATE);
        vm.warp(block.timestamp + 1 days);

        vm.expectRevert(abi.encodeWithSignature("AddressZeroForArgument(string)", "to"));
        vm.prank(delegate);
        module.executeAllowanceTransfer(address(safe), address(token), payable(address(0)));
    }

    function test_ExecuteAllowanceTransfer_RevertsSafeTransactionFailed() public {
        AlwaysFailingSafe badSafe = new AlwaysFailingSafe();
        vm.deal(address(badSafe), 10 ether);

        vm.prank(address(badSafe));
        module.setAllowance(delegate, NATIVE_TOKEN, 1 ether);
        vm.warp(block.timestamp + 1 days);

        vm.expectRevert(abi.encodeWithSignature("SafeTransactionFailed()"));
        vm.prank(delegate);
        module.executeAllowanceTransfer(address(badSafe), NATIVE_TOKEN, payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsTransferFailed_FeeOnTransferToken() public {
        FeeOnTransferERC20 feeToken = new FeeOnTransferERC20();
        MockSafe feeSafe = new MockSafe();
        feeToken.mint(address(feeSafe), 1_000e18);

        vm.prank(address(feeSafe));
        module.setAllowance(delegate, address(feeToken), DAY_RATE);
        vm.warp(block.timestamp + 1 days);

        vm.expectRevert(
            abi.encodeWithSignature(
                "TransferFailed(address,address,address)",
                address(feeSafe),
                delegate,
                address(feeToken)
            )
        );
        vm.prank(delegate);
        module.executeAllowanceTransfer(address(feeSafe), address(feeToken), payable(recipient));
    }

