    //////////////////////////////////////////////////////////////////////*/

    function test_GetBalance_NativeAndErc20() public {
        assertEq(module.getBalance(address(safe), NATIVE_TOKEN), address(safe).balance);
        assertEq(module.getBalance(address(safe), address(token)), token.balanceOf(address(safe)));
