        uint256 fee = (amount * FEE_BPS) / 10_000;
        uint256 sent = amount - fee;
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += sent;
        emit Transfer(msg.sender, to, sent);
        return true;
    }
}

/// @notice Malicious delegate/recipient used to attempt a reentrant call into
///         `executeAllowanceTransfer` while receiving its own native-token payout.
contract MaliciousDelegate {
    LinearAllowanceSingletonForGnosisSafe public immutable module;
    address public immutable safeAddr;
    address public immutable token;
    bool public attacked;

    constructor(LinearAllowanceSingletonForGnosisSafe _module, address _safeAddr, address _token) {
        module = _module;
        safeAddr = _safeAddr;
        token = _token;
    }

    function attack() external returns (uint256) {
        return module.executeAllowanceTransfer(safeAddr, token, payable(address(this)));
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            // Reentrant call — must be blocked by the nonReentrant guard.
            module.executeAllowanceTransfer(safeAddr, token, payable(address(this)));
        }
    }
}

