contract MockERC20 {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    uint256 private _totalSupply;

    string public name = "MockToken";
    string public symbol = "MOCK";
    uint8 public decimals = 18;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    function mint(address to, uint256 amount) external {
        _balances[to] += amount;
        _totalSupply += amount;
        emit Transfer(address(0), to, amount);
    }

    function totalSupply() external view returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function allowance(address owner, address spender) external view returns (uint256) {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _allowances[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = _allowances[from][msg.sender];
        require(allowed >= amount, "insufficient allowance");
        _allowances[from][msg.sender] = allowed - amount;
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(_balances[from] >= amount, "insufficient balance");
        _balances[from] -= amount;
        _balances[to] += amount;
        emit Transfer(from, to, amount);
    }
}

/// @notice A "fee on transfer"-style / broken ERC20: `transfer` always reports
///         success but never actually moves balances. Used to exercise the
///         singleton's post-transfer balance verification (`TransferFailed`).
contract NoOpERC20 {
    mapping(address => uint256) private _balances;

    function mint(address to, uint256 amount) external {
        _balances[to] += amount;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }

    function allowance(address, address) external pure returns (uint256) {
        return 0;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function totalSupply() external pure returns (uint256) {
        return 0;
    }
}

/// @notice Attempts to re-enter `executeAllowanceTransfer` from within the ETH
///         receive hook, to prove the singleton's `nonReentrant` guard holds.
contract ReentrantReceiver {
    LinearAllowanceSingletonForGnosisSafe public singleton;
    address public safe;
    address public token;
    bool public attacked;

    constructor(LinearAllowanceSingletonForGnosisSafe _singleton) {
        singleton = _singleton;
    }

    function configure(address _safe, address _token) external {
        safe = _safe;
        token = _token;
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            singleton.executeAllowanceTransfer(safe, token, payable(address(this)));
        }
    }
}

contract LinearAllowanceSingletonForGnosisSafeTest is Test {
    LinearAllowanceSingletonForGnosisSafe internal singleton;
    MockSafe internal safe;
    MockERC20 internal token;

    address internal delegate;
    address internal recipient;

    function setUp() public {
        singleton = new LinearAllowanceSingletonForGnosisSafe();
        safe = new MockSafe();
        token = new MockERC20();

        delegate = makeAddr("delegate");
        recipient = makeAddr("recipient");

        vm.deal(address(safe), 100 ether);
        token.mint(address(safe), 1_000_000 ether);
    }

    /* -------------------------------------------------------------------- */
    /*                             setAllowance(s)                         */
    /* -------------------------------------------------------------------- */

    function test_SetAllowance_EmitsEvent() public {
        vm.expectEmit(true, true, true, true, address(singleton));
        emit LinearAllowanceSingletonForGnosisSafe.AllowanceSet(address(safe), delegate, address(token), 100 ether);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
    }

    function test_SetAllowance_RevertsOnZeroDelegate() public {
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.AddressZeroForArgument.selector, "delegate")
        );
        vm.prank(address(safe));
        singleton.setAllowance(address(0), address(token), 100 ether);
    }

    function test_SetAllowance_PreservesAccruedAmountWhenRateChanges() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.warp(block.timestamp + 12 hours);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 200 ether);

        // Already-accrued 50 ether must survive the rate change.
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 50 ether);

        vm.warp(block.timestamp + 1 days);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 250 ether);
    }

    function test_SetAllowances_RevertsOnArrayLengthMismatch() public {
        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](1);
        uint192[] memory rates = new uint192[](2);

        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.ArrayLengthsMismatch.selector, 2, 1, 2)
        );
        vm.prank(address(safe));
        singleton.setAllowances(delegates, tokens, rates);
    }

    function test_SetAllowances_BatchSetsMultipleIndependently() public {
        address delegate2 = makeAddr("delegate2");
        MockERC20 token2 = new MockERC20();

        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](2);
        uint192[] memory rates = new uint192[](2);

        delegates[0] = delegate;
        tokens[0] = address(token);
        rates[0] = 50 ether;

        delegates[1] = delegate2;
        tokens[1] = address(token2);
        rates[1] = 200 ether;

        vm.prank(address(safe));
        singleton.setAllowances(delegates, tokens, rates);

        vm.warp(block.timestamp + 1 days);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 50 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate2, address(token2)), 200 ether);
    }

    /* -------------------------------------------------------------------- */
    /*                            revokeAllowance(s)                       */
    /* -------------------------------------------------------------------- */

    function test_RevokeAllowance_ResetsAllowanceAndEmits() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.warp(block.timestamp + 1 days);

        uint256 expectedUnspent = singleton.getTotalUnspent(address(safe), delegate, address(token));
        assertEq(expectedUnspent, 100 ether);

        vm.expectEmit(true, true, true, true, address(singleton));
        emit LinearAllowanceSingletonForGnosisSafe.AllowanceRevoked(
            address(safe), delegate, address(token), expectedUnspent
        );

        vm.prank(address(safe));
        singleton.revokeAllowance(delegate, address(token));

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);

        // Drip rate was reset to zero, so no further accrual happens.
        vm.warp(block.timestamp + 1 days);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);
    }

    function test_RevokeAllowance_NoOpWhenNoPriorAllowance() public {
        vm.expectEmit(true, true, true, true, address(singleton));
        emit LinearAllowanceSingletonForGnosisSafe.AllowanceRevoked(address(safe), delegate, address(token), 0);

        vm.prank(address(safe));
        singleton.revokeAllowance(delegate, address(token));
    }

    function test_RevokeAllowance_RevertsOnZeroDelegate() public {
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.AddressZeroForArgument.selector, "delegate")
        );
        vm.prank(address(safe));
        singleton.revokeAllowance(address(0), address(token));
    }

    function test_RevokeAllowances_RevertsOnArrayLengthMismatch() public {
        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](1);

        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.ArrayLengthsMismatch.selector, 2, 1, 0)
        );
        vm.prank(address(safe));
        singleton.revokeAllowances(delegates, tokens);
    }

    function test_RevokeAllowances_BatchRevokesMultiple() public {
        vm.startPrank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        singleton.setAllowance(delegate, NATIVE_TOKEN, 10 ether);
        vm.stopPrank();

        vm.warp(block.timestamp + 1 days);

        address[] memory delegates = new address[](2);
        address[] memory tokens = new address[](2);
        delegates[0] = delegate;
        tokens[0] = address(token);
        delegates[1] = delegate;
        tokens[1] = NATIVE_TOKEN;

        vm.prank(address(safe));
        singleton.revokeAllowances(delegates, tokens);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, NATIVE_TOKEN), 0);
    }

    /* -------------------------------------------------------------------- */
    /*                              view helpers                            */
    /* -------------------------------------------------------------------- */

    function test_GetTotalUnspent_AccruesLinearly() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);

        vm.warp(block.timestamp + 12 hours);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 50 ether);

        vm.warp(block.timestamp + 12 hours);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 100 ether);
    }

    function test_GetTotalUnspent_NoAccrualWithoutAllowanceEverSet() public {
        vm.warp(block.timestamp + 30 days);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);
    }

    function test_GetBalance_NativeAndERC20() public view {
        assertEq(singleton.getBalance(address(safe), NATIVE_TOKEN), address(safe).balance);
        assertEq(singleton.getBalance(address(safe), address(token)), token.balanceOf(address(safe)));
    }

    function test_GetMaxWithdrawableAmount_ZeroWhenNoAllowance() public view {
        assertEq(singleton.getMaxWithdrawableAmount(address(safe), delegate, address(token)), 0);
    }

    function test_GetMaxWithdrawableAmount_CapsAtSafeBalance() public {
        vm.deal(address(safe), 5 ether);
        vm.prank(address(safe));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 100 ether);
        vm.warp(block.timestamp + 1 days);

        assertEq(singleton.getTotalUnspent(address(safe), delegate, NATIVE_TOKEN), 100 ether);
        assertEq(singleton.getMaxWithdrawableAmount(address(safe), delegate, NATIVE_TOKEN), 5 ether);
    }

    /* -------------------------------------------------------------------- */
    /*                        executeAllowanceTransfer                      */
    /* -------------------------------------------------------------------- */

    function test_ExecuteAllowanceTransfer_NativeToken() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 100 ether);

        vm.warp(block.timestamp + 1 days);

        uint256 recipientBefore = recipient.balance;

        vm.expectEmit(true, true, true, true, address(singleton));
        emit LinearAllowanceSingletonForGnosisSafe.AllowanceTransferred(
            address(safe), delegate, NATIVE_TOKEN, recipient, 100 ether
        );

        vm.prank(delegate);
        uint256 amount = singleton.executeAllowanceTransfer(address(safe), NATIVE_TOKEN, payable(recipient));

        assertEq(amount, 100 ether);
        assertEq(recipient.balance - recipientBefore, 100 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, NATIVE_TOKEN), 0);
    }

    function test_ExecuteAllowanceTransfer_ERC20() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);

        vm.warp(block.timestamp + 1 days);

        vm.prank(delegate);
        uint256 amount = singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));

        assertEq(amount, 100 ether);
        assertEq(token.balanceOf(recipient), 100 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), 0);
    }

    function test_ExecuteAllowanceTransfer_CappedBySafeBalance() public {
        vm.deal(address(safe), 10 ether);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 100 ether);

        vm.warp(block.timestamp + 1 days);

        vm.prank(delegate);
        uint256 amount = singleton.executeAllowanceTransfer(address(safe), NATIVE_TOKEN, payable(recipient));

        assertEq(amount, 10 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, NATIVE_TOKEN), 90 ether);
    }

    /// @dev Mirrors the exact example from the contract's NatSpec:
    ///      100 DAI/day, 12h -> 50 available, spend 30 -> 20 unspent,
    ///      +24h -> 20 + 100 = 120 available.
    function test_ExecuteAllowanceTransfer_UnspentCarriesOver_MatchesDocExample() public {
        MockERC20 dai = new MockERC20();
        dai.mint(address(safe), 30 ether);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(dai), 100 ether);

        vm.warp(block.timestamp + 12 hours);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(dai)), 50 ether);

        // Safe balance (30) caps the withdrawal below the 50 accrued.
        vm.prank(delegate);
        uint256 firstTransfer = singleton.executeAllowanceTransfer(address(safe), address(dai), payable(recipient));
        assertEq(firstTransfer, 30 ether);
        assertEq(dai.balanceOf(recipient), 30 ether);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(dai)), 20 ether);

        // Top up the safe and accrue 24 more hours -> 20 + 100 = 120.
        dai.mint(address(safe), 200 ether);
        vm.warp(block.timestamp + 24 hours);
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(dai)), 120 ether);

        vm.prank(delegate);
        uint256 secondTransfer = singleton.executeAllowanceTransfer(address(safe), address(dai), payable(recipient));
        assertEq(secondTransfer, 120 ether);
        assertEq(dai.balanceOf(recipient), 150 ether);
    }

    function test_ExecuteAllowanceTransfer_RevertsWithNoAllowance() public {
        vm.expectRevert(
            abi.encodeWithSelector(
                LinearAllowanceSingletonForGnosisSafe.NoAllowanceToTransfer.selector,
                address(safe),
                delegate,
                address(token)
            )
        );
        vm.prank(delegate);
        singleton.executeAllowanceTransfer(address(safe), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsWhenSafeHasNoBalance() public {
        MockERC20 emptyToken = new MockERC20();

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(emptyToken), 100 ether);

        vm.warp(block.timestamp + 1 days);

        vm.expectRevert(
            abi.encodeWithSelector(
                LinearAllowanceSingletonForGnosisSafe.ZeroTransfer.selector,
                address(safe),
                delegate,
                address(emptyToken)
            )
        );
        vm.prank(delegate);
        singleton.executeAllowanceTransfer(address(safe), address(emptyToken), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsOnZeroSafe() public {
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.AddressZeroForArgument.selector, "safe")
        );
        vm.prank(delegate);
        singleton.executeAllowanceTransfer(address(0), address(token), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsOnZeroTo() public {
        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.AddressZeroForArgument.selector, "to")
        );
        vm.prank(delegate);
        singleton.executeAllowanceTransfer(address(safe), address(token), payable(address(0)));
    }

    function test_ExecuteAllowanceTransfer_RevertsWhenSafeExecutionFails() public {
        vm.prank(address(safe));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 100 ether);

        vm.warp(block.timestamp + 1 days);

        safe.setForceFail(true);

        vm.expectRevert(LinearAllowanceSingletonForGnosisSafe.SafeTransactionFailed.selector);
        vm.prank(delegate);
        singleton.executeAllowanceTransfer(address(safe), NATIVE_TOKEN, payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_RevertsWhenBalanceDoesNotIncrease() public {
        NoOpERC20 badToken = new NoOpERC20();
        badToken.mint(address(safe), 1000 ether);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(badToken), 100 ether);

        vm.warp(block.timestamp + 1 days);

        vm.expectRevert(
            abi.encodeWithSelector(
                LinearAllowanceSingletonForGnosisSafe.TransferFailed.selector,
                address(safe),
                delegate,
                address(badToken)
            )
        );
        vm.prank(delegate);
        singleton.executeAllowanceTransfer(address(safe), address(badToken), payable(recipient));
    }

    function test_ExecuteAllowanceTransfer_BlocksReentrancy() public {
        ReentrantReceiver attacker = new ReentrantReceiver(singleton);
        attacker.configure(address(safe), NATIVE_TOKEN);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 100 ether);

        vm.warp(block.timestamp + 1 days);

        // The reentrant call reverts inside the low-level `call`, which makes
        // the Safe-side call report failure, which the singleton surfaces as
        // SafeTransactionFailed - proving the nonReentrant guard held.
        vm.expectRevert(LinearAllowanceSingletonForGnosisSafe.SafeTransactionFailed.selector);
        vm.prank(delegate);
        singleton.executeAllowanceTransfer(address(safe), NATIVE_TOKEN, payable(address(attacker)));
    }

    /* -------------------------------------------------------------------- */
    /*                       executeAllowanceTransfers                      */
    /* -------------------------------------------------------------------- */

    function test_ExecuteAllowanceTransfers_Batch() public {
        MockSafe safe2 = new MockSafe();
        vm.deal(address(safe2), 50 ether);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), 100 ether);
        vm.prank(address(safe2));
        singleton.setAllowance(delegate, NATIVE_TOKEN, 10 ether);

        vm.warp(block.timestamp + 1 days);

        address[] memory safes = new address[](2);
        address[] memory tokens = new address[](2);
        address[] memory tos = new address[](2);

        safes[0] = address(safe);
        tokens[0] = address(token);
        tos[0] = recipient;

        safes[1] = address(safe2);
        tokens[1] = NATIVE_TOKEN;
        tos[1] = recipient;

        vm.prank(delegate);
        uint256[] memory amounts = singleton.executeAllowanceTransfers(safes, tokens, tos);

        assertEq(amounts[0], 100 ether);
        assertEq(amounts[1], 10 ether);
        assertEq(token.balanceOf(recipient), 100 ether);
        assertEq(recipient.balance, 10 ether);
    }

    function test_ExecuteAllowanceTransfers_RevertsOnArrayLengthMismatch() public {
        address[] memory safes = new address[](2);
        address[] memory tokens = new address[](1);
        address[] memory tos = new address[](2);

        vm.expectRevert(
            abi.encodeWithSelector(LinearAllowanceSingletonForGnosisSafe.ArrayLengthsMismatch.selector, 2, 1, 2)
        );
        vm.prank(delegate);
        singleton.executeAllowanceTransfers(safes, tokens, tos);
    }

    /* -------------------------------------------------------------------- */
    /*                                 fuzz                                  */
    /* -------------------------------------------------------------------- */

    function testFuzz_LinearAccrual(uint96 dripRate, uint32 timeElapsed) public {
        vm.assume(dripRate > 0);

        vm.prank(address(safe));
        singleton.setAllowance(delegate, address(token), dripRate);

        vm.warp(block.timestamp + timeElapsed);

        uint256 expected = (uint256(timeElapsed) * uint256(dripRate)) / 1 days;
        assertEq(singleton.getTotalUnspent(address(safe), delegate, address(token)), expected);
    }
}

