        (, , uint256 qf2, uint256 lf2) = qf.getTally(2);

        uint256 sumPerProjectFunding = qf1 + lf1 + qf2 + lf2;

        // Rounding dust: sum(project funding) <= totalFunding()
        assertLe(sumPerProjectFunding, qf.totalFunding());
    }
