        qf.processVote(1, 1, 1);
        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, 1);
        assertEq(p.sumSquareRoots, 1);
    }

    function testFuzz_ProcessVote_ExactSqrtAlwaysAccepted(uint256 contribution) public {
        contribution = bound(contribution, 1, 1e40);
        uint256 sqrtVal = contribution.sqrt();
        qf.processVote(1, contribution, sqrtVal);
        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, contribution);
        assertEq(p.sumSquareRoots, sqrtVal);
    }

    // ---------------------------------------------------------------------
    // Aggregation math (single project, incremental updates)
    // ---------------------------------------------------------------------

    function test_ProcessVote_AccumulatesSingleProject() public {
        qf.processVote(1, 100, 10); // sumSqrt = 10
        qf.processVote(1, 400, 20); // sumSqrt = 30

        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, 500);
        assertEq(p.sumSquareRoots, 30);

        // totalQuadraticSum should equal (30)^2 = 900
        assertEq(qf.totalQuadraticSum(), 900);
        // totalLinearSum should equal 500
        assertEq(qf.totalLinearSum(), 500);
    }

    function test_ProcessVote_TotalFundingAtAlphaOne() public {
        // alpha defaults to 1.0 -> totalFunding == totalQuadraticSum
        qf.processVote(1, 100, 10);
        qf.processVote(1, 400, 20);
        assertEq(qf.totalFunding(), qf.totalQuadraticSum());
    }

    function test_ProcessVote_MultipleProjectsAggregateQuadraticSumPerProject() public {
        qf.processVote(1, 100, 10); // project 1 sumSqrt = 10 -> 100
        qf.processVote(2, 400, 20); // project 2 sumSqrt = 20 -> 400

        // totalQuadraticSum must be the SUM of each project's squared sumSqrt,
        // i.e. 10^2 + 20^2 = 500, NOT (10+20)^2 = 900.
        assertEq(qf.totalQuadraticSum(), 500);
        assertEq(qf.totalLinearSum(), 500);
    }

    function test_ProcessVote_IndependentProjectsDoNotInterfere() public {
        qf.processVote(1, 100, 10);
        qf.processVote(2, 900, 30);

        ProperQF.Project memory p1 = qf.projects(1);
        ProperQF.Project memory p2 = qf.projects(2);

        assertEq(p1.sumContributions, 100);
        assertEq(p1.sumSquareRoots, 10);
        assertEq(p2.sumContributions, 900);
        assertEq(p2.sumSquareRoots, 30);
    }

    function test_ProcessVote_IncrementalUpdateMatchesRecomputationFromScratch() public {
        // Multiple votes across two projects, compare running totals against
        // a from-scratch recomputation based on final per-project sums.
        qf.processVote(1, 100, 10);
        qf.processVote(2, 64, 8);
        qf.processVote(1, 44, 6); // sumSqrt(1) 10->16, tolerance ok? contribution 44 sqrt=6 (6^2=36<=44), actualSqrt=6, ok
        qf.processVote(2, 36, 6); // sumSqrt(2) 8->14

        ProperQF.Project memory p1 = qf.projects(1);
        ProperQF.Project memory p2 = qf.projects(2);

        uint256 expectedQuadratic = p1.sumSquareRoots * p1.sumSquareRoots + p2.sumSquareRoots * p2.sumSquareRoots;
        uint256 expectedLinear = p1.sumContributions + p2.sumContributions;

        assertEq(qf.totalQuadraticSum(), expectedQuadratic);
        assertEq(qf.totalLinearSum(), expectedLinear);
    }

    // ---------------------------------------------------------------------
    // _processVoteUnchecked (bypasses validation)
    // ---------------------------------------------------------------------

    function test_ProcessVoteUnchecked_SkipsValidation() public {
        // voteWeight has no relation to sqrt(contribution); would revert via processVote
        qf.processVoteUnchecked(1, 100, 999);
        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, 100);
        assertEq(p.sumSquareRoots, 999);
        assertEq(qf.totalQuadraticSum(), 999 * 999);
        assertEq(qf.totalLinearSum(), 100);
    }

    function test_ProcessVoteUnchecked_AllowsZeroContribution() public {
        qf.processVoteUnchecked(1, 0, 0);
        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, 0);
        assertEq(p.sumSquareRoots, 0);
    }

    // ---------------------------------------------------------------------
    // Forced invariant-violation branches
    // ---------------------------------------------------------------------

    function test_RevertWhen_QuadraticSumUnderflow() public {
        // Force project.sumSquareRoots to be nonzero while totalQuadraticSum stays 0,
        // so oldQuadraticFunding > totalQuadraticSum on the next update.
        qf.setProjectRaw(1, 0, 100);
        vm.expectRevert(ProperQF.QuadraticSumUnderflow.selector);
        qf.processVoteUnchecked(1, 1, 1);
    }

    function test_RevertWhen_LinearSumUnderflow() public {
        // sumSquareRoots stays 0 so the quadratic check passes (0 !< 0),
        // but sumContributions is forced above totalLinearSum (0).
        qf.setProjectRaw(1, 100, 0);
        vm.expectRevert(ProperQF.LinearSumUnderflow.selector);
        qf.processVoteUnchecked(1, 1, 1);
    }

    // ---------------------------------------------------------------------
    // getTally
    // ---------------------------------------------------------------------

    function test_GetTally_AtAlphaOne() public {
        qf.processVote(1, 100, 10);
        qf.processVote(1, 400, 20);

        (uint256 sumContributions, uint256 sumSquareRoots, uint256 quadraticFunding, uint256 linearFunding) =
            qf.getTally(1);

        assertEq(sumContributions, 500);
        assertEq(sumSquareRoots, 30);
        assertEq(quadraticFunding, 900); // alpha = 1 -> full quadratic
        assertEq(linearFunding, 0); // 1 - alpha = 0
    }

    function test_GetTally_AtAlphaZero() public {
        qf.setAlpha(0, 1);
        qf.processVote(1, 100, 10);

        (, , uint256 quadraticFunding, uint256 linearFunding) = qf.getTally(1);
        assertEq(quadraticFunding, 0);
        assertEq(linearFunding, 100);
    }

    function test_GetTally_AtAlphaHalf() public {
        qf.setAlpha(1, 2);
        qf.processVote(1, 100, 10); // sumSqrt = 10 -> quadratic raw = 100

        (, , uint256 quadraticFunding, uint256 linearFunding) = qf.getTally(1);
        assertEq(quadraticFunding, 50); // floor(100 * 1/2)
        assertEq(linearFunding, 50); // floor(100 * 1/2)
    }

    function test_GetTally_UnknownProjectIsZero() public view {
        (uint256 sumContributions, uint256 sumSquareRoots, uint256 quadraticFunding, uint256 linearFunding) =
            qf.getTally(999);
        assertEq(sumContributions, 0);
        assertEq(sumSquareRoots, 0);
        assertEq(quadraticFunding, 0);
        assertEq(linearFunding, 0);
    }

    // ---------------------------------------------------------------------
    // _setAlpha
    // ---------------------------------------------------------------------

    function test_RevertWhen_AlphaDenominatorIsZero() public {
        vm.expectRevert(ProperQF.DenominatorMustBePositive.selector);
        qf.setAlpha(1, 0);
    }

    function test_RevertWhen_AlphaNumeratorExceedsDenominator() public {
        vm.expectRevert(ProperQF.AlphaMustBeLessOrEqualToOne.selector);
        qf.setAlpha(2, 1);
    }

    function test_SetAlpha_UpdatesGetAlpha() public {
        qf.setAlpha(3, 4);
        (uint256 num, uint256 den) = qf.getAlpha();
        assertEq(num, 3);
        assertEq(den, 4);
    }

    function test_SetAlpha_EmitsEvent() public {
        vm.expectEmit(true, true, true, true);
        emit AlphaUpdated(10000, 10000, 1, 2);
        qf.setAlpha(1, 2);
    }

    function test_SetAlpha_RecalculatesTotalFunding() public {
        qf.processVote(1, 100, 10); // sumSqrt = 10, quadratic raw = 100, linear = 100
        assertEq(qf.totalFunding(), 100); // alpha = 1 initially

        qf.setAlpha(0, 1); // pure linear
        assertEq(qf.totalFunding(), 100); // 100% of linear (100) = 100

        qf.setAlpha(1, 2); // half/half
        assertEq(qf.totalFunding(), 50 + 50);
    }

    function test_SetAlpha_ToZeroNumeratorZeroDenominatorEdgeAllowed() public {
        // numerator == denominator == 0 is technically not blocked (0 <= 0),
        // but denominator == 0 must revert first due to check order.
        vm.expectRevert(ProperQF.DenominatorMustBePositive.selector);
        qf.setAlpha(0, 0);
    }

    function test_SetAlpha_FullRangeBoundaries() public {
        qf.setAlpha(0, 1); // alpha = 0, allowed
        (uint256 num0, uint256 den0) = qf.getAlpha();
        assertEq(num0, 0);
        assertEq(den0, 1);

        qf.setAlpha(5, 5); // alpha = 1, allowed (numerator == denominator)
        (uint256 num1, uint256 den1) = qf.getAlpha();
        assertEq(num1, 5);
        assertEq(den1, 5);
    }

    // ---------------------------------------------------------------------
    // _calculateOptimalAlpha
    // ---------------------------------------------------------------------

    function test_OptimalAlpha_NoQuadraticAdvantageReturnsZero() public view {
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(0, 100, 200, 0);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_EqualQuadraticAndLinearReturnsZero() public view {
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(0, 100, 100, 0);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_InsufficientAssetsForLinearReturnsZero() public view {
        // quadraticSum > linearSum, but total assets available <= linearSum
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(0, 150, 100, 50);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_ExactlyAtLinearBoundaryReturnsZero() public view {
        // totalAssetsAvailable == linearSum -> falls into the <= branch
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(0, 150, 100, 100);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_SufficientForFullQuadraticReturnsOne() public view {
        // quadraticSum=150, linearSum=100 -> quadraticAdvantage=50
        // totalAssetsAvailable=200 -> numerator=100 >= 50
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(100, 150, 100, 100);
        assertEq(num, 1);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_ExactlyEnoughForFullQuadraticReturnsOne() public view {
        // numerator == quadraticAdvantage boundary
        // quadraticSum=150, linearSum=100 -> quadraticAdvantage=50
        // totalAssetsAvailable=150 -> numerator=50 == 50
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(50, 150, 100, 100);
        assertEq(num, 1);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_FractionalCase() public view {
        // quadraticSum=200, linearSum=100 -> quadraticAdvantage=100
        // totalAssetsAvailable = 30 (matching) + 100 (deposits) = 130 -> numerator = 30
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(30, 200, 100, 100);
        assertEq(num, 30);
        assertEq(den, 100);
    }

    function testFuzz_OptimalAlpha_NeverExceedsOne(
        uint256 matchingPoolAmount,
        uint256 quadraticSum,
        uint256 linearSum,
        uint256 totalUserDeposits
    ) public view {
        matchingPoolAmount = bound(matchingPoolAmount, 0, 1e30);
        quadraticSum = bound(quadraticSum, 0, 1e30);
        linearSum = bound(linearSum, 0, 1e30);
        totalUserDeposits = bound(totalUserDeposits, 0, 1e30);

        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(
            matchingPoolAmount, quadraticSum, linearSum, totalUserDeposits
        );

        assertGt(den, 0);
        assertLe(num, den);
    }

    // ---------------------------------------------------------------------
    // _calculateWeightedTotalFunding view helper consistency
    // ---------------------------------------------------------------------

    function test_CalculateWeightedTotalFundingMatchesStoredTotalFunding() public {
        qf.processVote(1, 100, 10);
        qf.processVote(2, 400, 20);
        qf.setAlpha(3, 7);

        assertEq(qf.calculateWeightedTotalFunding(), qf.totalFunding());
    }

    function testFuzz_ProcessVote_TotalFundingBoundedBySumOfProjectFundings(
        uint256 c1,
        uint256 c2,
        uint256 alphaNum
    ) public {
        c1 = bound(c1, 1, 1e30);
        c2 = bound(c2, 1, 1e30);
        alphaNum = bound(alphaNum, 0, 10000);

        qf.setAlpha(alphaNum, 10000);

        uint256 w1 = c1.sqrt();
        uint256 w2 = c2.sqrt();

        qf.processVote(1, c1, w1);
        qf.processVote(2, c2, w2);

        (, , uint256 qf1, uint256 lf1) = qf.getTally(1);
        (, , uint256 qf2, uint256 lf2) = qf.getTally(2);

        uint256 sumPerProjectFunding = qf1 + lf1 + qf2 + lf2;

        // Rounding dust: sum(project funding) <= totalFunding()
        assertLe(sumPerProjectFunding, qf.totalFunding());
    }
}

