// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

import { Test } from "forge-std/Test.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { ProperQF } from "src/mechanisms/voting-strategy/ProperQF.sol";

/// @notice Test harness exposing internal functions of ProperQF for testing purposes.
contract ProperQFHarness is ProperQF {
    function processVote(uint256 projectId, uint256 contribution, uint256 voteWeight) external {
        _processVote(projectId, contribution, voteWeight);
    }

    function processVoteUnchecked(uint256 projectId, uint256 contribution, uint256 voteWeight) external {
        _processVoteUnchecked(projectId, contribution, voteWeight);
    }

    function setAlpha(uint256 newNumerator, uint256 newDenominator) external {
        _setAlpha(newNumerator, newDenominator);
    }

    function calculateWeightedTotalFunding() external view returns (uint256) {
        return _calculateWeightedTotalFunding();
    }

    function calculateOptimalAlpha(
        uint256 matchingPoolAmount,
        uint256 quadraticSum,
        uint256 linearSum,
        uint256 totalUserDeposits
    ) external pure returns (uint256, uint256) {
        return _calculateOptimalAlpha(matchingPoolAmount, quadraticSum, linearSum, totalUserDeposits);
    }

    /// @notice Test-only helper to directly corrupt total sums, used to exercise the
    ///         internal underflow guards in `_processVoteUnchecked` which are otherwise
    ///         unreachable via the normal accounting invariants.
    function forceTotalSums(uint256 quadraticSum, uint256 linearSum) external {
        ProperQFStorage storage s = _getProperQFStorage();
        s.totalQuadraticSum = quadraticSum;
        s.totalLinearSum = linearSum;
    }

    /// @notice Test-only helper to directly seed a project's sums without touching totals,
    ///         used together with forceTotalSums to construct underflow scenarios.
    function forceProject(uint256 projectId, uint256 sumContributions, uint256 sumSquareRoots) external {
        ProperQFStorage storage s = _getProperQFStorage();
        s.projects[projectId].sumContributions = sumContributions;
        s.projects[projectId].sumSquareRoots = sumSquareRoots;
    }
}

contract ProperQFTest is Test {
    using Math for uint256;

    ProperQFHarness internal qf;

    event AlphaUpdated(uint256 oldNumerator, uint256 oldDenominator, uint256 newNumerator, uint256 newDenominator);

    function setUp() public {
        qf = new ProperQFHarness();
    }

    // ----------------------------------------------------------------------
    // Constructor / default state
    // ----------------------------------------------------------------------

    function test_DefaultAlphaIsOne() public view {
        (uint256 num, uint256 den) = qf.getAlpha();
        assertEq(num, 10000);
        assertEq(den, 10000);
    }

    function test_DefaultTotalsAreZero() public view {
        assertEq(qf.totalQuadraticSum(), 0);
        assertEq(qf.totalLinearSum(), 0);
        assertEq(qf.totalFunding(), 0);
    }

    function test_DefaultProjectIsEmpty() public view {
        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, 0);
        assertEq(p.sumSquareRoots, 0);
    }

    // ----------------------------------------------------------------------
    // _processVote validation
    // ----------------------------------------------------------------------

    function test_RevertWhen_ContributionIsZero() public {
        vm.expectRevert(ProperQF.ContributionMustBePositive.selector);
        qf.processVote(1, 0, 1);
    }

    function test_RevertWhen_VoteWeightIsZero() public {
        vm.expectRevert(ProperQF.VoteWeightMustBePositive.selector);
        qf.processVote(1, 100, 0);
    }

    function test_RevertWhen_VoteWeightSquaredExceedsContribution() public {
        // voteWeight=11 -> 121 > 100
        vm.expectRevert(ProperQF.SquareRootTooLarge.selector);
        qf.processVote(1, 100, 11);
    }

    function test_RevertWhen_VoteWeightSquaredOverflows() public {
        uint256 hugeWeight = type(uint128).max;
        // hugeWeight * hugeWeight does not overflow uint256 actually (128*2=256 bits, borderline)
        // Use a value guaranteed to overflow uint256 when squared.
        uint256 overflowWeight = type(uint256).max;
        vm.expectRevert(); // arithmetic overflow panic
        qf.processVote(1, 100, overflowWeight);
    }

    function test_RevertWhen_VoteWeightBelowTolerance() public {
        // contribution = 100, actualSqrt = 10, tolerance = 1 -> valid range [9,10]
        // voteWeight = 8 is below tolerance floor.
        vm.expectRevert(ProperQF.VoteWeightOutsideTolerance.selector);
        qf.processVote(1, 100, 8);
    }

    function test_ProcessVote_AtExactSqrt_Succeeds() public {
        qf.processVote(1, 100, 10);
        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, 100);
        assertEq(p.sumSquareRoots, 10);
    }

    function test_ProcessVote_AtLowerToleranceBound_Succeeds() public {
        // contribution = 100, actualSqrt = 10, tolerance = 1 -> lower bound = 9
        qf.processVote(1, 100, 9);
        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumSquareRoots, 9);
    }

    function test_ProcessVote_SmallContributionExactMatch() public {
        // contribution = 1, actualSqrt = 1, tolerance = 0 -> only voteWeight=1 works
        qf.processVote(1, 1, 1);
        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, 1);
        assertEq(p.sumSquareRoots, 1);
    }

    function test_RevertWhen_SmallContributionToleranceZeroAndWeightTooLow() public {
        // contribution = 4, actualSqrt = 2, tolerance = 0 -> only voteWeight=2 works, 1 must revert
        vm.expectRevert(ProperQF.VoteWeightOutsideTolerance.selector);
        qf.processVote(1, 4, 1);
    }

    // ----------------------------------------------------------------------
    // State accounting after valid votes
    // ----------------------------------------------------------------------

    function test_ProcessVote_UpdatesTotalsCorrectly() public {
        qf.processVote(1, 100, 10);
        // quadratic sum = 10^2 = 100; linear sum = 100
        assertEq(qf.totalQuadraticSum(), 100);
        assertEq(qf.totalLinearSum(), 100);
        // alpha = 1 by default => totalFunding = quadratic contribution fully weighted
        assertEq(qf.totalFunding(), 100);
    }

    function test_ProcessVote_AccumulatesForSameProject() public {
        qf.processVote(1, 100, 10); // sumSqrt=10, sumContrib=100
        qf.processVote(1, 100, 10); // sumSqrt=20, sumContrib=200

        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, 200);
        assertEq(p.sumSquareRoots, 20);

        assertEq(qf.totalQuadraticSum(), 20 * 20);
        assertEq(qf.totalLinearSum(), 200);
    }

    function test_ProcessVote_MultipleProjectsIndependent() public {
        qf.processVote(1, 100, 10);
        qf.processVote(2, 400, 20);

        ProperQF.Project memory p1 = qf.projects(1);
        ProperQF.Project memory p2 = qf.projects(2);

        assertEq(p1.sumContributions, 100);
        assertEq(p1.sumSquareRoots, 10);
        assertEq(p2.sumContributions, 400);
        assertEq(p2.sumSquareRoots, 20);

        assertEq(qf.totalQuadraticSum(), 10 * 10 + 20 * 20);
        assertEq(qf.totalLinearSum(), 100 + 400);
    }

    function test_GetTally_ReturnsExpectedValues() public {
        qf.processVote(1, 100, 10);
        qf.processVote(1, 100, 10);

        (uint256 sumContributions, uint256 sumSquareRoots, uint256 quadraticFunding, uint256 linearFunding) =
            qf.getTally(1);

        assertEq(sumContributions, 200);
        assertEq(sumSquareRoots, 20);
        // alpha = 1 (10000/10000) => quadraticFunding = 20^2 = 400, linearFunding = 0
        assertEq(quadraticFunding, 400);
        assertEq(linearFunding, 0);
    }

    function test_GetTally_UnknownProjectIsZero() public view {
        (uint256 sumContributions, uint256 sumSquareRoots, uint256 quadraticFunding, uint256 linearFunding) =
            qf.getTally(999);
        assertEq(sumContributions, 0);
        assertEq(sumSquareRoots, 0);
        assertEq(quadraticFunding, 0);
        assertEq(linearFunding, 0);
    }

    // ----------------------------------------------------------------------
    // _processVoteUnchecked
    // ----------------------------------------------------------------------

    function test_ProcessVoteUnchecked_SkipsValidation() public {
        // voteWeight^2 > contribution, would revert in checked path, but not here.
        qf.processVoteUnchecked(1, 10, 100);
        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, 10);
        assertEq(p.sumSquareRoots, 100);
        assertEq(qf.totalQuadraticSum(), 100 * 100);
        assertEq(qf.totalLinearSum(), 10);
    }

    // ----------------------------------------------------------------------
    // Alpha weighting
    // ----------------------------------------------------------------------

    function test_SetAlpha_UpdatesValuesAndEmitsEvent() public {
        vm.expectEmit(true, true, true, true);
        emit AlphaUpdated(10000, 10000, 5000, 10000);
        qf.setAlpha(5000, 10000);

        (uint256 num, uint256 den) = qf.getAlpha();
        assertEq(num, 5000);
        assertEq(den, 10000);
    }

    function test_RevertWhen_AlphaDenominatorIsZero() public {
        vm.expectRevert(ProperQF.DenominatorMustBePositive.selector);
        qf.setAlpha(1, 0);
    }

    function test_RevertWhen_AlphaNumeratorExceedsDenominator() public {
        vm.expectRevert(ProperQF.AlphaMustBeLessOrEqualToOne.selector);
        qf.setAlpha(2, 1);
    }

    function test_SetAlpha_ZeroMeansFullyLinear() public {
        qf.processVote(1, 100, 10); // quadratic=100, linear=100
        qf.setAlpha(0, 1);
        assertEq(qf.totalFunding(), 100); // fully linear: (1-0)*100 = 100
    }

    function test_SetAlpha_HalfWeightsBothComponents() public {
        qf.processVote(1, 100, 10); // quadratic sum = 100, linear sum = 100
        qf.setAlpha(1, 2);
        // weightedQuadratic = 100 * 1/2 = 50, weightedLinear = 100 * 1/2 = 50
        assertEq(qf.totalFunding(), 100);
    }

    function test_SetAlpha_RecalculatesTotalFundingImmediately() public {
        qf.processVote(1, 400, 20); // quadratic=400, linear=400
        qf.setAlpha(10000, 10000); // alpha = 1 (default, no-op logically)
        assertEq(qf.totalFunding(), 400);

        qf.setAlpha(0, 1); // fully linear
        assertEq(qf.totalFunding(), 400);
    }

    function test_CalculateWeightedTotalFunding_MatchesTotalFunding() public {
        qf.processVote(1, 100, 10);
        qf.processVote(2, 400, 20);
        qf.setAlpha(3000, 10000);
        assertEq(qf.calculateWeightedTotalFunding(), qf.totalFunding());
    }

    // ----------------------------------------------------------------------
    // Underflow guards (forced via test-only harness helpers)
    // ----------------------------------------------------------------------

    function test_RevertWhen_QuadraticSumUnderflow() public {
        // Seed a project with nonzero sumSquareRoots but leave totalQuadraticSum at 0,
        // so oldQuadraticFunding (sumSquareRoots^2) > totalQuadraticSum.
        qf.forceProject(1, 100, 10);
        qf.forceTotalSums(0, 100);

        vm.expectRevert(ProperQF.QuadraticSumUnderflow.selector);
        qf.processVoteUnchecked(1, 100, 10);
    }

    function test_RevertWhen_LinearSumUnderflow() public {
        // Seed a project with nonzero sumContributions but leave totalLinearSum at 0,
        // so totalLinearSum < project.sumContributions.
        qf.forceProject(1, 100, 10);
        qf.forceTotalSums(100, 0);

        vm.expectRevert(ProperQF.LinearSumUnderflow.selector);
        qf.processVoteUnchecked(1, 100, 10);
    }

    // ----------------------------------------------------------------------
    // _calculateOptimalAlpha
    // ----------------------------------------------------------------------

    function test_OptimalAlpha_NoQuadraticBenefit_ReturnsZero() public view {
        // quadraticSum <= linearSum
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(100, 200, 200, 100);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_QuadraticLessThanLinear_ReturnsZero() public view {
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(0, 100, 500, 0);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_InsufficientAssetsForLinear_ReturnsZero() public view {
        // quadraticSum=1000, linearSum=200 -> advantage=800
        // totalAssetsAvailable = deposits+pool = 150 <= linearSum(200)
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(50, 1000, 200, 100);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_EnoughForFullQuadratic_ReturnsOne() public view {
        // quadraticSum=1000, linearSum=200 -> advantage=800
        // totalAssetsAvailable = 900+200=1100, numerator=1100-200=900 >= 800
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(200, 1000, 200, 900);
        assertEq(num, 1);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_FractionalCase() public view {
        // quadraticSum=1000, linearSum=200 -> advantage=800
        // totalAssetsAvailable = 300+100=400, numerator=400-200=200 < 800
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(100, 1000, 200, 300);
        assertEq(num, 200);
        assertEq(den, 800);
    }

    function test_OptimalAlpha_ExactBoundary_TotalAssetsEqualsLinearSum() public view {
        // totalAssetsAvailable == linearSum exactly -> falls into "not enough" branch (<=)
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(100, 1000, 200, 100);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_OptimalAlpha_ExactBoundary_NumeratorEqualsAdvantage() public view {
        // quadraticSum=1000, linearSum=200 -> advantage=800
        // totalAssetsAvailable - linearSum == 800 exactly -> full quadratic
        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(500, 1000, 200, 500);
        assertEq(num, 1);
        assertEq(den, 1);
    }

    // ----------------------------------------------------------------------
    // Fuzz tests
    // ----------------------------------------------------------------------

    function testFuzz_ProcessVote_AtActualSqrt_AlwaysSucceeds(uint256 contribution) public {
        contribution = bound(contribution, 1, 1e36);
        uint256 actualSqrt = contribution.sqrt();

        qf.processVote(1, contribution, actualSqrt);

        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumContributions, contribution);
        assertEq(p.sumSquareRoots, actualSqrt);
    }

    function testFuzz_ProcessVote_BelowToleranceFloorReverts(uint256 contribution) public {
        // Pick contributions where actualSqrt is large enough to have meaningful tolerance.
        contribution = bound(contribution, 10_000, 1e36);
        uint256 actualSqrt = contribution.sqrt();
        uint256 tolerance = actualSqrt / 10;
        vm.assume(tolerance > 0);
        uint256 floor = actualSqrt - tolerance;
        vm.assume(floor > 0);

        uint256 belowFloor = floor - 1;

        vm.expectRevert(ProperQF.VoteWeightOutsideTolerance.selector);
        qf.processVote(1, contribution, belowFloor);
    }

    function testFuzz_ProcessVote_WithinToleranceRangeSucceeds(uint256 contribution, uint256 offset) public {
        contribution = bound(contribution, 100, 1e36);
        uint256 actualSqrt = contribution.sqrt();
        uint256 tolerance = actualSqrt / 10;

        offset = bound(offset, 0, tolerance);
        uint256 voteWeight = actualSqrt - offset;
        vm.assume(voteWeight > 0);
        vm.assume(voteWeight * voteWeight <= contribution);

        qf.processVote(1, contribution, voteWeight);

        ProperQF.Project memory p = qf.projects(1);
        assertEq(p.sumSquareRoots, voteWeight);
        assertEq(p.sumContributions, contribution);
    }

    function testFuzz_TotalFunding_NeverExceedsSumOfComponents(uint256 alphaNum, uint256 alphaDen) public {
        alphaDen = bound(alphaDen, 1, 10000);
        alphaNum = bound(alphaNum, 0, alphaDen);

        qf.processVote(1, 100, 10);
        qf.processVote(2, 400, 20);
        qf.setAlpha(alphaNum, alphaDen);

        uint256 quadraticSum = qf.totalQuadraticSum();
        uint256 linearSum = qf.totalLinearSum();

        uint256 expectedQuadratic = (quadraticSum * alphaNum) / alphaDen;
        uint256 expectedLinear = (linearSum * (alphaDen - alphaNum)) / alphaDen;

        assertEq(qf.totalFunding(), expectedQuadratic + expectedLinear);
    }

    function testFuzz_OptimalAlpha_NeverExceedsOne(
        uint256 matchingPoolAmount,
        uint256 quadraticSum,
        uint256 linearSum,
        uint256 totalUserDeposits
    ) public view {
        matchingPoolAmount = bound(matchingPoolAmount, 0, 1e30);
        quadraticSum = bound(quadraticSum, 0, 1e30);
        linearSum = bound(linearSum, 0, 1e30);
        totalUserDeposits = bound(totalUserDeposits, 0, 1e30);

        (uint256 num, uint256 den) = qf.calculateOptimalAlpha(
            matchingPoolAmount, quadraticSum, linearSum, totalUserDeposits
        );

        assertGt(den, 0);
        assertLe(num, den);
    }
}

