        vm.expectRevert(stdError.arithmeticError);
        harness.processVote(1, 1, hugeWeight);
    }

    function test_processVote_revertsWhenVoteWeightBelowTolerance() public {
        // sqrt(10000) = 100, tolerance = 10 -> acceptable range [90, 100]
        vm.expectRevert(ProperQF.VoteWeightOutsideTolerance.selector);
        harness.processVote(1, 10000, 89);
    }

    function test_processVote_acceptsLowerToleranceBoundary() public {
        // sqrt(10000) = 100, tolerance = 10 -> 90 is the lowest accepted voteWeight
        harness.processVote(1, 10000, 90);
        ProperQF.Project memory p = harness.projects(1);
        assertEq(p.sumContributions, 10000);
        assertEq(p.sumSquareRoots, 90);
    }

    function test_processVote_acceptsExactSqrt() public {
        harness.processVote(1, 10000, 100);
        ProperQF.Project memory p = harness.projects(1);
        assertEq(p.sumContributions, 10000);
        assertEq(p.sumSquareRoots, 100);
    }

    function test_processVote_smallestPositiveContribution() public {
        // sqrt(1) = 1, tolerance = 0 -> voteWeight must equal exactly 1
        harness.processVote(1, 1, 1);
        ProperQF.Project memory p = harness.projects(1);
        assertEq(p.sumContributions, 1);
        assertEq(p.sumSquareRoots, 1);
    }

    function test_processVote_smallContribution_toleranceZero_revertsBelowExact() public {
        // sqrt(4) = 2, tolerance = 0 -> only voteWeight == 2 accepted
        vm.expectRevert(ProperQF.VoteWeightOutsideTolerance.selector);
        harness.processVote(1, 4, 1);
    }

    /*//////////////////////////////////////////////////////////////
                        _processVote: ACCOUNTING / TALLY
    //////////////////////////////////////////////////////////////*/

    function test_processVote_singleVoteUpdatesTallyAndTotals() public {
        harness.processVote(1, 100, 10);

        (uint256 sumContributions, uint256 sumSquareRoots, uint256 quadraticFunding, uint256 linearFunding) =
            harness.getTally(1);

        assertEq(sumContributions, 100);
        assertEq(sumSquareRoots, 10);
        // alpha = 1 by default -> quadraticFunding = 10^2 * 1 = 100, linearFunding = 100 * 0 = 0
        assertEq(quadraticFunding, 100);
        assertEq(linearFunding, 0);

        assertEq(harness.totalQuadraticSum(), 100);
        assertEq(harness.totalLinearSum(), 100);
        assertEq(harness.totalFunding(), 100);
    }

    function test_processVote_multipleVotesSameProjectAccumulate() public {
        harness.processVote(1, 100, 10);
        harness.processVote(1, 100, 10);

        ProperQF.Project memory p = harness.projects(1);
        assertEq(p.sumContributions, 200);
        assertEq(p.sumSquareRoots, 20);

        // Quadratic sum uses (sum of sqrt)^2 = 20^2 = 400, not sum of squares (100 + 100 = 200)
        assertEq(harness.totalQuadraticSum(), 400);
        assertEq(harness.totalLinearSum(), 200);
        assertEq(harness.totalFunding(), 400); // alpha = 1
    }

    function test_processVote_multipleProjectsIndependentAndSummed() public {
        harness.processVote(1, 100, 10); // sqrt(100) = 10
        harness.processVote(2, 400, 20); // sqrt(400) = 20

        ProperQF.Project memory p1 = harness.projects(1);
        ProperQF.Project memory p2 = harness.projects(2);
        assertEq(p1.sumSquareRoots, 10);
        assertEq(p2.sumSquareRoots, 20);

        // totalQuadraticSum = sum over projects of (sumSquareRoots_j)^2 = 100 + 400 = 500
        assertEq(harness.totalQuadraticSum(), 500);
        assertEq(harness.totalLinearSum(), 500);
        assertEq(harness.totalFunding(), 500);
    }

    function test_processVote_projectIsolation() public {
        harness.processVote(1, 100, 10);

        ProperQF.Project memory p2 = harness.projects(2);
        assertEq(p2.sumContributions, 0);
        assertEq(p2.sumSquareRoots, 0);
    }

    function test_getTally_reflectsAlphaWeighting() public {
        harness.processVote(1, 10000, 100); // sumSquareRoots = 100, sumContributions = 10000
        harness.setAlpha(5000, 10000); // alpha = 0.5

        (uint256 sumContributions, uint256 sumSquareRoots, uint256 quadraticFunding, uint256 linearFunding) =
            harness.getTally(1);

        assertEq(sumContributions, 10000);
        assertEq(sumSquareRoots, 100);
        // raw quadratic = 100^2 = 10000; quadraticFunding = 10000 * 5000 / 10000 = 5000
        assertEq(quadraticFunding, 5000);
        // linearFunding = 10000 * (10000-5000) / 10000 = 5000
        assertEq(linearFunding, 5000);
    }

    /*//////////////////////////////////////////////////////////////
                        _processVoteUnchecked: SKIPS VALIDATION
    //////////////////////////////////////////////////////////////*/

    function test_processVoteUnchecked_skipsValidation() public {
        // Would revert via _processVote (voteWeight^2 > contribution), but unchecked path allows it.
        harness.processVoteUnchecked(1, 10, 100);
        ProperQF.Project memory p = harness.projects(1);
        assertEq(p.sumContributions, 10);
        assertEq(p.sumSquareRoots, 100);
    }

    function test_processVoteUnchecked_revertsOnQuadraticSumUnderflow() public {
        // Poke project state directly without updating totals, so the invariant
        // s.totalQuadraticSum >= oldQuadraticFunding (sumSquareRoots^2) is broken.
        harness.setProjectRaw(1, 100, 10);
        // totalQuadraticSum is still 0 here, but oldQuadraticFunding = 10^2 = 100 > 0
        vm.expectRevert(ProperQF.QuadraticSumUnderflow.selector);
        harness.processVoteUnchecked(1, 1, 1);
    }

    function test_processVoteUnchecked_revertsOnLinearSumUnderflow() public {
        // sumSquareRoots = 0 so the quadratic check passes (0 >= 0), but sumContributions
        // exceeds totalLinearSum (still 0), breaking the linear invariant.
        harness.setProjectRaw(1, 100, 0);
        vm.expectRevert(ProperQF.LinearSumUnderflow.selector);
        harness.processVoteUnchecked(1, 1, 1);
    }

    /*//////////////////////////////////////////////////////////////
                                _setAlpha
    //////////////////////////////////////////////////////////////*/

    function test_setAlpha_revertsOnZeroDenominator() public {
        vm.expectRevert(ProperQF.DenominatorMustBePositive.selector);
        harness.setAlpha(1, 0);
    }

    function test_setAlpha_revertsWhenNumeratorExceedsDenominator() public {
        vm.expectRevert(ProperQF.AlphaMustBeLessOrEqualToOne.selector);
        harness.setAlpha(2, 1);
    }

    function test_setAlpha_allowsNumeratorEqualToDenominator() public {
        harness.setAlpha(7, 7);
        (uint256 num, uint256 den) = harness.getAlpha();
        assertEq(num, 7);
        assertEq(den, 7);
    }

    function test_setAlpha_allowsZeroNumerator() public {
        harness.setAlpha(0, 5);
        (uint256 num, uint256 den) = harness.getAlpha();
        assertEq(num, 0);
        assertEq(den, 5);
    }

    function test_setAlpha_updatesStateAndEmitsEvent() public {
        vm.expectEmit(true, true, true, true, address(harness));
        emit AlphaUpdated(10000, 10000, 5000, 10000);
        harness.setAlpha(5000, 10000);

        (uint256 num, uint256 den) = harness.getAlpha();
        assertEq(num, 5000);
        assertEq(den, 10000);
    }

    function test_setAlpha_recalculatesTotalFunding() public {
        harness.processVote(1, 10000, 100); // sumSquareRoots=100 -> quadratic=10000, linear=10000

        // alpha = 1 initially -> totalFunding = 10000
        assertEq(harness.totalFunding(), 10000);

        harness.setAlpha(0, 1); // alpha = 0 -> fully linear
        assertEq(harness.totalFunding(), 10000);

        harness.setAlpha(5000, 10000); // alpha = 0.5
        // weightedQuadratic = 10000*5000/10000=5000, weightedLinear=10000*5000/10000=5000
        assertEq(harness.totalFunding(), 10000);
        assertEq(harness.totalFunding(), harness.calculateWeightedTotalFunding());
    }

    function test_setAlpha_zeroAlphaGivesPureLinearFunding() public {
        harness.processVote(1, 100, 10); // quadratic contribution would be 100, linear 100
        harness.setAlpha(0, 1);
        assertEq(harness.totalFunding(), harness.totalLinearSum());
    }

    function test_setAlpha_fullAlphaGivesPureQuadraticFunding() public {
        harness.processVote(1, 100, 10);
        harness.setAlpha(1, 1);
        assertEq(harness.totalFunding(), harness.totalQuadraticSum());
    }

    /*//////////////////////////////////////////////////////////////
                        _calculateOptimalAlpha
    //////////////////////////////////////////////////////////////*/

    function test_calculateOptimalAlpha_noQuadraticAdvantage_returnsZero() public view {
        (uint256 num, uint256 den) = harness.calculateOptimalAlpha(100, 500, 500, 100);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_calculateOptimalAlpha_quadraticSumLessThanLinear_returnsZero() public view {
        (uint256 num, uint256 den) = harness.calculateOptimalAlpha(100, 400, 500, 100);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_calculateOptimalAlpha_insufficientAssetsForLinear_returnsZero() public view {
        // quadraticSum > linearSum, but totalAssetsAvailable <= linearSum
        (uint256 num, uint256 den) = harness.calculateOptimalAlpha(0, 1000, 500, 100);
        assertEq(num, 0);
        assertEq(den, 1);
    }

    function test_calculateOptimalAlpha_enoughForFullQuadratic_returnsOne() public view {
        // quadraticSum=1000, linearSum=200, advantage=800
        // totalAssetsAvailable = totalUserDeposits + matchingPoolAmount = 900 + 100 = 1000
        // numerator = 1000 - 200 = 800 >= advantage(800) -> alpha = 1
        (uint256 num, uint256 den) = harness.calculateOptimalAlpha(100, 1000, 200, 900);
        assertEq(num, 1);
        assertEq(den, 1);
    }

    function test_calculateOptimalAlpha_fractionalAlpha() public view {
        // quadraticSum=1000, linearSum=200, advantage=800
        // totalAssetsAvailable = 300 + 100 = 400
        // numerator = 400 - 200 = 200 < advantage(800) -> alpha = 200/800
        (uint256 num, uint256 den) = harness.calculateOptimalAlpha(100, 1000, 200, 300);
        assertEq(num, 200);
        assertEq(den, 800);
    }

    function test_calculateOptimalAlpha_boundaryEqualsAdvantage_returnsOne() public view {
        // numerator exactly equal to quadraticAdvantage -> full alpha
        // quadraticSum=1000, linearSum=0, advantage=1000
        // totalAssetsAvailable = 1000, numerator = 1000 == advantage
        (uint256 num, uint256 den) = harness.calculateOptimalAlpha(0, 1000, 0, 1000);
        assertEq(num, 1);
        assertEq(den, 1);
    }

    /*//////////////////////////////////////////////////////////////
                                FUZZING
    //////////////////////////////////////////////////////////////*/

    function testFuzz_processVote_exactSqrtAlwaysAccepted(uint256 contribution) public {
        contribution = bound(contribution, 1, 1e40);
        uint256 voteWeight = contribution.sqrt();

        harness.processVote(1, contribution, voteWeight);

        ProperQF.Project memory p = harness.projects(1);
        assertEq(p.sumContributions, contribution);
        assertEq(p.sumSquareRoots, voteWeight);
        assertEq(harness.totalQuadraticSum(), voteWeight * voteWeight);
        assertEq(harness.totalLinearSum(), contribution);
    }

    function testFuzz_processVote_belowMinToleranceReverts(uint256 contribution) public {
        // Need actualSqrt large enough that tolerance >= 1, so we can go strictly below the floor.
        contribution = bound(contribution, 100, 1e40);
        uint256 actualSqrt = contribution.sqrt();
        uint256 tolerance = actualSqrt / 10;
        vm.assume(tolerance > 0);
        uint256 tooLow = actualSqrt - tolerance - 1;

        vm.expectRevert(ProperQF.VoteWeightOutsideTolerance.selector);
        harness.processVote(1, contribution, tooLow);
    }

    function testFuzz_processVote_aboveSqrtReverts(uint256 contribution) public {
        contribution = bound(contribution, 1, 1e40);
        uint256 actualSqrt = contribution.sqrt();
        uint256 tooHigh = actualSqrt + 1;
        // tooHigh^2 > contribution always holds since actualSqrt is the floor sqrt
        vm.expectRevert(ProperQF.SquareRootTooLarge.selector);
        harness.processVote(1, contribution, tooHigh);
    }

    function testFuzz_setAlpha_validRangeNeverReverts(uint256 num, uint256 den) public {
        den = bound(den, 1, type(uint128).max);
        num = bound(num, 0, den);

        harness.setAlpha(num, den);
        (uint256 gotNum, uint256 gotDen) = harness.getAlpha();
        assertEq(gotNum, num);
        assertEq(gotDen, den);
    }

    function testFuzz_setAlpha_invalidNumeratorReverts(uint256 num, uint256 den) public {
        den = bound(den, 1, type(uint128).max);
        num = bound(num, den + 1, type(uint256).max);

        vm.expectRevert(ProperQF.AlphaMustBeLessOrEqualToOne.selector);
        harness.setAlpha(num, den);
    }

    function testFuzz_calculateOptimalAlpha_neverRevertsAndRatioBounded(
        uint256 matchingPoolAmount,
        uint256 quadraticSum,
        uint256 linearSum,
        uint256 totalUserDeposits
    ) public view {
        matchingPoolAmount = bound(matchingPoolAmount, 0, 1e40);
        quadraticSum = bound(quadraticSum, 0, 1e40);
        linearSum = bound(linearSum, 0, 1e40);
        totalUserDeposits = bound(totalUserDeposits, 0, 1e40);

        (uint256 num, uint256 den) = harness.calculateOptimalAlpha(
            matchingPoolAmount, quadraticSum, linearSum, totalUserDeposits
        );

        assertGt(den, 0);
        assertLe(num, den);
    }
}

