/// @dev Mock "strategy" implementing every interface YieldForwarder depends on
///      (IReportable, IRedeemable, IMaxRedeem, IConvertible) plus IERC20 for its
///      own share token. Highly configurable so tests can drive every branch of
///      `reportAndForward`.
contract MockStrategy is IReportable, IRedeemable, IMaxRedeem, IConvertible, IERC20 {
    MockERC20 public immutable asset;

    // --- share ledger (this contract IS the share token) ---
    mapping(address => uint256) public balanceOf;
    uint256 public totalSupply;
    mapping(address => mapping(address => uint256)) public allowance;

    // --- report() configuration ---
    address public reportRecipient;
    uint256 public profitToMint;
    uint256 public lossToReport;
    uint256 public reportCallCount;
    bool public revertOnReport;

    // --- maxRedeem / convertToAssets / redeem configuration ---
    uint256 public maxRedeemAmount = type(uint256).max;
    uint256 public convertRateWad = 1e18; // assets returned per share, 1e18 = 1:1
    bool public revertOnRedeem;

    uint256 public redeemCallCount;
    uint256 public lastRedeemShares;
    address public lastRedeemReceiver;
    address public lastRedeemOwner;
    uint256 public lastMaxLoss;

    // --- reentrancy testing ---
    address public reentrantTarget;
    address public reentrantStrategy;
    uint256 public reentrantMaxLoss;

    constructor(MockERC20 _asset) {
        asset = _asset;
    }

    // ---------------- test configuration helpers ----------------

    function setReportRecipient(address r) external {
        reportRecipient = r;
    }

    function setProfit(uint256 p) external {
        profitToMint = p;
    }

    function setLoss(uint256 l) external {
        lossToReport = l;
    }

    function setRevertOnReport(bool b) external {
        revertOnReport = b;
    }

    function setMaxRedeem(uint256 m) external {
        maxRedeemAmount = m;
    }

    function setConvertRateWad(uint256 r) external {
        convertRateWad = r;
    }

    function setRevertOnRedeem(bool b) external {
        revertOnRedeem = b;
    }

    function setReentrant(address target, address strategy_, uint256 maxLoss_) external {
        reentrantTarget = target;
        reentrantStrategy = strategy_;
        reentrantMaxLoss = maxLoss_;
    }

    function mintShares(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }

    // ---------------- IReportable ----------------

    function report() external returns (uint256 profit, uint256 loss) {
        reportCallCount++;
        if (revertOnReport) revert("MockStrategy: report reverted");

        profit = profitToMint;
        loss = lossToReport;

        if (profit > 0) {
            balanceOf[reportRecipient] += profit;
            totalSupply += profit;
            // fund the strategy with enough underlying to honor a subsequent redeem
            asset.mint(address(this), (profit * convertRateWad) / 1e18);
        }

        profitToMint = 0;
        lossToReport = 0;
    }

    // ---------------- IMaxRedeem ----------------

    function maxRedeem(address) external view returns (uint256) {
        return maxRedeemAmount;
    }

    // ---------------- IConvertible ----------------

    function convertToAssets(uint256 shares) public view returns (uint256) {
        return (shares * convertRateWad) / 1e18;
    }

    // ---------------- IRedeemable ----------------

    function redeem(uint256 shares, address receiver_, address owner, uint256 maxLoss)
        external
        returns (uint256 assets)
    {
        redeemCallCount++;
        lastRedeemShares = shares;
        lastRedeemReceiver = receiver_;
        lastRedeemOwner = owner;
        lastMaxLoss = maxLoss;

        if (revertOnRedeem) revert("MockStrategy: redeem reverted");

        assets = convertToAssets(shares);
        if (assets == 0) revert("ZERO_ASSETS");

        balanceOf[owner] -= shares;
        totalSupply -= shares;
        asset.transfer(receiver_, assets);

        if (reentrantTarget != address(0)) {
            address target = reentrantTarget;
            reentrantTarget = address(0); // arm a single reentry attempt only
            YieldForwarder(target).reportAndForward(reentrantStrategy, reentrantMaxLoss);
        }
    }

    // ---------------- IERC20 (share token) ----------------

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - amount;
        }
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }
}

contract YieldForwarderTest is Test {
