        reentrantMaxLoss = maxLoss_;
    }

    function mintShares(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }

    // ---------------- IReportable ----------------

    function report() external returns (uint256 profit, uint256 loss) {
        reportCallCount++;
        if (revertOnReport) revert("MockStrategy: report reverted");

        profit = profitToMint;
        loss = lossToReport;

        if (profit > 0) {
            balanceOf[reportRecipient] += profit;
            totalSupply += profit;
            // fund the strategy with enough underlying to honor a subsequent redeem
            asset.mint(address(this), (profit * convertRateWad) / 1e18);
        }

        profitToMint = 0;
        lossToReport = 0;
    }

    // ---------------- IMaxRedeem ----------------

    function maxRedeem(address) external view returns (uint256) {
        return maxRedeemAmount;
    }

    // ---------------- IConvertible ----------------

    function convertToAssets(uint256 shares) public view returns (uint256) {
        return (shares * convertRateWad) / 1e18;
    }

    // ---------------- IRedeemable ----------------

    function redeem(uint256 shares, address receiver_, address owner, uint256 maxLoss)
        external
        returns (uint256 assets)
    {
        redeemCallCount++;
        lastRedeemShares = shares;
        lastRedeemReceiver = receiver_;
        lastRedeemOwner = owner;
        lastMaxLoss = maxLoss;

        if (revertOnRedeem) revert("MockStrategy: redeem reverted");

        assets = convertToAssets(shares);
        if (assets == 0) revert("ZERO_ASSETS");

        balanceOf[owner] -= shares;
        totalSupply -= shares;
        asset.transfer(receiver_, assets);

        if (reentrantTarget != address(0)) {
            address target = reentrantTarget;
            reentrantTarget = address(0); // arm a single reentry attempt only
            YieldForwarder(target).reportAndForward(reentrantStrategy, reentrantMaxLoss);
        }
    }

    // ---------------- IERC20 (share token) ----------------

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - amount;
        }
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }
}

