    // reportAndForward: access control
    // ================================================================

    function test_reportAndForward_revertsForNonKeeper() public {
        vm.prank(stranger);
        vm.expectRevert(YieldForwarder.OnlyKeeper.selector);
        forwarder.reportAndForward(address(strategy), 0);
    }

    function test_reportAndForward_callableByKeeper() public {
        vm.prank(keeper);
        forwarder.reportAndForward(address(strategy), 0);
        assertEq(strategy.reportCallCount(), 1);
    }

    // ================================================================
    // reportAndForward: no profit
    // ================================================================

    function test_reportAndForward_noProfit_returnsZeroAndSkipsRedeem() public {
        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 0);
        assertEq(strategy.reportCallCount(), 1);
        assertEq(strategy.redeemCallCount(), 0);
    }

    // ================================================================
    // reportAndForward: happy path
    // ================================================================

    function test_reportAndForward_happyPath() public {
        strategy.setProfit(100e18);

        vm.expectEmit(true, true, false, true, address(forwarder));
        emit YieldForwarded(address(strategy), receiver, 100e18, 100e18);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 50);

        assertEq(assets, 100e18);
        assertEq(asset.balanceOf(receiver), 100e18);
        assertEq(strategy.balanceOf(address(forwarder)), 0);
        assertEq(strategy.lastRedeemReceiver(), receiver);
        assertEq(strategy.lastRedeemOwner(), address(forwarder));
        assertEq(strategy.lastMaxLoss(), 50);
        assertEq(strategy.redeemCallCount(), 1);
    }

    function testFuzz_reportAndForward_happyPath(uint96 profit) public {
        vm.assume(profit > 0);
        strategy.setProfit(profit);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, profit);
        assertEq(asset.balanceOf(receiver), profit);
        assertEq(strategy.balanceOf(address(forwarder)), 0);
    }

