    // reportAndForward: maxRedeem cap
    // ================================================================

    function test_reportAndForward_capsAtMaxRedeem() public {
        strategy.setProfit(100e18);
        strategy.setMaxRedeem(40e18);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 40e18);
        assertEq(strategy.balanceOf(address(forwarder)), 60e18);
        assertEq(asset.balanceOf(receiver), 40e18);
    }

    function test_reportAndForward_zeroMaxRedeem_skipsRedeem() public {
        strategy.setProfit(100e18);
        strategy.setMaxRedeem(0);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 0);
        assertEq(strategy.redeemCallCount(), 0);
        assertEq(strategy.balanceOf(address(forwarder)), 100e18);
    }

    function test_reportAndForward_residualSharesPickedUpOnLaterCall() public {
        strategy.setProfit(100e18);
        strategy.setMaxRedeem(40e18);

        vm.prank(keeper);
        forwarder.reportAndForward(address(strategy), 0);
        assertEq(strategy.balanceOf(address(forwarder)), 60e18);

        // headroom recovers; no new profit this round
        strategy.setMaxRedeem(type(uint256).max);
        vm.prank(keeper);
        uint256 assets2 = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets2, 60e18);
        assertEq(strategy.balanceOf(address(forwarder)), 0);
        assertEq(asset.balanceOf(receiver), 100e18);
    }

    function testFuzz_reportAndForward_capsAtMaxRedeem(uint96 profit, uint96 maxRedeemAmt) public {
        vm.assume(profit > 0);
        strategy.setProfit(profit);
        strategy.setMaxRedeem(maxRedeemAmt);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        uint256 expectedShares = maxRedeemAmt < profit ? maxRedeemAmt : profit;
        assertEq(assets, expectedShares);
        assertEq(strategy.balanceOf(address(forwarder)), profit - expectedShares);
    }

    // ================================================================
    // reportAndForward: convertToAssets rounds to zero (loss-impaired dust)
    // ================================================================

    function test_reportAndForward_zeroConvertedAssets_skipsRedeem() public {
        strategy.setProfit(1);
