        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 0);
        assertEq(strategy.redeemCallCount(), 0);
        assertEq(strategy.balanceOf(address(forwarder)), 1);
    }

    // ================================================================
    // reportAndForward: reverts bubble through
    // ================================================================

    function test_reportAndForward_bubblesReportRevert() public {
        strategy.setRevertOnReport(true);

        vm.prank(keeper);
        vm.expectRevert("MockStrategy: report reverted");
        forwarder.reportAndForward(address(strategy), 0);
    }

    function test_reportAndForward_bubblesRedeemRevert() public {
        strategy.setProfit(10e18);
        strategy.setRevertOnRedeem(true);

        vm.prank(keeper);
        vm.expectRevert("MockStrategy: redeem reverted");
        forwarder.reportAndForward(address(strategy), 0);
    }

    // ================================================================
    // reportAndForward: reentrancy guard
    // ================================================================

    function test_reportAndForward_reentrancyReverts() public {
        strategy.setProfit(10e18);
        strategy.setReentrant(address(forwarder), address(strategy), 0);

        vm.prank(keeper);
        vm.expectRevert();
        forwarder.reportAndForward(address(strategy), 0);
    }

