        asset.mint(address(forwarder), 500e18);

        vm.expectEmit(true, true, false, true, address(forwarder));
        emit TokenForwarded(address(asset), receiver, 500e18);

        vm.prank(keeper);
        forwarder.forwardToken(address(asset));

        assertEq(asset.balanceOf(receiver), 500e18);
        assertEq(asset.balanceOf(address(forwarder)), 0);
    }

    function test_forwardToken_worksForStrategyShareTokens() public {
        strategy.mintShares(address(forwarder), 10e18);

        vm.prank(keeper);
        forwarder.forwardToken(address(strategy));

        assertEq(strategy.balanceOf(receiver), 10e18);
        assertEq(strategy.balanceOf(address(forwarder)), 0);
