/// @dev Minimal mintable ERC20 used both as the "underlying asset" the
///      strategy pays out and as a generic airdrop-style token for
///      forwardToken() tests.
contract MockERC20 is ERC20 {
    constructor() ERC20("Mock Asset", "mAST") {}

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Configurable mock strategy implementing the four minimal interfaces
///      YieldForwarder depends on, plus a bare-bones `balanceOf`/`transfer`
///      pair so it can also stand in for the "strategy shares" ERC20 that
///      report() mints into the forwarder.
contract MockStrategy is IReportable, IRedeemable, IMaxRedeem, IConvertible {
    MockERC20 public immutable asset;

    mapping(address => uint256) public balanceOf;

    uint256 public rateNumerator = 1e18;
    uint256 public rateDenominator = 1e18;
    uint256 public maxRedeemAmount = type(uint256).max;
    uint256 public nextProfitShares;
    uint256 public nextLoss;
    uint256 public reportCallCount;
    uint256 public lastMaxLoss;
    bool public revertOnReport;

    bool public reentrantOnReport;
    bool public reentrantOnRedeem;
    address public reentrantTarget;
    bytes public reentrantCalldata;

    constructor(MockERC20 _asset) {
        asset = _asset;
    }

    // ---- test configuration helpers ----

    function setNextProfitShares(uint256 v) external {
        nextProfitShares = v;
    }

    function setNextLoss(uint256 v) external {
        nextLoss = v;
    }

    function setMaxRedeemAmount(uint256 v) external {
        maxRedeemAmount = v;
    }

    function setExchangeRate(uint256 num, uint256 den) external {
        rateNumerator = num;
        rateDenominator = den;
    }

    function setRevertOnReport(bool v) external {
        revertOnReport = v;
    }

    function mintSharesTo(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function setReentrancy(bool onReport, bool onRedeem, address target, bytes calldata data) external {
        reentrantOnReport = onReport;
        reentrantOnRedeem = onRedeem;
        reentrantTarget = target;
        reentrantCalldata = data;
    }

    // ---- IReportable ----

    function report() external override returns (uint256 profit, uint256 loss) {
        if (revertOnReport) revert("report reverted");

        reportCallCount++;

        if (nextProfitShares > 0) {
            balanceOf[msg.sender] += nextProfitShares;
            profit = nextProfitShares;
            nextProfitShares = 0;
        }
        loss = nextLoss;
        nextLoss = 0;

        if (reentrantOnReport) {
            reentrantOnReport = false; // avoid infinite recursion
            (bool ok, ) = reentrantTarget.call(reentrantCalldata);
            require(ok, "reentrant-report-call-failed");
        }
    }

    // ---- IMaxRedeem ----

    function maxRedeem(address) external view override returns (uint256) {
        return maxRedeemAmount;
    }

    // ---- IConvertible ----

    function convertToAssets(uint256 shares) public view override returns (uint256) {
        if (rateDenominator == 0) return 0;
        return (shares * rateNumerator) / rateDenominator;
    }

    // ---- IRedeemable ----

    function redeem(uint256 shares, address receiver_, address owner, uint256 maxLoss)
        external
        override
        returns (uint256 assets)
    {
        lastMaxLoss = maxLoss;
        require(balanceOf[owner] >= shares, "insufficient shares");
        balanceOf[owner] -= shares;
        assets = convertToAssets(shares);
        asset.mint(receiver_, assets);

        if (reentrantOnRedeem) {
            reentrantOnRedeem = false; // avoid infinite recursion
            (bool ok, ) = reentrantTarget.call(reentrantCalldata);
            require(ok, "reentrant-redeem-call-failed");
        }
    }

    // ---- minimal ERC20-like transfer, so strategy "shares" can also be
    //      flushed through forwardToken() ----

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

/// @dev Malicious ERC20 whose `transfer` re-enters `forwardToken` to probe
