    }

    // ============================================================
    // forwardToken -- access control
    // ============================================================

    function test_ForwardToken_RevertsIfNotKeeper() public {
        asset.mint(address(forwarder), 10e18);

        vm.prank(stranger);
        vm.expectRevert(YieldForwarder.OnlyKeeper.selector);
        forwarder.forwardToken(address(asset));
    }

    // ============================================================
    // forwardToken -- happy paths
    // ============================================================

    function test_ForwardToken_HappyPath() public {
        asset.mint(address(forwarder), 250e18);

        vm.expectEmit(true, true, false, true, address(forwarder));
        emit TokenForwarded(address(asset), receiver, 250e18);

        vm.prank(keeper);
        forwarder.forwardToken(address(asset));

        assertEq(asset.balanceOf(receiver), 250e18);
        assertEq(asset.balanceOf(address(forwarder)), 0);
    }

    function test_ForwardToken_ZeroBalanceNoRevertNoEvent() public {
