        assertEq(strategy.balanceOf(receiver), 777e18);
        assertEq(strategy.balanceOf(address(forwarder)), 0);
    }

    // ============================================================
    // forwardToken -- reentrancy
    // ============================================================

    function test_ForwardToken_RevertsOnReentrancy() public {
        MaliciousReentrantToken evilToken = new MaliciousReentrantToken();
        evilToken.mint(address(forwarder), 100e18);
