// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import { Test, Vm } from "forge-std/Test.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import {
    YieldForwarder,
    IReportable,
    IRedeemable,
    IMaxRedeem,
    IConvertible
} from "src/core/YieldForwarder.sol";

// ============================================================
// MOCKS
// ============================================================

/// @dev Minimal mintable ERC20 used both as the "underlying asset" the
///      strategy pays out and as a generic airdrop-style token for
///      forwardToken() tests.
contract MockERC20 is ERC20 {
    constructor() ERC20("Mock Asset", "mAST") {}

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Configurable mock strategy implementing the four minimal interfaces
///      YieldForwarder depends on, plus a bare-bones `balanceOf`/`transfer`
///      pair so it can also stand in for the "strategy shares" ERC20 that
///      report() mints into the forwarder.
contract MockStrategy is IReportable, IRedeemable, IMaxRedeem, IConvertible {
    MockERC20 public immutable asset;

    mapping(address => uint256) public balanceOf;

    uint256 public rateNumerator = 1e18;
    uint256 public rateDenominator = 1e18;
    uint256 public maxRedeemAmount = type(uint256).max;
    uint256 public nextProfitShares;
    uint256 public nextLoss;
    uint256 public reportCallCount;
    uint256 public lastMaxLoss;
    bool public revertOnReport;

    bool public reentrantOnReport;
    bool public reentrantOnRedeem;
    address public reentrantTarget;
    bytes public reentrantCalldata;

    constructor(MockERC20 _asset) {
        asset = _asset;
    }

    // ---- test configuration helpers ----

    function setNextProfitShares(uint256 v) external {
        nextProfitShares = v;
    }

    function setNextLoss(uint256 v) external {
        nextLoss = v;
    }

    function setMaxRedeemAmount(uint256 v) external {
        maxRedeemAmount = v;
    }

    function setExchangeRate(uint256 num, uint256 den) external {
        rateNumerator = num;
        rateDenominator = den;
    }

    function setRevertOnReport(bool v) external {
        revertOnReport = v;
    }

    function mintSharesTo(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function setReentrancy(bool onReport, bool onRedeem, address target, bytes calldata data) external {
        reentrantOnReport = onReport;
        reentrantOnRedeem = onRedeem;
        reentrantTarget = target;
        reentrantCalldata = data;
    }

    // ---- IReportable ----

    function report() external override returns (uint256 profit, uint256 loss) {
        if (revertOnReport) revert("report reverted");

        reportCallCount++;

        if (nextProfitShares > 0) {
            balanceOf[msg.sender] += nextProfitShares;
            profit = nextProfitShares;
            nextProfitShares = 0;
        }
        loss = nextLoss;
        nextLoss = 0;

        if (reentrantOnReport) {
            reentrantOnReport = false; // avoid infinite recursion
            (bool ok, ) = reentrantTarget.call(reentrantCalldata);
            require(ok, "reentrant-report-call-failed");
        }
    }

    // ---- IMaxRedeem ----

    function maxRedeem(address) external view override returns (uint256) {
        return maxRedeemAmount;
    }

    // ---- IConvertible ----

    function convertToAssets(uint256 shares) public view override returns (uint256) {
        if (rateDenominator == 0) return 0;
        return (shares * rateNumerator) / rateDenominator;
    }

    // ---- IRedeemable ----

    function redeem(uint256 shares, address receiver_, address owner, uint256 maxLoss)
        external
        override
        returns (uint256 assets)
    {
        lastMaxLoss = maxLoss;
        require(balanceOf[owner] >= shares, "insufficient shares");
        balanceOf[owner] -= shares;
        assets = convertToAssets(shares);
        asset.mint(receiver_, assets);

        if (reentrantOnRedeem) {
            reentrantOnRedeem = false; // avoid infinite recursion
            (bool ok, ) = reentrantTarget.call(reentrantCalldata);
            require(ok, "reentrant-redeem-call-failed");
        }
    }

    // ---- minimal ERC20-like transfer, so strategy "shares" can also be
    //      flushed through forwardToken() ----

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

/// @dev Malicious ERC20 whose `transfer` re-enters `forwardToken` to probe
///      the nonReentrant guard.
contract MaliciousReentrantToken {
    mapping(address => uint256) public balanceOf;
    YieldForwarder public forwarder;
    bool public attack;

    function setForwarder(YieldForwarder _f) external {
        forwarder = _f;
    }

    function setAttack(bool v) external {
        attack = v;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;

        if (attack) {
            attack = false;
            forwarder.forwardToken(address(this));
        }
        return true;
    }
}

// ============================================================
// TESTS
// ============================================================

contract YieldForwarderTest is Test {
    YieldForwarder internal forwarder;
    MockERC20 internal asset;
    MockStrategy internal strategy;

    address internal receiver = makeAddr("receiver");
    address internal keeper = makeAddr("keeper");
    address internal stranger = makeAddr("stranger");

    // Re-declared locally so `vm.expectEmit` + `emit` work regardless of
    // which contract actually emits (topic0 is determined by signature).
    event YieldForwarded(address indexed strategy, address indexed receiver, uint256 shares, uint256 assets);
    event TokenForwarded(address indexed token, address indexed receiver, uint256 amount);

    function setUp() public {
        asset = new MockERC20();
        forwarder = new YieldForwarder(receiver, keeper);
        strategy = new MockStrategy(asset);
    }

    // ============================================================
    // Constructor
    // ============================================================

    function test_Constructor_SetsImmutables() public view {
        assertEq(forwarder.receiver(), receiver);
        assertEq(forwarder.keeper(), keeper);
    }

    function test_Constructor_RevertsOnZeroReceiver() public {
        vm.expectRevert(YieldForwarder.InvalidReceiver.selector);
        new YieldForwarder(address(0), keeper);
    }

    function test_Constructor_RevertsOnZeroKeeper() public {
        vm.expectRevert(YieldForwarder.InvalidKeeper.selector);
        new YieldForwarder(receiver, address(0));
    }

    // ============================================================
    // reportAndForward -- access control
    // ============================================================

    function test_ReportAndForward_RevertsIfNotKeeper() public {
        vm.prank(stranger);
        vm.expectRevert(YieldForwarder.OnlyKeeper.selector);
        forwarder.reportAndForward(address(strategy), 0);
    }

    // ============================================================
    // reportAndForward -- happy paths
    // ============================================================

    function test_ReportAndForward_NoProfitReturnsZeroButStillReports() public {
        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 0);
        assertEq(strategy.reportCallCount(), 1);
        assertEq(asset.balanceOf(receiver), 0);
    }

    function test_ReportAndForward_HappyPath() public {
        strategy.setNextProfitShares(1000e18);

        vm.expectEmit(true, true, false, true, address(forwarder));
        emit YieldForwarded(address(strategy), receiver, 1000e18, 1000e18);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 1000e18);
        assertEq(asset.balanceOf(receiver), 1000e18);
        assertEq(strategy.balanceOf(address(forwarder)), 0);
        assertEq(strategy.reportCallCount(), 1);
    }

    function test_ReportAndForward_PassesMaxLossThrough() public {
        strategy.setNextProfitShares(10e18);

        vm.prank(keeper);
        forwarder.reportAndForward(address(strategy), 250);

        assertEq(strategy.lastMaxLoss(), 250);
    }

    function test_ReportAndForward_BubblesRevertFromReport() public {
        strategy.setRevertOnReport(true);

        vm.prank(keeper);
        vm.expectRevert("report reverted");
        forwarder.reportAndForward(address(strategy), 0);
    }

    // ============================================================
    // reportAndForward -- maxRedeem cap behavior
    // ============================================================

    function test_ReportAndForward_CapsAtMaxRedeem() public {
        strategy.setNextProfitShares(1000e18);
        strategy.setMaxRedeemAmount(400e18);

        vm.expectEmit(true, true, false, true, address(forwarder));
        emit YieldForwarded(address(strategy), receiver, 400e18, 400e18);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 400e18);
        assertEq(asset.balanceOf(receiver), 400e18);
        assertEq(strategy.balanceOf(address(forwarder)), 600e18, "residual shares remain at forwarder");
    }

    function test_ReportAndForward_ResidualPickedUpOnLaterCall() public {
        strategy.setNextProfitShares(1000e18);
        strategy.setMaxRedeemAmount(400e18);

        vm.prank(keeper);
        forwarder.reportAndForward(address(strategy), 0);
        assertEq(strategy.balanceOf(address(forwarder)), 600e18);

        // Vault headroom recovers.
        strategy.setMaxRedeemAmount(type(uint256).max);

        vm.prank(keeper);
        uint256 assets2 = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets2, 600e18);
        assertEq(strategy.balanceOf(address(forwarder)), 0);
        assertEq(asset.balanceOf(receiver), 1000e18);
    }

    function test_ReportAndForward_ZeroMaxRedeemSkipsRedeemButKeepsReport() public {
        strategy.setNextProfitShares(500e18);
        strategy.setMaxRedeemAmount(0);

        vm.recordLogs();
        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        assertEq(assets, 0);
        assertEq(strategy.reportCallCount(), 1, "report() side effects still commit");
        assertEq(strategy.balanceOf(address(forwarder)), 500e18, "shares remain at forwarder");
        assertEq(asset.balanceOf(receiver), 0);
        assertEq(logs.length, 0, "no YieldForwarded event when redeem is skipped");
    }

    // ============================================================
    // reportAndForward -- convertToAssets == 0 (dust / loss-impaired)
    // ============================================================

    function test_ReportAndForward_ZeroConvertToAssetsSkipsRedeem() public {
        strategy.setNextProfitShares(3); // dust
        strategy.setExchangeRate(0, 1e18); // convertToAssets always floors to 0

        vm.recordLogs();
        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        assertEq(assets, 0);
        assertEq(strategy.reportCallCount(), 1);
        assertEq(strategy.balanceOf(address(forwarder)), 3, "dust shares remain");
        assertEq(asset.balanceOf(receiver), 0);
        assertEq(logs.length, 0);
    }

    // ============================================================
    // reportAndForward -- reentrancy
    // ============================================================

    function test_ReportAndForward_RevertsOnReentrancyViaReport() public {
        strategy.setNextProfitShares(100e18);
        bytes memory data = abi.encodeWithSelector(YieldForwarder.reportAndForward.selector, address(strategy), 0);
        strategy.setReentrancy(true, false, address(forwarder), data);

        vm.prank(keeper);
        vm.expectRevert();
        forwarder.reportAndForward(address(strategy), 0);
    }

    function test_ReportAndForward_RevertsOnReentrancyViaRedeem() public {
        strategy.setNextProfitShares(100e18);
        bytes memory data = abi.encodeWithSelector(YieldForwarder.reportAndForward.selector, address(strategy), 0);
        strategy.setReentrancy(false, true, address(forwarder), data);

        vm.prank(keeper);
        vm.expectRevert();
        forwarder.reportAndForward(address(strategy), 0);
    }

    // ============================================================
    // reportAndForward -- fuzz
    // ============================================================

    function testFuzz_ReportAndForward_CapsAtMaxRedeem(uint128 profitShares, uint128 maxRedeemCap) public {
        vm.assume(profitShares > 0);
        strategy.setNextProfitShares(profitShares);
        strategy.setMaxRedeemAmount(maxRedeemCap);

        uint256 expectedShares =
            uint256(profitShares) < uint256(maxRedeemCap) ? uint256(profitShares) : uint256(maxRedeemCap);

        vm.prank(keeper);
