        if (expectedShares == 0) {
            assertEq(assets, 0);
            assertEq(asset.balanceOf(receiver), 0);
        } else {
            assertEq(assets, expectedShares); // 1:1 exchange rate by default
            assertEq(asset.balanceOf(receiver), expectedShares);
        }
