contract YieldForwarderTest is Test {
    address internal keeper = makeAddr("keeper");
    address internal receiver = makeAddr("receiver");
    address internal stranger = makeAddr("stranger");

    YieldForwarder internal forwarder;
    MockERC20 internal asset;
    MockStrategy internal strategy;

    event YieldForwarded(address indexed strategy, address indexed receiver, uint256 shares, uint256 assets);
    event TokenForwarded(address indexed token, address indexed receiver, uint256 amount);

    function setUp() public {
        asset = new MockERC20();
        strategy = new MockStrategy(asset);
        forwarder = new YieldForwarder(receiver, keeper);
    }

    // ============================================
    // CONSTRUCTOR
    // ============================================

    function test_Constructor_SetsImmutables() public view {
        assertEq(forwarder.receiver(), receiver);
        assertEq(forwarder.keeper(), keeper);
    }

    function test_Constructor_RevertsOnZeroReceiver() public {
        vm.expectRevert(YieldForwarder.InvalidReceiver.selector);
        new YieldForwarder(address(0), keeper);
    }

    function test_Constructor_RevertsOnZeroKeeper() public {
        vm.expectRevert(YieldForwarder.InvalidKeeper.selector);
        new YieldForwarder(receiver, address(0));
    }

    // ============================================
    // reportAndForward
    // ============================================

    function test_ReportAndForward_RevertsIfNotKeeper() public {
        vm.prank(stranger);
        vm.expectRevert(YieldForwarder.OnlyKeeper.selector);
        forwarder.reportAndForward(address(strategy), 0);
    }

    function test_ReportAndForward_CallsReportRegardless() public {
        vm.prank(keeper);
        forwarder.reportAndForward(address(strategy), 0);
        assertEq(strategy.reportCallCount(), 1);
    }

    function test_ReportAndForward_ReturnsZeroWhenNoProfitShares() public {
        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);
        assertEq(assets, 0);
        assertEq(strategy.redeemCallCount(), 0);
    }

    function test_ReportAndForward_ReturnsZeroWhenMaxRedeemIsZero() public {
        strategy.setNextReportProfit(100 ether, address(forwarder));
        strategy.setMaxRedeemCap(0);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 0);
        assertEq(strategy.redeemCallCount(), 0);
        // report() still committed its side effects: profit shares were minted
        assertEq(strategy.balanceOf(address(forwarder)), 100 ether);
    }

    function test_ReportAndForward_SkipsRedeemWhenConvertToAssetsRoundsToZero() public {
        strategy.setNextReportProfit(5, address(forwarder));
        strategy.setForceConvertToAssetsZero(true);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 0);
        assertEq(strategy.redeemCallCount(), 0);
        // dust shares remain at the forwarder, not burned
        assertEq(strategy.balanceOf(address(forwarder)), 5);
    }

    function test_ReportAndForward_HappyPath_RedeemsAndForwardsAssets() public {
        strategy.setNextReportProfit(100 ether, address(forwarder));

        vm.expectEmit(true, true, false, true, address(forwarder));
        emit YieldForwarded(address(strategy), receiver, 100 ether, 100 ether);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 42);

        assertEq(assets, 100 ether);
        assertEq(strategy.redeemCallCount(), 1);
        assertEq(strategy.lastRedeemShares(), 100 ether);
        assertEq(strategy.lastRedeemReceiver(), receiver);
        assertEq(strategy.lastRedeemOwner(), address(forwarder));
        assertEq(strategy.lastRedeemMaxLoss(), 42);

        assertEq(strategy.balanceOf(address(forwarder)), 0);
        assertEq(asset.balanceOf(receiver), 100 ether);
    }

    function test_ReportAndForward_CapsSharesAtMaxRedeem_LeavesResidual() public {
        strategy.setNextReportProfit(100 ether, address(forwarder));
        strategy.setMaxRedeemCap(40 ether);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 40 ether);
        assertEq(strategy.lastRedeemShares(), 40 ether);
        // residual shares remain at the forwarder for a later call
        assertEq(strategy.balanceOf(address(forwarder)), 60 ether);
        assertEq(asset.balanceOf(receiver), 40 ether);
    }

    function test_ReportAndForward_RespectsConversionRatio() public {
        // 1 share == 0.5 asset
        strategy.setConversionRatio(1, 2);
        strategy.setNextReportProfit(100 ether, address(forwarder));

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 50 ether);
        assertEq(asset.balanceOf(receiver), 50 ether);
    }

    function test_ReportAndForward_PicksUpResidualSharesOnSubsequentCall() public {
        strategy.setNextReportProfit(100 ether, address(forwarder));
        strategy.setMaxRedeemCap(40 ether);

        vm.prank(keeper);
        forwarder.reportAndForward(address(strategy), 0);
        assertEq(strategy.balanceOf(address(forwarder)), 60 ether);

        // headroom recovers, no new profit this round
        strategy.setMaxRedeemCap(type(uint256).max);

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, 60 ether);
        assertEq(strategy.balanceOf(address(forwarder)), 0);
        assertEq(asset.balanceOf(receiver), 60 ether);
    }

    function testFuzz_ReportAndForward_CapsAtMaxRedeem(uint96 profitShares, uint96 cap) public {
        vm.assume(profitShares > 0);
        strategy.setNextReportProfit(profitShares, address(forwarder));
        strategy.setMaxRedeemCap(cap);

        uint256 expectedShares = profitShares < cap ? profitShares : cap;

        vm.prank(keeper);
        uint256 assets = forwarder.reportAndForward(address(strategy), 0);

        assertEq(assets, expectedShares);
        assertEq(strategy.balanceOf(address(forwarder)), profitShares - expectedShares);
    }

    function test_ReportAndForward_NonReentrant_ViaReportAndForward() public {
        ReentrantStrategy evilStrategy = new ReentrantStrategy(asset);
        evilStrategy.setForwarder(forwarder);
        evilStrategy.setNextReportProfit(10 ether, address(forwarder));
        evilStrategy.armReportAndForwardAttack(0);

        vm.prank(keeper);
        vm.expectRevert(ReentrancyGuard.ReentrancyGuardReentrantCall.selector);
        forwarder.reportAndForward(address(evilStrategy), 0);
    }

    function test_ReportAndForward_NonReentrant_ViaForwardToken() public {
        ReentrantStrategy evilStrategy = new ReentrantStrategy(asset);
        evilStrategy.setForwarder(forwarder);
        evilStrategy.setNextReportProfit(10 ether, address(forwarder));
        evilStrategy.armForwardTokenAttack();

        vm.prank(keeper);
        vm.expectRevert(ReentrancyGuard.ReentrancyGuardReentrantCall.selector);
        forwarder.reportAndForward(address(evilStrategy), 0);
    }

    // ============================================
    // forwardToken
    // ============================================

    function test_ForwardToken_RevertsIfNotKeeper() public {
        vm.prank(stranger);
        vm.expectRevert(YieldForwarder.OnlyKeeper.selector);
        forwarder.forwardToken(address(asset));
    }

    function test_ForwardToken_NoopWhenZeroBalance() public {
        vm.recordLogs();
        vm.prank(keeper);
        forwarder.forwardToken(address(asset));

        assertEq(vm.getRecordedLogs().length, 0);
        assertEq(asset.balanceOf(receiver), 0);
    }

    function test_ForwardToken_ForwardsFullBalance() public {
        asset.mint(address(forwarder), 7 ether);

        vm.expectEmit(true, true, false, true, address(forwarder));
        emit TokenForwarded(address(asset), receiver, 7 ether);

        vm.prank(keeper);
        forwarder.forwardToken(address(asset));

        assertEq(asset.balanceOf(receiver), 7 ether);
        assertEq(asset.balanceOf(address(forwarder)), 0);
    }

    function test_ForwardToken_CanForwardStrategyShareTokenItself() public {
        strategy.mintShares(address(forwarder), 3 ether);

        vm.prank(keeper);
        forwarder.forwardToken(address(strategy));

        assertEq(strategy.balanceOf(receiver), 3 ether);
        assertEq(strategy.balanceOf(address(forwarder)), 0);
    }

    function testFuzz_ForwardToken_ForwardsBalance(uint96 amount) public {
        vm.assume(amount > 0);
        asset.mint(address(forwarder), amount);

        vm.prank(keeper);
        forwarder.forwardToken(address(asset));

        assertEq(asset.balanceOf(receiver), amount);
        assertEq(asset.balanceOf(address(forwarder)), 0);
    }

    function test_ForwardToken_NonReentrant() public {
        MaliciousReentrantToken evilToken = new MaliciousReentrantToken();
        evilToken.setForwarder(forwarder);
        evilToken.mint(address(forwarder), 1 ether);
        evilToken.setAttack(true);

        vm.prank(keeper);
        vm.expectRevert(ReentrancyGuard.ReentrancyGuardReentrantCall.selector);
        forwarder.forwardToken(address(evilToken));
    }
}
