    uint256 public ratioDenominator = 1;
    bool public forceConvertToAssetsZero;

    uint256 public reportCallCount;

    uint256 public lastRedeemShares;
    address public lastRedeemReceiver;
    address public lastRedeemOwner;
    uint256 public lastRedeemMaxLoss;
    uint256 public redeemCallCount;

    constructor(MockERC20 _asset) {
        asset = _asset;
    }

    // ---------------- test configuration ----------------

    function setNextReportProfit(uint256 shares, address mintTo) external {
        profitToMint = shares;
        profitReceiver = mintTo;
    }

    function setMaxRedeemCap(uint256 cap) external {
        maxRedeemCap = cap;
    }

    function setConversionRatio(uint256 numerator, uint256 denominator) external {
        ratioNumerator = numerator;
        ratioDenominator = denominator;
    }

    function setForceConvertToAssetsZero(bool value) external {
        forceConvertToAssetsZero = value;
    }

    function mintShares(address to, uint256 amount) external {
        _mint(to, amount);
    }

    // ---------------- IReportable ----------------

    function report() external virtual override returns (uint256 profit, uint256 loss) {
        reportCallCount++;
        if (profitToMint > 0) {
            _mint(profitReceiver, profitToMint);
            profit = profitToMint;
            profitToMint = 0;
        }
        loss = 0;
    }

    // ---------------- IMaxRedeem ----------------

    function maxRedeem(address) external view override returns (uint256) {
        return maxRedeemCap;
    }

    // ---------------- IConvertible ----------------

    function convertToAssets(uint256 shares) public view override returns (uint256) {
        if (forceConvertToAssetsZero) return 0;
        return (shares * ratioNumerator) / ratioDenominator;
    }

    // ---------------- IRedeemable ----------------

    function redeem(uint256 shares, address to, address owner, uint256 maxLoss)
        external
        virtual
        override
        returns (uint256 assets)
    {
        redeemCallCount++;
        require(balanceOf[owner] >= shares, "insufficient shares");
        _burn(owner, shares);
        assets = convertToAssets(shares);
        if (assets > 0) {
            asset.mint(to, assets);
        }
        lastRedeemShares = shares;
        lastRedeemReceiver = to;
        lastRedeemOwner = owner;
        lastRedeemMaxLoss = maxLoss;
    }

    // ---------------- IERC20 ----------------

    function transfer(address to, uint256 amount) external override returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external override returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external override returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            require(allowed >= amount, "insufficient allowance");
            allowance[from][msg.sender] = allowed - amount;
        }
        _transfer(from, to, amount);
        return true;
    }

    function _mint(address to, uint256 amount) internal {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function _burn(address from, uint256 amount) internal {
        balanceOf[from] -= amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(balanceOf[from] >= amount, "insufficient balance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
    }
}

