/// @dev Helper used to force-send ETH into the factory, which has no receive/fallback function.
contract Forcer {
    constructor() payable { }

    function destroy(address payable target) external {
        selfdestruct(target);
    }
}

/// @dev Helper that always reverts on receiving ETH, used to test sweep failure path.
contract RejectingReceiver {
    receive() external payable {
        revert("nope");
    }
