// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { PaymentSplitterFactory } from "src/factories/PaymentSplitterFactory.sol";
import { PaymentSplitter } from "src/core/PaymentSplitter.sol";

/// @dev Helper used to force-send ETH into the factory, which has no receive/fallback function.
contract Forcer {
    constructor() payable { }

    function destroy(address payable target) external {
        selfdestruct(target);
    }
}

/// @dev Helper that always reverts on receiving ETH, used to test sweep failure path.
contract RejectingReceiver {
    receive() external payable {
        revert("nope");
    }
}

contract PaymentSplitterFactoryTest is Test {
    PaymentSplitterFactory internal factory;

    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");
    address internal carol = makeAddr("carol");
    address internal deployer1 = makeAddr("deployer1");
    address internal deployer2 = makeAddr("deployer2");

    event PaymentSplitterCreated(
        address indexed deployer,
        address indexed paymentSplitter,
        address[] payees,
        string[] payeeNames,
        uint256[] shares
    );

    event PaymentSplitterCreatedWithSalt(
        address indexed deployer,
        address indexed paymentSplitter,
        bytes32 indexed salt,
        address[] payees,
        string[] payeeNames,
        uint256[] shares
    );

    function setUp() public {
        factory = new PaymentSplitterFactory();
    }

    // ============================================
    // HELPERS
    // ============================================

    function _defaultPayees() internal view returns (address[] memory payees) {
        payees = new address[](3);
        payees[0] = alice;
        payees[1] = bob;
        payees[2] = carol;
    }

    function _defaultNames() internal pure returns (string[] memory names) {
        names = new string[](3);
        names[0] = "GrantRoundOperator";
        names[1] = "ESF";
        names[2] = "OpEx";
    }

    function _defaultShares() internal pure returns (uint256[] memory shares) {
        shares = new uint256[](3);
        shares[0] = 50;
        shares[1] = 30;
        shares[2] = 20;
    }

    // ============================================
    // CONSTRUCTOR
    // ============================================

    function test_constructor_setsImplementationAndOwner() public {
        assertEq(factory.owner(), address(this));
        assertTrue(factory.implementation() != address(0));
        assertTrue(factory.implementation().code.length > 0);
    }

    // ============================================
    // createPaymentSplitter
    // ============================================

    function test_createPaymentSplitter_deploysProxyAtPredictedAddress() public {
        address predicted = factory.predictDeterministicAddress(address(this));
        address splitter = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());

        assertEq(splitter, predicted);
        assertTrue(splitter.code.length > 0);
    }

    function test_createPaymentSplitter_initializesSharesCorrectly() public {
        address splitterAddr = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());
        PaymentSplitter splitter = PaymentSplitter(payable(splitterAddr));

        assertEq(splitter.totalShares(), 100);
        assertEq(splitter.shares(alice), 50);
        assertEq(splitter.shares(bob), 30);
        assertEq(splitter.shares(carol), 20);
        assertEq(splitter.payee(0), alice);
        assertEq(splitter.payee(1), bob);
        assertEq(splitter.payee(2), carol);
    }

    function test_createPaymentSplitter_singlePayeeFullShares() public {
        address[] memory payees = new address[](1);
        payees[0] = alice;
        string[] memory names = new string[](1);
        names[0] = "Solo";
        uint256[] memory sharesArr = new uint256[](1);
        sharesArr[0] = 1;

        address splitterAddr = factory.createPaymentSplitter(payees, names, sharesArr);
        PaymentSplitter splitter = PaymentSplitter(payable(splitterAddr));
        assertEq(splitter.totalShares(), 1);
        assertEq(splitter.shares(alice), 1);
    }

    function test_createPaymentSplitter_storesSplitterInfo() public {
        address splitterAddr = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());

        PaymentSplitterFactory.SplitterInfo[] memory infos = factory.getSplittersByDeployer(address(this));
        assertEq(infos.length, 1);
        assertEq(infos[0].splitterAddress, splitterAddr);
        assertEq(infos[0].payees.length, 3);
        assertEq(infos[0].payees[0], alice);
        assertEq(infos[0].payeeNames[0], "GrantRoundOperator");
        assertEq(infos[0].payeeNames[2], "OpEx");
    }

    function test_createPaymentSplitter_emitsEvent() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();

        address predicted = factory.predictDeterministicAddress(address(this));

        vm.expectEmit(true, true, false, true, address(factory));
        emit PaymentSplitterCreated(address(this), predicted, payees, names, sharesArr);
        factory.createPaymentSplitter(payees, names, sharesArr);
    }

    function test_createPaymentSplitter_revertsOnPayeeNameLengthMismatch() public {
        string[] memory names = new string[](2);
        names[0] = "A";
        names[1] = "B";

        vm.expectRevert(bytes("PaymentSplitterFactory: length mismatch"));
        factory.createPaymentSplitter(_defaultPayees(), names, _defaultShares());
    }

    function test_createPaymentSplitter_revertsOnSharesLengthMismatch() public {
        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 50;

        vm.expectRevert(bytes("PaymentSplitterFactory: length mismatch"));
        factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), sharesArr);
    }

    function test_createPaymentSplitter_revertsOnEmptyArrays() public {
        address[] memory payees = new address[](0);
        string[] memory names = new string[](0);
        uint256[] memory sharesArr = new uint256[](0);

        vm.expectRevert(bytes("PaymentSplitterFactory: initialization failed"));
        factory.createPaymentSplitter(payees, names, sharesArr);
    }

    function test_createPaymentSplitter_revertsOnDuplicatePayee() public {
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = alice;
        string[] memory names = new string[](2);
        names[0] = "A";
        names[1] = "B";
        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 50;

        vm.expectRevert(bytes("PaymentSplitterFactory: initialization failed"));
        factory.createPaymentSplitter(payees, names, sharesArr);
    }

    function test_createPaymentSplitter_revertsOnZeroSharesForPayee() public {
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;
        string[] memory names = new string[](2);
        names[0] = "A";
        names[1] = "B";
        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 0;

        vm.expectRevert(bytes("PaymentSplitterFactory: initialization failed"));
        factory.createPaymentSplitter(payees, names, sharesArr);
    }

    function test_createPaymentSplitter_revertsOnZeroAddressPayee() public {
        address[] memory payees = new address[](2);
        payees[0] = address(0);
        payees[1] = bob;
        string[] memory names = new string[](2);
        names[0] = "A";
        names[1] = "B";
        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 50;

        vm.expectRevert(bytes("PaymentSplitterFactory: initialization failed"));
        factory.createPaymentSplitter(payees, names, sharesArr);
    }

    function test_createPaymentSplitter_secondDeploymentUsesNewSalt() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();

        address first = factory.createPaymentSplitter(payees, names, sharesArr);
        address second = factory.createPaymentSplitter(payees, names, sharesArr);

        assertTrue(first != second);

        PaymentSplitterFactory.SplitterInfo[] memory infos = factory.getSplittersByDeployer(address(this));
        assertEq(infos.length, 2);
        assertEq(infos[0].splitterAddress, first);
        assertEq(infos[1].splitterAddress, second);
    }

    function test_createPaymentSplitter_differentDeployersIndependentNonces() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();

        vm.prank(deployer1);
        address splitter1 = factory.createPaymentSplitter(payees, names, sharesArr);

        vm.prank(deployer2);
        address splitter2 = factory.createPaymentSplitter(payees, names, sharesArr);

        assertTrue(splitter1 != splitter2);
        assertEq(factory.getSplittersByDeployer(deployer1).length, 1);
        assertEq(factory.getSplittersByDeployer(deployer2).length, 1);
    }

    function test_getSplittersByDeployer_emptyForUnknownDeployer() public {
        PaymentSplitterFactory.SplitterInfo[] memory infos = factory.getSplittersByDeployer(deployer1);
        assertEq(infos.length, 0);
    }

    // ============================================
    // predictDeterministicAddress
    // ============================================

    function test_predictDeterministicAddress_matchesActualDeploymentAndAdvances() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();

        address predicted = factory.predictDeterministicAddress(address(this));
        address actual = factory.createPaymentSplitter(payees, names, sharesArr);
        assertEq(predicted, actual);

        address predictedNext = factory.predictDeterministicAddress(address(this));
        assertTrue(predictedNext != actual);
    }

    // ============================================
    // createPaymentSplitterWithETH
    // ============================================

    function test_createPaymentSplitterWithETH_forwardsValue() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();

        uint256 value = 5 ether;
        vm.deal(address(this), value);
        address splitter = factory.createPaymentSplitterWithETH{ value: value }(payees, names, sharesArr);

        assertEq(splitter.balance, value);
        assertEq(address(factory).balance, 0);
    }

    function test_createPaymentSplitterWithETH_zeroValueWorks() public {
        address splitter =
            factory.createPaymentSplitterWithETH(_defaultPayees(), _defaultNames(), _defaultShares());
        assertEq(splitter.balance, 0);
    }

    function test_createPaymentSplitterWithETH_revertsOnLengthMismatch() public {
        string[] memory names = new string[](1);
        names[0] = "A";

        vm.expectRevert(bytes("PaymentSplitterFactory: length mismatch"));
        factory.createPaymentSplitterWithETH(_defaultPayees(), names, _defaultShares());
    }

    function test_createPaymentSplitterWithETH_releaseWorksProportionally() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares(); // 50/30/20

        uint256 value = 100 ether;
        vm.deal(address(this), value);
        address splitterAddr = factory.createPaymentSplitterWithETH{ value: value }(payees, names, sharesArr);
        PaymentSplitter splitter = PaymentSplitter(payable(splitterAddr));

        uint256 aliceBalBefore = alice.balance;
        splitter.release(payable(alice));
        assertEq(alice.balance - aliceBalBefore, 50 ether);

        uint256 bobBalBefore = bob.balance;
        splitter.release(payable(bob));
        assertEq(bob.balance - bobBalBefore, 30 ether);

        uint256 carolBalBefore = carol.balance;
        splitter.release(payable(carol));
        assertEq(carol.balance - carolBalBefore, 20 ether);
    }

    // ============================================
    // sweep
    // ============================================

    function test_sweep_revertsForNonOwner() public {
        vm.prank(alice);
        vm.expectRevert(bytes("PaymentSplitterFactory: not owner"));
        factory.sweep(payable(alice));
    }

