        assertEq(address(factory).balance, 0);
    }

    function test_sweep_revertsIfRecipientRejectsETH() public {
        Forcer forcer = new Forcer{ value: 1 ether }();
        forcer.destroy(payable(address(factory)));

        RejectingReceiver rejecter = new RejectingReceiver();
