        factory.sweep(payable(address(rejecter)));
    }

    // ============================================
    // createPaymentSplitterWithSalt
    // ============================================

    function test_createPaymentSplitterWithSalt_deploysAtPredictedAddress() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
