        bytes32 salt = keccak256("proposal-1");

        address predicted = factory.predictDeterministicAddressWithSalt(address(this), payees, sharesArr, salt);
        address actual = factory.createPaymentSplitterWithSalt(payees, names, sharesArr, salt);

        assertEq(predicted, actual);
        assertTrue(actual.code.length > 0);
    }

    function test_createPaymentSplitterWithSalt_emitsEventWithSalt() public {
