        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();
        bytes32 salt = keccak256("proposal-2");

        address predicted = factory.predictDeterministicAddressWithSalt(address(this), payees, sharesArr, salt);

        vm.expectEmit(true, true, true, true, address(factory));
        emit PaymentSplitterCreatedWithSalt(address(this), predicted, salt, payees, names, sharesArr);
        factory.createPaymentSplitterWithSalt(payees, names, sharesArr, salt);
    }

    function test_createPaymentSplitterWithSalt_revertsOnReuse() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();
        bytes32 salt = keccak256("proposal-3");

        factory.createPaymentSplitterWithSalt(payees, names, sharesArr, salt);

        vm.expectRevert();
        factory.createPaymentSplitterWithSalt(payees, names, sharesArr, salt);
    }

    function test_createPaymentSplitterWithSalt_differentSaltsProduceDifferentAddresses() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();

        address a = factory.createPaymentSplitterWithSalt(payees, names, sharesArr, keccak256("s1"));
        address b = factory.createPaymentSplitterWithSalt(payees, names, sharesArr, keccak256("s2"));
        assertTrue(a != b);
    }

    function test_createPaymentSplitterWithSalt_revertsOnLengthMismatch() public {
        string[] memory names = new string[](1);
        names[0] = "A";

        vm.expectRevert(bytes("PaymentSplitterFactory: length mismatch"));
        factory.createPaymentSplitterWithSalt(_defaultPayees(), names, _defaultShares(), keccak256("s"));
    }

    function test_createPaymentSplitterWithSalt_advancesSequentialNonceCounterToo() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();

        address predictedSequential = factory.predictDeterministicAddress(address(this));
        factory.createPaymentSplitterWithSalt(payees, names, sharesArr, keccak256("salted"));

        // Salt-based deployment still appends to deployerToSplitters, shifting sequential prediction.
        address newPredictedSequential = factory.predictDeterministicAddress(address(this));
        assertTrue(newPredictedSequential != predictedSequential);

        address actualSequential = factory.createPaymentSplitter(payees, names, sharesArr);
        assertEq(actualSequential, newPredictedSequential);
    }

    // ============================================
    // createPaymentSplitterWithETHAndSalt
    // ============================================

    function test_createPaymentSplitterWithETHAndSalt_forwardsValueAndMatchesPrediction() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();
        bytes32 salt = keccak256("eth-salt");

        address predicted = factory.predictDeterministicAddressWithSalt(address(this), payees, sharesArr, salt);

        uint256 value = 2 ether;
        vm.deal(address(this), value);
        address actual = factory.createPaymentSplitterWithETHAndSalt{ value: value }(payees, names, sharesArr, salt);

        assertEq(actual, predicted);
        assertEq(actual.balance, value);
    }

    function test_createPaymentSplitterWithETHAndSalt_revertsOnLengthMismatch() public {
        uint256[] memory sharesArr = new uint256[](1);
        sharesArr[0] = 100;

        vm.expectRevert(bytes("PaymentSplitterFactory: length mismatch"));
        factory.createPaymentSplitterWithETHAndSalt(_defaultPayees(), _defaultNames(), sharesArr, keccak256("s"));
    }

    // ============================================
    // predictDeterministicAddressWithSalt
    // ============================================

    function test_predictDeterministicAddressWithSalt_variesWithDeployerSaltAndShares() public {
        address[] memory payees = _defaultPayees();
        uint256[] memory sharesArr = _defaultShares();
        bytes32 salt = keccak256("vary");

        address p1 = factory.predictDeterministicAddressWithSalt(address(this), payees, sharesArr, salt);
        address p2 = factory.predictDeterministicAddressWithSalt(deployer1, payees, sharesArr, salt);
        assertTrue(p1 != p2);

        address p3 = factory.predictDeterministicAddressWithSalt(address(this), payees, sharesArr, keccak256("vary2"));
        assertTrue(p1 != p3);

        uint256[] memory sharesArr2 = new uint256[](3);
        sharesArr2[0] = 1;
        sharesArr2[1] = 1;
        sharesArr2[2] = 1;
        address p4 = factory.predictDeterministicAddressWithSalt(address(this), payees, sharesArr2, salt);
        assertTrue(p1 != p4);
    }

    // ============================================
    // Clone initialization guard
    // ============================================

    function test_clone_cannotBeInitializedTwice() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory sharesArr = _defaultShares();

