// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { PaymentSplitterFactory } from "src/factories/PaymentSplitterFactory.sol";
import { PaymentSplitter } from "src/core/PaymentSplitter.sol";
import { Clones } from "@openzeppelin/contracts/proxy/Clones.sol";

/// @dev Helper contract that cannot receive plain ETH transfers (no receive/fallback).
contract RejectEther {
    function callSweep(PaymentSplitterFactory factory, address payable recipient) external {
        factory.sweep(recipient);
    }
}

contract PaymentSplitterFactoryTest is Test {
    PaymentSplitterFactory internal factory;

    address internal payee1;
    address internal payee2;
    address internal payee3;

    event PaymentSplitterCreated(
        address indexed deployer,
        address indexed paymentSplitter,
        address[] payees,
        string[] payeeNames,
        uint256[] shares
    );

    event PaymentSplitterCreatedWithSalt(
        address indexed deployer,
        address indexed paymentSplitter,
        bytes32 indexed salt,
        address[] payees,
        string[] payeeNames,
        uint256[] shares
    );

    // Allow this test contract to receive swept ETH.
    receive() external payable {}

    function setUp() public {
        factory = new PaymentSplitterFactory();

        payee1 = makeAddr("payee1");
        payee2 = makeAddr("payee2");
        payee3 = makeAddr("payee3");
    }

    // ============================================
    // HELPERS
    // ============================================

    function _defaultPayees() internal view returns (address[] memory) {
        address[] memory payees = new address[](3);
        payees[0] = payee1;
        payees[1] = payee2;
        payees[2] = payee3;
        return payees;
    }

    function _defaultNames() internal pure returns (string[] memory) {
        string[] memory names = new string[](3);
        names[0] = "GrantRoundOperator";
        names[1] = "ESF";
        names[2] = "OpEx";
        return names;
    }

    function _defaultShares() internal pure returns (uint256[] memory) {
        uint256[] memory shares = new uint256[](3);
        shares[0] = 50;
        shares[1] = 30;
        shares[2] = 20;
        return shares;
    }

    // ============================================
    // CONSTRUCTOR / IMMUTABLES
    // ============================================

    function test_ConstructorSetsOwner() public view {
        assertEq(factory.owner(), address(this));
    }

    function test_ConstructorDeploysImplementation() public view {
        assertTrue(factory.implementation() != address(0));
        assertTrue(factory.implementation().code.length > 0);
    }

    function test_DifferentFactoriesHaveDifferentImplementations() public {
        PaymentSplitterFactory other = new PaymentSplitterFactory();
        assertTrue(other.implementation() != factory.implementation());
    }

    // ============================================
    // createPaymentSplitter
    // ============================================

    function test_CreatePaymentSplitter_DeploysCloneWithCode() public {
        address splitter = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());
        assertTrue(splitter != address(0));
        assertTrue(splitter.code.length > 0);
    }

    function test_CreatePaymentSplitter_InitializesCorrectly() public {
        address splitter = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());

        PaymentSplitter ps = PaymentSplitter(payable(splitter));
        assertEq(ps.totalShares(), 100);
        assertEq(ps.shares(payee1), 50);
        assertEq(ps.shares(payee2), 30);
        assertEq(ps.shares(payee3), 20);
    }

    function test_CreatePaymentSplitter_RevertsOnPayeesNamesLengthMismatch() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = new string[](2);
        names[0] = "A";
        names[1] = "B";
        uint256[] memory shares = _defaultShares();

        vm.expectRevert(bytes("PaymentSplitterFactory: length mismatch"));
        factory.createPaymentSplitter(payees, names, shares);
    }

    function test_CreatePaymentSplitter_RevertsOnPayeesSharesLengthMismatch() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory shares = new uint256[](2);
        shares[0] = 1;
        shares[1] = 1;

        vm.expectRevert(bytes("PaymentSplitterFactory: length mismatch"));
        factory.createPaymentSplitter(payees, names, shares);
    }

    function test_CreatePaymentSplitter_EmitsEvent() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = _defaultNames();
        uint256[] memory shares = _defaultShares();

        address predicted = factory.predictDeterministicAddress(address(this));

        vm.expectEmit(true, true, false, true, address(factory));
        emit PaymentSplitterCreated(address(this), predicted, payees, names, shares);

        factory.createPaymentSplitter(payees, names, shares);
