    function test_CreatePaymentSplitter_MatchesPrediction() public {
        address predicted = factory.predictDeterministicAddress(address(this));
        address actual = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());
        assertEq(actual, predicted);
    }

    function test_CreatePaymentSplitter_TracksSplitterInfo() public {
