        assertEq(infos.length, 1);
        assertEq(infos[0].splitterAddress, splitter);
        assertEq(infos[0].payees.length, payees.length);
        for (uint256 i = 0; i < payees.length; i++) {
            assertEq(infos[0].payees[i], payees[i]);
            assertEq(infos[0].payeeNames[i], names[i]);
        }
    }

    function test_CreatePaymentSplitter_PublicMappingGetterReturnsAddress() public {
        address splitter = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());
        address stored = factory.deployerToSplitters(address(this), 0);
        assertEq(stored, splitter);
    }

    function test_CreatePaymentSplitter_MultipleDeploymentsProduceUniqueAddresses() public {
        address first = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());
        address second = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());

        assertTrue(first != second);

        PaymentSplitterFactory.SplitterInfo[] memory infos = factory.getSplittersByDeployer(address(this));
        assertEq(infos.length, 2);
        assertEq(infos[0].splitterAddress, first);
        assertEq(infos[1].splitterAddress, second);
    }

    function test_CreatePaymentSplitter_DifferentDeployersGetDifferentAddresses() public {
        address deployerA = makeAddr("deployerA");
        address deployerB = makeAddr("deployerB");

        vm.prank(deployerA);
        address splitterA = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());

        vm.prank(deployerB);
        address splitterB = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());

        assertTrue(splitterA != splitterB);
    }

    function testFuzz_PredictDeterministicAddress_MatchesActualDeployment(address deployer) public {
        vm.assume(deployer != address(0));
        vm.assume(deployer.code.length == 0);

        address predicted = factory.predictDeterministicAddress(deployer);

        vm.prank(deployer);
        address actual = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());

        assertEq(actual, predicted);
    }

    // ============================================
    // createPaymentSplitterWithETH
    // ============================================

    function test_CreatePaymentSplitterWithETH_ForwardsValueToClone() public {
        uint256 value = 1 ether;
        address splitter = factory.createPaymentSplitterWithETH{ value: value }(
            _defaultPayees(),
            _defaultNames(),
            _defaultShares()
        );
        assertEq(splitter.balance, value);
        assertEq(address(factory).balance, 0);
    }

    function test_CreatePaymentSplitterWithETH_ZeroValueWorks() public {
        address splitter = factory.createPaymentSplitterWithETH(_defaultPayees(), _defaultNames(), _defaultShares());
        assertEq(splitter.balance, 0);
    }

    function test_CreatePaymentSplitterWithETH_RevertsOnLengthMismatch() public {
        address[] memory payees = _defaultPayees();
        string[] memory names = new string[](1);
        names[0] = "A";
        uint256[] memory shares = _defaultShares();

        vm.expectRevert(bytes("PaymentSplitterFactory: length mismatch"));
        factory.createPaymentSplitterWithETH{ value: 1 ether }(payees, names, shares);
    }

    function test_CreatePaymentSplitterWithETH_InitializesCorrectly() public {
        address splitter = factory.createPaymentSplitterWithETH{ value: 1 ether }(
            _defaultPayees(),
            _defaultNames(),
            _defaultShares()
        );
        PaymentSplitter ps = PaymentSplitter(payable(splitter));
        assertEq(ps.totalShares(), 100);
    }

    // ============================================
    // sweep
    // ============================================

    function test_Sweep_OnlyOwnerCanCall() public {
        vm.deal(address(factory), 1 ether);

        vm.prank(makeAddr("notOwner"));
        vm.expectRevert(bytes("PaymentSplitterFactory: not owner"));
        factory.sweep(payable(address(this)));
    }

    function test_Sweep_RevertsWhenNoBalance() public {
        vm.expectRevert(bytes("PaymentSplitterFactory: no ETH to sweep"));
        factory.sweep(payable(address(this)));
    }

    function test_Sweep_TransfersFullBalanceToRecipient() public {
        vm.deal(address(factory), 3 ether);
        address recipient = makeAddr("recipient");

        factory.sweep(payable(recipient));

        assertEq(address(factory).balance, 0);
        assertEq(recipient.balance, 3 ether);
    }

    function test_Sweep_RevertsWhenTransferFails() public {
        RejectEther rejecter = new RejectEther();
        vm.prank(address(rejecter));
        PaymentSplitterFactory f2 = new PaymentSplitterFactory();

        assertEq(f2.owner(), address(rejecter));

        vm.deal(address(f2), 1 ether);

        vm.expectRevert(bytes("PaymentSplitterFactory: sweep failed"));
        rejecter.callSweep(f2, payable(address(rejecter)));
    }

    // ============================================
    // getSplittersByDeployer
    // ============================================

    function test_GetSplittersByDeployer_EmptyForNewDeployer() public view {
        PaymentSplitterFactory.SplitterInfo[] memory infos = factory.getSplittersByDeployer(makeAddr("fresh"));
        assertEq(infos.length, 0);
    }

    // ============================================
    // createPaymentSplitterWithSalt
    // ============================================

    function test_CreatePaymentSplitterWithSalt_DeploysAndMatchesPrediction() public {
        bytes32 salt = keccak256("my-governance-salt");
