        address predicted = factory.predictDeterministicAddressWithSalt(address(this), payees, shares, salt);
        address actual = factory.createPaymentSplitterWithSalt(payees, _defaultNames(), shares, salt);

        assertEq(actual, predicted);
        assertTrue(actual.code.length > 0);
    }

    function test_CreatePaymentSplitterWithSalt_EmitsEventWithSalt() public {
