    // getSplittersByDeployer
    // ============================================

    function test_GetSplittersByDeployer_EmptyForNewDeployer() public view {
        PaymentSplitterFactory.SplitterInfo[] memory infos = factory.getSplittersByDeployer(deployer);
        assertEq(infos.length, 0);
    }

    function test_GetSplittersByDeployer_AccumulatesMultipleDeployments() public {
        vm.startPrank(deployer);
        factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());
        factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());
        factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());
        vm.stopPrank();

        assertEq(factory.getSplittersByDeployer(deployer).length, 3);
    }

    // ============================================
    // FUZZ
    // ============================================

    function testFuzz_CreatePaymentSplitter_VariablePayeeCount(uint8 count, uint96 seed) public {
        count = uint8(bound(count, 1, 10));

        address[] memory payees = new address[](count);
        string[] memory names = new string[](count);
        uint256[] memory shares = new uint256[](count);

        for (uint256 i = 0; i < count; i++) {
            payees[i] = address(uint160(uint256(keccak256(abi.encode(seed, i))) | 1));
            names[i] = "Payee";
            shares[i] = 1 + (uint256(seed) % 100) + i;
        }

        vm.prank(deployer);
        address splitter = factory.createPaymentSplitter(payees, names, shares);

        assertTrue(_hasCode(splitter));
        assertEq(factory.getSplittersByDeployer(deployer)[0].payees.length, count);
    }
}

contract RejectingReceiver {
    receive() external payable {
        revert("nope");
    }
}
