// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { PaymentSplitterFactory } from "src/factories/PaymentSplitterFactory.sol";

contract PaymentSplitterFactoryTest is Test {
    PaymentSplitterFactory internal factory;

    address internal deployer = makeAddr("deployer");
    address internal otherDeployer = makeAddr("otherDeployer");

    address internal payee1 = makeAddr("payee1");
    address internal payee2 = makeAddr("payee2");
    address internal payee3 = makeAddr("payee3");

    // Mirrors the events declared in PaymentSplitterFactory for vm.expectEmit checks
    event PaymentSplitterCreated(
        address indexed deployer,
        address indexed paymentSplitter,
        address[] payees,
        string[] payeeNames,
        uint256[] shares
    );

    event PaymentSplitterCreatedWithSalt(
        address indexed deployer,
        address indexed paymentSplitter,
        bytes32 indexed salt,
        address[] payees,
        string[] payeeNames,
        uint256[] shares
    );

    function setUp() public {
        factory = new PaymentSplitterFactory();
    }

    // ============================================
    // HELPERS
    // ============================================

    function _defaultPayees() internal view returns (address[] memory payees) {
        payees = new address[](3);
        payees[0] = payee1;
        payees[1] = payee2;
        payees[2] = payee3;
    }

    function _defaultNames() internal pure returns (string[] memory names) {
        names = new string[](3);
        names[0] = "GrantRoundOperator";
        names[1] = "ESF";
        names[2] = "OpEx";
    }

    function _defaultShares() internal pure returns (uint256[] memory shares) {
        shares = new uint256[](3);
        shares[0] = 50;
        shares[1] = 30;
        shares[2] = 20;
    }

    function _hasCode(address account) internal view returns (bool) {
        return account.code.length > 0;
    }

    // ============================================
    // CONSTRUCTOR / IMMUTABLES
    // ============================================

    function test_Constructor_SetsOwnerToDeployer() public {
        vm.prank(deployer);
        PaymentSplitterFactory f = new PaymentSplitterFactory();
        assertEq(f.owner(), deployer);
    }

    function test_Constructor_DeploysImplementationWithCode() public view {
        assertTrue(_hasCode(factory.implementation()));
    }

    function test_Constructor_ImplementationIsUniquePerFactory() public {
        PaymentSplitterFactory f2 = new PaymentSplitterFactory();
        assertTrue(factory.implementation() != f2.implementation());
    }

    // ============================================
    // createPaymentSplitter
    // ============================================

    function test_CreatePaymentSplitter_DeploysCloneWithCode() public {
        vm.prank(deployer);
