        assertTrue(splitter != address(0));
        assertTrue(_hasCode(splitter));
        assertTrue(splitter != factory.implementation());
    }

    function test_CreatePaymentSplitter_EmitsEvent() public {
        address predicted = factory.predictDeterministicAddress(deployer);

        vm.expectEmit(true, true, false, true, address(factory));
        emit PaymentSplitterCreated(deployer, predicted, _defaultPayees(), _defaultNames(), _defaultShares());

        vm.prank(deployer);
        factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());
    }

    function test_CreatePaymentSplitter_StoresSplitterInfo() public {
        vm.prank(deployer);
        address splitter = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());

        PaymentSplitterFactory.SplitterInfo[] memory infos = factory.getSplittersByDeployer(deployer);
        assertEq(infos.length, 1);
        assertEq(infos[0].splitterAddress, splitter);
        assertEq(infos[0].payees.length, 3);
        assertEq(infos[0].payees[0], payee1);
        assertEq(infos[0].payees[1], payee2);
        assertEq(infos[0].payees[2], payee3);
        assertEq(infos[0].payeeNames[0], "GrantRoundOperator");
        assertEq(infos[0].payeeNames[1], "ESF");
        assertEq(infos[0].payeeNames[2], "OpEx");
    }

    function test_CreatePaymentSplitter_PublicMappingGetterReturnsAddress() public {
        vm.prank(deployer);
        address splitter = factory.createPaymentSplitter(_defaultPayees(), _defaultNames(), _defaultShares());

