    // ============================================
    // CONSTRUCTOR
    // ============================================

    /**
     * @notice Constructor disables direct initialization
     * @dev Prevents using this contract directly - must be used via proxy pattern
     *      Disables initializers so only proxy instances can be initialized
     */
