            splitter.release(token, bob);
        }
    }

    function testFuzz_totalReleasedNeverExceedsTotalReceived(uint96 amount1, uint96 amount2) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        _initDefault();

        vm.deal(address(this), uint256(amount1));
        (bool s1,) = address(splitter).call{ value: amount1 }("");
        assertTrue(s1);

        if (splitter.releasable(alice) > 0) splitter.release(payable(alice));
        if (splitter.releasable(bob) > 0) splitter.release(payable(bob));
        if (splitter.releasable(charlie) > 0) splitter.release(payable(charlie));

        vm.deal(address(this), uint256(amount2));
        (bool s2,) = address(splitter).call{ value: amount2 }("");
        assertTrue(s2);

        if (splitter.releasable(alice) > 0) splitter.release(payable(alice));
        if (splitter.releasable(bob) > 0) splitter.release(payable(bob));
        if (splitter.releasable(charlie) > 0) splitter.release(payable(charlie));

        assertLe(splitter.totalReleased(), uint256(amount1) + uint256(amount2));
    }
}
