// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { PaymentSplitter } from "src/core/PaymentSplitter.sol";
import { Clones } from "@openzeppelin/contracts/proxy/Clones.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/// @dev Minimal mintable ERC20 for testing token distribution
contract ERC20Mock is ERC20 {
    constructor() ERC20("Mock Token", "MOCK") { }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev A contract that always reverts on receiving ETH, used to test sendValue failure paths
contract RevertingReceiver {
// no receive/fallback -> ETH transfers to this contract revert
}

/// @dev A contract that accepts ETH, used as a normal payee
contract PayableReceiver {
    receive() external payable { }
}

contract PaymentSplitterTest is Test {
    PaymentSplitter internal implementation;
    PaymentSplitter internal splitter;

    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");
    address internal charlie = makeAddr("charlie");

    ERC20Mock internal token;

    event PayeeAdded(address account, uint256 shares);
    event PaymentReleased(address to, uint256 amount);
    event ERC20PaymentReleased(IERC20 indexed token, address to, uint256 amount);
    event PaymentReceived(address from, uint256 amount);

    function setUp() public {
        implementation = new PaymentSplitter();
        token = new ERC20Mock();
    }

    // ============================================
    // HELPERS
    // ============================================

    function _deployClone() internal returns (PaymentSplitter) {
        return PaymentSplitter(payable(Clones.clone(address(implementation))));
    }

    function _defaultPayees() internal view returns (address[] memory payees, uint256[] memory sharesArr) {
        payees = new address[](3);
        payees[0] = alice;
        payees[1] = bob;
        payees[2] = charlie;

        sharesArr = new uint256[](3);
        sharesArr[0] = 50;
        sharesArr[1] = 30;
        sharesArr[2] = 20;
    }

    function _initDefault() internal {
        (address[] memory payees, uint256[] memory sharesArr) = _defaultPayees();
        splitter = _deployClone();
        splitter.initialize(payees, sharesArr);
    }

    // ============================================
    // INITIALIZATION
    // ============================================

    function test_constructor_disablesInitializersOnImplementation() public {
        (address[] memory payees, uint256[] memory sharesArr) = _defaultPayees();
        vm.expectRevert();
        implementation.initialize(payees, sharesArr);
    }

    function test_initialize_setsPayeesAndShares() public {
        (address[] memory payees, uint256[] memory sharesArr) = _defaultPayees();
        splitter = _deployClone();

        vm.expectEmit(true, true, true, true, address(splitter));
        emit PayeeAdded(alice, 50);
        vm.expectEmit(true, true, true, true, address(splitter));
        emit PayeeAdded(bob, 30);
        vm.expectEmit(true, true, true, true, address(splitter));
        emit PayeeAdded(charlie, 20);

        splitter.initialize(payees, sharesArr);

        assertEq(splitter.totalShares(), 100);
        assertEq(splitter.shares(alice), 50);
        assertEq(splitter.shares(bob), 30);
        assertEq(splitter.shares(charlie), 20);
        assertEq(splitter.payee(0), alice);
        assertEq(splitter.payee(1), bob);
        assertEq(splitter.payee(2), charlie);
    }

    function test_initialize_revertsWhenCalledTwice() public {
        _initDefault();
        (address[] memory payees, uint256[] memory sharesArr) = _defaultPayees();
        vm.expectRevert();
        splitter.initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnLengthMismatch() public {
        splitter = _deployClone();
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;
        uint256[] memory sharesArr = new uint256[](1);
        sharesArr[0] = 50;

        vm.expectRevert(bytes("PaymentSplitter: payees and shares length mismatch"));
        splitter.initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnEmptyPayees() public {
        splitter = _deployClone();
        address[] memory payees = new address[](0);
        uint256[] memory sharesArr = new uint256[](0);

        vm.expectRevert(bytes("PaymentSplitter: no payees"));
        splitter.initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnZeroAddress() public {
        splitter = _deployClone();
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = address(0);
        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 50;

        vm.expectRevert(bytes("PaymentSplitter: account is the zero address"));
        splitter.initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnZeroShares() public {
        splitter = _deployClone();
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;
        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 0;

        vm.expectRevert(bytes("PaymentSplitter: shares are 0"));
        splitter.initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnDuplicatePayee() public {
        splitter = _deployClone();
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = alice;
        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 50;

        vm.expectRevert(bytes("PaymentSplitter: account already has shares"));
        splitter.initialize(payees, sharesArr);
    }

    function test_initialize_payableAllowsEthAtInit() public {
        (address[] memory payees, uint256[] memory sharesArr) = _defaultPayees();
        splitter = _deployClone();
        splitter.initialize{ value: 1 ether }(payees, sharesArr);
        assertEq(address(splitter).balance, 1 ether);
    }

    // ============================================
    // RECEIVE
    // ============================================

    function test_receive_emitsEventAndUpdatesBalance() public {
        _initDefault();
        vm.deal(address(this), 1 ether);

        vm.expectEmit(true, true, true, true, address(splitter));
        emit PaymentReceived(address(this), 1 ether);

        (bool success,) = address(splitter).call{ value: 1 ether }("");
        assertTrue(success);
        assertEq(address(splitter).balance, 1 ether);
    }

    // ============================================
    // ETH RELEASE
    // ============================================

    function test_releasable_returnsZeroBeforeAnyPayment() public {
        _initDefault();
        assertEq(splitter.releasable(alice), 0);
    }

    function test_release_distributesProportionally() public {
        _initDefault();
        vm.deal(address(this), 100 ether);
        (bool success,) = address(splitter).call{ value: 100 ether }("");
        assertTrue(success);

        assertEq(splitter.releasable(alice), 50 ether);
        assertEq(splitter.releasable(bob), 30 ether);
        assertEq(splitter.releasable(charlie), 20 ether);

        uint256 aliceBalBefore = alice.balance;
        vm.expectEmit(true, true, true, true, address(splitter));
        emit PaymentReleased(alice, 50 ether);
        splitter.release(payable(alice));

        assertEq(alice.balance, aliceBalBefore + 50 ether);
        assertEq(splitter.released(alice), 50 ether);
        assertEq(splitter.totalReleased(), 50 ether);
        assertEq(splitter.releasable(alice), 0);
    }

    function test_release_anyoneCanTriggerReleaseForPayee() public {
        _initDefault();
        vm.deal(address(this), 10 ether);
        (bool success,) = address(splitter).call{ value: 10 ether }("");
        assertTrue(success);

        vm.prank(bob); // bob triggers alice's release; funds still go to alice
        splitter.release(payable(alice));

        assertEq(alice.balance, 5 ether);
    }

    function test_release_accountsForSubsequentDeposits() public {
        _initDefault();
        vm.deal(address(this), 100 ether);

        (bool s1,) = address(splitter).call{ value: 50 ether }("");
        assertTrue(s1);
        splitter.release(payable(alice));
        assertEq(alice.balance, 25 ether);

        (bool s2,) = address(splitter).call{ value: 50 ether }("");
        assertTrue(s2);
        // total received now 100 ether, alice's total entitlement 50 ether, already released 25 ether
        assertEq(splitter.releasable(alice), 25 ether);
        splitter.release(payable(alice));
        assertEq(alice.balance, 50 ether);
    }

    function test_release_revertsForNonPayee() public {
        _initDefault();
        vm.deal(address(this), 10 ether);
        (bool success,) = address(splitter).call{ value: 10 ether }("");
        assertTrue(success);

        address stranger = makeAddr("stranger");
        vm.expectRevert(bytes("PaymentSplitter: account has no shares"));
        splitter.release(payable(stranger));
    }

    function test_release_revertsWhenNothingDue() public {
        _initDefault();
        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        splitter.release(payable(alice));
    }

    function test_release_revertsWhenAlreadyFullyReleased() public {
        _initDefault();
        vm.deal(address(this), 10 ether);
        (bool success,) = address(splitter).call{ value: 10 ether }("");
        assertTrue(success);

        splitter.release(payable(alice));

        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        splitter.release(payable(alice));
    }

    function test_release_revertsWhenRecipientRejectsEth() public {
        RevertingReceiver rejecter = new RevertingReceiver();

        address[] memory payees = new address[](2);
        payees[0] = address(rejecter);
        payees[1] = bob;
        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 50;

        splitter = _deployClone();
        splitter.initialize(payees, sharesArr);

        vm.deal(address(this), 10 ether);
        (bool success,) = address(splitter).call{ value: 10 ether }("");
        assertTrue(success);

        vm.expectRevert();
        splitter.release(payable(address(rejecter)));
    }

    function test_release_worksForContractPayee() public {
        PayableReceiver receiver = new PayableReceiver();

        address[] memory payees = new address[](2);
        payees[0] = address(receiver);
        payees[1] = bob;
        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 50;

        splitter = _deployClone();
        splitter.initialize(payees, sharesArr);

        vm.deal(address(this), 10 ether);
        (bool success,) = address(splitter).call{ value: 10 ether }("");
        assertTrue(success);

        splitter.release(payable(address(receiver)));
        assertEq(address(receiver).balance, 5 ether);
    }

    // ============================================
    // ERC20 RELEASE
    // ============================================

    function test_erc20Releasable_returnsZeroBeforeAnyPayment() public {
        _initDefault();
        assertEq(splitter.releasable(token, alice), 0);
    }

    function test_erc20Release_distributesProportionally() public {
        _initDefault();
        token.mint(address(splitter), 1000 ether);

        assertEq(splitter.releasable(token, alice), 500 ether);
        assertEq(splitter.releasable(token, bob), 300 ether);
        assertEq(splitter.releasable(token, charlie), 200 ether);

        vm.expectEmit(true, true, true, true, address(splitter));
        emit ERC20PaymentReleased(token, alice, 500 ether);
        splitter.release(token, alice);

        assertEq(token.balanceOf(alice), 500 ether);
        assertEq(splitter.released(token, alice), 500 ether);
        assertEq(splitter.totalReleased(token), 500 ether);
        assertEq(splitter.releasable(token, alice), 0);
    }

    function test_erc20Release_accountsForSubsequentDeposits() public {
        _initDefault();
        token.mint(address(splitter), 500 ether);
        splitter.release(token, alice);
        assertEq(token.balanceOf(alice), 250 ether);

        token.mint(address(splitter), 500 ether);
        assertEq(splitter.releasable(token, alice), 250 ether);
        splitter.release(token, alice);
        assertEq(token.balanceOf(alice), 500 ether);
    }

    function test_erc20Release_revertsForNonPayee() public {
        _initDefault();
        token.mint(address(splitter), 1000 ether);

        address stranger = makeAddr("stranger");
        vm.expectRevert(bytes("PaymentSplitter: account has no shares"));
        splitter.release(token, stranger);
    }

    function test_erc20Release_revertsWhenNothingDue() public {
        _initDefault();
        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        splitter.release(token, alice);
    }

    function test_erc20Release_revertsWhenAlreadyFullyReleased() public {
        _initDefault();
        token.mint(address(splitter), 1000 ether);
        splitter.release(token, alice);

        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        splitter.release(token, alice);
    }

    function test_erc20Release_independentFromEthAccounting() public {
        _initDefault();
        vm.deal(address(this), 10 ether);
        (bool success,) = address(splitter).call{ value: 10 ether }("");
        assertTrue(success);
        token.mint(address(splitter), 1000 ether);

        splitter.release(payable(alice));
        splitter.release(token, alice);

        assertEq(alice.balance, 5 ether);
        assertEq(token.balanceOf(alice), 500 ether);
        assertEq(splitter.releasable(alice), 0);
        assertEq(splitter.releasable(token, alice), 0);
    }

    // ============================================
    // VIEW GETTERS
    // ============================================

    function test_payee_revertsOutOfBounds() public {
        _initDefault();
        vm.expectRevert();
        splitter.payee(3);
    }

    function test_shares_returnsZeroForNonPayee() public {
        _initDefault();
        assertEq(splitter.shares(makeAddr("nobody")), 0);
    }

    function test_released_returnsZeroInitially() public {
        _initDefault();
        assertEq(splitter.released(alice), 0);
        assertEq(splitter.released(token, alice), 0);
    }

    // ============================================
    // FUZZ
    // ============================================

    function testFuzz_release_neverExceedsShareEntitlement(uint96 amount) public {
        vm.assume(amount > 0);
        _initDefault();
        vm.deal(address(this), amount);
        (bool success,) = address(splitter).call{ value: amount }("");
        assertTrue(success);

        uint256 expectedAlice = (uint256(amount) * 50) / 100;
        assertEq(splitter.releasable(alice), expectedAlice);

        if (expectedAlice > 0) {
            splitter.release(payable(alice));
            assertEq(alice.balance, expectedAlice);
        } else {
            vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
            splitter.release(payable(alice));
        }
    }

    function testFuzz_erc20Release_neverExceedsShareEntitlement(uint96 amount) public {
        vm.assume(amount > 0);
        _initDefault();
        token.mint(address(splitter), amount);

        uint256 expectedBob = (uint256(amount) * 30) / 100;
        assertEq(splitter.releasable(token, bob), expectedBob);

        if (expectedBob > 0) {
            splitter.release(token, bob);
            assertEq(token.balanceOf(bob), expectedBob);
        } else {
            vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
            splitter.release(token, bob);
        }
    }

    function testFuzz_totalReleasedNeverExceedsTotalReceived(uint96 amount1, uint96 amount2) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        _initDefault();

        vm.deal(address(this), uint256(amount1));
        (bool s1,) = address(splitter).call{ value: amount1 }("");
        assertTrue(s1);

        if (splitter.releasable(alice) > 0) splitter.release(payable(alice));
        if (splitter.releasable(bob) > 0) splitter.release(payable(bob));
        if (splitter.releasable(charlie) > 0) splitter.release(payable(charlie));

        vm.deal(address(this), uint256(amount2));
        (bool s2,) = address(splitter).call{ value: amount2 }("");
        assertTrue(s2);

        if (splitter.releasable(alice) > 0) splitter.release(payable(alice));
        if (splitter.releasable(bob) > 0) splitter.release(payable(bob));
        if (splitter.releasable(charlie) > 0) splitter.release(payable(charlie));

        assertLe(splitter.totalReleased(), uint256(amount1) + uint256(amount2));
    }
}

