        assertEq(splitter.releasable(alice), expectedAlice);
        assertEq(splitter.releasable(bob), expectedBob);
    }

    // ============================================
    // ERC20 RELEASE
    // ============================================

    function test_releasableERC20_computesProportionalShare() public {
