// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { PaymentSplitter } from "src/core/PaymentSplitter.sol";
import { Initializable } from "@openzeppelin/contracts/proxy/utils/Initializable.sol";
import { Clones } from "@openzeppelin/contracts/proxy/Clones.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/// @dev Simple mintable ERC20 used to exercise the token-release paths.
contract MockERC20 is ERC20 {
    constructor() ERC20("Mock Token", "MOCK") {}

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

/// @dev Contract that unconditionally rejects ETH transfers, used to exercise the
///      Address.sendValue failure branch of `release(address payable)`.
contract RevertingReceiver {
    receive() external payable {
        revert("nope");
    }
}

contract PaymentSplitterTest is Test {
    PaymentSplitter internal implementation;

    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");
    address internal carol = makeAddr("carol");
    address internal stranger = makeAddr("stranger");

    event PayeeAdded(address account, uint256 shares);
    event PaymentReleased(address to, uint256 amount);
    event ERC20PaymentReleased(IERC20 indexed token, address to, uint256 amount);
    event PaymentReceived(address from, uint256 amount);

    function setUp() public {
        implementation = new PaymentSplitter();
    }

    // ============================================
    // HELPERS
    // ============================================

    function _deploy(address[] memory payees, uint256[] memory sharesArr) internal returns (PaymentSplitter) {
        address clone = Clones.clone(address(implementation));
        PaymentSplitter splitter = PaymentSplitter(payable(clone));
        splitter.initialize(payees, sharesArr);
        return splitter;
    }

    function _defaultSplitter() internal returns (PaymentSplitter) {
        address[] memory payees = new address[](3);
        payees[0] = alice;
        payees[1] = bob;
        payees[2] = carol;

        uint256[] memory sharesArr = new uint256[](3);
        sharesArr[0] = 100;
        sharesArr[1] = 200;
        sharesArr[2] = 700;

        return _deploy(payees, sharesArr);
    }

    function _single(address a, uint256[] memory arr, uint256 idx) internal pure returns (uint256) {
        return arr[idx];
    }

    // ============================================
    // INITIALIZATION
    // ============================================

    function test_initialize_setsPayeesAndShares() public {
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;

        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 60;
        sharesArr[1] = 40;

        PaymentSplitter splitter = _deploy(payees, sharesArr);

        assertEq(splitter.totalShares(), 100);
        assertEq(splitter.shares(alice), 60);
        assertEq(splitter.shares(bob), 40);
        assertEq(splitter.payee(0), alice);
        assertEq(splitter.payee(1), bob);
        assertEq(splitter.shares(stranger), 0);
    }

    function test_initialize_emitsPayeeAddedForEachPayee() public {
        address clone = Clones.clone(address(implementation));

        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;

        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 60;
        sharesArr[1] = 40;

        vm.expectEmit(true, true, true, true, clone);
        emit PayeeAdded(alice, 60);
        vm.expectEmit(true, true, true, true, clone);
        emit PayeeAdded(bob, 40);

        PaymentSplitter(payable(clone)).initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnLengthMismatch() public {
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;

        uint256[] memory sharesArr = new uint256[](1);
        sharesArr[0] = 100;

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: payees and shares length mismatch"));
        PaymentSplitter(payable(clone)).initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnEmptyPayees() public {
        address[] memory payees = new address[](0);
        uint256[] memory sharesArr = new uint256[](0);

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: no payees"));
        PaymentSplitter(payable(clone)).initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnZeroAddressPayee() public {
        address[] memory payees = new address[](1);
        payees[0] = address(0);

        uint256[] memory sharesArr = new uint256[](1);
        sharesArr[0] = 100;

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: account is the zero address"));
        PaymentSplitter(payable(clone)).initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnZeroShares() public {
        address[] memory payees = new address[](1);
        payees[0] = alice;

        uint256[] memory sharesArr = new uint256[](1);
        sharesArr[0] = 0;

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: shares are 0"));
        PaymentSplitter(payable(clone)).initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnDuplicatePayee() public {
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = alice;

        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 50;

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: account already has shares"));
        PaymentSplitter(payable(clone)).initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnSecondCall() public {
        PaymentSplitter splitter = _defaultSplitter();

        address[] memory payees = new address[](1);
        payees[0] = stranger;
        uint256[] memory sharesArr = new uint256[](1);
        sharesArr[0] = 1;

        vm.expectRevert(Initializable.InvalidInitialization.selector);
        splitter.initialize(payees, sharesArr);
    }

    function test_initialize_revertsOnImplementationDirectly() public {
        address[] memory payees = new address[](1);
        payees[0] = alice;
        uint256[] memory sharesArr = new uint256[](1);
        sharesArr[0] = 1;

        // The constructor calls _disableInitializers(), so the implementation itself
        // can never be initialized directly (must go through a proxy/clone).
        vm.expectRevert(Initializable.InvalidInitialization.selector);
        implementation.initialize(payees, sharesArr);
    }

    // ============================================
    // VIEW FUNCTIONS (misc)
    // ============================================

    function test_payee_revertsOutOfBounds() public {
        PaymentSplitter splitter = _defaultSplitter();
        vm.expectRevert();
        splitter.payee(3);
    }

    function test_shares_and_released_defaultToZeroForNonPayee() public {
        PaymentSplitter splitter = _defaultSplitter();
        assertEq(splitter.shares(stranger), 0);
        assertEq(splitter.released(stranger), 0);
        assertEq(splitter.releasable(stranger), 0);
    }

    // ============================================
    // RECEIVE
    // ============================================

    function test_receive_emitsPaymentReceivedAndIncreasesBalance() public {
        PaymentSplitter splitter = _defaultSplitter();

        vm.deal(stranger, 10 ether);
        vm.prank(stranger);
        vm.expectEmit(true, true, true, true, address(splitter));
        emit PaymentReceived(stranger, 1 ether);
        (bool ok, ) = address(splitter).call{ value: 1 ether }("");
        assertTrue(ok);

        assertEq(address(splitter).balance, 1 ether);
    }

    // ============================================
    // ETH RELEASE
    // ============================================

    function test_releasable_computesProportionalShare() public {
        PaymentSplitter splitter = _defaultSplitter();
        vm.deal(address(splitter), 1000 wei);

        assertEq(splitter.releasable(alice), 100);
        assertEq(splitter.releasable(bob), 200);
        assertEq(splitter.releasable(carol), 700);
    }

    function test_release_transfersAndUpdatesState() public {
        PaymentSplitter splitter = _defaultSplitter();
        vm.deal(address(splitter), 1000 wei);

        uint256 balBefore = alice.balance;

        vm.expectEmit(true, true, true, true, address(splitter));
        emit PaymentReleased(alice, 100);
        splitter.release(payable(alice));

        assertEq(alice.balance, balBefore + 100);
        assertEq(splitter.released(alice), 100);
        assertEq(splitter.totalReleased(), 100);
        assertEq(splitter.releasable(alice), 0);
    }

    function test_release_anyoneCanTriggerReleaseForAPayee() public {
        PaymentSplitter splitter = _defaultSplitter();
        vm.deal(address(splitter), 1000 wei);

        uint256 balBefore = alice.balance;
        vm.prank(stranger);
        splitter.release(payable(alice));

        assertEq(alice.balance, balBefore + 100);
    }

    function test_release_revertsForAccountWithNoShares() public {
        PaymentSplitter splitter = _defaultSplitter();
        vm.deal(address(splitter), 1000 wei);

        vm.expectRevert(bytes("PaymentSplitter: account has no shares"));
        splitter.release(payable(stranger));
    }

    function test_release_revertsWhenNothingDue() public {
        PaymentSplitter splitter = _defaultSplitter();
        vm.deal(address(splitter), 1000 wei);

        splitter.release(payable(alice));

        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        splitter.release(payable(alice));
    }

    function test_release_revertsWhenNoFundsEverReceived() public {
        PaymentSplitter splitter = _defaultSplitter();

        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        splitter.release(payable(alice));
    }

    function test_release_accumulatesAcrossMultipleDeposits() public {
        PaymentSplitter splitter = _defaultSplitter();

        vm.deal(address(splitter), 1000 wei);
        splitter.release(payable(alice));
        assertEq(alice.balance, 100);

        // Second deposit
        vm.deal(stranger, 1000 wei);
        vm.prank(stranger);
        (bool ok, ) = address(splitter).call{ value: 1000 wei }("");
        assertTrue(ok);

        assertEq(splitter.releasable(alice), 100);
        splitter.release(payable(alice));
        assertEq(alice.balance, 200);
        assertEq(splitter.released(alice), 200);
    }

    function test_release_allPayeesSumToTotalReceived() public {
        PaymentSplitter splitter = _defaultSplitter();
        vm.deal(address(splitter), 1000 wei);

        splitter.release(payable(alice));
        splitter.release(payable(bob));
        splitter.release(payable(carol));

        assertEq(alice.balance + bob.balance + carol.balance, 1000);
        assertEq(splitter.totalReleased(), 1000);
    }

    function test_release_revertsWhenTransferFails() public {
        RevertingReceiver rejector = new RevertingReceiver();

        address[] memory payees = new address[](2);
        payees[0] = address(rejector);
        payees[1] = bob;

        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = 50;
        sharesArr[1] = 50;

        PaymentSplitter splitter = _deploy(payees, sharesArr);
        vm.deal(address(splitter), 1000 wei);

        vm.expectRevert();
        splitter.release(payable(address(rejector)));

        // State must not have been mutated on failure.
        assertEq(splitter.released(address(rejector)), 0);
        assertEq(splitter.totalReleased(), 0);
    }

    function testFuzz_releasable_matchesFormula(uint128 amount, uint96 aShares, uint96 bShares) public {
        vm.assume(aShares > 0 && bShares > 0);

        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;

        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = aShares;
        sharesArr[1] = bShares;

        PaymentSplitter splitter = _deploy(payees, sharesArr);
        vm.deal(address(splitter), amount);

        uint256 totalShares = uint256(aShares) + uint256(bShares);
        uint256 expectedAlice = (uint256(amount) * aShares) / totalShares;
        uint256 expectedBob = (uint256(amount) * bShares) / totalShares;

        assertEq(splitter.releasable(alice), expectedAlice);
        assertEq(splitter.releasable(bob), expectedBob);
    }

    // ============================================
    // ERC20 RELEASE
    // ============================================

    function test_releasableERC20_computesProportionalShare() public {
        PaymentSplitter splitter = _defaultSplitter();
        MockERC20 token = new MockERC20();
        token.mint(address(splitter), 1000);

        assertEq(splitter.releasable(token, alice), 100);
        assertEq(splitter.releasable(token, bob), 200);
        assertEq(splitter.releasable(token, carol), 700);
    }

    function test_releaseERC20_transfersAndUpdatesState() public {
        PaymentSplitter splitter = _defaultSplitter();
        MockERC20 token = new MockERC20();
        token.mint(address(splitter), 1000);

        vm.expectEmit(true, true, true, true, address(splitter));
        emit ERC20PaymentReleased(IERC20(address(token)), alice, 100);
        splitter.release(IERC20(address(token)), alice);

        assertEq(token.balanceOf(alice), 100);
        assertEq(splitter.released(IERC20(address(token)), alice), 100);
        assertEq(splitter.totalReleased(IERC20(address(token))), 100);
        assertEq(splitter.releasable(IERC20(address(token)), alice), 0);
    }

    function test_releaseERC20_revertsForAccountWithNoShares() public {
        PaymentSplitter splitter = _defaultSplitter();
        MockERC20 token = new MockERC20();
        token.mint(address(splitter), 1000);

        vm.expectRevert(bytes("PaymentSplitter: account has no shares"));
        splitter.release(IERC20(address(token)), stranger);
    }

    function test_releaseERC20_revertsWhenNothingDue() public {
        PaymentSplitter splitter = _defaultSplitter();
        MockERC20 token = new MockERC20();
        token.mint(address(splitter), 1000);

        splitter.release(IERC20(address(token)), alice);

        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        splitter.release(IERC20(address(token)), alice);
    }

    function test_releaseERC20_accumulatesAcrossMultipleDeposits() public {
        PaymentSplitter splitter = _defaultSplitter();
        MockERC20 token = new MockERC20();

        token.mint(address(splitter), 1000);
        splitter.release(IERC20(address(token)), alice);
        assertEq(token.balanceOf(alice), 100);

        token.mint(address(splitter), 1000);
        assertEq(splitter.releasable(IERC20(address(token)), alice), 100);

        splitter.release(IERC20(address(token)), alice);
        assertEq(token.balanceOf(alice), 200);
        assertEq(splitter.released(IERC20(address(token)), alice), 200);
    }

    function test_releaseERC20_independentAcrossDifferentTokens() public {
        PaymentSplitter splitter = _defaultSplitter();
        MockERC20 tokenA = new MockERC20();
        MockERC20 tokenB = new MockERC20();

        tokenA.mint(address(splitter), 1000);
        tokenB.mint(address(splitter), 500);

        splitter.release(IERC20(address(tokenA)), alice);
        assertEq(tokenA.balanceOf(alice), 100);
        // Token B is untouched and independently releasable.
        assertEq(splitter.releasable(IERC20(address(tokenB)), alice), 50);

        splitter.release(IERC20(address(tokenB)), alice);
        assertEq(tokenB.balanceOf(alice), 50);
        assertEq(splitter.totalReleased(IERC20(address(tokenA))), 100);
        assertEq(splitter.totalReleased(IERC20(address(tokenB))), 50);
    }

    function testFuzz_releasableERC20_matchesFormula(uint128 amount, uint96 aShares, uint96 bShares) public {
        vm.assume(aShares > 0 && bShares > 0);

        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;

        uint256[] memory sharesArr = new uint256[](2);
        sharesArr[0] = aShares;
        sharesArr[1] = bShares;

        PaymentSplitter splitter = _deploy(payees, sharesArr);
        MockERC20 token = new MockERC20();
        token.mint(address(splitter), amount);

        uint256 totalShares = uint256(aShares) + uint256(bShares);
        uint256 expectedAlice = (uint256(amount) * aShares) / totalShares;
        uint256 expectedBob = (uint256(amount) * bShares) / totalShares;

        assertEq(splitter.releasable(IERC20(address(token)), alice), expectedAlice);
        assertEq(splitter.releasable(IERC20(address(token)), bob), expectedBob);
    }
}

