    function _deploy(address[] memory payees, uint256[] memory shares_) internal returns (PaymentSplitter) {
        address clone = Clones.clone(address(implementation));
        PaymentSplitter(payable(clone)).initialize(payees, shares_);
        return PaymentSplitter(payable(clone));
    }

    function _defaultPayees() internal view returns (address[] memory payees, uint256[] memory shares_) {
        payees = new address[](3);
        payees[0] = alice;
        payees[1] = bob;
        payees[2] = charlie;

        shares_ = new uint256[](3);
        shares_[0] = 50;
        shares_[1] = 30;
        shares_[2] = 20;
    }

    // ============================================
    // INITIALIZATION
    // ============================================

    function test_RevertWhen_ImplementationInitializedDirectly() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        vm.expectRevert(Initializable.InvalidInitialization.selector);
        implementation.initialize(payees, shares_);
    }

    function test_RevertWhen_DoubleInitialize() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.expectRevert(Initializable.InvalidInitialization.selector);
        s.initialize(payees, shares_);
    }

    function test_RevertWhen_InitializeLengthMismatch() public {
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;
        uint256[] memory shares_ = new uint256[](1);
        shares_[0] = 1;

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: payees and shares length mismatch"));
        PaymentSplitter(payable(clone)).initialize(payees, shares_);
    }

    function test_RevertWhen_InitializeEmptyPayees() public {
        address[] memory payees = new address[](0);
        uint256[] memory shares_ = new uint256[](0);

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: no payees"));
        PaymentSplitter(payable(clone)).initialize(payees, shares_);
    }

    function test_RevertWhen_InitializeZeroAddressPayee() public {
        address[] memory payees = new address[](1);
        payees[0] = address(0);
        uint256[] memory shares_ = new uint256[](1);
        shares_[0] = 1;

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: account is the zero address"));
        PaymentSplitter(payable(clone)).initialize(payees, shares_);
    }

    function test_RevertWhen_InitializeZeroShares() public {
        address[] memory payees = new address[](1);
        payees[0] = alice;
        uint256[] memory shares_ = new uint256[](1);
        shares_[0] = 0;

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: shares are 0"));
        PaymentSplitter(payable(clone)).initialize(payees, shares_);
    }

    function test_RevertWhen_InitializeDuplicatePayee() public {
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = alice;
        uint256[] memory shares_ = new uint256[](2);
        shares_[0] = 1;
        shares_[1] = 1;

        address clone = Clones.clone(address(implementation));
        vm.expectRevert(bytes("PaymentSplitter: account already has shares"));
        PaymentSplitter(payable(clone)).initialize(payees, shares_);
    }

    function test_Initialize_EmitsPayeeAddedEvents() public {
        address[] memory payees = new address[](2);
        payees[0] = alice;
        payees[1] = bob;
        uint256[] memory shares_ = new uint256[](2);
        shares_[0] = 1;
        shares_[1] = 3;

        address clone = Clones.clone(address(implementation));

        vm.expectEmit(true, true, true, true, clone);
        emit PaymentSplitter.PayeeAdded(alice, 1);
        vm.expectEmit(true, true, true, true, clone);
        emit PaymentSplitter.PayeeAdded(bob, 3);

        PaymentSplitter(payable(clone)).initialize(payees, shares_);

        assertEq(PaymentSplitter(payable(clone)).totalShares(), 4);
    }

    // ============================================
    // VIEW FUNCTIONS
    // ============================================

    function test_ViewFunctions_AfterDeploy() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        assertEq(s.totalShares(), 100);
        assertEq(s.shares(alice), 50);
        assertEq(s.shares(bob), 30);
        assertEq(s.shares(charlie), 20);
        assertEq(s.shares(stranger), 0);
        assertEq(s.payee(0), alice);
        assertEq(s.payee(1), bob);
        assertEq(s.payee(2), charlie);
        assertEq(s.totalReleased(), 0);
        assertEq(s.released(alice), 0);
        assertEq(s.totalReleased(token), 0);
        assertEq(s.released(token, alice), 0);
        assertEq(s.releasable(alice), 0);
        assertEq(s.releasable(token, alice), 0);
    }

    function test_Payee_RevertWhen_IndexOutOfBounds() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.expectRevert();
        s.payee(3);
    }

    // ============================================
    // RECEIVE
    // ============================================

    function test_Receive_EmitsPaymentReceivedAndUpdatesBalance() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.deal(address(this), 1 ether);
        vm.expectEmit(true, true, true, true, address(s));
        emit PaymentSplitter.PaymentReceived(address(this), 1 ether);
        (bool sent,) = address(s).call{ value: 1 ether }("");
        assertTrue(sent);

        assertEq(address(s).balance, 1 ether);
    }

    // ============================================
    // ETH RELEASE
    // ============================================

    function test_Release_Eth_HappyPath() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.deal(address(this), 100 ether);
        (bool sent,) = address(s).call{ value: 100 ether }("");
        assertTrue(sent);

        assertEq(s.releasable(alice), 50 ether);
        assertEq(s.releasable(bob), 30 ether);
        assertEq(s.releasable(charlie), 20 ether);

        uint256 aliceBalBefore = alice.balance;
        vm.expectEmit(true, true, true, true, address(s));
        emit PaymentSplitter.PaymentReleased(alice, 50 ether);
        s.release(payable(alice));

        assertEq(alice.balance - aliceBalBefore, 50 ether);
        assertEq(s.released(alice), 50 ether);
        assertEq(s.totalReleased(), 50 ether);
        assertEq(s.releasable(alice), 0);
    }

    function test_Release_Eth_AccountsForNewFundsAfterPriorRelease() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.deal(address(this), 200 ether);
        (bool sent1,) = address(s).call{ value: 100 ether }("");
        assertTrue(sent1);
        s.release(payable(alice)); // 50 ether released

        (bool sent2,) = address(s).call{ value: 100 ether }("");
        assertTrue(sent2);

        // total received is now 200 ether; alice's cut is 100 ether, 50 already released
        assertEq(s.releasable(alice), 50 ether);
        s.release(payable(alice));
        assertEq(s.released(alice), 100 ether);
        assertEq(s.totalReleased(), 100 ether);
    }

    function test_RevertWhen_ReleaseEthNoShares() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.deal(address(this), 10 ether);
        (bool sent,) = address(s).call{ value: 10 ether }("");
        assertTrue(sent);

        vm.expectRevert(bytes("PaymentSplitter: account has no shares"));
        s.release(payable(stranger));
    }

    function test_RevertWhen_ReleaseEthNotDue() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        s.release(payable(alice));
    }

    function test_RevertWhen_ReleaseEthAlreadyReleased() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.deal(address(this), 10 ether);
        (bool sent,) = address(s).call{ value: 10 ether }("");
        assertTrue(sent);

        s.release(payable(alice));

        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        s.release(payable(alice));
    }

    function test_RevertWhen_RecipientRejectsEth() public {
        RevertingReceiver rejector = new RevertingReceiver();

        address[] memory payees = new address[](2);
        payees[0] = address(rejector);
        payees[1] = alice;
        uint256[] memory shares_ = new uint256[](2);
        shares_[0] = 1;
        shares_[1] = 1;
        PaymentSplitter s = _deploy(payees, shares_);

        vm.deal(address(this), 10 ether);
        (bool sent,) = address(s).call{ value: 10 ether }("");
        assertTrue(sent);

        vm.expectRevert();
        s.release(payable(address(rejector)));
    }

    function testFuzz_Release_Eth_ProportionalSplit(uint96 amount) public {
        vm.assume(amount > 0);
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.deal(address(this), amount);
        (bool sent,) = address(s).call{ value: amount }("");
        assertTrue(sent);

        for (uint256 i = 0; i < payees.length; i++) {
            uint256 expected = (uint256(amount) * shares_[i]) / s.totalShares();
            if (expected == 0) {
                vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
                s.release(payable(payees[i]));
            } else {
                uint256 balBefore = payees[i].balance;
                s.release(payable(payees[i]));
                assertEq(payees[i].balance - balBefore, expected);
                assertEq(s.released(payees[i]), expected);
            }
        }
    }

    // ============================================
    // ERC20 RELEASE
    // ============================================

    function test_Release_Erc20_HappyPath() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        token.mint(address(s), 1000 ether);

        assertEq(s.releasable(token, alice), 500 ether);
        assertEq(s.releasable(token, bob), 300 ether);
        assertEq(s.releasable(token, charlie), 200 ether);

        vm.expectEmit(true, true, true, true, address(s));
        emit PaymentSplitter.ERC20PaymentReleased(token, bob, 300 ether);
        s.release(token, bob);

        assertEq(token.balanceOf(bob), 300 ether);
        assertEq(s.released(token, bob), 300 ether);
        assertEq(s.totalReleased(token), 300 ether);
        assertEq(s.releasable(token, bob), 0);
    }

    function test_Release_Erc20_AccountsForNewFundsAfterPriorRelease() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        token.mint(address(s), 1000 ether);
        s.release(token, alice); // 500 ether

        token.mint(address(s), 1000 ether);
        // total received now 2000 ether; alice's cut is 1000 ether, 500 already released
        assertEq(s.releasable(token, alice), 500 ether);
        s.release(token, alice);
        assertEq(s.released(token, alice), 1000 ether);
        assertEq(s.totalReleased(token), 1000 ether);
    }

    function test_RevertWhen_ReleaseErc20NoShares() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        token.mint(address(s), 1000 ether);

        vm.expectRevert(bytes("PaymentSplitter: account has no shares"));
        s.release(token, stranger);
    }

    function test_RevertWhen_ReleaseErc20NotDue() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        s.release(token, alice);
    }

    function test_RevertWhen_ReleaseErc20AlreadyReleased() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        token.mint(address(s), 1000 ether);
        s.release(token, alice);

        vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
        s.release(token, alice);
    }

    function testFuzz_Release_Erc20_ProportionalSplit(uint96 amount) public {
        vm.assume(amount > 0);
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        token.mint(address(s), amount);

        for (uint256 i = 0; i < payees.length; i++) {
            uint256 expected = (uint256(amount) * shares_[i]) / s.totalShares();
            if (expected == 0) {
                vm.expectRevert(bytes("PaymentSplitter: account is not due payment"));
                s.release(token, payees[i]);
            } else {
                s.release(token, payees[i]);
                assertEq(token.balanceOf(payees[i]), expected);
                assertEq(s.released(token, payees[i]), expected);
            }
        }
    }

    // ============================================
    // MULTIPLE PAYEES / TOKENS INDEPENDENCE
    // ============================================

    function test_EthAndErc20AccountingAreIndependent() public {
        (address[] memory payees, uint256[] memory shares_) = _defaultPayees();
        PaymentSplitter s = _deploy(payees, shares_);

        vm.deal(address(this), 10 ether);
        (bool sent,) = address(s).call{ value: 10 ether }("");
        assertTrue(sent);
        token.mint(address(s), 1000 ether);

        s.release(payable(alice));
        s.release(token, alice);

        assertEq(s.released(alice), 5 ether);
        assertEq(s.released(token, alice), 500 ether);
        assertEq(s.releasable(alice), 0);
        assertEq(s.releasable(token, alice), 0);
    }
}

