// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import { UniswapV4SwapperAdapter, IV4PoolManager } from "src/swappers/UniswapV4SwapperAdapter.sol";

// ============================================
// MOCK ERC20
// ============================================

contract MockERC20 is ERC20 {
    constructor(string memory name_, string memory symbol_) ERC20(name_, symbol_) { }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

// ============================================
// MOCK V4 POOL MANAGER
// ============================================

interface IUnlockCallback {
    function unlockCallback(bytes calldata data) external returns (bytes memory);
}

/// @notice Minimal but faithful mock of the V4 PoolManager's accounting model.
/// @dev Tracks per-currency deltas during an unlock() session exactly like the real
///      PoolManager: swap() moves the delta away from zero, sync()+settle() and take()
///      move it back towards zero. unlock() reverts if any touched currency delta is
///      left non-zero at the end of the callback, mirroring CurrencyNotSettled.
contract MockPoolManager is IV4PoolManager {
    uint256 internal constant BPS_DENOM = 10_000;

    bool public locked;
    address public lastSynced;

    mapping(address => uint256) public reserveBefore;
    mapping(address => int256) public currencyDelta;
    mapping(address => bool) internal _isTouched;
    address[] internal _touched;

    // poolId => zeroForOne => rate (scaled 1e18, amountOut per unit amountIn)
    mapping(bytes32 => mapping(bool => uint256)) public rateOf;
    // poolId => zeroForOne => bps of the specified input actually consumed (default 10_000 = 100%)
    mapping(bytes32 => mapping(bool => uint256)) public consumedBpsOf;

    function _poolId(IV4PoolManager.PoolKey memory key) internal pure returns (bytes32) {
        return keccak256(abi.encode(key.currency0, key.currency1, key.fee, key.tickSpacing, key.hooks));
    }

    function setRate(
        address currency0,
        address currency1,
        uint24 fee_,
        int24 tickSpacing_,
        address hooks_,
        bool zeroForOne,
        uint256 rateWad
    ) external {
        bytes32 id = keccak256(abi.encode(currency0, currency1, fee_, tickSpacing_, hooks_));
        rateOf[id][zeroForOne] = rateWad;
    }

    function setConsumedBps(
        address currency0,
        address currency1,
        uint24 fee_,
        int24 tickSpacing_,
        address hooks_,
        bool zeroForOne,
        uint256 bps
    ) external {
        bytes32 id = keccak256(abi.encode(currency0, currency1, fee_, tickSpacing_, hooks_));
        consumedBpsOf[id][zeroForOne] = bps;
    }

    function _track(address currency) internal {
        if (!_isTouched[currency]) {
            _isTouched[currency] = true;
            _touched.push(currency);
        }
    }

    function unlock(bytes calldata data) external override returns (bytes memory result) {
        require(!locked, "MockPoolManager: already locked");
        locked = true;

        result = IUnlockCallback(msg.sender).unlockCallback(data);

        for (uint256 i = 0; i < _touched.length; i++) {
            address c = _touched[i];
            require(currencyDelta[c] == 0, "MockPoolManager: CurrencyNotSettled");
            _isTouched[c] = false;
            currencyDelta[c] = 0;
        }
        delete _touched;
        locked = false;
    }

    function swap(
        IV4PoolManager.PoolKey memory key,
        IV4PoolManager.SwapParams memory params,
        bytes calldata
    ) external override returns (int256 swapDelta) {
        require(locked, "MockPoolManager: not unlocked");
        require(params.amountSpecified < 0, "MockPoolManager: only exact-input supported");

        uint256 amountSpecifiedIn = uint256(-params.amountSpecified);

        bytes32 id = _poolId(key);
        uint256 rate = rateOf[id][params.zeroForOne];
        require(rate != 0, "MockPoolManager: rate not configured");

        uint256 bps = consumedBpsOf[id][params.zeroForOne];
        if (bps == 0) bps = BPS_DENOM;

        uint256 actualIn = (amountSpecifiedIn * bps) / BPS_DENOM;
        uint256 amountOut = (actualIn * rate) / 1e18;

        address inputCurrency = params.zeroForOne ? key.currency0 : key.currency1;
        address outputCurrency = params.zeroForOne ? key.currency1 : key.currency0;

        _track(inputCurrency);
        _track(outputCurrency);
        currencyDelta[inputCurrency] -= int256(actualIn);
        currencyDelta[outputCurrency] += int256(amountOut);

        int128 amount0;
        int128 amount1;
        if (params.zeroForOne) {
            amount0 = -int128(int256(actualIn));
            amount1 = int128(int256(amountOut));
        } else {
            amount1 = -int128(int256(actualIn));
            amount0 = int128(int256(amountOut));
        }

        swapDelta = (int256(amount0) << 128) | int256(uint256(uint128(amount1)));
    }

    function sync(address currency) external override {
        require(locked, "MockPoolManager: not unlocked");
        lastSynced = currency;
        reserveBefore[currency] = IERC20(currency).balanceOf(address(this));
        _track(currency);
    }

    function settle() external payable override returns (uint256 paid) {
        require(locked, "MockPoolManager: not unlocked");
        address currency = lastSynced;
        uint256 bal = IERC20(currency).balanceOf(address(this));
        paid = bal - reserveBefore[currency];
        currencyDelta[currency] += int256(paid);
    }

    function take(address currency, address to, uint256 amount) external override {
        require(locked, "MockPoolManager: not unlocked");
        _track(currency);
        currencyDelta[currency] -= int256(amount);
        IERC20(currency).transfer(to, amount);
    }
}

// ============================================
// TESTS
// ============================================

contract UniswapV4SwapperAdapterTest is Test {
    uint256 internal constant WAD = 1e18;
    uint256 internal constant AMOUNT_IN = 1000e18;

    MockPoolManager internal pm;
    MockERC20 internal tokenA;
    MockERC20 internal tokenB; // used as "base" for multi-hop adapter
    MockERC20 internal tokenC;

    UniswapV4SwapperAdapter internal adapterSingle; // base = address(0)
    UniswapV4SwapperAdapter internal adapterMulti; // base = tokenB

    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");

    uint24 internal constant FEE1 = 3000;
    int24 internal constant TICK1 = 60;
    uint24 internal constant FEE2 = 500;
    int24 internal constant TICK2 = 10;

    function setUp() public {
        pm = new MockPoolManager();
        tokenA = new MockERC20("Token A", "TKA");
        tokenB = new MockERC20("Token B (base)", "TKB");
        tokenC = new MockERC20("Token C", "TKC");

        adapterSingle = new UniswapV4SwapperAdapter(
            address(pm), FEE1, TICK1, address(0), address(0), 0, 0, address(0)
        );

        adapterMulti = new UniswapV4SwapperAdapter(
            address(pm), FEE1, TICK1, address(0), address(tokenB), FEE2, TICK2, address(0)
        );

        // Fund users
        tokenA.mint(alice, 1_000_000e18);
        tokenB.mint(alice, 1_000_000e18);
        tokenC.mint(alice, 1_000_000e18);

        // Fund the pool manager with "liquidity" for whichever token it may need to take()
        tokenA.mint(address(pm), 10_000_000e18);
        tokenB.mint(address(pm), 10_000_000e18);
        tokenC.mint(address(pm), 10_000_000e18);
    }

    // ============================================
    // HELPERS
    // ============================================

    function _sorted(address x, address y) internal pure returns (address, address) {
        return x < y ? (x, y) : (y, x);
    }

    function _expectedOut(uint256 amountIn, uint256 bps, uint256 rateWad) internal pure returns (uint256) {
        uint256 actualIn = (amountIn * bps) / 10_000;
        return (actualIn * rateWad) / 1e18;
    }

    function _configurePool(
        address tokenIn,
        address tokenOut,
        uint24 poolFee,
        int24 poolTick,
        uint256 rateWad,
        uint256 bps
    ) internal {
        (address c0, address c1) = _sorted(tokenIn, tokenOut);
        bool zeroForOne = tokenIn < tokenOut;
        pm.setRate(c0, c1, poolFee, poolTick, address(0), zeroForOne, rateWad);
        if (bps != 0) {
            pm.setConsumedBps(c0, c1, poolFee, poolTick, address(0), zeroForOne, bps);
        }
    }

    // ============================================
    // CONSTRUCTOR
    // ============================================

    function test_Constructor_SetsImmutables_SingleHop() public view {
        assertEq(adapterSingle.poolManager(), address(pm));
        assertEq(adapterSingle.fee(), FEE1);
        assertEq(adapterSingle.tickSpacing(), TICK1);
        assertEq(adapterSingle.hooks(), address(0));
        assertEq(adapterSingle.base(), address(0));
    }

    function test_Constructor_SetsImmutables_MultiHop() public view {
        assertEq(adapterMulti.base(), address(tokenB));
        assertEq(adapterMulti.feeOut(), FEE2);
        assertEq(adapterMulti.tickSpacingOut(), TICK2);
        assertEq(adapterMulti.hooksOut(), address(0));
    }

    function test_Constructor_RevertsOnZeroPoolManager() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidPoolManager.selector);
        new UniswapV4SwapperAdapter(address(0), FEE1, TICK1, address(0), address(0), 0, 0, address(0));
    }

    function test_Constructor_RevertsOnZeroTickSpacing() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidTickSpacing.selector);
        new UniswapV4SwapperAdapter(address(pm), FEE1, 0, address(0), address(0), 0, 0, address(0));
    }

    function test_Constructor_RevertsOnZeroTickSpacingOut_WhenBaseSet() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidTickSpacing.selector);
        new UniswapV4SwapperAdapter(address(pm), FEE1, TICK1, address(0), address(tokenB), FEE2, 0, address(0));
    }

    function test_Constructor_AllowsZeroTickSpacingOut_WhenBaseIsZero() public {
        // tickSpacingOut is ignored when base == address(0)
        UniswapV4SwapperAdapter a =
            new UniswapV4SwapperAdapter(address(pm), FEE1, TICK1, address(0), address(0), 0, 0, address(0));
        assertEq(a.base(), address(0));
    }

    // ============================================
    // SWAP() ENTRYPOINT VALIDATION
    // ============================================

    function test_Swap_RevertsOnZeroTokenIn() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidToken.selector);
        adapterSingle.swap(address(0), address(tokenC), 1e18, 0, alice);
    }

    function test_Swap_RevertsOnZeroTokenOut() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidToken.selector);
        adapterSingle.swap(address(tokenA), address(0), 1e18, 0, alice);
    }

    function test_Swap_RevertsWithoutApproval() public {
        vm.prank(alice);
        vm.expectRevert();
        adapterSingle.swap(address(tokenA), address(tokenC), 1e18, 0, alice);
    }

    function test_UnlockCallback_RevertsIfCallerIsNotPoolManager() public {
        vm.expectRevert(UniswapV4SwapperAdapter.UnauthorizedCallback.selector);
        adapterSingle.unlockCallback(
            abi.encode(alice, address(tokenA), address(tokenC), uint256(1e18), uint256(0), alice)
        );
    }

    // ============================================
    // SINGLE-HOP SWAPS
    // ============================================

    function test_SingleHop_Success_FullFill() public {
        _configurePool(address(tokenA), address(tokenC), FEE1, TICK1, WAD, 0);

        uint256 expectedOut = _expectedOut(AMOUNT_IN, 10_000, WAD);

        uint256 aliceTokenABefore = tokenA.balanceOf(alice);
        uint256 aliceTokenCBefore = tokenC.balanceOf(alice);

        vm.startPrank(alice);
        tokenA.approve(address(adapterSingle), AMOUNT_IN);
        uint256 amountOut = adapterSingle.swap(address(tokenA), address(tokenC), AMOUNT_IN, expectedOut, alice);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
        assertEq(tokenA.balanceOf(alice), aliceTokenABefore - AMOUNT_IN);
        assertEq(tokenC.balanceOf(alice), aliceTokenCBefore + expectedOut);
    }

    function test_SingleHop_Success_ReverseDirection() public {
        // Covers the !zeroForOne branch regardless of actual token address ordering.
        _configurePool(address(tokenC), address(tokenA), FEE1, TICK1, WAD, 0);

        uint256 expectedOut = _expectedOut(AMOUNT_IN, 10_000, WAD);

        vm.startPrank(alice);
        tokenC.approve(address(adapterSingle), AMOUNT_IN);
        uint256 amountOut = adapterSingle.swap(address(tokenC), address(tokenA), AMOUNT_IN, expectedOut, alice);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
    }

    function test_SingleHop_SendsOutputToReceiver_NotCaller() public {
        _configurePool(address(tokenA), address(tokenC), FEE1, TICK1, WAD, 0);
        uint256 expectedOut = _expectedOut(AMOUNT_IN, 10_000, WAD);

        uint256 bobBefore = tokenC.balanceOf(bob);

        vm.startPrank(alice);
        tokenA.approve(address(adapterSingle), AMOUNT_IN);
        adapterSingle.swap(address(tokenA), address(tokenC), AMOUNT_IN, expectedOut, bob);
        vm.stopPrank();

        assertEq(tokenC.balanceOf(bob), bobBefore + expectedOut);
        assertEq(tokenC.balanceOf(alice), 1_000_000e18); // unchanged
    }

    function test_SingleHop_RevertsOnInsufficientOutput() public {
        _configurePool(address(tokenA), address(tokenC), FEE1, TICK1, WAD, 0);
        uint256 actualOut = _expectedOut(AMOUNT_IN, 10_000, WAD);
        uint256 minOut = actualOut + 1;

        vm.startPrank(alice);
        tokenA.approve(address(adapterSingle), AMOUNT_IN);
        vm.expectRevert(
            abi.encodeWithSelector(UniswapV4SwapperAdapter.InsufficientOutput.selector, minOut, actualOut)
        );
        adapterSingle.swap(address(tokenA), address(tokenC), AMOUNT_IN, minOut, alice);
        vm.stopPrank();
    }

    function test_SingleHop_PartialFill_ReturnsUnusedTokenInToCaller() public {
        uint256 bps = 8000; // pool only fills 80% of requested input
        _configurePool(address(tokenA), address(tokenC), FEE1, TICK1, WAD, bps);

        uint256 expectedOut = _expectedOut(AMOUNT_IN, bps, WAD);
        uint256 consumed = (AMOUNT_IN * bps) / 10_000;
        uint256 unused = AMOUNT_IN - consumed;

        uint256 aliceTokenABefore = tokenA.balanceOf(alice);

        vm.startPrank(alice);
        tokenA.approve(address(adapterSingle), AMOUNT_IN);
        uint256 amountOut = adapterSingle.swap(address(tokenA), address(tokenC), AMOUNT_IN, expectedOut, alice);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
        // Net tokenA spent by alice equals only what was actually consumed by the pool.
        assertEq(tokenA.balanceOf(alice), aliceTokenABefore - consumed);
        assertGt(unused, 0);
        // Adapter itself should hold no residual balance.
        assertEq(tokenA.balanceOf(address(adapterSingle)), 0);
    }

    function test_SingleHop_TokenInIsBase_UsesSecondHopConfig() public {
        // adapterMulti: base = tokenB. tokenIn == base => must route through
        // feeOut/tickSpacingOut/hooksOut (the base->tokenOut pool), single-hop.
        _configurePool(address(tokenB), address(tokenC), FEE2, TICK2, WAD, 0);
        // Intentionally do NOT configure a FEE1/TICK1 pool for tokenB/tokenC —
        // if the adapter picked the wrong config, the mock would revert with
        // "rate not configured".

        uint256 expectedOut = _expectedOut(AMOUNT_IN, 10_000, WAD);

        vm.startPrank(alice);
        tokenB.approve(address(adapterMulti), AMOUNT_IN);
        uint256 amountOut = adapterMulti.swap(address(tokenB), address(tokenC), AMOUNT_IN, expectedOut, alice);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
    }

    function test_SingleHop_TokenOutIsBase_UsesFirstHopConfig() public {
        // adapterMulti: base = tokenB. tokenOut == base (but tokenIn != base) =>
        // must route through fee/tickSpacing/hooks (the tokenIn->base pool), single-hop.
        _configurePool(address(tokenA), address(tokenB), FEE1, TICK1, WAD, 0);
        // Intentionally do NOT configure a FEE2/TICK2 pool for tokenA/tokenB.

        uint256 expectedOut = _expectedOut(AMOUNT_IN, 10_000, WAD);

        vm.startPrank(alice);
        tokenA.approve(address(adapterMulti), AMOUNT_IN);
        uint256 amountOut = adapterMulti.swap(address(tokenA), address(tokenB), AMOUNT_IN, expectedOut, alice);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
    }

    // ============================================
    // MULTI-HOP SWAPS
    // ============================================

    function test_MultiHop_Success_FullFill() public {
        uint256 rate1 = 2 * WAD; // 1 tokenA -> 2 tokenB
        uint256 rate2 = WAD / 2; // 1 tokenB -> 0.5 tokenC

        _configurePool(address(tokenA), address(tokenB), FEE1, TICK1, rate1, 0);
        _configurePool(address(tokenB), address(tokenC), FEE2, TICK2, rate2, 0);

        uint256 baseAmount = _expectedOut(AMOUNT_IN, 10_000, rate1);
        uint256 expectedOut = _expectedOut(baseAmount, 10_000, rate2);

        uint256 aliceTokenABefore = tokenA.balanceOf(alice);
        uint256 aliceTokenCBefore = tokenC.balanceOf(alice);
        uint256 aliceTokenBBefore = tokenB.balanceOf(alice);

        vm.startPrank(alice);
        tokenA.approve(address(adapterMulti), AMOUNT_IN);
        uint256 amountOut = adapterMulti.swap(address(tokenA), address(tokenC), AMOUNT_IN, expectedOut, alice);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
        assertEq(tokenA.balanceOf(alice), aliceTokenABefore - AMOUNT_IN);
        assertEq(tokenC.balanceOf(alice), aliceTokenCBefore + expectedOut);
        // No base-token residue leaks to the caller when both hops fully match.
        assertEq(tokenB.balanceOf(alice), aliceTokenBBefore);
        assertEq(tokenB.balanceOf(address(adapterMulti)), 0);
    }

    function test_MultiHop_RevertsOnInsufficientOutput() public {
        _configurePool(address(tokenA), address(tokenB), FEE1, TICK1, WAD, 0);
        _configurePool(address(tokenB), address(tokenC), FEE2, TICK2, WAD, 0);

        uint256 actualOut = _expectedOut(AMOUNT_IN, 10_000, WAD);
        uint256 minOut = actualOut + 1;

        vm.startPrank(alice);
        tokenA.approve(address(adapterMulti), AMOUNT_IN);
        vm.expectRevert(
            abi.encodeWithSelector(UniswapV4SwapperAdapter.InsufficientOutput.selector, minOut, actualOut)
        );
        adapterMulti.swap(address(tokenA), address(tokenC), AMOUNT_IN, minOut, alice);
        vm.stopPrank();
    }

    function test_MultiHop_UnusedBase_ReturnedToCaller() public {
        uint256 hop2Bps = 7000; // hop2 only consumes 70% of the base produced by hop1
        _configurePool(address(tokenA), address(tokenB), FEE1, TICK1, WAD, 0);
        _configurePool(address(tokenB), address(tokenC), FEE2, TICK2, WAD, hop2Bps);

        uint256 baseAmount = _expectedOut(AMOUNT_IN, 10_000, WAD);
        uint256 baseConsumed = (baseAmount * hop2Bps) / 10_000;
        uint256 unusedBase = baseAmount - baseConsumed;
        uint256 expectedOut = _expectedOut(baseAmount, hop2Bps, WAD);

        uint256 aliceTokenBBefore = tokenB.balanceOf(alice);

        vm.startPrank(alice);
        tokenA.approve(address(adapterMulti), AMOUNT_IN);
        uint256 amountOut = adapterMulti.swap(address(tokenA), address(tokenC), AMOUNT_IN, expectedOut, alice);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
        assertGt(unusedBase, 0);
        assertEq(tokenB.balanceOf(alice), aliceTokenBBefore + unusedBase);
        assertEq(tokenB.balanceOf(address(adapterMulti)), 0);
    }

    function test_MultiHop_UnusedTokenIn_ReturnedToCaller() public {
        uint256 hop1Bps = 9000; // hop1 only consumes 90% of the requested tokenIn
        _configurePool(address(tokenA), address(tokenB), FEE1, TICK1, WAD, hop1Bps);
        _configurePool(address(tokenB), address(tokenC), FEE2, TICK2, WAD, 0);

        uint256 consumed = (AMOUNT_IN * hop1Bps) / 10_000;
        uint256 unusedTokenIn = AMOUNT_IN - consumed;
        uint256 baseAmount = _expectedOut(AMOUNT_IN, hop1Bps, WAD);
        uint256 expectedOut = _expectedOut(baseAmount, 10_000, WAD);

        uint256 aliceTokenABefore = tokenA.balanceOf(alice);

        vm.startPrank(alice);
        tokenA.approve(address(adapterMulti), AMOUNT_IN);
        uint256 amountOut = adapterMulti.swap(address(tokenA), address(tokenC), AMOUNT_IN, expectedOut, alice);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
        assertGt(unusedTokenIn, 0);
        // Net tokenA spent equals only what hop1 actually consumed.
        assertEq(tokenA.balanceOf(alice), aliceTokenABefore - consumed);
        assertEq(tokenA.balanceOf(address(adapterMulti)), 0);
    }

    function test_MultiHop_SendsOutputToReceiver_NotCaller() public {
        _configurePool(address(tokenA), address(tokenB), FEE1, TICK1, WAD, 0);
        _configurePool(address(tokenB), address(tokenC), FEE2, TICK2, WAD, 0);

        uint256 expectedOut = _expectedOut(AMOUNT_IN, 10_000, WAD);
        uint256 bobBefore = tokenC.balanceOf(bob);

        vm.startPrank(alice);
        tokenA.approve(address(adapterMulti), AMOUNT_IN);
        adapterMulti.swap(address(tokenA), address(tokenC), AMOUNT_IN, expectedOut, bob);
        vm.stopPrank();

        assertEq(tokenC.balanceOf(bob), bobBefore + expectedOut);
    }

    // ============================================
    // FUZZ
    // ============================================

    function testFuzz_SingleHop_FullFill(uint256 amountIn) public {
        amountIn = bound(amountIn, 1e6, 500_000e18);
        tokenA.mint(alice, amountIn);

        _configurePool(address(tokenA), address(tokenC), FEE1, TICK1, WAD, 0);
        uint256 expectedOut = _expectedOut(amountIn, 10_000, WAD);

        uint256 aliceTokenABefore = tokenA.balanceOf(alice);
        uint256 aliceTokenCBefore = tokenC.balanceOf(alice);

        vm.startPrank(alice);
        tokenA.approve(address(adapterSingle), amountIn);
        uint256 amountOut = adapterSingle.swap(address(tokenA), address(tokenC), amountIn, expectedOut, alice);
        vm.stopPrank();

        assertEq(amountOut, expectedOut);
        assertEq(tokenA.balanceOf(alice), aliceTokenABefore - amountIn);
        assertEq(tokenC.balanceOf(alice), aliceTokenCBefore + expectedOut);
        assertEq(tokenA.balanceOf(address(adapterSingle)), 0);
        assertEq(tokenC.balanceOf(address(adapterSingle)), 0);
    }
}
