import { UniswapV4SwapperAdapter, IV4PoolManager } from "src/swappers/UniswapV4SwapperAdapter.sol";

// ============================================
// Mocks
// ============================================

/// @dev Minimal mintable ERC20 for testing. No access control on mint since
///      only the test suite and MockPoolManager use it.
contract MockERC20 is ERC20 {
    constructor(string memory name_, string memory symbol_) ERC20(name_, symbol_) { }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

interface IUnlockCallback {
    function unlockCallback(bytes calldata data) external returns (bytes memory);
}

/// @dev Minimal but faithful mock of the Uniswap V4 PoolManager singleton.
///      Implements unlock()/swap()/sync()/settle()/take() using the same
///      delta-accounting + packed-BalanceDelta ABI as the real contract, so
///      UniswapV4SwapperAdapter's bit-packing/unpacking logic is exercised
///      exactly as it would be against the real PoolManager.
///
///      Each configured pool has a fixed exchange rate (WAD-scaled) and an
///      optional partial-fill percentage (in bps) to simulate shallow pools
///      that don't fully consume the specified input.
contract MockPoolManager is IV4PoolManager {
    using SafeERC20 for IERC20;

    mapping(bytes32 => uint256) public rateWad; // output per input, 1e18 = 1:1
    mapping(bytes32 => uint256) public fillBps; // 10000 = full fill
    mapping(address => int256) public currencyDelta;

    mapping(address => uint256) internal _reserve;
    address internal _syncedCurrency;

    function configure(
        address c0,
        address c1,
        uint24 feeVal,
        int24 tickSpacingVal,
        address hooksAddr,
        uint256 _rateWad,
        uint256 _fillBps
    ) external {
        bytes32 k = _poolKey(c0, c1, feeVal, tickSpacingVal, hooksAddr);
        rateWad[k] = _rateWad;
        fillBps[k] = _fillBps;
    }

    function _poolKey(
        address c0,
        address c1,
        uint24 feeVal,
        int24 tickSpacingVal,
        address hooksAddr
    ) internal pure returns (bytes32) {
        return keccak256(abi.encode(c0, c1, feeVal, tickSpacingVal, hooksAddr));
    }

    function unlock(bytes calldata data) external returns (bytes memory) {
        return IUnlockCallback(msg.sender).unlockCallback(data);
    }

    function swap(
        PoolKey memory key,
        SwapParams memory params,
        bytes calldata
    ) external returns (int256 swapDelta) {
        uint256 amountIn = uint256(-params.amountSpecified);
        bytes32 k = _poolKey(key.currency0, key.currency1, key.fee, key.tickSpacing, key.hooks);

        uint256 rate = rateWad[k];
        require(rate != 0, "MockPoolManager: pool not configured");
        uint256 bps = fillBps[k];
        if (bps == 0) bps = 10_000;

        uint256 consumed = (amountIn * bps) / 10_000;
        uint256 amountOut = (consumed * rate) / 1e18;

        address tokenIn = params.zeroForOne ? key.currency0 : key.currency1;
        address tokenOut = params.zeroForOne ? key.currency1 : key.currency0;

        currencyDelta[tokenIn] -= int256(consumed);
        currencyDelta[tokenOut] += int256(amountOut);

        // Simulate the pool paying out: mint fresh output tokens to the PM balance.
        MockERC20(tokenOut).mint(address(this), amountOut);

        int128 amount0;
        int128 amount1;
        if (params.zeroForOne) {
            amount0 = -int128(int256(consumed));
            amount1 = int128(int256(amountOut));
        } else {
            amount1 = -int128(int256(consumed));
            amount0 = int128(int256(amountOut));
        }
        swapDelta = _toBalanceDelta(amount0, amount1);
    }

    function _toBalanceDelta(int128 amount0, int128 amount1) internal pure returns (int256 delta) {
        delta = (int256(amount0) << 128) | int256(uint256(uint128(amount1)));
    }

    function sync(address currency) external {
