contract UniswapV4SwapperAdapterTest is Test {
    MockPoolManager internal pm;

    MockERC20 internal tokenA;
    MockERC20 internal tokenB;
    MockERC20 internal tokenBase;

    address internal lower; // tokenA/tokenB sorted: numerically smaller
    address internal higher; // tokenA/tokenB sorted: numerically larger

