// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.25;

import { Test } from "forge-std/Test.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import { UniswapV4SwapperAdapter, IV4PoolManager } from "src/swappers/UniswapV4SwapperAdapter.sol";

// ============================================
// Mocks
// ============================================

/// @dev Minimal mintable ERC20 for testing. No access control on mint since
///      only the test suite and MockPoolManager use it.
contract MockERC20 is ERC20 {
    constructor(string memory name_, string memory symbol_) ERC20(name_, symbol_) { }

    function mint(address to, uint256 amount) external {
        _mint(to, amount);
    }
}

interface IUnlockCallback {
    function unlockCallback(bytes calldata data) external returns (bytes memory);
}

/// @dev Minimal but faithful mock of the Uniswap V4 PoolManager singleton.
///      Implements unlock()/swap()/sync()/settle()/take() using the same
///      delta-accounting + packed-BalanceDelta ABI as the real contract, so
///      UniswapV4SwapperAdapter's bit-packing/unpacking logic is exercised
///      exactly as it would be against the real PoolManager.
///
///      Each configured pool has a fixed exchange rate (WAD-scaled) and an
///      optional partial-fill percentage (in bps) to simulate shallow pools
///      that don't fully consume the specified input.
contract MockPoolManager is IV4PoolManager {
    using SafeERC20 for IERC20;

    mapping(bytes32 => uint256) public rateWad; // output per input, 1e18 = 1:1
    mapping(bytes32 => uint256) public fillBps; // 10000 = full fill
    mapping(address => int256) public currencyDelta;

    mapping(address => uint256) internal _reserve;
    address internal _syncedCurrency;

    function configure(
        address c0,
        address c1,
        uint24 feeVal,
        int24 tickSpacingVal,
        address hooksAddr,
        uint256 _rateWad,
        uint256 _fillBps
    ) external {
        bytes32 k = _poolKey(c0, c1, feeVal, tickSpacingVal, hooksAddr);
        rateWad[k] = _rateWad;
        fillBps[k] = _fillBps;
    }

    function _poolKey(
        address c0,
        address c1,
        uint24 feeVal,
        int24 tickSpacingVal,
        address hooksAddr
    ) internal pure returns (bytes32) {
        return keccak256(abi.encode(c0, c1, feeVal, tickSpacingVal, hooksAddr));
    }

    function unlock(bytes calldata data) external returns (bytes memory) {
        return IUnlockCallback(msg.sender).unlockCallback(data);
    }

    function swap(
        PoolKey memory key,
        SwapParams memory params,
        bytes calldata
    ) external returns (int256 swapDelta) {
        uint256 amountIn = uint256(-params.amountSpecified);
        bytes32 k = _poolKey(key.currency0, key.currency1, key.fee, key.tickSpacing, key.hooks);

        uint256 rate = rateWad[k];
        require(rate != 0, "MockPoolManager: pool not configured");
        uint256 bps = fillBps[k];
        if (bps == 0) bps = 10_000;

        uint256 consumed = (amountIn * bps) / 10_000;
        uint256 amountOut = (consumed * rate) / 1e18;

        address tokenIn = params.zeroForOne ? key.currency0 : key.currency1;
        address tokenOut = params.zeroForOne ? key.currency1 : key.currency0;

        currencyDelta[tokenIn] -= int256(consumed);
        currencyDelta[tokenOut] += int256(amountOut);

        // Simulate the pool paying out: mint fresh output tokens to the PM balance.
        MockERC20(tokenOut).mint(address(this), amountOut);

        int128 amount0;
        int128 amount1;
        if (params.zeroForOne) {
            amount0 = -int128(int256(consumed));
            amount1 = int128(int256(amountOut));
        } else {
            amount1 = -int128(int256(consumed));
            amount0 = int128(int256(amountOut));
        }
        swapDelta = _toBalanceDelta(amount0, amount1);
    }

    function _toBalanceDelta(int128 amount0, int128 amount1) internal pure returns (int256 delta) {
        delta = (int256(amount0) << 128) | int256(uint256(uint128(amount1)));
    }

    function sync(address currency) external {
        _syncedCurrency = currency;
        _reserve[currency] = IERC20(currency).balanceOf(address(this));
    }

    function settle() external payable returns (uint256 paid) {
        address currency = _syncedCurrency;
        uint256 bal = IERC20(currency).balanceOf(address(this));
        paid = bal - _reserve[currency];
        currencyDelta[currency] += int256(paid);
    }

    function take(address currency, address to, uint256 amount) external {
        currencyDelta[currency] -= int256(amount);
        IERC20(currency).safeTransfer(to, amount);
    }
}

// ============================================
// Tests
// ============================================

contract UniswapV4SwapperAdapterTest is Test {
    MockPoolManager internal pm;

    MockERC20 internal tokenA;
    MockERC20 internal tokenB;
    MockERC20 internal tokenBase;

    address internal lower; // tokenA/tokenB sorted: numerically smaller
    address internal higher; // tokenA/tokenB sorted: numerically larger

    address internal user = makeAddr("user");
    address internal receiver = makeAddr("receiver");

    uint24 internal constant FEE = 3000;
    int24 internal constant TICK_SPACING = 60;
    address internal constant HOOKS = address(0);

    uint24 internal constant FEE_OUT = 500;
    int24 internal constant TICK_SPACING_OUT = 10;
    address internal constant HOOKS_OUT = address(0);

    UniswapV4SwapperAdapter internal singleHopAdapter;
    UniswapV4SwapperAdapter internal multiHopAdapter;

    function setUp() public {
        pm = new MockPoolManager();

        tokenA = new MockERC20("Token A", "TKA");
        tokenB = new MockERC20("Token B", "TKB");
        tokenBase = new MockERC20("Base Token", "BASE");

        (lower, higher) = address(tokenA) < address(tokenB) ? (address(tokenA), address(tokenB)) : (address(tokenB), address(tokenA));

        singleHopAdapter = new UniswapV4SwapperAdapter(address(pm), FEE, TICK_SPACING, HOOKS, address(0), 0, 0, address(0));

        multiHopAdapter = new UniswapV4SwapperAdapter(
            address(pm), FEE, TICK_SPACING, HOOKS, address(tokenBase), FEE_OUT, TICK_SPACING_OUT, HOOKS_OUT
        );

        MockERC20(lower).mint(user, 1_000_000 ether);
        MockERC20(higher).mint(user, 1_000_000 ether);
        tokenBase.mint(user, 1_000_000 ether);

        vm.startPrank(user);
        IERC20(lower).approve(address(singleHopAdapter), type(uint256).max);
        IERC20(higher).approve(address(singleHopAdapter), type(uint256).max);
        IERC20(lower).approve(address(multiHopAdapter), type(uint256).max);
        IERC20(higher).approve(address(multiHopAdapter), type(uint256).max);
        tokenBase.approve(address(multiHopAdapter), type(uint256).max);
        vm.stopPrank();
    }

    function _sorted(address x, address y) internal pure returns (address, address) {
        return x < y ? (x, y) : (y, x);
    }

    // ============================================
    // Constructor
    // ============================================

    function test_Constructor_RevertsOnZeroPoolManager() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidPoolManager.selector);
        new UniswapV4SwapperAdapter(address(0), FEE, TICK_SPACING, HOOKS, address(0), 0, 0, address(0));
    }

    function test_Constructor_RevertsOnZeroTickSpacing() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidTickSpacing.selector);
        new UniswapV4SwapperAdapter(address(pm), FEE, 0, HOOKS, address(0), 0, 0, address(0));
    }

    function test_Constructor_RevertsOnZeroTickSpacingOut_WhenBaseSet() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidTickSpacing.selector);
        new UniswapV4SwapperAdapter(address(pm), FEE, TICK_SPACING, HOOKS, address(tokenBase), FEE_OUT, 0, HOOKS_OUT);
    }

    function test_Constructor_AllowsZeroTickSpacingOut_WhenBaseNotSet() public {
        // tickSpacingOut is ignored when base == address(0), even if zero.
        UniswapV4SwapperAdapter a =
            new UniswapV4SwapperAdapter(address(pm), FEE, TICK_SPACING, HOOKS, address(0), 0, 0, address(0));
        assertEq(a.tickSpacingOut(), 0);
    }

    function test_Constructor_SetsImmutables_SingleHop() public view {
        assertEq(singleHopAdapter.poolManager(), address(pm));
        assertEq(singleHopAdapter.fee(), FEE);
        assertEq(singleHopAdapter.tickSpacing(), TICK_SPACING);
        assertEq(singleHopAdapter.hooks(), HOOKS);
        assertEq(singleHopAdapter.base(), address(0));
    }

    function test_Constructor_SetsImmutables_MultiHop() public view {
        assertEq(multiHopAdapter.poolManager(), address(pm));
        assertEq(multiHopAdapter.fee(), FEE);
        assertEq(multiHopAdapter.tickSpacing(), TICK_SPACING);
        assertEq(multiHopAdapter.hooks(), HOOKS);
        assertEq(multiHopAdapter.base(), address(tokenBase));
        assertEq(multiHopAdapter.feeOut(), FEE_OUT);
        assertEq(multiHopAdapter.tickSpacingOut(), TICK_SPACING_OUT);
        assertEq(multiHopAdapter.hooksOut(), HOOKS_OUT);
    }

    // ============================================
    // Input validation
    // ============================================

    function test_Swap_RevertsOnZeroTokenIn() public {
        vm.prank(user);
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidToken.selector);
        singleHopAdapter.swap(address(0), higher, 1 ether, 0, receiver);
    }

    function test_Swap_RevertsOnZeroTokenOut() public {
        vm.prank(user);
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidToken.selector);
        singleHopAdapter.swap(lower, address(0), 1 ether, 0, receiver);
    }

    // ============================================
    // unlockCallback access control
    // ============================================

    function test_UnlockCallback_RevertsIfNotPoolManager() public {
        bytes memory data = abi.encode(user, lower, higher, uint256(1 ether), uint256(0), receiver);
        vm.expectRevert(UniswapV4SwapperAdapter.UnauthorizedCallback.selector);
        singleHopAdapter.unlockCallback(data);
    }

    // ============================================
    // Single-hop swaps
    // ============================================

