///      during `unlock()` must net to a zero delta by the time `unlock()` returns, or
///      the mock reverts with `CurrencyNotSettled` — this is what actually verifies the
///      adapter's sync/transfer/settle/take bookkeeping is correct.
contract MockPoolManager is IV4PoolManager {
    using SafeERC20 for IERC20;

    struct SwapConfig {
        uint256 outputAmount;
        uint256 consumedAmount;
    }

    struct RecordedSwap {
        address currency0;
        address currency1;
        uint24 fee;
        int24 tickSpacing;
        address hooks;
        bool zeroForOne;
        int256 amountSpecified;
        uint160 sqrtPriceLimitX96;
    }

    error CurrencyNotSettled(address currency, int256 delta);

    SwapConfig[] internal swapQueue;
    uint256 internal swapCallIndex;

    mapping(address => int256) public currencyDelta;
    mapping(address => uint256) internal reservesBefore;
    address internal syncedCurrency;

    address[] internal touchedCurrencies;
    mapping(address => bool) internal isTouched;

    RecordedSwap[] public recordedSwaps;

    function queueSwap(uint256 outputAmount, uint256 consumedAmount) external {
        swapQueue.push(SwapConfig(outputAmount, consumedAmount));
    }

    function recordedSwapsLength() external view returns (uint256) {
        return recordedSwaps.length;
    }

    function _touch(address currency) internal {
        if (!isTouched[currency]) {
            isTouched[currency] = true;
            touchedCurrencies.push(currency);
        }
    }

    function unlock(bytes calldata data) external returns (bytes memory result) {
        result = IUnlockCallback(msg.sender).unlockCallback(data);

        for (uint256 i = 0; i < touchedCurrencies.length; i++) {
            address c = touchedCurrencies[i];
            int256 d = currencyDelta[c];
            if (d != 0) revert CurrencyNotSettled(c, d);
            isTouched[c] = false;
            currencyDelta[c] = 0;
        }
        delete touchedCurrencies;
        delete swapQueue;
        swapCallIndex = 0;
        delete recordedSwaps;
    }

    function swap(
        PoolKey memory key,
        SwapParams memory params,
        bytes calldata
    ) external returns (int256 swapDelta) {
        require(swapCallIndex < swapQueue.length, "MockPoolManager: no queued swap");
        SwapConfig memory cfg = swapQueue[swapCallIndex];
        swapCallIndex++;

        recordedSwaps.push(
            RecordedSwap({
                currency0: key.currency0,
                currency1: key.currency1,
                fee: key.fee,
                tickSpacing: key.tickSpacing,
                hooks: key.hooks,
                zeroForOne: params.zeroForOne,
                amountSpecified: params.amountSpecified,
                sqrtPriceLimitX96: params.sqrtPriceLimitX96
            })
        );

        address inputCurrency = params.zeroForOne ? key.currency0 : key.currency1;
        address outputCurrency = params.zeroForOne ? key.currency1 : key.currency0;

        _touch(inputCurrency);
        _touch(outputCurrency);

        currencyDelta[inputCurrency] -= int256(cfg.consumedAmount);
        currencyDelta[outputCurrency] += int256(cfg.outputAmount);

        int128 amount0;
        int128 amount1;
        if (params.zeroForOne) {
            amount0 = -int128(int256(cfg.consumedAmount));
            amount1 = int128(int256(cfg.outputAmount));
        } else {
            amount1 = -int128(int256(cfg.consumedAmount));
            amount0 = int128(int256(cfg.outputAmount));
        }

        uint256 packed = (uint256(uint128(amount0)) << 128) | uint256(uint128(amount1));
        swapDelta = int256(packed);
    }

    function sync(address currency) external {
        syncedCurrency = currency;
        reservesBefore[currency] = IERC20(currency).balanceOf(address(this));
        _touch(currency);
    }

    function settle() external payable returns (uint256 paid) {
        address currency = syncedCurrency;
        uint256 currentBalance = IERC20(currency).balanceOf(address(this));
        paid = currentBalance - reservesBefore[currency];
        currencyDelta[currency] += int256(paid);
    }

    function take(address currency, address to, uint256 amount) external {
        currencyDelta[currency] -= int256(amount);
        _touch(currency);
        IERC20(currency).safeTransfer(to, amount);
    }
}

contract UniswapV4SwapperAdapterTest is Test {
    uint160 internal constant MIN_SQRT_PRICE_LIMIT = 4295128740;
    uint160 internal constant MAX_SQRT_PRICE_LIMIT = 1461446703485210103287273052203988822378723970341;

    uint24 internal constant FEE = 3000;
    int24 internal constant TICK_SPACING = 60;
    address internal constant HOOKS = address(0x1111);

    uint24 internal constant FEE_OUT = 500;
    int24 internal constant TICK_SPACING_OUT = 10;
    address internal constant HOOKS_OUT = address(0x2222);

    MockPoolManager internal poolManager;
    MockERC20 internal tokenA;
    MockERC20 internal tokenB;
    MockERC20 internal tokenC; // base token for multi-hop adapter

    UniswapV4SwapperAdapter internal singleHopAdapter;
    UniswapV4SwapperAdapter internal multiHopAdapter;

    address internal user = makeAddr("user");
    address internal receiver = makeAddr("receiver");

    function setUp() public {
        poolManager = new MockPoolManager();
        tokenA = new MockERC20("Token A", "TKA");
        tokenB = new MockERC20("Token B", "TKB");
        tokenC = new MockERC20("Token C (base)", "TKC");

        singleHopAdapter = new UniswapV4SwapperAdapter(
            address(poolManager), FEE, TICK_SPACING, HOOKS, address(0), 0, 0, address(0)
        );

        multiHopAdapter = new UniswapV4SwapperAdapter(
            address(poolManager),
            FEE,
            TICK_SPACING,
            HOOKS,
            address(tokenC),
            FEE_OUT,
            TICK_SPACING_OUT,
            HOOKS_OUT
        );

        tokenA.mint(user, 1_000e18);
        tokenC.mint(user, 1_000e18);

        // Liquidity the mock PoolManager can `take()` from.
        tokenB.mint(address(poolManager), 1_000_000e18);
        tokenC.mint(address(poolManager), 1_000_000e18);

        vm.startPrank(user);
        tokenA.approve(address(singleHopAdapter), type(uint256).max);
        tokenA.approve(address(multiHopAdapter), type(uint256).max);
        tokenC.approve(address(multiHopAdapter), type(uint256).max);
        vm.stopPrank();
    }

    // ============================================
    // CONSTRUCTOR
    // ============================================

    function test_Constructor_RevertsIfPoolManagerIsZero() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidPoolManager.selector);
        new UniswapV4SwapperAdapter(address(0), FEE, TICK_SPACING, HOOKS, address(0), 0, 0, address(0));
    }

    function test_Constructor_RevertsIfTickSpacingIsZero() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidTickSpacing.selector);
        new UniswapV4SwapperAdapter(address(poolManager), FEE, 0, HOOKS, address(0), 0, 0, address(0));
    }

    function test_Constructor_RevertsIfTickSpacingOutIsZeroWithBaseSet() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidTickSpacing.selector);
        new UniswapV4SwapperAdapter(
            address(poolManager), FEE, TICK_SPACING, HOOKS, address(tokenC), FEE_OUT, 0, HOOKS_OUT
        );
    }

    function test_Constructor_AllowsZeroTickSpacingOutWhenBaseIsZero() public {
        // tickSpacingOut is ignored (and thus unchecked) when base == address(0)
        UniswapV4SwapperAdapter adapter =
            new UniswapV4SwapperAdapter(address(poolManager), FEE, TICK_SPACING, HOOKS, address(0), 0, 0, address(0));
        assertEq(adapter.base(), address(0));
    }

    function test_Constructor_SetsImmutables_SingleHop() public view {
        assertEq(singleHopAdapter.poolManager(), address(poolManager));
        assertEq(singleHopAdapter.fee(), FEE);
        assertEq(singleHopAdapter.tickSpacing(), TICK_SPACING);
        assertEq(singleHopAdapter.hooks(), HOOKS);
        assertEq(singleHopAdapter.base(), address(0));
        assertEq(singleHopAdapter.feeOut(), 0);
        assertEq(singleHopAdapter.tickSpacingOut(), 0);
        assertEq(singleHopAdapter.hooksOut(), address(0));
    }

    function test_Constructor_SetsImmutables_MultiHop() public view {
        assertEq(multiHopAdapter.poolManager(), address(poolManager));
        assertEq(multiHopAdapter.fee(), FEE);
        assertEq(multiHopAdapter.tickSpacing(), TICK_SPACING);
        assertEq(multiHopAdapter.hooks(), HOOKS);
        assertEq(multiHopAdapter.base(), address(tokenC));
        assertEq(multiHopAdapter.feeOut(), FEE_OUT);
        assertEq(multiHopAdapter.tickSpacingOut(), TICK_SPACING_OUT);
        assertEq(multiHopAdapter.hooksOut(), HOOKS_OUT);
    }

    // ============================================
    // INPUT VALIDATION
    // ============================================

    function test_Swap_RevertsIfTokenInIsZero() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidToken.selector);
        singleHopAdapter.swap(address(0), address(tokenB), 1e18, 0, receiver);
    }

    function test_Swap_RevertsIfTokenOutIsZero() public {
        vm.expectRevert(UniswapV4SwapperAdapter.InvalidToken.selector);
        singleHopAdapter.swap(address(tokenA), address(0), 1e18, 0, receiver);
    }

    function test_UnlockCallback_RevertsIfCallerIsNotPoolManager() public {
        bytes memory data = abi.encode(user, address(tokenA), address(tokenB), 1e18, 0, receiver);
        vm.expectRevert(UniswapV4SwapperAdapter.UnauthorizedCallback.selector);
        singleHopAdapter.unlockCallback(data);
    }

    // ============================================
    // SINGLE-HOP SWAPS
    // ============================================

    function test_Swap_SingleHop_Success() public {
        uint256 amountIn = 10e18;
        uint256 outputAmount = 9.5e18;
        poolManager.queueSwap(outputAmount, amountIn);

        uint256 userBalanceBefore = tokenA.balanceOf(user);

        vm.prank(user);
        uint256 amountOut = singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 9e18, receiver);

        assertEq(amountOut, outputAmount);
        assertEq(tokenB.balanceOf(receiver), outputAmount);
        assertEq(userBalanceBefore - tokenA.balanceOf(user), amountIn);
        assertEq(tokenA.balanceOf(address(singleHopAdapter)), 0);
        assertEq(tokenA.balanceOf(address(poolManager)), amountIn);
    }

    function test_Swap_SingleHop_RevertsOnInsufficientOutput() public {
        uint256 amountIn = 10e18;
        uint256 outputAmount = 5e18;
        poolManager.queueSwap(outputAmount, amountIn);

        vm.expectRevert(
            abi.encodeWithSelector(UniswapV4SwapperAdapter.InsufficientOutput.selector, 9e18, outputAmount)
        );
        vm.prank(user);
        singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 9e18, receiver);
    }

    function test_Swap_SingleHop_PartialFill_RefundsUnusedTokenInToCaller() public {
        uint256 amountIn = 10e18;
        uint256 consumed = 7e18;
        uint256 outputAmount = 6.5e18;
        poolManager.queueSwap(outputAmount, consumed);

        uint256 userBalanceBefore = tokenA.balanceOf(user);

        vm.prank(user);
        uint256 amountOut = singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        assertEq(amountOut, outputAmount);
        assertEq(tokenB.balanceOf(receiver), outputAmount);
        // Net tokenA spent by the caller equals only what the pool actually consumed.
        assertEq(userBalanceBefore - tokenA.balanceOf(user), consumed);
        assertEq(tokenA.balanceOf(address(singleHopAdapter)), 0);
        assertEq(tokenA.balanceOf(address(poolManager)), consumed);
    }

    function test_Swap_SingleHop_PassesCorrectPoolKeyAndParams() public {
        uint256 amountIn = 3e18;
        poolManager.queueSwap(2.9e18, amountIn);

        vm.prank(user);
        singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        bool expectedZeroForOne = address(tokenA) < address(tokenB);
        (
            address c0,
            address c1,
            uint24 f,
            int24 ts,
            address hk,
            bool zfo,
            int256 amtSpec,
            uint160 sqrtLimit
        ) = poolManager.recordedSwaps(0);

        assertEq(c0, expectedZeroForOne ? address(tokenA) : address(tokenB));
        assertEq(c1, expectedZeroForOne ? address(tokenB) : address(tokenA));
        assertEq(f, FEE);
        assertEq(ts, TICK_SPACING);
        assertEq(hk, HOOKS);
        assertEq(zfo, expectedZeroForOne);
        assertEq(amtSpec, -int256(amountIn));
        assertEq(sqrtLimit, expectedZeroForOne ? MIN_SQRT_PRICE_LIMIT : MAX_SQRT_PRICE_LIMIT);
    }

    function testFuzz_Swap_SingleHop_FullConsumption(uint96 amountInSeed, uint96 outputSeed) public {
        uint256 amountIn = uint256(amountInSeed) + 1;
        uint256 outputAmount = uint256(outputSeed) + 1;

        tokenA.mint(user, amountIn);
        tokenB.mint(address(poolManager), outputAmount);
        poolManager.queueSwap(outputAmount, amountIn);

        vm.prank(user);
        uint256 amountOut = singleHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        assertEq(amountOut, outputAmount);
        assertEq(tokenB.balanceOf(receiver), outputAmount);
    }

    // ============================================
    // MULTI-HOP SWAPS
    // ============================================

    function test_Swap_MultiHop_Success() public {
        uint256 amountIn = 10e18;
        uint256 hop1Out = 9.8e18; // base received from hop 1
        uint256 hop2Out = 9.6e18; // tokenOut received from hop 2, fully consuming hop1Out

        poolManager.queueSwap(hop1Out, amountIn);
        poolManager.queueSwap(hop2Out, hop1Out);

        vm.prank(user);
        uint256 amountOut = multiHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 9e18, receiver);

        assertEq(amountOut, hop2Out);
        assertEq(tokenB.balanceOf(receiver), hop2Out);
        assertEq(poolManager.recordedSwapsLength(), 2);
    }

    function test_Swap_MultiHop_RefundsUnusedBaseToCaller() public {
        uint256 amountIn = 10e18;
        uint256 hop1Out = 9.8e18;
        uint256 hop2Consumed = 9e18; // less than hop1Out -> unusedBase = 0.8e18
        uint256 hop2Out = 8.7e18;

        poolManager.queueSwap(hop1Out, amountIn);
        poolManager.queueSwap(hop2Out, hop2Consumed);

        uint256 userTokenCBefore = tokenC.balanceOf(user);

        vm.prank(user);
        uint256 amountOut = multiHopAdapter.swap(address(tokenA), address(tokenB), amountIn, 0, receiver);

        assertEq(amountOut, hop2Out);
        assertEq(tokenC.balanceOf(user) - userTokenCBefore, hop1Out - hop2Consumed);
    }

    function test_Swap_MultiHop_RevertsOnInsufficientOutput() public {
        uint256 amountIn = 10e18;
        uint256 hop1Out = 9.8e18;
        uint256 hop2Out = 1e18;

        poolManager.queueSwap(hop1Out, amountIn);
        poolManager.queueSwap(hop2Out, hop1Out);

        vm.expectRevert(
            abi.encodeWithSelector(UniswapV4SwapperAdapter.InsufficientOutput.selector, 5e18, hop2Out)
        );
        vm.prank(user);
