    }

    function test_Swap_MultiHopAdapter_WhenTokenOutIsBase_UsesSingleHopWithFirstHopConfig() public {
        uint256 amountIn = 5e18;
        uint256 outputAmount = 4.9e18;
        poolManager.queueSwap(outputAmount, amountIn);

