        (, , uint24 recordedFee, int24 recordedTickSpacing, address recordedHooks, , , ) = poolManager.recordedSwaps(0);
        assertEq(recordedFee, FEE);
        assertEq(recordedTickSpacing, TICK_SPACING);
        assertEq(recordedHooks, HOOKS);
    }
